def _load_settings():
    """Đọc settings.json và áp dụng vào các global path."""
    global VIDEOCR_CLI_DIR, SUBTITLE_EDIT_PATH, VOXCPM_ENV_OVERRIDE, VIENEU_ENV_OVERRIDE, VIENEU_MODEL_DIR, FFMPEG_DIR, FFMPEG, FFPROBE
