# ── Loại trừ lẫn nhau: Provider voice ↔ RVC ↔ VoxCPM ─────────────────────────
# Tick RVC  → làm mờ Provider voice (provider/voice/delay/api key) + VoxCPM
# Tick VoxCPM → làm mờ Provider voice + RVC (gồm cả Device)
# Bỏ tick cả hai → mọi thứ sáng lại
_voice_block_ctrls = [
    provider_menu, voice_menu,
    delay_min_entry, delay_max_entry,
    api_key_entry, _show_key_check,
]
_rvc_all_ctrls = [
    rvc_enable_check,
    rvc_model_entry, rvc_model_btn,
    rvc_index_entry, rvc_index_btn,
    rvc_pitch_entry, rvc_algo_menu,
]
_voxcpm_all_ctrls = [
    voxcpm_enable_check,
    voxcpm_ckpt_entry, voxcpm_ref_entry,
]
_vieneu_all_ctrls = [
    vieneu_enable_check,
    vieneu_model_entry, vieneu_model_btn,
    vieneu_ref_entry, vieneu_ref_btn,
]
_f5tts_all_ctrls = [
    f5tts_enable_check,
    f5tts_model_entry, f5tts_model_btn,
    f5tts_ref_entry, f5tts_ref_btn,
]
_omnivoice_all_ctrls = [
    omnivoice_enable_check,
    omnivoice_model_entry, omnivoice_model_btn,
    omnivoice_ref_entry, omnivoice_ref_btn,
]

def _set_state(widgets, state):
    for w in widgets:
        try:
            w.configure(state=state)
        except Exception:
            pass

def _apply_voice_exclusivity():
    # Loại trừ lẫn nhau: chỉ 1 trong {Provider voice, RVC, VoxCPM, VieNeu, F5-TTS, OmniVoice} hoạt động.
    rvc_on = rvc_enable_var.get()
    vox_on = voxcpm_enable_var.get()
    vie_on = vieneu_enable_var.get()
    f5_on  = f5tts_enable_var.get()
    omni_on = omnivoice_enable_var.get()
    if rvc_on:
        _set_state(_voice_block_ctrls, "disabled")
        _set_state(_voxcpm_all_ctrls, "disabled")
        _set_state(_vieneu_all_ctrls, "disabled")
        _set_state(_f5tts_all_ctrls, "disabled")
        _set_state(_omnivoice_all_ctrls, "disabled")
        _set_state(_rvc_all_ctrls, "normal")
    elif vox_on:
        _set_state(_voice_block_ctrls, "disabled")
        _set_state(_rvc_all_ctrls, "disabled")
        _set_state(_vieneu_all_ctrls, "disabled")
        _set_state(_f5tts_all_ctrls, "disabled")
        _set_state(_omnivoice_all_ctrls, "disabled")
        _set_state(_voxcpm_all_ctrls, "normal")
    elif vie_on:
        _set_state(_voice_block_ctrls, "disabled")
        _set_state(_rvc_all_ctrls, "disabled")
        _set_state(_voxcpm_all_ctrls, "disabled")
        _set_state(_f5tts_all_ctrls, "disabled")
        _set_state(_omnivoice_all_ctrls, "disabled")
        _set_state(_vieneu_all_ctrls, "normal")
    elif f5_on:
        _set_state(_voice_block_ctrls, "disabled")
        _set_state(_rvc_all_ctrls, "disabled")
        _set_state(_voxcpm_all_ctrls, "disabled")
        _set_state(_vieneu_all_ctrls, "disabled")
        _set_state(_omnivoice_all_ctrls, "disabled")
        _set_state(_f5tts_all_ctrls, "normal")
    elif omni_on:
        _set_state(_voice_block_ctrls, "disabled")
        _set_state(_rvc_all_ctrls, "disabled")
        _set_state(_voxcpm_all_ctrls, "disabled")
        _set_state(_vieneu_all_ctrls, "disabled")
        _set_state(_f5tts_all_ctrls, "disabled")
        _set_state(_omnivoice_all_ctrls, "normal")
    else:
        _set_state(_voice_block_ctrls, "normal")
        _set_state(_rvc_all_ctrls, "normal")
        _set_state(_voxcpm_all_ctrls, "normal")
        _set_state(_vieneu_all_ctrls, "normal")
        _set_state(_f5tts_all_ctrls, "normal")
        _set_state(_omnivoice_all_ctrls, "normal")

# ── Voice Profiles (Hồ sơ giọng) ─────────────────────────────────────────────
# Lưu toàn bộ cấu hình giọng hiện tại (provider/engine + model + ref audio +
# speed/emotion...) thành hồ sơ có tên, chọn lại bằng 1 dropdown.
# File riêng (voice_profiles.json) để _save_settings() không ghi đè mất.
_VOICE_PROFILES_FILE = os.path.join(
    os.path.dirname(_SETTINGS_FILE) or ".", "voice_profiles.json")

def _voice_profiles_load():
    try:
        if os.path.isfile(_VOICE_PROFILES_FILE):
            with open(_VOICE_PROFILES_FILE, "r", encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict):
                return d
    except Exception:
        pass
    return {}

def _voice_profiles_write(d):
    try:
        with open(_VOICE_PROFILES_FILE, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
        return True
    except Exception as e:
        log(f"[Hồ sơ giọng] ❌ Không ghi được {_VOICE_PROFILES_FILE}: {e}")
        return False

def _voice_profile_capture():
    """Chụp toàn bộ cấu hình giọng hiện tại thành 1 dict."""
    if RVC_ENABLED:        eng = "rvc"
    elif VOXCPM_ENABLED:   eng = "voxcpm"
    elif VIENEU_ENABLED:   eng = "vieneu"
    elif F5TTS_ENABLED:    eng = "f5tts"
    elif OMNIVOICE_ENABLED: eng = "omnivoice"
    else:                  eng = "provider"
    return {
        "engine":   eng,
        "provider": provider_var.get(),
        "voice":    voice_var.get(),
        "edge_rate": edge_rate_var.get(), "edge_pitch": edge_pitch_var.get(),
        "rvc_model": rvc_model_var.get(),  "rvc_index": rvc_index_var.get(),
        "rvc_pitch": rvc_pitch_var.get(),  "rvc_algo":  rvc_algo_var.get(),
        "voxcpm_ckpt": voxcpm_ckpt_var.get(), "voxcpm_ref": voxcpm_ref_var.get(),
        "voxcpm_reftext": voxcpm_reftext_var.get(),
        "voxcpm_steps": voxcpm_steps_var.get(), "voxcpm_cfg": voxcpm_cfg_var.get(),
        "vieneu_model": vieneu_model_var.get(), "vieneu_ref": vieneu_ref_var.get(),
        "vieneu_reftext": vieneu_reftext_var.get(),
        "vieneu_voice": vieneu_voice_var.get(), "vieneu_emotion": vieneu_emotion_var.get(),
        "f5tts_model": f5tts_model_var.get(), "f5tts_ref": f5tts_ref_var.get(),
        "f5tts_reftext": f5tts_reftext_var.get(), "f5tts_speed": f5tts_speed_var.get(),
        "omnivoice_model": omnivoice_model_var.get(), "omnivoice_ref": omnivoice_ref_var.get(),
        "omnivoice_reftext": omnivoice_reftext_var.get(),
    }

def _voice_profile_apply(p):
    """Áp dụng 1 hồ sơ giọng vào toàn bộ UI vars + bật đúng engine."""
    try:
        # 1) Điền các trường (kể cả engine đang tắt — vô hại)
        if p.get("provider"): set_provider(p["provider"]); provider_var.set(p["provider"])
        if p.get("voice"):    voice_var.set(p["voice"]);   set_voice(p["voice"])
        for key, var in (
            ("edge_rate", edge_rate_var), ("edge_pitch", edge_pitch_var),
            ("rvc_model", rvc_model_var), ("rvc_index", rvc_index_var),
            ("rvc_pitch", rvc_pitch_var), ("rvc_algo", rvc_algo_var),
            ("voxcpm_ckpt", voxcpm_ckpt_var), ("voxcpm_ref", voxcpm_ref_var),
            ("voxcpm_reftext", voxcpm_reftext_var),
            ("voxcpm_steps", voxcpm_steps_var), ("voxcpm_cfg", voxcpm_cfg_var),
            ("vieneu_model", vieneu_model_var), ("vieneu_ref", vieneu_ref_var),
            ("vieneu_reftext", vieneu_reftext_var),
            ("vieneu_voice", vieneu_voice_var), ("vieneu_emotion", vieneu_emotion_var),
            ("f5tts_model", f5tts_model_var), ("f5tts_ref", f5tts_ref_var),
            ("f5tts_reftext", f5tts_reftext_var), ("f5tts_speed", f5tts_speed_var),
            ("omnivoice_model", omnivoice_model_var), ("omnivoice_ref", omnivoice_ref_var),
            ("omnivoice_reftext", omnivoice_reftext_var),
        ):
            if key in p:
                var.set(p.get(key) or "")
        # 2) Bật đúng engine, tắt các engine khác (toggle tự pack/unpack panel)
        eng = p.get("engine", "provider")
        rvc_enable_var.set(eng == "rvc")
        voxcpm_enable_var.set(eng == "voxcpm")
        vieneu_enable_var.set(eng == "vieneu")
        f5tts_enable_var.set(eng == "f5tts")
        omnivoice_enable_var.set(eng == "omnivoice")
        _toggle_rvc_panel()
        _toggle_voxcpm_panel()
        _toggle_vieneu_panel()
        _toggle_f5tts_panel()
        _toggle_omnivoice_panel()
        _apply_voice_exclusivity()
    except Exception as e:
        log(f"[Hồ sơ giọng] ❌ Lỗi áp dụng hồ sơ: {e}")

_VP_EMPTY = "(chưa có hồ sơ)"

def _voice_profiles_names():
    names = sorted(_voice_profiles_load().keys())
    return names if names else [_VP_EMPTY]

def _voice_profiles_refresh_menu(select=None):
    names = _voice_profiles_names()
    voice_profile_menu.configure(values=names)
    if select and select in names:
        voice_profile_var.set(select)
    elif voice_profile_var.get() not in names:
        voice_profile_var.set(names[0])

def _voice_profile_save_current():
    dlg = ctk.CTkInputDialog(text="Tên hồ sơ giọng (vd: Nữ thuyết minh):",
                             title="Lưu hồ sơ giọng")
    name = (dlg.get_input() or "").strip()
    if not name:
        return
    profiles = _voice_profiles_load()
    profiles[name] = _voice_profile_capture()
    if _voice_profiles_write(profiles):
        _voice_profiles_refresh_menu(select=name)
        log(f"[Hồ sơ giọng] ✅ Đã lưu hồ sơ: {name} (engine: {profiles[name]['engine']})")

def _voice_profile_delete_selected():
    name = voice_profile_var.get()
    if name == _VP_EMPTY:
        return
    if not msg.askyesno("Xóa hồ sơ giọng", f"Xóa hồ sơ '{name}'?"):
        return
    profiles = _voice_profiles_load()
    profiles.pop(name, None)
    if _voice_profiles_write(profiles):
        _voice_profiles_refresh_menu()
        log(f"[Hồ sơ giọng] Đã xóa hồ sơ: {name}")

def _voice_profile_on_select(name):
    if name == _VP_EMPTY:
        return
    p = _voice_profiles_load().get(name)
    if not p:
        log(f"[Hồ sơ giọng] ❌ Không tìm thấy hồ sơ: {name}")
        return
    _voice_profile_apply(p)
    log(f"[Hồ sơ giọng] ✅ Đã áp dụng hồ sơ: {name} (engine: {p.get('engine','provider')})")

# ── Từ điển phát âm (Glossary) ───────────────────────────────────────────────
# Map "từ/tên riêng" → "cách đọc" áp dụng cho MỌI engine TTS ngay trước khi
# sinh audio: save_tts() cho provider online; _glossary_items()/_apply_glossary()
# tại các điểm ghi texts-json cho VoxCPM/VieNeu/F5-TTS/OmniVoice. KHÔNG áp dụng
# cho dịch thuật, hiển thị subtitle hay file SRT — chỉ đổi text đưa vào TTS.
# File riêng (glossary.json) cạnh settings.json để _save_settings() không ghi đè.
_GLOSSARY_FILE = os.path.join(
    os.path.dirname(_SETTINGS_FILE) or ".", "glossary.json")
GLOSSARY = {}            # term → cách đọc
_GLOSSARY_RX = [None]    # regex gộp biên dịch sẵn (None = từ điển rỗng)
_GLOSSARY_LMAP = [{}]    # lookup lower(term) → cách đọc (cho sub không phân biệt hoa thường)

def _glossary_compile():
    """Biên dịch GLOSSARY thành 1 regex duy nhất: term dài ưu tiên khớp trước,
    không phân biệt hoa thường, chỉ khớp nguyên từ khi term bắt đầu/kết thúc
    bằng chữ-số (tên có ký hiệu như "C++" vẫn khớp đúng)."""
    _GLOSSARY_LMAP[0] = {k.lower(): v for k, v in GLOSSARY.items()}
    if not GLOSSARY:
        _GLOSSARY_RX[0] = None
        return
    parts = []
    for term in sorted(GLOSSARY, key=len, reverse=True):
        p = re.escape(term)
        if term[0].isalnum() or term[0] == "_":
            p = r"(?<!\w)" + p
        if term[-1].isalnum() or term[-1] == "_":
            p = p + r"(?!\w)"
        parts.append(p)
    _GLOSSARY_RX[0] = re.compile("|".join(parts), re.IGNORECASE)

def _glossary_load():
    global GLOSSARY
    try:
        if os.path.isfile(_GLOSSARY_FILE):
            with open(_GLOSSARY_FILE, "r", encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict):
                GLOSSARY = {str(k).strip(): str(v)
                            for k, v in d.items() if str(k).strip()}
    except Exception as e:
        log(f"[Từ điển] ⚠ Không đọc được {_GLOSSARY_FILE}: {e}")
    _glossary_compile()

def _glossary_save():
    try:
        with open(_GLOSSARY_FILE, "w", encoding="utf-8") as f:
            json.dump(GLOSSARY, f, ensure_ascii=False, indent=2)
    except Exception as e:
        log(f"[Từ điển] ❌ Không ghi được {_GLOSSARY_FILE}: {e}")

# ── Đọc số kiểu Việt (tiền tệ / ngày tháng / giờ) ────────────────────────────
# TTS đọc "1.500.000đ" / "20/11/2024" / "19h30" rất tệ — chuyển thành chữ
# trước khi sinh audio. Pattern chọn lọc (cần đuôi đ/đồng, đủ dd/mm/yyyy,
# NhMM) để tránh false-positive với phân số, tỷ số, mã số.
_VI_DIGITS = ["không", "một", "hai", "ba", "bốn",
              "năm", "sáu", "bảy", "tám", "chín"]

def _vi_three(n, full):
    """Đọc nhóm 3 chữ số 0..999. full=True → đọc đủ 'không trăm linh x'
    (dùng cho nhóm đứng sau nhóm lớn hơn, vd 1.005.000)."""
    tr, du = divmod(n, 100)
    ch, dv = divmod(du, 10)
    parts = []
    if tr or full:
        parts.append(_VI_DIGITS[tr] + " trăm")
    if ch == 0:
        if dv and (tr or full):
            parts.append("linh " + _VI_DIGITS[dv])
        elif dv:
            parts.append(_VI_DIGITS[dv])
    elif ch == 1:
        parts.append("mười" + ("" if dv == 0 else
                     " lăm" if dv == 5 else " " + _VI_DIGITS[dv]))
    else:
        s = _VI_DIGITS[ch] + " mươi"
        if dv == 1:
            s += " mốt"
        elif dv == 5:
            s += " lăm"
        elif dv:
            s += " " + _VI_DIGITS[dv]
        parts.append(s)
    return " ".join(parts)

def _vi_int_words(n):
    """Số nguyên không âm → chữ tiếng Việt (tới nghìn tỷ; lớn hơn giữ nguyên)."""
    if n == 0:
        return "không"
    if n >= 10 ** 15:
        return str(n)
    units = ["", " nghìn", " triệu", " tỷ", " nghìn tỷ"]
    gs = []
    digits = str(n)
    while digits:
        gs.append(int(digits[-3:]))
        digits = digits[:-3]
    parts = []
    started = False
    for i in range(len(gs) - 1, -1, -1):
        if gs[i] == 0:
            continue
        parts.append(_vi_three(gs[i], full=started) + units[i])
        started = True
    return " ".join(parts)

def _vi_num_normalize(text):
    """Chuyển tiền tệ / ngày dd/mm/yyyy / giờ NhMM trong text thành chữ Việt."""
    def _money(m):
        try:
            return _vi_int_words(int(re.sub(r"[.,]", "", m.group(1)))) + " đồng"
        except Exception:
            return m.group(0)
    text = re.sub(
        r"\b(\d{1,3}(?:[.,]\d{3})+|\d+)\s*(?:đồng|vnđ|vnd|₫|đ)(?!\w)",
        _money, text, flags=re.IGNORECASE)

    def _date(m):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if not (1 <= d <= 31 and 1 <= mo <= 12 and 1000 <= y <= 9999):
            return m.group(0)
        pre = ("" if re.search(r"ngày\s*$", m.string[:m.start()], re.IGNORECASE)
               else "ngày ")
        return (f"{pre}{_vi_int_words(d)} tháng {_vi_int_words(mo)} "
                f"năm {_vi_int_words(y)}")
    text = re.sub(r"\b(\d{1,2})/(\d{1,2})/(\d{4})\b", _date, text)

    def _time(m):
        h = int(m.group(1))
        if h > 23:
            return m.group(0)
        s = _vi_int_words(h) + " giờ"
        if m.group(2) is not None:
            mv = int(m.group(2))
            if mv > 59:
                return m.group(0)
            if mv:
                s += " " + _vi_int_words(mv) + " phút"
        return s
    text = re.sub(r"\b(\d{1,2})[hH](\d{2})?\b", _time, text)
    return text


# Ký tự "đọc được": có ít nhất 1 chữ cái / chữ số (mọi ngôn ngữ, Unicode).
# Dòng chỉ gồm dấu câu / ký hiệu / nốt nhạc (♪) → TTS chỉ ra im lặng (novoice)
# nên ta bỏ qua, không phí lượt gen.
_SPEAKABLE_RE = re.compile(r"[^\W_]", re.UNICODE)

def _is_speakable(text):
    """True nếu text có ít nhất 1 chữ cái hoặc chữ số → đáng để gọi TTS."""
    return bool(text) and bool(_SPEAKABLE_RE.search(text))


# Bảng ký tự cần XÓA khỏi text TTS: ký tự vô hình (zero-width U+200B–200F,
# bidi U+202A–202E, word-joiner U+2060, BOM U+FEFF, soft-hyphen U+00AD) +
# control chars (giữ lại \t \n \r vì chúng là khoảng trắng hợp lệ).
_OCR_DROP_CODEPOINTS = (
    list(range(0x00, 0x09)) + [0x0b, 0x0c]      # control (giữ \t)
    + list(range(0x0e, 0x20)) + [0x7f]          # control (giữ \n \r)
    + [0x00ad]                                  # soft hyphen
    + list(range(0x200b, 0x2010))               # zero-width + bidi marks
    + list(range(0x202a, 0x202f))               # bidi embedding/override
    + [0x2060, 0xfeff]                          # word joiner, BOM
)
_OCR_DROP_CHARS = {cp: None for cp in _OCR_DROP_CODEPOINTS}


def _clean_ocr_text(text):
    """Khử các ký tự 'bẩn' từ OCR/nguồn lạ làm Edge/TTS đọc lặp (toolong),
    cắt giữa chừng (tooshort) hoặc ra im lặng (novoice). Chạy cho MỌI engine,
    NGAY từ lần gen đầu (khác _sanitize_tts_text — chỉ chạy ở lần retry cuối) vì
    đây là lỗi tất định: cùng ký tự bẩn thì retry bao nhiêu lần cũng lỗi y hệt.
    KHÔNG xóa nội dung đọc được — chỉ loại ký hiệu gây nhiễu engine."""
    if not text:
        return text
    try:
        t = unicodedata.normalize("NFKC", text)   # gộp ký tự lạ về dạng chuẩn
    except Exception:
        t = text
    t = t.replace("�", "")           # ký tự thay thế OCR "�"
    # ký tự vô hình (zero-width, bidi marks, BOM, soft hyphen) + control chars
    # (giữ \t \n \r dạng khoảng trắng bình thường)
    t = t.translate(_OCR_DROP_CHARS)
    # ký tự phá SSML của Edge TTS (< > &) → khoảng trắng, tránh bị cắt giữa chừng
    t = re.sub(r"[<>&]", " ", t)
    # gộp ký tự lặp bệnh lý (>4 lần liên tiếp) → 2, chống runaway.
    # Loại trừ chữ số để không phá số lớn (vd "1000000").
    t = re.sub(r"([^\d\s])\1{4,}", r"\1\1", t)
    t = re.sub(r"\s{2,}", " ", t).strip()
    return t or text                               # không trả chuỗi rỗng


# ── Teencode / viết tắt chat → từ đầy đủ (đọc TTS không bị "cờ-a-ca") ────────
# SRT từ chat/comment/STT hay dính "ko", "dc", "vs"… — TTS đánh vần vô nghĩa.
# CHỈ match NGUYÊN TỪ viết THƯỜNG (case-sensitive): "BT"/"VS"/"CK" viết hoa là
# tên riêng/thuật ngữ nên không đụng. Danh sách cố ý hẹp (từ chat phổ biến,
# ít khả năng là từ thật) — cùng triết lý chống false-positive với
# _vi_num_normalize. Tắt bằng checkbox teencode_var ("Đọc teencode").
_TEENCODE_MAP = {
    "ko": "không", "hok": "không", "dc": "được", "đc": "được",
    "vs": "với", "ntn": "như thế nào", "bt": "bình thường", "trc": "trước",
    "ae": "anh em", "mn": "mọi người", "cx": "cũng", "vd": "ví dụ",
    "vv": "vân vân", "klq": "không liên quan", "ngta": "người ta",
    "mik": "mình", "mk": "mình", "bik": "biết", "j": "gì",
    "đt": "điện thoại", "nt": "nhắn tin", "sn": "sinh nhật",
    "tl": "trả lời", "nx": "nữa", "ny": "người yêu",
    "ck": "chồng", "vk": "vợ", "tks": "cảm ơn",
}
_TEENCODE_RX = re.compile(
    r"(?<!\w)(" + "|".join(sorted(_TEENCODE_MAP, key=len, reverse=True))
    + r")(?!\w)")


def _teencode_normalize(text):
    return _TEENCODE_RX.sub(lambda m: _TEENCODE_MAP[m.group(1)], text)


def _apply_glossary(text):
    """Tiền xử lý text TRƯỚC khi đưa vào TTS (mọi engine, mọi luồng): khử ký tự
    bẩn OCR → từ điển phát âm → (teencode_var) từ viết tắt chat → (vi_num_var)
    đọc số tiền/ngày/giờ kiểu Việt. KHÔNG ảnh hưởng file SRT, bản dịch hay text
    hiển thị. Từ điển phát âm chạy TRƯỚC teencode để định nghĩa của người dùng
    luôn thắng bảng mặc định."""
    text = _clean_ocr_text(text)
    rx = _GLOSSARY_RX[0]
    if rx is not None and text:
        lmap = _GLOSSARY_LMAP[0]
        text = rx.sub(lambda m: lmap.get(m.group(0).lower(), m.group(0)), text)
    try:
        if text and teencode_var.get():
            text = _teencode_normalize(text)
    except Exception:
        pass
    try:
        if text and vi_num_var.get():
            text = _vi_num_normalize(text)
    except Exception:
        pass                      # chuẩn hóa số lỗi → giữ text gốc, không chặn TTS
    return text

def _glossary_items(items):
    """Bản sao items (payload texts-json cho helper local) với text đã áp từ điển."""
    return [dict(it, text=_apply_glossary(it.get("text") or "")) for it in items]

def _glossary_suggest_terms():
    """Quét SRT/PDF đang nạp tìm từ 'lạ' — token Latin không dấu (tên riêng,
    thuật ngữ, viết tắt mà TTS hay đọc sai) → [(term, count)] xếp theo tần suất.
    Heuristic: từ có chữ HOA / chữ số / ký hiệu (+ . -) là ứng viên ngay;
    từ thường toàn chữ thường phải lặp ≥5 lần (lọc bớt từ tiếng Anh phổ thông)."""
    texts = []
    if subtitles_cache:
        texts.extend(clean_text(s.content) for s in subtitles_cache)
    if PDF_CHUNKS:
        texts.extend(c or "" for c in PDF_CHUNKS)
    if not texts:
        return []
    rx = re.compile(r"[A-Za-z][A-Za-z0-9+.\-]{2,}")
    groups = {}   # lower → {form: count}
    for t in texts:
        for w in rx.findall(t):
            w = w.rstrip(".-")
            if len(w) < 3 or w.isdigit():
                continue
            groups.setdefault(w.lower(), {})
            groups[w.lower()][w] = groups[w.lower()].get(w, 0) + 1
    lmap = _GLOSSARY_LMAP[0]
    out = []
    for low, forms in groups.items():
        if low in lmap:
            continue                      # đã có trong từ điển
        total = sum(forms.values())
        # dạng xuất hiện nhiều nhất làm đại diện
        best = max(forms, key=forms.get)
        notable = (any(ch.isupper() or ch.isdigit() for ch in best)
                   or "+" in best or "." in best or "-" in best)
        if notable or total >= 5:
            out.append((best, total))
    out.sort(key=lambda x: -x[1])
    return out[:30]


def open_glossary_dialog():
    """Cửa sổ soạn từ điển phát âm — mỗi dòng: từ = cách đọc."""
    win = ctk.CTkToplevel(app)
    win.title("📖 Từ điển phát âm")
    win.geometry("600x520")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    ctk.CTkLabel(win, text="Từ điển phát âm — áp dụng cho mọi engine TTS",
                 font=("Arial", 13, "bold")).pack(pady=(10, 2))
    ctk.CTkLabel(win, text="Mỗi dòng một mục:  từ = cách đọc   (ví dụ:  ChatGPT = chát gi pi ti)\n"
                           "Không phân biệt hoa thường, khớp nguyên từ. Dòng bắt đầu bằng # bị bỏ qua.\n"
                           "Chỉ đổi giọng đọc — KHÔNG ảnh hưởng file SRT, bản dịch hay text hiển thị.",
                 font=("Arial", 11), justify="left").pack(pady=(0, 6))

    box = ctk.CTkTextbox(win, wrap="word", font=("Consolas", 13))
    box.pack(fill="both", expand=True, padx=10, pady=4)
    box.insert("1.0", "\n".join(f"{k} = {v}" for k, v in GLOSSARY.items()))
    _attach_telex_input(box, quick_tts_telex_var)

    def _save():
        new = {}
        for line in box.get("1.0", "end").splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            term, sep, repl = line.partition("=")
            term = term.strip()
            repl = repl.split("#", 1)[0].strip()  # bỏ chú thích cuối dòng
            if not sep or not term or not repl:
                continue                          # chưa điền cách đọc → bỏ qua
            new[term] = repl
        GLOSSARY.clear()
        GLOSSARY.update(new)
        _glossary_compile()
        _glossary_save()
        log(f"[Từ điển] ✅ Đã lưu {len(GLOSSARY)} mục phát âm.")
        win.destroy()

    def _suggest():
        sugg = _glossary_suggest_terms()
        if not sugg:
            log("[Từ điển] Không tìm thấy từ lạ — hãy Load SRT/PDF trước rồi quét lại.")
            return
        # bỏ những từ đã có sẵn trong textbox (kể cả dòng người dùng đang soạn dở)
        existing = set()
        for line in box.get("1.0", "end").splitlines():
            term = line.partition("=")[0].strip().lower()
            if term:
                existing.add(term)
        new_terms = [(t, c) for t, c in sugg if t.lower() not in existing]
        if not new_terms:
            log("[Từ điển] Các từ lạ tìm thấy đều đã có trong từ điển.")
            return
        cur = box.get("1.0", "end").strip()
        lines = [f"# ── Gợi ý từ SRT/PDF đang nạp (điền cách đọc, xóa dòng không cần) ──"]
        lines += [f"{t} =        # xuất hiện {c} lần" for t, c in new_terms]
        box.insert("end", ("\n" if cur else "") + "\n".join(lines) + "\n")
        box.see("end")
        log(f"[Từ điển] 🔍 Gợi ý {len(new_terms)} từ — điền cách đọc rồi nhấn Lưu.")

    def _listen():
        """Nghe thử CÁCH ĐỌC của dòng đang đặt con trỏ (provider hiện tại)."""
        line = box.get("insert linestart", "insert lineend").strip()
        if not line or line.startswith("#"):
            log("[Từ điển] Đặt con trỏ vào dòng 'từ = cách đọc' rồi bấm 🔊.")
            return
        term, sep, repl = line.partition("=")
        text = (repl.split("#", 1)[0].strip() if sep else "") or term.strip()
        if not text:
            return
        def _run():
            import tempfile
            # tên theo pattern srt_tts_preview* để được dọn chung với Nghe thử
            tmp = os.path.join(tempfile.gettempdir(),
                               f"srt_tts_preview_g{int(time.time() * 1000)}.mp3")
            try:
                ok = asyncio.run(save_tts(text, tmp))
                if ok and os.path.isfile(tmp):
                    log(f"[Từ điển] 🔊 \"{text}\"")
                    _play_audio_file(tmp)
                else:
                    log("[Từ điển] ❌ Không tạo được audio nghe thử.")
            except Exception as e:
                log(f"[Từ điển] ❌ Nghe thử lỗi: {e}")
        threading.Thread(target=_run, daemon=True).start()

    btn_row = ctk.CTkFrame(win, fg_color="transparent")
    btn_row.pack(fill="x", padx=10, pady=(4, 10))
    ctk.CTkButton(btn_row, text="🔊 Nghe dòng này", command=_listen,
                  height=34, width=120).pack(side="left", padx=(0, 4))
    ctk.CTkButton(btn_row, text="🔍 Gợi ý từ (quét SRT/PDF)", command=_suggest,
                  height=34).pack(side="left", expand=True, fill="x", padx=(0, 4))
    ctk.CTkButton(btn_row, text="💾 Lưu từ điển", command=_save,
                  height=34).pack(side="left", expand=True, fill="x", padx=(0, 4))
    ctk.CTkButton(btn_row, text="Đóng", command=win.destroy, height=34,
                  fg_color="#8a3344", hover_color="#a04055"
                  ).pack(side="left", expand=True, fill="x", padx=(4, 0))

_glossary_load()

