_quick_tts_output_var = ctk.StringVar(value="")

# Token lượt Nghe thử: chỉ lượt MỚI NHẤT được phát — lượt cũ (text dài, gen lâu)
# xong muộn sẽ bị bỏ qua thay vì phát đè lên audio của lượt mới.
_QT_PREVIEW_SEQ = [0]

# Điều khiển Gen Audio (Text → Audio): tiến trình helper đang chạy + cờ dừng
_QT_GEN_PROC = [None]    # subprocess engine đang chạy (để Dừng Gen)
_QT_GEN_STOP = [False]   # cờ yêu cầu dừng tạo audio

# ── Bộ gõ Telex tích hợp ──────────────────────────────────────────────────────
# Unikey/EVKey hook đôi khi không tới được cửa sổ Tk (UIPI/hook bị chặn) → gõ
# "chaof" ra nguyên chữ thay vì "chào". Engine Telex thuần Python dưới đây
# compose ngay trong Entry nên gõ tiếng Việt được bất kể IME ngoài.
quick_tts_telex_var = ctk.BooleanVar(value=True)

_TELEX_TONE_KEYS = {"s": 1, "f": 2, "r": 3, "x": 4, "j": 5}
_TELEX_FAMILIES = {
    "a": "aáàảãạ", "ă": "ăắằẳẵặ", "â": "âấầẩẫậ",
    "e": "eéèẻẽẹ", "ê": "êếềểễệ",
    "i": "iíìỉĩị",
    "o": "oóòỏõọ", "ô": "ôốồổỗộ", "ơ": "ơớờởỡợ",
    "u": "uúùủũụ", "ư": "ưứừửữự",
    "y": "yýỳỷỹỵ",
}
# char → (base_char cùng case, tone_index)
_TELEX_BASE = {}
for _fb, _forms in _TELEX_FAMILIES.items():
    for _ti, _fc in enumerate(_forms):
        _TELEX_BASE[_fc] = (_fb, _ti)
        _TELEX_BASE[_fc.upper()] = (_fb.upper(), _ti)

def _telex_toned(base_char, tone):
    fam = _TELEX_FAMILIES.get(base_char.lower())
    if not fam:
        return base_char
    ch = fam[tone]
    return ch.upper() if base_char.isupper() else ch

def _telex_nucleus(base):
    """Vị trí cụm nguyên âm cuối của từ (đã loại u trong 'qu', i trong 'gi')."""
    run = []
    for i in range(len(base) - 1, -1, -1):
        if base[i] in _TELEX_BASE:
            run.insert(0, i)
        elif run:
            break
    if len(run) > 1:
        first = run[0]
        c0 = base[first].lower()
        if first > 0:
            prev = base[first - 1].lower()
            if (c0 == "u" and prev == "q") or (c0 == "i" and prev == "g"):
                run = run[1:]
    return run

def _telex_apply_tone(base, tone):
    run = _telex_nucleus(base)
    if not run:
        return None
    marked = [i for i in run
              if _TELEX_BASE[base[i]][0].lower() in "ăâêôơư"]
    if marked:
        pos = marked[-1]
    elif len(run) >= 2 and run[-1] == len(base) - 1:
        pos = run[0]          # không có phụ âm cuối → dấu vào nguyên âm đầu cụm
    else:
        pos = run[-1]
    b, old = _TELEX_BASE[base[pos]]
    # gỡ dấu cũ trên cả cụm (1 từ chỉ 1 dấu thanh)
    chars = list(base)
    for i in run:
        bb, tt = _TELEX_BASE[chars[i]]
        if tt:
            chars[i] = _telex_toned(bb, 0)
    if old == tone:
        # gõ lặp dấu → trả chữ gốc + ký tự thường (vd "clas s" kiểu Unikey)
        return "".join(chars), True
    chars[pos] = _telex_toned(b, tone)
    return "".join(chars), False

def _telex_remove_tone(base):
    chars = list(base)
    changed = False
    for i in _telex_nucleus(base):
        b, t = _TELEX_BASE[chars[i]]
        if t:
            chars[i] = _telex_toned(b, 0)
            changed = True
    return "".join(chars) if changed else None

def _telex_apply_w(base):
    if not base or base[-1] not in _TELEX_BASE:
        return None
    b, t = _TELEX_BASE[base[-1]]
    m = {"a": "ă", "o": "ơ", "u": "ư"}
    bl = b.lower()
    if bl not in m:
        return None
    nb = m[bl].upper() if b.isupper() else m[bl]
    out = base[:-1] + _telex_toned(nb, t)
    # uo + w → ươ
    if bl == "o" and len(base) >= 2 and base[-2] in _TELEX_BASE:
        b2, t2 = _TELEX_BASE[base[-2]]
        if b2.lower() == "u":
            nu = "Ư" if b2.isupper() else "ư"
            out = base[:-2] + _telex_toned(nu, t2) + _telex_toned(nb, t)
    return out

def _telex_apply_double(base, cl):
    if not base or base[-1] not in _TELEX_BASE:
        return None
    b, t = _TELEX_BASE[base[-1]]
    circ = {"a": "â", "e": "ê", "o": "ô"}[cl]
    bl = b.lower()
    if bl == cl:
        nb = circ.upper() if b.isupper() else circ
        return base[:-1] + _telex_toned(nb, t)
    if bl == circ:
        # ââ → revert "aa" + chữ vừa gõ (gõ 3 lần ra chữ đôi thường)
        plain = cl.upper() if b.isupper() else cl
        return base[:-1] + _telex_toned(plain, t) + plain
    return None

def _telex_transform(word):
    """Nhận từ (ký tự vừa gõ nằm cuối) → từ đã compose; trả lại nguyên nếu không đổi."""
    if len(word) < 2:
        return word
    base, c = word[:-1], word[-1]
    cl = c.lower()
    if cl in _TELEX_TONE_KEYS:
        out = _telex_apply_tone(base, _TELEX_TONE_KEYS[cl])
        if out is None:
            return word
        body, literal = out
        return body + c if literal else body
    if cl == "z":
        out = _telex_remove_tone(base)
        return out if out is not None else word
    if cl == "w":
        out = _telex_apply_w(base)
        return out if out is not None else word
    if cl in ("a", "e", "o"):
        out = _telex_apply_double(base, cl)
        return out if out is not None else word
    if cl == "d" and base and base[-1] in "dD":
        return base[:-1] + ("Đ" if base[-1] == "D" else "đ")
    return word

def _attach_telex_input(ctk_widget, enabled_var):
    """Gắn bộ gõ Telex vào CTkEntry hoặc CTkTextbox (compose từ ngay trước con trỏ)."""
    tk_w = getattr(ctk_widget, "_entry", None) or getattr(ctk_widget, "_textbox", None) or ctk_widget
    is_text = hasattr(tk_w, "mark_set")  # tk.Text (CTkTextbox) vs tk.Entry

    def _on_key(event):
        if not enabled_var.get():
            return
        ch = event.char
        if not ch or len(ch) != 1 or not ch.isalpha():
            return
        if event.state & 0x4:  # Ctrl đang giữ (vd Ctrl+V)
            return
        try:
            if is_text:
                _line, _c = tk_w.index("insert").split(".")
                pos = int(_c)
                s = tk_w.get(f"{_line}.0", f"{_line}.end")
            else:
                pos = tk_w.index("insert")
                s = tk_w.get()
        except Exception:
            return
        start = pos
        while start > 0 and s[start - 1].isalpha():
            start -= 1
        word = s[start:pos]
        new = _telex_transform(word)
        if new != word:
            if is_text:
                tk_w.delete(f"{_line}.{start}", f"{_line}.{pos}")
                tk_w.insert(f"{_line}.{start}", new)
                tk_w.mark_set("insert", f"{_line}.{start + len(new)}")
            else:
                tk_w.delete(start, pos)
                tk_w.insert(start, new)
                tk_w.icursor(start + len(new))

    tk_w.bind("<KeyRelease>", _on_key, add="+")

def _quick_tts_choose_output():
    path = filedialog.asksaveasfilename(
        title="Chọn file audio output",
        defaultextension=".mp3",
        filetypes=[("MP3", "*.mp3"), ("All files", "*.*")],
        initialfile="quick_tts_output.mp3",
    )
    if path:
        _quick_tts_output_var.set(path)
        log(f"[Quick TTS] Output: {path}")

def _quick_tts_open_output():
    """Mở thư mục chứa file output (hoặc OUTPUT_DIR nếu chưa chọn)."""
    out = _quick_tts_output_var.get().strip()
    try:
        folder = os.path.dirname(os.path.abspath(out)) if out else OUTPUT_DIR
        if not folder or not os.path.isdir(folder):
            folder = OUTPUT_DIR
        os.startfile(folder)
        log(f"[Quick TTS] Mở thư mục: {folder}")
    except Exception as e:
        log(f"[Quick TTS] Không mở được thư mục output: {e}")

# (nut Output -> workspace "Text -> Audio")

# MCI mpegvideo là thread-affine: device gắn với thread đã `open` nó — nếu
# thread đó thoát (mỗi lượt Nghe thử là 1 worker thread chết ngay sau `play`),
# lệnh `close` từ thread khác âm thầm thất bại → audio cũ KHÔNG dừng được và
# phát đè lên audio mới (+ file bị giữ → Errno 13). Fix: MỘT thread audio
# thường trực sở hữu mọi lệnh MCI của Nghe thử (giống _audio_loop của Edit Studio).
_QT_AUDIO_Q = [None]

def _qt_audio_send(*cmd):
    if _QT_AUDIO_Q[0] is None:
        import queue as _queue
        _QT_AUDIO_Q[0] = _queue.Queue()

        def _worker():
            import ctypes
            winmm = ctypes.windll.winmm

            def _mci(c):
                return winmm.mciSendStringW(c, None, 0, None)

            while True:
                c = _QT_AUDIO_Q[0].get()
                try:
                    if c[0] == "play":
                        _mci('close qt_preview')
                        _mci(f'open "{c[1]}" type mpegvideo alias qt_preview')
                        _mci('play qt_preview')
                    elif c[0] == "stop":
                        _mci('close qt_preview')
                    elif c[0] == "pause":
                        _mci('pause qt_preview')
                    elif c[0] == "resume":
                        # resume từ vị trí đã tạm dừng (play cũng tiếp tục được)
                        _mci('resume qt_preview')
                except Exception as e:
                    log(f"[Nghe thử] ❌ Không phát được audio: {e}")

        threading.Thread(target=_worker, daemon=True).start()
    _QT_AUDIO_Q[0].put(cmd)

def _qt_preview_close():
    """Dừng audio Nghe thử + nhả file đang bị MCI giữ."""
    _qt_audio_send("stop")

def _quick_tts_stop_preview():
    """Nút ⏹ Dừng nghe: dừng audio đang phát + hủy cả lượt Nghe thử đang gen dở."""
    _QT_PREVIEW_SEQ[0] += 1  # lượt đang gen (nếu có) thành stale → sẽ không phát
    _qt_preview_close()
    log("[Nghe thử] ⏹ Đã dừng phát")

def _quick_tts_pause_preview():
    """Nút ⏸ Tạm dừng nghe: tạm dừng audio Nghe thử đang phát."""
    _qt_audio_send("pause")
    log("[Nghe thử] ⏸ Tạm dừng phát")

def _quick_tts_resume_preview():
    """Nút ▶ Tiếp tục nghe: phát tiếp audio đã tạm dừng."""
    _qt_audio_send("resume")
    log("[Nghe thử] ▶ Tiếp tục phát")

class _QTGenStopped(Exception):
    """Người dùng bấm 'Dừng Gen' trong khi engine đang chạy."""
    pass

def _qt_run_proc(cmd):
    """Chạy 1 subprocess engine cho Gen Audio, lưu lại để có thể Dừng giữa chừng.
    Trả về object có .returncode / .stdout / .stderr (giống subprocess.run).
    Nếu bị Dừng giữa chừng → raise _QTGenStopped để thoát sạch khỏi luồng gen."""
    proc = subprocess.Popen(
        cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        text=True, encoding="utf-8", errors="replace",
        creationflags=CREATE_NO_WINDOW,
    )
    _QT_GEN_PROC[0] = proc
    try:
        out, err = proc.communicate()
    finally:
        _QT_GEN_PROC[0] = None
    if _QT_GEN_STOP[0]:
        raise _QTGenStopped()
    class _R:
        pass
    r = _R()
    r.returncode = proc.returncode
    r.stdout = out or ""
    r.stderr = err or ""
    return r

def _quick_tts_stop_gen():
    """Nút ⏹ Dừng Gen: dừng tiến trình tạo audio đang chạy (local engine)."""
    _QT_GEN_STOP[0] = True
    p = _QT_GEN_PROC[0]
    if p is not None:
        _proc_tree_action(p, "kill")
    log("[Quick TTS] ⏹ Đã yêu cầu dừng tạo audio")

def _play_audio_file(path):
    """Phát 1 file audio (mp3/wav) ngay trong app qua MCI — dùng cho Nghe thử."""
    _qt_audio_send("play", path)


# ── 🎙 Thu âm giọng mẫu ngay trong app (ffmpeg dshow) ────────────────────────
# Voice clone cần ref audio — khỏi phải thu bằng app ngoài rồi Browse. Ghi PCM
# THÔ (headerless → kill-safe, bấm Dừng sớm file vẫn dùng được) rồi bọc WAV
# bằng một lượt ffmpeg thứ hai. File lưu ở <_CONFIG_DIR>\recordings\.
# Nút 🎙 cạnh ô Audio mẫu của cả 4 engine (lambda late-binding).

def _list_dshow_audio_devices(ffmpeg):
    """Tên các thiết bị thu âm dshow ('Microphone (…)', 'Stereo Mix (…)')."""
    try:
        r = subprocess.run(
            [ffmpeg, "-hide_banner", "-list_devices", "true",
             "-f", "dshow", "-i", "dummy"],
            capture_output=True, text=True, encoding="utf-8",
            errors="replace", timeout=20, creationflags=CREATE_NO_WINDOW)
        out = (r.stderr or "") + (r.stdout or "")
        return re.findall(r'"([^"]+)"\s+\(audio\)', out)
    except Exception:
        return []


def open_record_dialog(target_var):
    """🎙 Dialog thu âm mic → WAV mono 44.1kHz → điền vào ô Audio mẫu."""
    ffmpeg_ok, ffmpeg_path, guide = _check_ffmpeg_exists()
    if not ffmpeg_ok:
        for line in guide.splitlines():
            log(line)
        return
    devs = _list_dshow_audio_devices(ffmpeg_path)
    if not devs:
        msg.showerror("Thu âm", "Không tìm thấy thiết bị thu âm nào (dshow). "
                                "Kiểm tra micro đã cắm/bật chưa.")
        return

    win = ctk.CTkToplevel(app)
    win.title("🎙 Thu âm giọng mẫu")
    win.geometry("560x270")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    ctk.CTkLabel(win, text="Đọc một đoạn 10–20 giây, giọng tự nhiên, phòng yên tĩnh.\n"
                           "(Có thể chạy tiếp 'Lọc audio mẫu' sau khi thu để khử ồn.)",
                 font=("Arial", 12), justify="left").pack(pady=(12, 6))

    row1 = ctk.CTkFrame(win, fg_color="transparent")
    row1.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row1, text="Micro:", font=("Arial", 12), width=80,
                 anchor="w").pack(side="left")
    _mic_guess = next((d for d in devs if "micro" in d.lower()), devs[0])
    v_dev = ctk.StringVar(value=_mic_guess)
    ctk.CTkOptionMenu(row1, variable=v_dev, values=devs, width=340).pack(side="left")

    row2 = ctk.CTkFrame(win, fg_color="transparent")
    row2.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row2, text="Thời lượng:", font=("Arial", 12), width=80,
                 anchor="w").pack(side="left")
    v_dur = ctk.StringVar(value="15")
    ctk.CTkEntry(row2, textvariable=v_dur, width=60,
                 justify="center").pack(side="left")
    ctk.CTkLabel(row2, text="giây (3–120; ⏹ dừng sớm vẫn giữ phần đã thu)",
                 font=("Arial", 11), text_color="#888").pack(side="left", padx=8)

    status = ctk.CTkLabel(win, text="Sẵn sàng.", font=("Arial", 13, "bold"))
    status.pack(pady=(8, 2))

    state = {"proc": None, "pcm": "", "wav": "", "running": False, "left": 0}

    row3 = ctk.CTkFrame(win, fg_color="transparent")
    row3.pack(fill="x", padx=14, pady=(6, 10))
    b_rec = ctk.CTkButton(row3, text="🔴 Thu", fg_color="#a33c3c",
                          hover_color="#c04848", height=36)
    b_rec.pack(side="left", expand=True, fill="x", padx=4)
    b_stop = ctk.CTkButton(row3, text="⏹ Dừng", state="disabled", height=36)
    b_stop.pack(side="left", expand=True, fill="x", padx=4)
    b_play = ctk.CTkButton(row3, text="▶ Nghe lại", state="disabled", height=36,
                           command=lambda: state["wav"] and _play_audio_file(state["wav"]))
    b_play.pack(side="left", expand=True, fill="x", padx=4)

    def _tick():
        if not state["running"] or not win.winfo_exists():
            return
        state["left"] -= 1
        if state["left"] > 0:
            status.configure(text=f"🔴 Đang thu… còn {state['left']}s")
            win.after(1000, _tick)

    def _finish():
        state["running"] = False
        proc = state["proc"]
        state["proc"] = None
        pcm, wav = state["pcm"], state["wav"]
        ok = False
        try:
            if os.path.isfile(pcm) and os.path.getsize(pcm) > 44100:  # ≥ ~0.5s
                r = subprocess.run(
                    [ffmpeg_path, "-y", "-v", "quiet", "-f", "s16le",
                     "-ar", "44100", "-ac", "1", "-i", pcm, wav],
                    capture_output=True, timeout=120,
                    creationflags=CREATE_NO_WINDOW)
                ok = r.returncode == 0 and os.path.isfile(wav)
            try:
                os.remove(pcm)
            except Exception:
                pass
        except Exception:
            ok = False
        if not win.winfo_exists():
            return
        if ok:
            dur_s = os.path.getsize(wav) / (44100 * 2)
            target_var.set(wav)
            log(f"🎙 Đã thu {dur_s:.1f}s → {os.path.basename(wav)} (đã điền vào ô Audio mẫu)")
            status.configure(text=f"✅ Đã thu {dur_s:.1f}s — đã điền vào ô Audio mẫu.")
            b_play.configure(state="normal")
        else:
            status.configure(text="❌ Thu thất bại / quá ngắn — thử lại (kiểm tra micro).")
        b_rec.configure(state="normal")
        b_stop.configure(state="disabled")

    def _start():
        if state["running"]:
            return
        try:
            dur = max(3, min(int(float(v_dur.get().strip() or "15")), 120))
        except Exception:
            dur = 15
        rec_dir = os.path.join(_CONFIG_DIR, "recordings")
        try:
            os.makedirs(rec_dir, exist_ok=True)
        except Exception as e:
            status.configure(text=f"❌ Không tạo được thư mục lưu: {e}")
            return
        base = time.strftime("ref_%Y%m%d_%H%M%S")
        state["pcm"] = os.path.join(rec_dir, base + ".pcm")
        state["wav"] = os.path.join(rec_dir, base + ".wav")
        try:
            proc = subprocess.Popen(
                [ffmpeg_path, "-y", "-v", "error", "-f", "dshow",
                 "-i", f"audio={v_dev.get()}", "-t", str(dur),
                 "-ac", "1", "-ar", "44100", "-f", "s16le", state["pcm"]],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                creationflags=CREATE_NO_WINDOW)
        except Exception as e:
            status.configure(text=f"❌ Không chạy được ffmpeg: {e}")
            return
        state["proc"] = proc
        state["running"] = True
        state["left"] = dur + 1
        b_rec.configure(state="disabled")
        b_stop.configure(state="normal")
        b_play.configure(state="disabled")
        _tick()

        def _waiter():
            proc.wait()
            app.after(0, _finish)
        threading.Thread(target=_waiter, daemon=True).start()

    def _stop():
        p = state["proc"]
        if p:
            try:
                p.kill()   # PCM thô headerless → phần đã ghi vẫn dùng được
            except Exception:
                pass

    b_rec.configure(command=_start)
    b_stop.configure(command=_stop)

    def _on_close():
        _stop()
        win.destroy()
    win.protocol("WM_DELETE_WINDOW", _on_close)

def _quick_tts_run(preview=False):
    """preview=True → sinh ra file tạm và phát ngay (Nghe thử), không hỏi nơi lưu."""
    text = quick_tts_textbox.get("1.0", "end").strip()
    if not text:
        msg.showwarning("Quick TTS", "Vui lòng nhập text trước khi tạo audio.")
        return
    if preview:
        import tempfile, glob
        _qt_preview_close()  # dừng + nhả file preview cũ đang bị MCI giữ
        _QT_PREVIEW_SEQ[0] += 1
        _my_seq = _QT_PREVIEW_SEQ[0]
        _tmpdir = tempfile.gettempdir()
        # dọn các preview cũ (file đang bị giữ thì bỏ qua)
        for _old in glob.glob(os.path.join(_tmpdir, "srt_tts_preview*.mp3")):
            try:
                os.remove(_old)
            except OSError:
                pass
        # mỗi lượt một file riêng → lượt cũ đang gen dở không ghi đè lượt mới
        out = os.path.join(_tmpdir, f"srt_tts_preview_{_my_seq}.mp3")
    else:
        _my_seq = None
        out = _quick_tts_output_var.get().strip()
    if not out:
        out = filedialog.asksaveasfilename(
            title="Chọn file audio output",
            defaultextension=".mp3",
            filetypes=[("MP3", "*.mp3"), ("All files", "*.*")],
            initialfile="quick_tts_output.mp3",
        )
        if not out:
            return
        _quick_tts_output_var.set(out)

    def _run():
        _QT_GEN_STOP[0] = False   # mỗi lượt gen mới → xóa cờ dừng cũ
        # ── Pre-flight kiểm tra trước khi chạy ──────────────────────────────
        if VOXCPM_ENABLED:
            _qt_ckpt = voxcpm_ckpt_var.get().strip()
            if not _qt_ckpt:
                log("[Quick TTS] ❌ VoxCPM Clone: Chưa nhập đường dẫn thư mục Model")
                log("  • Nhấn Browse ở ô Model để chọn thư mục chứa model VoxCPM")
                return
            if not os.path.isdir(_qt_ckpt):
                log(f"[Quick TTS] ❌ VoxCPM Clone: Không tìm thấy thư mục Model: {_qt_ckpt}")
                log("  • Kiểm tra lại đường dẫn — thư mục có thể đã bị di chuyển")
                return
            _qt_ref = voxcpm_ref_var.get().strip()
            if _qt_ref and not os.path.isfile(_qt_ref):
                log(f"[Quick TTS] ❌ VoxCPM Clone: Không tìm thấy file Audio mẫu: {_qt_ref}")
                log("  • Browse lại để chọn đúng file, hoặc để trống nếu không dùng")
                return
        elif VIENEU_ENABLED:
            _qt_model = vieneu_model_var.get().strip()
            if _qt_model and not os.path.isdir(_qt_model):
                log(f"[Quick TTS] ❌ VieNeu-TTS: Đường dẫn Model không tồn tại: {_qt_model}")
                log("  • Để trống ô Model để tự tải, hoặc Browse lại thư mục đúng")
                return
            _qt_ref = vieneu_ref_var.get().strip()
            if _qt_ref and not os.path.isfile(_qt_ref):
                log(f"[Quick TTS] ❌ VieNeu-TTS: Không tìm thấy file Audio mẫu: {_qt_ref}")
                log("  • Browse lại để chọn đúng file, hoặc để trống nếu dùng giọng có sẵn")
                return
        elif F5TTS_ENABLED:
            _qt_model = f5tts_model_var.get().strip()
            if not _qt_model or not os.path.isdir(_qt_model):
                log(f"[Quick TTS] ❌ F5-TTS: Thư mục Model trống/không tồn tại: {_qt_model}")
                log("  • Browse ô Model để chọn thư mục chứa model_last.pt + vocab.txt")
                return
            _qt_ref = f5tts_ref_var.get().strip()
            if not _qt_ref or not os.path.isfile(_qt_ref):
                log(f"[Quick TTS] ❌ F5-TTS: Chưa chọn/không tìm thấy file Audio mẫu: {_qt_ref}")
                log("  • F5-TTS bắt buộc cần audio mẫu để nhân bản giọng")
                return
        elif OMNIVOICE_ENABLED:
            _qt_model = omnivoice_model_var.get().strip()
            if _qt_model and not os.path.isdir(_qt_model):
                log(f"[Quick TTS] ❌ OmniVoice: Đường dẫn Model không tồn tại: {_qt_model}")
                log("  • Để trống ô Model để tự tải, hoặc Browse lại thư mục đúng")
                return
            _qt_ref = omnivoice_ref_var.get().strip()
            if not _qt_ref or not os.path.isfile(_qt_ref):
                log(f"[Quick TTS] ❌ OmniVoice: Chưa chọn/không tìm thấy file Audio mẫu: {_qt_ref}")
                log("  • OmniVoice bắt buộc cần audio mẫu để nhân bản giọng")
                return
        elif RVC_ENABLED:
            if not _check_rvc_preflight():
                return

        # VoxCPM / VieNeu / F5-TTS / OmniVoice chạy local; còn lại cần internet
        if (not VOXCPM_ENABLED and not VIENEU_ENABLED and not F5TTS_ENABLED
                and not OMNIVOICE_ENABLED and not _require_internet("Quick TTS")):
            return
        log("[Quick TTS] Đang tạo audio...")
        update_progress(5, 100)
        try:
            if VOXCPM_ENABLED:
                # VoxCPM: gọi helper subprocess cho 1 dòng text
                import json as _json
                ckpt_dir = voxcpm_ckpt_var.get().strip()
                voxcpm_py = _find_voxcpm_python(ckpt_dir) if ckpt_dir else None
                if not voxcpm_py:
                    log("[Quick TTS] ❌ Không tìm thấy VoxCPM python. Kiểm tra Model dir.")
                    return
                helper = None
                for _d in [
                    getattr(sys, "_MEIPASS", None),
                    os.path.dirname(__file__),
                    os.path.dirname(sys.argv[0]),
                    os.path.dirname(sys.executable),
                ]:
                    if _d and os.path.isfile(os.path.join(_d, "voxcpm_helper.py")):
                        helper = os.path.join(_d, "voxcpm_helper.py")
                        break
                if not helper:
                    log("[Quick TTS] ❌ Không tìm thấy voxcpm_helper.py.")
                    return
                out_dir  = os.path.dirname(os.path.abspath(out))
                tmp_json = os.path.join(out_dir, "_quick_tts_texts.json")
                with open(tmp_json, "w", encoding="utf-8") as f:
                    _json.dump([{"index": 0, "text": _apply_glossary(text)}], f, ensure_ascii=False)
                ref_audio = voxcpm_ref_var.get().strip() or None
                ref_text  = voxcpm_reftext_var.get().strip() or None
                cmd = [
                    voxcpm_py, helper,
                    "--texts-json", tmp_json,
                    "--output-dir", out_dir,
                    "--ckpt-dir",   ckpt_dir,
                    "--timesteps",  voxcpm_steps_var.get(),
                    "--cfg-value",  voxcpm_cfg_var.get(),
                ]
                if ref_audio: cmd += ["--reference",      ref_audio]
                if ref_text:  cmd += ["--reference-text", ref_text]
                proc = _qt_run_proc(cmd)
                gen_wav = os.path.join(out_dir, "line_0000.wav")
                if not os.path.isfile(gen_wav):
                    log(f"[Quick TTS] ❌ VoxCPM không tạo được file. stderr: {proc.stderr[-300:]}")
                    return
                update_progress(70, 100)
                ffmpeg = get_ffmpeg()
                subprocess.run(
                    [ffmpeg, "-y", "-i", gen_wav, "-q:a", "2", out],
                    creationflags=CREATE_NO_WINDOW, capture_output=True,
                )
                if os.path.isfile(gen_wav): os.remove(gen_wav)
                if os.path.isfile(tmp_json): os.remove(tmp_json)
            elif VIENEU_ENABLED:
                # VieNeu: gọi helper subprocess cho 1 dòng text
                import json as _json
                _ok, _model_dir, _vieneu_py, _helper = _vieneu_preflight()
                if not _ok:
                    return
                out_dir  = os.path.dirname(os.path.abspath(out))
                tmp_json = os.path.join(out_dir, "_quick_tts_vieneu.json")
                with open(tmp_json, "w", encoding="utf-8") as f:
                    _json.dump([{"index": 0, "text": _apply_glossary(text)}], f, ensure_ascii=False)
                cmd = _vieneu_build_cmd(_vieneu_py, _helper, tmp_json, out_dir, _model_dir)
                proc = _qt_run_proc(cmd)
                gen_wav = os.path.join(out_dir, "line_0000.wav")
                if not os.path.isfile(gen_wav):
                    log(f"[Quick TTS] ❌ VieNeu không tạo được file. stderr: {proc.stderr[-300:]}")
                    if os.path.isfile(tmp_json): os.remove(tmp_json)
                    return
                update_progress(70, 100)
                ffmpeg = get_ffmpeg()
                subprocess.run(
                    [ffmpeg, "-y", "-i", gen_wav, "-q:a", "2", out],
                    creationflags=CREATE_NO_WINDOW, capture_output=True,
                )
                if os.path.isfile(gen_wav): os.remove(gen_wav)
                if os.path.isfile(tmp_json): os.remove(tmp_json)
            elif F5TTS_ENABLED:
                # F5-TTS: gọi helper subprocess cho 1 dòng text
                import json as _json
                _ok, _model_dir, _f5tts_py, _helper = _f5tts_preflight()
                if not _ok:
                    return
                out_dir  = os.path.dirname(os.path.abspath(out))
                tmp_json = os.path.join(out_dir, "_quick_tts_f5tts.json")
                with open(tmp_json, "w", encoding="utf-8") as f:
                    _json.dump([{"index": 0, "text": _apply_glossary(text)}], f, ensure_ascii=False)
                cmd = _f5tts_build_cmd(_f5tts_py, _helper, tmp_json, out_dir, _model_dir)
                proc = _qt_run_proc(cmd)
                gen_wav = os.path.join(out_dir, "line_0000.wav")
                if not os.path.isfile(gen_wav):
                    log(f"[Quick TTS] ❌ F5-TTS không tạo được file. stderr: {proc.stderr[-300:]}")
                    if os.path.isfile(tmp_json): os.remove(tmp_json)
                    return
                update_progress(70, 100)
                ffmpeg = get_ffmpeg()
                subprocess.run(
                    [ffmpeg, "-y", "-i", gen_wav, "-q:a", "2", out],
                    creationflags=CREATE_NO_WINDOW, capture_output=True,
                )
                if os.path.isfile(gen_wav): os.remove(gen_wav)
                if os.path.isfile(tmp_json): os.remove(tmp_json)
            elif OMNIVOICE_ENABLED:
                # OmniVoice: gọi helper subprocess cho 1 dòng text
                import json as _json
                _ok, _model_dir, _omni_py, _helper = _omnivoice_preflight()
                if not _ok:
                    return
                out_dir  = os.path.dirname(os.path.abspath(out))
                tmp_json = os.path.join(out_dir, "_quick_tts_omnivoice.json")
                with open(tmp_json, "w", encoding="utf-8") as f:
                    _json.dump([{"index": 0, "text": _apply_glossary(text)}], f, ensure_ascii=False)
                cmd = _omnivoice_build_cmd(_omni_py, _helper, tmp_json, out_dir, _model_dir)
                proc = _qt_run_proc(cmd)
                gen_wav = os.path.join(out_dir, "line_0000.wav")
                if not os.path.isfile(gen_wav):
                    log(f"[Quick TTS] ❌ OmniVoice không tạo được file. stderr: {proc.stderr[-300:]}")
                    if os.path.isfile(tmp_json): os.remove(tmp_json)
                    return
                update_progress(70, 100)
                ffmpeg = get_ffmpeg()
                subprocess.run(
                    [ffmpeg, "-y", "-i", gen_wav, "-q:a", "2", out],
                    creationflags=CREATE_NO_WINDOW, capture_output=True,
                )
                if os.path.isfile(gen_wav): os.remove(gen_wav)
                if os.path.isfile(tmp_json): os.remove(tmp_json)
            else:
                asyncio.run(save_tts(text, out))
                update_progress(60, 100)
                if RVC_ENABLED:
                    log("[Quick TTS] Đang áp dụng RVC...")
                    try:
                        _apply_rvc_sync(out)
                        update_progress(95, 100)
                    except Exception as _rvc_err:
                        log(f"[Quick TTS] ❌ RVC thất bại: {_rvc_err}")
                        log("━━━ Hướng xử lý RVC ━━━")
                        log("  • Kiểm tra file model (.pth) có đúng đường dẫn không")
                        log("  • Đảm bảo rvc_env\\Scripts\\python.exe tồn tại")
                        log("  • Thử đổi Algo sang rmvpe hoặc harvest")
                        log("  • Thử chuyển Device sang CPU")
                        log("  • Xem thêm log chi tiết bên trên để biết nguyên nhân cụ thể")
                        return
            if _QT_GEN_STOP[0]:
                # provider (edge_tts) không qua subprocess kill được → chặn tại đây
                log("[Quick TTS] ⏹ Đã dừng tạo audio.")
                try:
                    if not preview and out and os.path.isfile(out):
                        os.remove(out)
                except Exception:
                    pass
                return
            log(f"[Quick TTS] ✅ Hoàn tất: {os.path.basename(out)}")
            update_progress(100, 100)
            if preview:
                if _my_seq != _QT_PREVIEW_SEQ[0]:
                    # đã có lượt Nghe thử mới hơn → bỏ qua, không phát đè
                    log("[Nghe thử] ⏭ Bỏ qua audio cũ (đã bấm Nghe thử mới)")
                    return
                if os.path.isfile(out):
                    log("[Nghe thử] ▶ Đang phát audio thử...")
                    _play_audio_file(out)
            else:
                app.after(0, show_fireworks)
                if os.path.isfile(out):
                    subprocess.Popen(["explorer", "/select,", os.path.abspath(out)])
        except _QTGenStopped:
            log("[Quick TTS] ⏹ Đã dừng tạo audio.")
            try:
                if not preview and out and os.path.isfile(out):
                    os.remove(out)
            except Exception:
                pass
        except Exception as e:
            log(f"[Quick TTS] ❌ Lỗi: {e}")

    threading.Thread(target=_run, daemon=True).start()

