# =====================================================================
# TẢI TRUYỆN (Webtoon) — trang "manga". Tải ảnh truyện về máy đọc offline,
# theo HỆ SITE-ADAPTER: truyenqq có adapter riêng (class="chapter-name",
# data-src, dò bù 100 chương); trang lạ dùng _MANGA_GENERIC (best-effort,
# tự thử data-src/data-original/.../src). Tách rời set_mode (như nút Dịch),
# tự khoá bằng cờ. Chỉ tải để đọc cá nhân — truyện có bản quyền của nhóm dịch.
# =====================================================================
_MANGA_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
             "(KHTML, like Gecko) Chrome/120.0 Safari/537.36")
_MANGA_RUNNING = [False]
_MANGA_STOP = [False]
_MANGA_PROC = [None]   # tiến trình gallery-dl đang chạy (để dừng được)
_MANGA_TR_RUNNING = [False]   # job DỊCH truyện đang chạy
_MANGA_TR_PROC = [None]       # tiến trình manga_ocr_helper đang chạy


class _MangaNoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *a, **k):
        return None   # không tự đi theo redirect → 302 = chương không tồn tại


_MANGA_NOREDIR = urllib.request.build_opener(_MangaNoRedirect)


def _manga_base(url):
    sp = urllib.parse.urlsplit(url)
    return f"{sp.scheme}://{sp.netloc}"


def _manga_safe_name(s):
    return re.sub(r'[<>:"/\\|?*]', "_", s).strip().strip(".") or "untitled"


def _manga_http(url, referer, binary=False, timeout=40, retries=3):
    """Tải 1 URL, thử lại khi gặp lỗi mạng tạm thời (host đóng kết nối:
    WinError 10054 / 'Remote end closed connection' / reset). Backoff tăng dần
    để tránh bị chặn do gọi quá nhanh."""
    last = None
    for attempt in range(max(1, retries)):
        if _MANGA_STOP[0]:
            raise RuntimeError("stopped")
        try:
            req = urllib.request.Request(
                url, headers={"User-Agent": _MANGA_UA, "Referer": referer})
            with urllib.request.urlopen(req, timeout=timeout) as r:
                data = r.read()
            return data if binary else data.decode("utf-8", "replace")
        except Exception as e:
            last = e
            if attempt < retries - 1:
                time.sleep(1.5 * (attempt + 1))   # 1.5s, 3s, 4.5s...
    raise last


def _manga_chapter_exists(url, referer):
    try:
        req = urllib.request.Request(
            url, headers={"User-Agent": _MANGA_UA, "Referer": referer})
        with _MANGA_NOREDIR.open(req, timeout=20) as r:
            return getattr(r, "status", r.getcode()) == 200
    except Exception:
        return False


def _manga_chap_key(num_str):
    """'120-4' -> (120,4); '28' -> (28,0). Sắp đúng thứ tự chương."""
    nums = [int(p) for p in re.split(r"[-.]", num_str) if p.isdigit()]
    return tuple(nums) if nums else (10 ** 9,)


# --- Site adapters: mỗi trang 1 cấu hình; trang lạ dùng GENERIC (best-effort).
# Thêm trang mới = copy 1 block trong _MANGA_ADAPTERS, sửa "match" + 2 regex.
_MANGA_GENERIC = {
    "name": "generic",
    "match": [],
    "chapter_link_re": r'<a[^>]+href="([^"]*(?:chap|chuong)[^"]*)"[^>]*>(.*?)</a>',
    "image_res": [
        r'<img[^>]+data-src="([^"]+)"',
        r'<img[^>]+data-original="([^"]+)"',
        r'<img[^>]+data-lazy-src="([^"]+)"',
        r'<img[^>]+data-aload="([^"]+)"',
        r'<img[^>]+src="([^"]+\.(?:jpg|jpeg|png|webp)[^"]*)"',
    ],
    "backfill": False,
}
_MANGA_ADAPTERS = [
    {
        "name": "truyenqq",
        "match": ["truyenqq"],
        "chapter_link_re":
            r'<a\s+href="([^"]+)"\s+class="chapter-name[^"]*"[^>]*>(.*?)</a>',
        "image_res": [r'<img[^>]+data-(?:src|original)="([^"]+)"'],
        "backfill": True,
        "chap_url": lambda base, i: f"{base}/chapter-{i}",
    },
    {
        # hentaivnx.com / .live — render TĨNH, không bị Cloudflare chặn UA.
        # Danh sách chương ở trang truyện (.../<slug>-<id>): mỗi chương là
        #   <a href=".../chapter-N/<id-số>" data-id="..">Chapter N</a>.
        # URL chương có ID số KHÔNG đoán được → backfill=False (lấy đủ từ list).
        # Ảnh nằm sẵn ở src trên CDN 2tcdn.cfd; regex 2 là dự phòng nếu đổi CDN
        # (bắt mọi src là file đánh số /N.jpg — kiểu của trang đọc truyện).
        # Lưu ý: trang truyện dùng nháy kép cho href, nhưng trang đọc chương
        # có khi dùng nháy ĐƠN cho thẻ <img src='...'> → regex chấp nhận cả hai.
        "name": "hentaivnx",
        "match": ["hentaivnx"],
        "chapter_link_re":
            r'''<a\s+href=["']([^"']+/chapter-[^"']+)["']\s+data-id=["']\d+["'][^>]*>(.*?)</a>''',
        "image_res": [
            r'''<img[^>]+src=["'](https?://[^"']*2tcdn\.cfd[^"']+\.(?:jpg|jpeg|png|webp)[^"']*)["']''',
            r'''<img[^>]+src=["']([^"']+/\d+\.(?:jpg|jpeg|png|webp)[^"']*)["']''',
        ],
        "backfill": False,
    },
]
_MANGA_IMG_JUNK = ("placeholder", "loading", "logo", "banner", "avatar",
                   "/ads", "nocover", "blank", "/icon")


def _manga_get_adapter(url):
    host = urllib.parse.urlsplit(url).netloc.lower()
    for a in _MANGA_ADAPTERS:
        if any(m in host for m in a["match"]):
            return a
    return _MANGA_GENERIC


def _manga_is_content_img(u):
    ul = u.lower()
    if any(j in ul for j in _MANGA_IMG_JUNK):
        return False
    return ul.split("?")[0].endswith((".jpg", ".jpeg", ".png", ".webp"))


def _manga_extract_images(html, adapter):
    """Thử từng regex ảnh của adapter, chọn list nhiều ảnh hợp lệ nhất."""
    best = []
    for rgx in adapter["image_res"]:
        urls = [u.strip() for u in re.findall(rgx, html, flags=re.I)]
        urls = [u for u in urls if _manga_is_content_img(u)]
        if len(urls) > len(best):
            best = urls
    return best


def _manga_extract_chap_num(href):
    for pat in (r"chapter-([\d.\-]+)", r"chuong-([\d.\-]+)", r"chap[-_]?([\d.\-]+)"):
        m = re.search(pat, href, flags=re.I)
        if m:
            return m.group(1)
    m = re.search(r"(\d+(?:[.\-]\d+)*)\D*$", href)
    return m.group(1) if m else href


def _manga_list_chapters(series_url, log_cb):
    """[(tên, url)] từ chương 1 → mới nhất (qua adapter theo tên miền). Với trang
    giới hạn chương hiển thị (vd truyenqq 100 chương) thì dò bù chương đầu."""
    adapter = _manga_get_adapter(series_url)
    base = _manga_base(series_url)
    html = _manga_http(series_url, base)
    pairs = re.findall(adapter["chapter_link_re"], html, flags=re.S | re.I)
    chapters = {}
    for href, label in pairs:
        href = href.strip()
        if not href or href.lower().startswith("javascript"):
            continue
        url = urllib.parse.urljoin(base, href)
        num = _manga_extract_chap_num(href)
        name = re.sub(r"\s+", " ", re.sub(r"<[^>]+>", "", label)).strip() \
            or f"Chapter {num}"
        chapters[num] = (name, url)
    if adapter.get("backfill"):
        int_chaps = [_manga_chap_key(n)[0] for n in chapters
                     if _manga_chap_key(n)[0] < 10 ** 9]
        if int_chaps:
            mn = min(int_chaps)
            if mn > 1:
                log_cb(f"   (Trang chỉ liệt kê từ chương {mn}; đang dò chương 1..{mn-1}...)")
                b = series_url.rstrip("/")
                cu = adapter.get("chap_url", lambda bb, i: f"{bb}/chapter-{i}")
                for i in range(1, mn):
                    if _MANGA_STOP[0] or str(i) in chapters:
                        continue
                    curl = cu(b, i)
                    if _manga_chapter_exists(curl, base):
                        chapters[str(i)] = (f"Chapter {i}", curl)
    return [chapters[k] for k in sorted(chapters, key=_manga_chap_key)]


def _manga_chapter_images(chapter_url):
    """URL ảnh thật trong 1 chương (qua adapter), đúng thứ tự."""
    adapter = _manga_get_adapter(chapter_url)
    base = _manga_base(chapter_url)
    html = _manga_http(chapter_url, base)
    return _manga_extract_images(html, adapter)


def _manga_image_ok(path):
    """True nếu file ảnh giải mã được trọn vẹn (phát hiện ảnh tải dở/đứt → tránh
    lỗi 'image file is truncated' khi gộp PDF)."""
    try:
        from PIL import ImageFile as _IF
        _prev = _IF.LOAD_TRUNCATED_IMAGES
        _IF.LOAD_TRUNCATED_IMAGES = False   # nghiêm: ảnh thiếu byte = lỗi
        try:
            with Image.open(path) as im:
                im.load()                   # ép giải mã toàn bộ pixel
        finally:
            _IF.LOAD_TRUNCATED_IMAGES = _prev
        return True
    except Exception:
        return False


def _manga_download_image(url, dest, referer):
    if os.path.exists(dest) and os.path.getsize(dest) > 1024 and _manga_image_ok(dest):
        return True
    # Tải + kiểm tra ảnh trọn vẹn; ảnh đứt (do host đóng kết nối) → thử lại.
    for attempt in range(4):
        if _MANGA_STOP[0]:
            return False
        try:
            data = _manga_http(url, referer, binary=True, timeout=60, retries=2)
            tmp = dest + ".part"
            with open(tmp, "wb") as f:
                f.write(data)
            if _manga_image_ok(tmp):
                os.replace(tmp, dest)
                return True
            os.remove(tmp)                  # ảnh bị cắt → bỏ, thử lại
        except Exception:
            pass
        time.sleep(1.5 * (attempt + 1))
    return False


def _manga_img_files(folder):
    return sorted(
        [os.path.join(folder, f) for f in os.listdir(folder)
         if f.lower().endswith((".jpg", ".jpeg", ".png", ".webp"))],
        key=lambda p: int(re.search(r"(\d+)", os.path.basename(p)).group(1))
        if re.search(r"(\d+)", os.path.basename(p)) else 0)


def _manga_imgs_to_pdf(img_paths, pdf_path, log_cb):
    if not img_paths:
        return False
    # Cho phép đọc ảnh hơi thiếu byte (vẫn hiện được) thay vì văng lỗi cả PDF.
    try:
        from PIL import ImageFile as _IF
        _IF.LOAD_TRUNCATED_IMAGES = True
    except Exception:
        pass
    try:
        # Stream từng ảnh thay vì nạp HẾT vào RAM cùng lúc (tránh ngốn vài GB
        # với chương nhiều trang / "1 PDF cả bộ"). PIL encode từng trang rồi
        # giải phóng ảnh trước, nên đỉnh bộ nhớ chỉ ~1–2 ảnh.
        _skip = [0]

        def _gen(paths):
            for p in paths:
                try:
                    im = Image.open(p)
                    im.load()               # ép giải mã ngay để bắt ảnh hỏng
                    if im.mode != "RGB":
                        im = im.convert("RGB")
                    yield im
                except Exception:
                    _skip[0] += 1           # ảnh hỏng → bỏ qua, không phá cả PDF

        gen = _gen(img_paths)
        try:
            first = next(gen)               # trang đầu hợp lệ đầu tiên
        except StopIteration:
            log_cb("❌ Lỗi tạo PDF: không có ảnh hợp lệ.")
            return False
        first.save(pdf_path, save_all=True, append_images=gen)
        if _skip[0]:
            log_cb(f"   ⚠ Bỏ qua {_skip[0]} ảnh hỏng khi tạo PDF.")
        log_cb(f"📕 PDF: {pdf_path}")
        return True
    except Exception as e:
        log_cb(f"❌ Lỗi tạo PDF: {e}")
        return False


def _manga_imgs_to_cbz(img_paths, cbz_path, log_cb, prefix=False):
    if not img_paths:
        return False
    try:
        import zipfile as _zip
        with _zip.ZipFile(cbz_path, "w", _zip.ZIP_STORED) as z:
            for i, p in enumerate(img_paths):
                ext = os.path.splitext(p)[1] or ".jpg"
                arc = f"{i+1:05d}{ext}" if prefix else os.path.basename(p)
                z.write(p, arc)
        log_cb(f"📦 CBZ: {cbz_path}")
        return True
    except Exception as e:
        log_cb(f"❌ Lỗi tạo CBZ: {e}")
        return False


# ── Chuyển định dạng truyện: Ảnh ↔ CBZ ↔ PDF (không cần thêm thư viện) ──────────
_MANGA_CONV_RUNNING = [False]
_MANGA_IMG_EXTS = (".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp")


def _manga_natkey(s):
    """Sắp tên file/đường dẫn theo thứ tự tự nhiên (1,2,10 thay vì 1,10,2)."""
    return [int(t) if t.isdigit() else t.lower()
            for t in re.split(r"(\d+)", s)]


def _manga_imgs_from_dir(folder):
    return sorted(
        [os.path.join(folder, f) for f in os.listdir(folder)
         if f.lower().endswith(_MANGA_IMG_EXTS)],
        key=lambda p: _manga_natkey(os.path.basename(p)))


def _manga_extract_cbz(cbz_path, tmp_dir):
    """Giải nén ảnh trong .cbz/.zip ra tmp_dir → list ảnh (đúng thứ tự tự nhiên)."""
    import zipfile as _zip
    out = []
    with _zip.ZipFile(cbz_path) as z:
        names = sorted(
            [n for n in z.namelist()
             if not n.endswith("/") and n.lower().endswith(_MANGA_IMG_EXTS)],
            key=_manga_natkey)
        for i, n in enumerate(names):
            ext = os.path.splitext(n)[1] or ".jpg"
            dest = os.path.join(tmp_dir, f"{i+1:05d}{ext}")
            with z.open(n) as src, open(dest, "wb") as f:
                f.write(src.read())
            out.append(dest)
    return out


def _manga_extract_pdf_imgs(pdf_path, tmp_dir):
    """Lấy ảnh nhúng trong PDF (truyện = mỗi trang 1 ảnh) qua pypdf → list ảnh."""
    from pypdf import PdfReader
    out = []
    reader = PdfReader(pdf_path)
    for pi, page in enumerate(reader.pages):
        try:
            imgs = list(page.images)
        except Exception:
            imgs = []
        for ii, img in enumerate(imgs):
            nm = getattr(img, "name", "") or f"{ii}.jpg"
            ext = os.path.splitext(nm)[1].lower() or ".jpg"
            if ext not in _MANGA_IMG_EXTS:
                ext = ".png"
            dest = os.path.join(tmp_dir, f"{pi+1:04d}_{ii+1:02d}{ext}")
            try:
                with open(dest, "wb") as f:
                    f.write(img.data)
                out.append(dest)
            except Exception:
                pass
    return out


def _manga_load_source_imgs(src, tmp_dir):
    """Đưa 1 nguồn (thư mục ảnh / .cbz / .zip / .pdf) về list đường dẫn ảnh."""
    low = src.lower()
    if os.path.isdir(src):
        return _manga_imgs_from_dir(src)
    if low.endswith((".cbz", ".zip")):
        return _manga_extract_cbz(src, tmp_dir)
    if low.endswith(".pdf"):
        return _manga_extract_pdf_imgs(src, tmp_dir)
    return []


def _manga_conv_collect(path):
    """Gom danh sách nguồn cần chuyển từ 1 đường dẫn người dùng chọn.
       - file .cbz/.zip/.pdf → [file] (1 truyện)
       - thư mục chứa ảnh trực tiếp → [thư mục] (1 truyện/chương)
       - thư mục chứa nhiều .cbz/.pdf hoặc nhiều thư mục con ảnh → mỗi cái 1 nguồn (hàng loạt)
    """
    if os.path.isfile(path):
        return [path] if path.lower().endswith((".cbz", ".zip", ".pdf")) else []
    if not os.path.isdir(path):
        return []
    if _manga_imgs_from_dir(path):          # thư mục có ảnh ngay → 1 nguồn
        return [path]
    srcs = []
    for nm in sorted(os.listdir(path), key=_manga_natkey):
        full = os.path.join(path, nm)
        if os.path.isfile(full) and nm.lower().endswith((".cbz", ".zip", ".pdf")):
            srcs.append(full)
        elif os.path.isdir(full) and _manga_imgs_from_dir(full):
            srcs.append(full)
    return srcs


def _manga_convert_worker(path, out_fmt, out_dir):
    try:
        import tempfile
        srcs = _manga_conv_collect(path)
        if not srcs:
            log("❌ Không tìm thấy nguồn để chuyển (cần thư mục ảnh, .cbz/.zip hoặc .pdf).")
            return
        os.makedirs(out_dir, exist_ok=True)
        log_color(f"🔄 Chuyển {len(srcs)} mục → {out_fmt}...", "#7cf")
        total = len(srcs)
        update_progress(0, total)
        ok_cnt = 0
        for idx, src in enumerate(srcs, 1):
            if _MANGA_STOP[0]:
                log("⏹ Đã dừng.")
                break
            base = _manga_safe_name(
                os.path.basename(src.rstrip("/\\"))
                if os.path.isdir(src) else os.path.splitext(os.path.basename(src))[0])
            log_color(f"[{idx}/{total}] {base}", "#9cf")
            tmp = tempfile.mkdtemp(prefix="mgconv_")
            try:
                imgs = _manga_load_source_imgs(src, tmp)
                if not imgs:
                    log(f"   [!] Không có ảnh trong nguồn này — bỏ qua.")
                    continue
                if out_fmt == "PDF":
                    if _manga_imgs_to_pdf(imgs, os.path.join(out_dir, base + ".pdf"), log):
                        ok_cnt += 1
                elif out_fmt == "CBZ":
                    if _manga_imgs_to_cbz(imgs, os.path.join(out_dir, base + ".cbz"),
                                          log, prefix=True):
                        ok_cnt += 1
                else:  # Ảnh (thư mục)
                    dest_folder = os.path.join(out_dir, base)
                    os.makedirs(dest_folder, exist_ok=True)
                    for i, p in enumerate(imgs):
                        ext = os.path.splitext(p)[1] or ".jpg"
                        shutil.copy2(p, os.path.join(dest_folder, f"{i+1:04d}{ext}"))
                    log(f"🖼 Ảnh: {dest_folder} ({len(imgs)} trang)")
                    ok_cnt += 1
            except Exception as e:
                log(f"   ❌ Lỗi chuyển '{base}': {e}")
            finally:
                shutil.rmtree(tmp, ignore_errors=True)
                update_progress(idx, total)
        if not _MANGA_STOP[0]:
            log_color(f"✅ Xong! Chuyển được {ok_cnt}/{total} mục. Lưu tại: {out_dir}", "#6f6")
            try:
                _reveal_output(out_dir)
            except Exception:
                pass
            app.after(0, show_fireworks)
    except Exception as e:
        log(f"❌ Lỗi chuyển định dạng: {e}")
    finally:
        _MANGA_CONV_RUNNING[0] = False
        app.after(0, lambda: _manga_set_running(False))
        app.after(0, lambda: update_progress(0, 1))


def _manga_convert_start():
    if _MANGA_RUNNING[0] or _MANGA_CONV_RUNNING[0] or _MANGA_TR_RUNNING[0]:
        log("⏳ Đang có tác vụ truyện chạy, vui lòng đợi/dừng trước.")
        return
    path = manga_conv_src_var.get().strip()
    if not path or not os.path.exists(path):
        log("❌ Chọn nguồn cần chuyển (thư mục ảnh, .cbz/.zip hoặc .pdf).")
        return
    out_dir = manga_conv_out_var.get().strip()
    if not out_dir:
        out_dir = (path if os.path.isdir(path) else os.path.dirname(path))
        manga_conv_out_var.set(out_dir)
    out_fmt = manga_conv_fmt_var.get()
    _MANGA_STOP[0] = False
    _MANGA_CONV_RUNNING[0] = True
    _manga_set_running(True)
    threading.Thread(target=_manga_convert_worker,
                     args=(path, out_fmt, out_dir), daemon=True).start()


def _manga_parse_range(s):
    """'1-10' / '1,2,5' / '1-3,7' → set số chương dạng chuỗi. Rỗng → None (tất cả)."""
    s = (s or "").strip()
    if not s:
        return None
    want = set()
    for part in s.split(","):
        part = part.strip()
        if "-" in part:
            a, b = part.split("-", 1)
            try:
                want.update(str(x) for x in range(int(a), int(b) + 1))
            except Exception:
                pass
        elif part:
            want.add(part)
    return want or None


def _manga_set_running(on):
    """Bật/tắt trạng thái nút (chạy trên main thread)."""
    try:
        btn_manga_run.configure(state="disabled" if on else "normal")
        btn_manga_stop.configure(state="normal" if on else "disabled")
    except Exception:
        pass


def _manga_stop():
    if _MANGA_RUNNING[0] or _MANGA_CONV_RUNNING[0] or _MANGA_TR_RUNNING[0]:
        _MANGA_STOP[0] = True
        # Job dịch: dừng cả pha _translate_segments (online + offline) đang chạy
        if _MANGA_TR_RUNNING[0]:
            global TRANSLATE_STOP, TRANSLATE_PAUSED
            TRANSLATE_STOP = True
            TRANSLATE_PAUSED = False
            _translate_send_proc("STOP")   # offline subprocess (nếu có)
        log("⏹ Đang dừng...")
        # Dừng cả tiến trình gallery-dl / OCR (nếu đang chạy)
        for _p in (_MANGA_PROC[0], _MANGA_TR_PROC[0]):
            if _p is not None:
                try:
                    _proc_tree_action(_p, "kill")
                except Exception:
                    try:
                        _p.kill()
                    except Exception:
                        pass


def _manga_start():
    if _MANGA_RUNNING[0] or _MANGA_CONV_RUNNING[0] or _MANGA_TR_RUNNING[0]:
        log("⚠ Đang có tác vụ truyện chạy, đợi xong hoặc bấm Dừng.")
        return
    url = manga_url_var.get().strip()
    if not url or "http" not in url:
        log("❌ Nhập URL bộ truyện hoặc 1 chương.")
        return
    out_dir = manga_out_var.get().strip()
    if not out_dir:
        out_dir = os.path.join(os.path.expanduser("~"), "Downloads", "Truyen")
        manga_out_var.set(out_dir)
    fmt = manga_format_var.get()
    rng = manga_chap_var.get().strip()
    delay = 0.3
    use_gdl = bool(manga_gallerydl_var.get())
    cookies = manga_cookies_var.get().strip()
    if cookies in ("", "(Không)"):
        cookies = ""
    # webtoonscan.com có Cloudflare → bắt buộc đi đường gallery-dl generic (urllib bị 403)
    if "webtoonscan.com" in url.lower():
        use_gdl = True
    _MANGA_STOP[0] = False
    _MANGA_PROC[0] = None
    _MANGA_RUNNING[0] = True
    _manga_set_running(True)
    if use_gdl:
        threading.Thread(target=_manga_gdl_worker, args=(url, out_dir, fmt, rng, cookies),
                         daemon=True).start()
    else:
        threading.Thread(target=_manga_worker, args=(url, out_dir, fmt, rng, delay),
                         daemon=True).start()


def _find_gallerydl():
    """Tìm gallery-dl → list lệnh để Popen. None nếu không có.
    Ưu tiên gallery-dl.exe (PATH / cạnh exe), fallback `python -m gallery_dl`."""
    exe = shutil.which("gallery-dl") or shutil.which("gallery-dl.exe")
    if exe:
        return [exe]
    try:
        for root in _install_dirs():
            cand = os.path.join(root, "gallery-dl.exe")
            if os.path.isfile(cand):
                return [cand]
    except Exception:
        pass
    py = _find_whisper_python() or _find_voxcpm_python("")
    if py:
        return [py, "-m", "gallery_dl"]
    return None


_MANGA_GDL_IMG_EXT = (".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp")


def _manga_gdl_chapter_dirs(root):
    """Các thư mục lá chứa ảnh (mỗi cái = 1 chương), sắp tự nhiên theo số."""
    dirs = []
    for dp, _dn, fn in os.walk(root):
        if any(f.lower().endswith(_MANGA_GDL_IMG_EXT) for f in fn):
            dirs.append(dp)

    def _key(p):
        nums = re.findall(r"\d+", os.path.basename(p))
        return ([int(n) for n in nums] or [10 ** 9], os.path.basename(p))
    return sorted(dirs, key=_key)


def _manga_gdl_finalize(dest, out_dir, title, fmt):
    """Gộp ảnh đã tải thành PDF/CBZ theo định dạng (dùng chung cho các worker gallery-dl)."""
    per_pdf = fmt == "PDF mỗi chương"
    per_cbz = fmt == "CBZ mỗi chương"
    merge_pdf = fmt == "1 PDF cả bộ"
    merge_cbz = fmt == "1 CBZ cả bộ"
    if not (per_pdf or per_cbz or merge_pdf or merge_cbz):
        return
    chap_dirs = _manga_gdl_chapter_dirs(dest)
    if not chap_dirs:
        log("   [!] Không tìm thấy ảnh đã tải để gộp.")
        return
    if per_pdf or per_cbz:
        for d in chap_dirs:
            imgs = _manga_img_files(d)
            nm = _manga_safe_name(os.path.basename(d))
            if per_pdf:
                _manga_imgs_to_pdf(imgs, os.path.join(dest, nm + ".pdf"), log)
            if per_cbz:
                _manga_imgs_to_cbz(imgs, os.path.join(dest, nm + ".cbz"), log)
    if merge_pdf or merge_cbz:
        all_imgs = []
        for d in chap_dirs:
            all_imgs.extend(_manga_img_files(d))
        log_color(f"🧩 Gộp cả bộ: {len(all_imgs)} trang từ "
                  f"{len(chap_dirs)} chương...", "#7cf")
        if merge_pdf:
            _manga_imgs_to_pdf(all_imgs, os.path.join(out_dir, title + ".pdf"), log)
        if merge_cbz:
            _manga_imgs_to_cbz(all_imgs, os.path.join(out_dir, title + ".cbz"),
                               log, prefix=True)


def _manga_wts_parts(url):
    """Tách (series_base_url, 'chapter-N' hoặc None) từ 1 URL webtoonscan."""
    p = url.split("?")[0].split("#")[0].rstrip("/")
    segs = p.split("/")
    if segs and segs[-1].lower().startswith("chapter-"):
        return "/".join(segs[:-1]), segs[-1]
    return p, None


# UA giả-Firefox để cf_clearance (cookie Cloudflare cấp bởi Firefox) chấp nhận request urllib.
# Chỉ là fallback — cf_clearance bị RÀNG BUỘC với đúng UA của Firefox đã vượt challenge,
# nên _manga_firefox_ua() đọc version thật từ profile (compatibility.ini) để UA luôn khớp
# (Firefox tự cập nhật → UA cứng lệch version → Cloudflare trả 403 dù cookie còn hạn).
_MANGA_WTS_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:152.0) "
                 "Gecko/20100101 Firefox/152.0")


def _manga_firefox_profile_db():
    """Đường dẫn cookies.sqlite của profile Firefox mới dùng nhất, '' nếu không có."""
    try:
        import glob
        pats = [os.path.expandvars(r"%APPDATA%\Mozilla\Firefox\Profiles\*\cookies.sqlite"),
                os.path.expanduser("~/.mozilla/firefox/*/cookies.sqlite")]
        cands = []
        for p in pats:
            cands += glob.glob(p)
        return max(cands, key=os.path.getmtime) if cands else ""
    except Exception:
        return ""


def _manga_firefox_ua():
    """UA khớp ĐÚNG version Firefox thật của máy (đọc compatibility.ini trong profile).
    cf_clearance bị bind với UA đã vượt challenge → UA phải khớp version, không thì 403."""
    try:
        db = _manga_firefox_profile_db()
        if db:
            ini = os.path.join(os.path.dirname(db), "compatibility.ini")
            with open(ini, "r", encoding="utf-8", errors="replace") as f:
                m = re.search(r"LastVersion\s*=\s*(\d+)\.", f.read())
            if m:
                v = m.group(1)
                return (f"Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:{v}.0) "
                        f"Gecko/20100101 Firefox/{v}.0")
    except Exception:
        pass
    return _MANGA_WTS_UA


def _manga_firefox_cookie_header(host_like="webtoonscan"):
    """Đọc cookie Firefox cho 1 host (Firefox lưu plaintext trong cookies.sqlite, không cần
    giải mã như Chrome) → chuỗi 'k=v; ...' để gắn header Cookie. '' nếu không có."""
    try:
        import sqlite3
        import tempfile
        db = _manga_firefox_profile_db()
        if not db:
            return ""
        tmp = os.path.join(tempfile.gettempdir(), "_wts_ff_ck.sqlite")
        shutil.copy2(db, tmp)                  # copy tránh khoá file khi Firefox đang mở
        con = sqlite3.connect(tmp)
        try:
            rows = con.execute(
                "SELECT name,value FROM moz_cookies WHERE host LIKE ?",
                ("%" + host_like + "%",)).fetchall()
        finally:
            con.close()
        try:
            os.remove(tmp)
        except Exception:
            pass
        return "; ".join(f"{n}={v}" for n, v in rows)
    except Exception:
        return ""


def _manga_wts_list_chapters(series_base, slug):
    """Danh sách (label, url) chương THẬT từ trang series webtoonscan — gồm cả chương lẻ
    (chapter-207-5 = chương 207.5). Trả [] nếu không lấy được (chưa mở/đóng Firefox, cookie
    hết hạn). Sắp tự nhiên (1, 2, ..., 207, 207-5, 208...)."""
    ck = _manga_firefox_cookie_header()
    if not ck:
        return []
    try:
        req = urllib.request.Request(series_base + "/", headers={
            "User-Agent": _manga_firefox_ua(),
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            "Accept-Language": "en-US,en;q=0.5",
            "Cookie": ck, "Referer": "https://webtoonscan.com/"})
        html = urllib.request.urlopen(req, timeout=40).read().decode("utf-8", "replace")
    except Exception:
        return []
    # chỉ lấy chương CỦA bộ này (slug) → bỏ link bộ khác ở sidebar
    pat = re.compile(r'href="([^"]*?/' + re.escape(slug)
                     + r'/chapter-([0-9][0-9.\-]*?))/?"', re.I)
    seen = {}
    for full, label in pat.findall(html):
        label = label.strip("-.").strip()
        if not label or label in seen:
            continue
        if not full.startswith("http"):
            full = "https://webtoonscan.com" + full
        seen[label] = full.rstrip("/") + "/"
    items = sorted(seen.items(), key=lambda it: _manga_chap_key(it[0]))
    return items


def _manga_wts_gdl_worker(url, out_dir, fmt, rng, cookies=""):
    """webtoonscan.com qua gallery-dl `generic:` (vượt Cloudflare bằng cookie trình duyệt).
    gallery-dl không có extractor riêng cho site này và `generic:` chỉ lấy 1 chương/URL,
    nên ta tự liệt kê chương theo pattern .../chapter-N/ rồi tải từng chương,
    lọc `--filter "'cdn' in imageurl"` để chỉ giữ ảnh nội dung (bỏ logo/thumbnail rác)."""
    try:
        cmd0 = _find_gallerydl()
        if not cmd0:
            log("❌ Chưa cài gallery-dl. Mở CMD chạy:  pip install -U gallery-dl")
            log("   (hoặc đặt gallery-dl.exe cạnh phần mềm)")
            return
        # Xác nhận gallery-dl thực sự chạy được trong môi trường app phân giải tới —
        # nếu không, báo rõ thay vì để mỗi chương về 0 ảnh rồi đoán nhầm "cookie hết hạn".
        try:
            _ver = subprocess.run(cmd0 + ["--version"], capture_output=True, text=True,
                                  timeout=60, creationflags=CREATE_NO_WINDOW)
            if _ver.returncode != 0:
                log(f"❌ gallery-dl không chạy được qua: {cmd0[0]}")
                _msg = (_ver.stderr or _ver.stdout or "").strip().splitlines()
                if _msg:
                    log(f"   {_msg[-1][:200]}")
                if "-m" in cmd0:
                    log(f"   Cài đúng môi trường:  \"{cmd0[0]}\" -m pip install -U gallery-dl")
                return
        except Exception as _e:
            log(f"❌ Không gọi được gallery-dl ({cmd0[0]}): {_e}")
            return
        if cookies != "firefox":
            # webtoonscan CHỈ dùng được cookie Firefox: họ Chromium (Chrome 127+/Edge/Brave...)
            # mã hoá cookie kiểu App-Bound nên gallery-dl KHÔNG giải mã được (đã test:
            # chrome = Permission denied, edge = Failed to decrypt cookie (DPAPI)).
            # → chưa chọn / chọn nhầm trình duyệt khác: tự chuyển sang Firefox nếu có cookie.
            if _manga_firefox_cookie_header():
                if cookies:
                    log(f"ℹ Cookie '{cookies}' không dùng được với webtoonscan "
                        "(Chrome/Edge mã hoá App-Bound) → tự chuyển sang cookie Firefox.")
                else:
                    log("ℹ Chưa chọn Cookie → tự dùng cookie Firefox (webtoonscan cần vượt Cloudflare).")
                cookies = "firefox"
            else:
                log("⚠ webtoonscan có Cloudflare — chỉ vượt được bằng cookie FIREFOX.")
                log("   (Chrome/Edge v127+ mã hoá App-Bound nên không đọc được cookie.)")
                log("   Mở truyện trong Firefox vượt Cloudflare → đóng Firefox → thử lại.")
                if cookies:
                    log(f"   Vẫn thử tiếp với cookie '{cookies}' (khả năng cao bị 403)...")

        series, chap_seg = _manga_wts_parts(url)
        slug = _manga_safe_name(series.rstrip("/").split("/")[-1]) or "webtoonscan"
        dest = os.path.join(out_dir, slug)
        os.makedirs(dest, exist_ok=True)
        ck_args = ["--cookies-from-browser", cookies] if cookies else []
        # cf_clearance bind với UA của Firefox đã vượt challenge → ép gallery-dl gửi
        # đúng UA đó (mặc định gallery-dl gửi UA riêng ≠ Firefox thật → Cloudflare 403).
        _ua = _manga_firefox_ua()
        ck_args += ["-o", "user-agent=" + _ua]
        filt = ["--filter", "'cdn' in imageurl"]
        base = series.rstrip("/")
        log_color(f"🌐 webtoonscan: {slug}"
                  + (f"  (cookies: {cookies})" if cookies else ""), "#7cf")
        log(f"   UA: ...Firefox/{_ua.rsplit('/', 1)[-1]}")

        def _dl_chapter(label, chap_url, report=False):
            """Tải 1 chương (URL cụ thể) vào dest/chapter-<label> → số ảnh tải được.
            report=True: nếu 0 ảnh thì in vài dòng output cuối của gallery-dl (lý do thật:
            403 challenge, cookie sai...) thay vì im lặng."""
            chap_dir = os.path.join(dest, f"chapter-{label}")
            proc = subprocess.Popen(
                cmd0 + ["-D", chap_dir] + filt + ck_args + ["generic:" + chap_url],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, encoding="utf-8", errors="replace",
                creationflags=CREATE_NO_WINDOW)
            _MANGA_PROC[0] = proc
            got = 0
            tail = []
            for line in proc.stdout:
                if _MANGA_STOP[0]:
                    break
                line = line.rstrip()
                if not line:
                    continue
                if line.lower().endswith(_MANGA_GDL_IMG_EXT):
                    got += 1
                else:
                    tail.append(line)
                    if len(tail) > 6:
                        tail.pop(0)
                    if line.startswith("[") and ("error" in line.lower()
                                                 or "challenge" in line.lower()):
                        log(f"   {line}")
            proc.wait()
            _MANGA_PROC[0] = None
            if got == 0:
                if report:                             # hiện lý do thật khi chương lẽ ra có ảnh
                    for t in tail:
                        log(f"   gdl: {t}")
                try:                                   # xoá thư mục chương rỗng
                    if os.path.isdir(chap_dir) and not _manga_img_files(chap_dir):
                        shutil.rmtree(chap_dir, ignore_errors=True)
                except Exception:
                    pass
            return got

        # Xác định danh sách chương: ưu tiên danh sách THẬT từ trang series (gồm chương lẻ),
        # fallback dò số nguyên 1,2,3... nếu không đọc được trang (cookie/Firefox).
        if chap_seg:                                   # URL 1 chương cụ thể
            label = chap_seg.split("chapter-", 1)[-1]
            chapters = [(label, url.rstrip("/") + "/")]
        else:
            chapters = _manga_wts_list_chapters(base, slug)
            if chapters:
                want = _manga_parse_range(rng)         # set số nguyên, hoặc None
                if want:                               # giữ chương có phần nguyên trong range
                    chapters = [c for c in chapters
                                if str(_manga_chap_key(c[0])[0]) in want]
                log(f"   Tìm thấy {len(chapters)} chương từ trang truyện (gồm chương lẻ).")
            else:
                log("   [!] Không đọc được danh sách chương (cần Firefox đã vượt Cloudflare"
                    " + đóng Firefox). Chuyển sang dò chương số nguyên.")
                chapters = None                        # tín hiệu fallback enumeration

        total_imgs = 0
        n_chap = 0
        if chapters is None:                           # fallback: dò 1,2,3... (bỏ chương lẻ)
            misses = 0
            n = 1
            while not _MANGA_STOP[0] and n <= 2000:
                got = _dl_chapter(str(n), f"{base}/chapter-{n}/")
                if got:
                    n_chap += 1
                    total_imgs += got
                    misses = 0
                    log(f"   ✔ Chương {n}: {got} ảnh")
                else:
                    misses += 1
                    if misses >= 2:                    # 2 chương trống liên tiếp = hết bộ
                        break
                n += 1
        else:
            tot = len(chapters)
            for i, (label, churl) in enumerate(chapters, 1):
                if _MANGA_STOP[0]:
                    break
                got = _dl_chapter(label, churl, report=(i == 1))
                if got:
                    n_chap += 1
                    total_imgs += got
                    log(f"   ✔ Chương {label}: {got} ảnh")
                else:
                    log(f"   [!] Chương {label}: không có ảnh (bỏ qua / bị chặn?)")
                update_progress(i, tot)

        if _MANGA_STOP[0]:
            log("⏹ Đã dừng.")
            return
        if n_chap == 0:
            log("❌ Không tải được ảnh nào. Cookie hết hạn hoặc URL sai?")
            log("   Mở lại truyện trong Firefox (vượt Cloudflare) → đóng Firefox → thử lại.")
            return
        log_color(f"   ✔ Tải xong {total_imgs} ảnh / {n_chap} chương.", "#6f6")

        _manga_gdl_finalize(dest, out_dir, slug, fmt)
        log_color(f"✅ Hoàn tất! Lưu tại: {dest}", "#6f6")
        try:
            _reveal_output(dest)
        except Exception:
            pass
        app.after(0, show_fireworks)
    except Exception as e:
        log(f"❌ Lỗi webtoonscan: {e}")
    finally:
        _MANGA_PROC[0] = None
        _MANGA_RUNNING[0] = False
        app.after(0, lambda: _manga_set_running(False))
        app.after(0, lambda: update_progress(0, 1))


def _manga_gdl_worker(url, out_dir, fmt, rng, cookies=""):
    """Backend gallery-dl cho truyện nước ngoài (MangaDex, mangakakalot, webtoons...).
    Tải ảnh xuống rồi tái dùng phần gộp PDF/CBZ sẵn có.
    cookies: tên trình duyệt để lấy cookie (vượt Cloudflare), rỗng = không dùng."""
    if "webtoonscan.com" in url.lower():               # site Cloudflare → luồng generic riêng
        return _manga_wts_gdl_worker(url, out_dir, fmt, rng, cookies)
    per_pdf = fmt in ("PDF mỗi chương",)
    per_cbz = fmt in ("CBZ mỗi chương",)
    merge_pdf = fmt in ("1 PDF cả bộ",)
    merge_cbz = fmt in ("1 CBZ cả bộ",)
    try:
        cmd0 = _find_gallerydl()
        if not cmd0:
            log("❌ Chưa cài gallery-dl. Mở CMD chạy:  pip install -U gallery-dl")
            log("   (hoặc đặt gallery-dl.exe cạnh phần mềm)")
            return
        title = _manga_safe_name(url.rstrip("/").split("/")[-1]) or "gallerydl"
        dest = os.path.join(out_dir, title)
        os.makedirs(dest, exist_ok=True)
        # Chương = "child extractor" trong gallery-dl → chọn bằng --child-range
        # (theo THỨ TỰ liệt kê: 1-10 = 10 chương đầu, 1,2,5...). Rỗng = cả bộ.
        rng_args = []
        if rng:
            rng_args = ["--child-range", rng.replace(" ", "")]
        # Cookie trình duyệt để vượt Cloudflare (chrome/edge/firefox...)
        ck_args = ["--cookies-from-browser", cookies] if cookies else []
        log_color(f"🌐 gallery-dl: {url}"
                  + (f"  (cookies: {cookies})" if cookies else ""), "#7cf")

        # Đếm trước tổng số ảnh (best-effort) để có thanh tiến trình
        total = 0
        try:
            probe = subprocess.run(cmd0 + ["--get-urls"] + ck_args + rng_args + [url],
                                   capture_output=True, text=True, timeout=180,
                                   creationflags=CREATE_NO_WINDOW)
            total = sum(1 for ln in probe.stdout.splitlines()
                        if ln.strip().startswith("http"))
            if total:
                log(f"   Tổng ~{total} ảnh.")
        except Exception:
            total = 0
        if _MANGA_STOP[0]:
            log("⏹ Đã dừng theo yêu cầu.")
            return

        update_progress(0, total or 1)
        proc = subprocess.Popen(
            cmd0 + ["-d", dest] + ck_args + rng_args + [url],
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, encoding="utf-8", errors="replace",
            creationflags=CREATE_NO_WINDOW)
        _MANGA_PROC[0] = proc
        done = 0
        for line in proc.stdout:
            if _MANGA_STOP[0]:
                break
            line = line.rstrip()
            if not line:
                continue
            if line.lower().endswith(_MANGA_GDL_IMG_EXT):
                done += 1
                if total:
                    update_progress(min(done, total), total)
                if done % 10 == 0:
                    log(f"   ⬇ {done}" + (f"/{total}" if total else "") + " ảnh...")
            elif line.startswith("[") and ("error" in line.lower()
                                           or "warning" in line.lower()):
                log(f"   {line}")
        proc.wait()
        _MANGA_PROC[0] = None
        if _MANGA_STOP[0]:
            log("⏹ Đã dừng.")
            return
        log(f"   ✔ Tải xong {done} ảnh.")

        # Gộp PDF/CBZ nếu cần (dùng lại helper sẵn có)
        _manga_gdl_finalize(dest, out_dir, title, fmt)

        log_color(f"✅ Hoàn tất! Lưu tại: {dest}", "#6f6")
        try:
            _reveal_output(dest)
        except Exception:
            pass
        app.after(0, show_fireworks)
    except Exception as e:
        log(f"❌ Lỗi gallery-dl: {e}")
    finally:
        _MANGA_PROC[0] = None
        _MANGA_RUNNING[0] = False
        app.after(0, lambda: _manga_set_running(False))
        app.after(0, lambda: update_progress(0, 1))


def _manga_worker(url, out_dir, fmt, rng, delay):
    per_pdf = fmt in ("PDF mỗi chương",)
    per_cbz = fmt in ("CBZ mỗi chương",)
    merge_pdf = fmt in ("1 PDF cả bộ",)
    merge_cbz = fmt in ("1 CBZ cả bộ",)
    try:
        os.makedirs(out_dir, exist_ok=True)
        # 1 chương lẻ
        if "/chapter-" in url or "/chuong-" in url:
            _parts = url.rstrip("/").split("/")
            # đoạn cuối là ID số (hentaivnx: .../chapter-8/612561) → tên chương
            # là đoạn áp chót; ngược lại (truyenqq: .../chapter-5) lấy như cũ.
            if len(_parts) >= 3 and _parts[-1].isdigit() and \
                    re.search(r"chapter-|chuong-", _parts[-2], re.I):
                title = _manga_safe_name(_parts[-3])
                name = _parts[-2]
            else:
                title = _manga_safe_name(_parts[-2])
                name = _parts[-1]
            root = os.path.join(out_dir, title)
            chapters = [(name, url)]
            log_color(f"📚 Tải 1 chương: {name}", "#7cf")
        else:
            title = _manga_safe_name(url.rstrip("/").split("/")[-1])
            root = os.path.join(out_dir, title)
            log_color(f"📚 Lấy danh sách chương: {title}...", "#7cf")
            chapters = _manga_list_chapters(url, log)
            if not chapters:
                log("❌ Không lấy được danh sách chương (cấu trúc trang có thể đã đổi).")
                return
            want = _manga_parse_range(rng)
            if want:
                sel = []
                for nm, u in chapters:
                    num = _manga_extract_chap_num(u)
                    base_num = num.split(".")[0].split("-")[0]
                    if num in want or base_num in want or nm.split()[-1] in want:
                        sel.append((nm, u))
                chapters = sel
                if not chapters:
                    log("❌ Không có chương nào khớp khoảng đã nhập.")
                    return
            log(f"   Tổng {len(chapters)} chương sẽ tải.")
        os.makedirs(root, exist_ok=True)

        done_folders = []
        total = len(chapters)
        update_progress(0, total)

        def _grab_chapter(label, name, churl):
            """Tải 1 chương. Trả về True nếu tải đủ tất cả trang, False nếu lỗi
            (lấy ảnh thất bại / không có ảnh / thiếu trang). Trang đã có thì bỏ
            qua nên gọi lại = chỉ tải phần còn thiếu (resume)."""
            log_color(f"{label} {name}", "#9cf")
            folder = os.path.join(root, _manga_safe_name(name))
            os.makedirs(folder, exist_ok=True)
            try:
                imgs = _manga_chapter_images(churl)
            except Exception as e:
                log(f"   ❌ Lỗi lấy ảnh chương: {e}")
                return False, folder
            if not imgs:
                log(f"   [!] Không tìm thấy ảnh trong {churl}")
                return False, folder
            ok = 0
            for i, img_url in enumerate(imgs):
                if _MANGA_STOP[0]:
                    break
                ext = os.path.splitext(urllib.parse.urlsplit(img_url).path)[1] or ".jpg"
                dest = os.path.join(folder, f"{i+1:03d}{ext}")
                if _manga_download_image(img_url, dest, churl):
                    ok += 1
                time.sleep(delay)
            log(f"   ✔ {ok}/{len(imgs)} trang")
            full = (ok == len(imgs))
            if full:
                if per_pdf:
                    _manga_imgs_to_pdf(_manga_img_files(folder), folder + ".pdf", log)
                if per_cbz:
                    _manga_imgs_to_cbz(_manga_img_files(folder), folder + ".cbz", log)
            else:
                log(f"   ⚠ Chương '{name}' thiếu trang — sẽ thử lại sau.")
            return full, folder

        failed = []   # [(name, churl)] các chương lỗi/thiếu trang
        for idx, (name, churl) in enumerate(chapters, 1):
            if _MANGA_STOP[0]:
                log("⏹ Đã dừng theo yêu cầu.")
                break
            full, folder = _grab_chapter(f"[{idx}/{total}]", name, churl)
            if full:
                done_folders.append(folder)
            else:
                failed.append((name, churl))
            update_progress(idx, total)

        # Tự thử lại các chương bị lỗi (host hay đóng kết nối → thường qua lần 2)
        for _pass in range(1, 3):
            if not failed or _MANGA_STOP[0]:
                break
            retry, failed = failed, []
            log_color(f"🔁 Thử lại {len(retry)} chương lỗi (lần {_pass})...", "#fc6")
            time.sleep(3)
            for j, (name, churl) in enumerate(retry, 1):
                if _MANGA_STOP[0]:
                    failed.extend(retry[j-1:])
                    break
                full, folder = _grab_chapter(f"   🔁[{j}/{len(retry)}]", name, churl)
                if full:
                    done_folders.append(folder)
                else:
                    failed.append((name, churl))

        if failed and not _MANGA_STOP[0]:
            log_color(f"⚠ Còn {len(failed)} chương chưa tải đủ "
                      f"(trang chặn/đóng kết nối). Chạy lại sẽ tải tiếp phần thiếu:",
                      "#f96")
            for name, churl in failed:
                log(f"     • {name}  →  {churl}")

        # Gộp cả bộ thành 1 file — theo ĐÚNG thứ tự chương (chương tải lại ở
        # cuối các pass nên done_folders bị xáo trộn; sắp lại theo chapters).
        if (merge_pdf or merge_cbz) and done_folders and not _MANGA_STOP[0]:
            _done_set = set(done_folders)
            ordered = [os.path.join(root, _manga_safe_name(nm))
                       for nm, _u in chapters
                       if os.path.join(root, _manga_safe_name(nm)) in _done_set]
            all_imgs = []
            for folder in ordered:
                all_imgs.extend(_manga_img_files(folder))
            log_color(f"🧩 Gộp cả bộ: {len(all_imgs)} trang từ "
                      f"{len(done_folders)} chương...", "#7cf")
            if merge_pdf:
                _manga_imgs_to_pdf(all_imgs, os.path.join(out_dir, title + ".pdf"), log)
            if merge_cbz:
                _manga_imgs_to_cbz(all_imgs, os.path.join(out_dir, title + ".cbz"),
                                   log, prefix=True)

        if not _MANGA_STOP[0]:
            log_color(f"✅ Hoàn tất! Lưu tại: {root}", "#6f6")
            try:
                _reveal_output(root)
            except Exception:
                pass
            app.after(0, show_fireworks)
    except Exception as e:
        log(f"❌ Lỗi tải truyện: {e}")
    finally:
        _MANGA_RUNNING[0] = False
        app.after(0, lambda: _manga_set_running(False))
        app.after(0, lambda: update_progress(0, 1))


# ══════════════════════════════════════════════════════════════════════════════
# DỊCH TRUYỆN NƯỚC NGOÀI → TIẾNG VIỆT  (OCR ảnh → dịch → ghi chữ Việt đè lên ảnh)
#   - OCR: manga_ocr_helper.py (EasyOCR) chạy trong env có torch (voxcpm_env)
#   - Dịch: tái dùng _translate_segments (theo dropdown Claude/Gemini/OpenAI/Offline)
#   - Typeset: PIL + _find_unicode_font, đè ô trắng + chữ Việt vào đúng vị trí
# ══════════════════════════════════════════════════════════════════════════════
_MANGA_OCR_LANGS = ["en", "chinese_sim", "chinese_cht", "japan", "korean"]
_MANGA_OCR_LANG_LABELS = {
    "Tiếng Anh": "en", "Tiếng Trung (giản thể)": "chinese_sim",
    "Tiếng Trung (phồn thể)": "chinese_cht", "Tiếng Nhật": "japan",
    "Tiếng Hàn": "korean",
}


def _find_manga_ocr_helper():
    """Tìm manga_ocr_helper.py (MEIPASS → cạnh app/exe → cạnh script)."""
    name = "manga_ocr_helper.py"
    search = [
        getattr(sys, "_MEIPASS", None),
        os.path.dirname(__file__) if "__file__" in globals() else None,
        os.path.dirname(sys.argv[0]),
        os.path.dirname(sys.executable),
    ]
    for d in search:
        if d:
            p = os.path.join(d, name)
            if os.path.isfile(p):
                return p
    return None


def _find_manga_ocr_python():
    """Env chạy OCR ảnh — ưu tiên override OCR riêng, rồi voxcpm_env (đã có torch)."""
    ov = globals().get("MANGA_OCR_ENV_OVERRIDE", "")
    if ov and os.path.isfile(ov):
        return ov
    return _find_voxcpm_python(globals().get("voxcpm_ckpt_var").get()
                               if globals().get("voxcpm_ckpt_var") else "")


def _manga_tr_wrap_text(draw, text, font, max_w):
    """Ngắt dòng theo chiều rộng tối đa (PIL). Trả về list dòng."""
    words = text.split()
    if not words:
        return [""]
    lines, cur = [], words[0]
    for w in words[1:]:
        trial = cur + " " + w
        if draw.textlength(trial, font=font) <= max_w:
            cur = trial
        else:
            lines.append(cur)
            cur = w
    lines.append(cur)
    return lines


def _manga_tr_fit_font(draw, text, font_path, box_w, box_h):
    """Chọn cỡ font lớn nhất để text vừa trong (box_w, box_h). Trả về (font, lines)."""
    from PIL import ImageFont
    pad = 6
    avail_w = max(10, box_w - 2 * pad)
    avail_h = max(10, box_h - 2 * pad)
    size = max(10, min(int(box_h * 0.8), 48))
    while size >= 9:
        try:
            font = ImageFont.truetype(font_path, size)
        except Exception:
            font = ImageFont.load_default()
            return font, _manga_tr_wrap_text(draw, text, font, avail_w)
        lines = _manga_tr_wrap_text(draw, text, font, avail_w)
        line_h = size + 4
        total_h = line_h * len(lines)
        widest = max((draw.textlength(ln, font=font) for ln in lines), default=0)
        if total_h <= avail_h and widest <= avail_w:
            return font, lines
        size -= 2
    return font, lines  # nhỏ nhất rồi vẫn dùng (sẽ tràn nhẹ)


def _manga_tr_render_page(img_path, blocks, translations, out_path, font_path, log_cb):
    """Đè ô trắng + chữ Việt vào từng khối → lưu out_path."""
    from PIL import Image, ImageDraw, ImageFont
    try:
        from PIL import ImageFile as _IF
        _IF.LOAD_TRUNCATED_IMAGES = True
    except Exception:
        pass
    try:
        im = Image.open(img_path)
        im.load()
        if im.mode != "RGB":
            im = im.convert("RGB")
        draw = ImageDraw.Draw(im)
        for blk, vi in zip(blocks, translations):
            vi = (vi or "").strip()
            if not vi:
                continue
            x1, y1, x2, y2 = blk["box"]
            bw, bh = max(8, x2 - x1), max(8, y2 - y1)
            # Ô trắng phủ chữ gốc — nới theo cỡ block (box OCR ôm sát chữ,
            # 3px cứng hay hở đuôi ký tự/dấu câu); không viền cho tàng hình
            mx = max(5, min(14, bw // 14))
            my = max(5, min(14, bh // 14))
            draw.rectangle([x1 - mx, y1 - my, x2 + mx, y2 + my],
                           fill=(255, 255, 255))
            if font_path:
                font, lines = _manga_tr_fit_font(draw, vi, font_path, bw, bh)
            else:
                font = ImageFont.load_default()
                lines = _manga_tr_wrap_text(draw, vi, font, bw - 8)
            try:
                size = font.size
            except Exception:
                size = 14
            line_h = size + 4
            total_h = line_h * len(lines)
            ty = y1 + max(0, (bh - total_h) // 2)
            for ln in lines:
                lw = draw.textlength(ln, font=font)
                tx = x1 + max(0, (bw - lw) // 2)
                draw.text((tx, ty), ln, fill=(15, 15, 15), font=font)
                ty += line_h
        os.makedirs(os.path.dirname(out_path), exist_ok=True)
        im.save(out_path)
        return True
    except Exception as e:
        log_cb(f"   ⚠ Lỗi ghi chữ ảnh {os.path.basename(img_path)}: {e}")
        return False


def _manga_tr_collect_images(src):
    """Nguồn dịch = thư mục ảnh, hoặc thư mục chứa nhiều thư mục chương.
    Trả về list (nhãn_chương, [ảnh...]) giữ nguyên thứ tự."""
    src = src.strip().strip('"')
    if not src or not os.path.isdir(src):
        return []
    direct = _manga_imgs_from_dir(src)
    if direct:
        return [(os.path.basename(src.rstrip("\\/")) or "truyen", direct)]
    # không có ảnh trực tiếp → coi mỗi thư mục con là 1 chương
    out = []
    for name in sorted(os.listdir(src), key=_manga_natkey):
        sub = os.path.join(src, name)
        if os.path.isdir(sub):
            imgs = _manga_imgs_from_dir(sub)
            if imgs:
                out.append((name, imgs))
    return out


def _manga_tr_set_running(on):
    try:
        btn_manga_tr.configure(state="disabled" if on else "normal")
        btn_manga_stop.configure(state="normal" if on else "disabled")
    except Exception:
        pass


def _manga_translate_start():
    if _MANGA_RUNNING[0] or _MANGA_CONV_RUNNING[0] or _MANGA_TR_RUNNING[0]:
        log("⚠ Đang có tác vụ truyện chạy, đợi xong đã.")
        return
    src = manga_tr_src_var.get().strip()
    chapters = _manga_tr_collect_images(src)
    if not chapters:
        log("❌ Nguồn dịch trống — chọn thư mục ảnh truyện (hoặc thư mục chứa các chương).")
        return
    # Preflight: helper + env OCR
    helper = _find_manga_ocr_helper()
    if not helper:
        log("❌ Không tìm thấy manga_ocr_helper.py (cạnh app/exe).")
        return
    ocr_py = _find_manga_ocr_python()
    if not ocr_py:
        log("❌ Không tìm thấy python có torch để OCR (voxcpm_env). "
            "Đặt voxcpm_env cạnh app, hoặc khai báo ở ⚙ Cài đặt.")
        return
    # Preflight engine dịch (online cần key; offline cần model — báo sớm)
    if (TRANSLATE_PROVIDER or "") != "Offline":
        try:
            _translate_active_key()
        except Exception as e:
            log(f"❌ {e}")
            return
    lang = _MANGA_OCR_LANG_LABELS.get(manga_tr_lang_var.get(), "en")
    out_fmt = manga_tr_fmt_var.get()
    write_script = bool(manga_tr_script_var.get())
    global TRANSLATE_STOP, TRANSLATE_PAUSED
    TRANSLATE_STOP = False
    TRANSLATE_PAUSED = False
    _MANGA_STOP[0] = False
    _MANGA_TR_RUNNING[0] = True
    _manga_tr_set_running(True)
    log_color(f"🌐 Dịch truyện ({manga_tr_lang_var.get()} → Tiếng Việt) "
              f"bằng {TRANSLATE_PROVIDER or 'Claude'} — {len(chapters)} chương", "#7ec8ff")
    threading.Thread(
        target=_manga_translate_worker,
        args=(chapters, lang, out_fmt, write_script, helper, ocr_py, src),
        daemon=True).start()


def _manga_tr_ocr_chapter(helper, ocr_py, imgs, lang, log_cb):
    """Chạy manga_ocr_helper cho 1 chương → list pages (dict). None nếu lỗi/dừng."""
    import tempfile
    td = tempfile.mkdtemp(prefix="mocr_")
    in_json = os.path.join(td, "imgs.json")
    out_json = os.path.join(td, "out.json")
    try:
        with open(in_json, "w", encoding="utf-8") as f:
            json.dump(imgs, f, ensure_ascii=False)
        cmd = [ocr_py, helper, "--images-json", in_json, "--out-json", out_json,
               "--lang", lang, "--device", "auto"]
        proc = subprocess.Popen(
            cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, encoding="utf-8", errors="replace",
            creationflags=CREATE_NO_WINDOW)
        _MANGA_TR_PROC[0] = proc
        for line in proc.stdout:
            line = line.rstrip()
            if not line:
                continue
            if line.startswith("PROGRESS:"):
                try:
                    _, d, t = line.split(":")
                    update_progress(int(d), int(t))
                except Exception:
                    pass
            elif line.startswith("PROGRESS_MSG:"):
                log_cb(f"   ℹ {line.split(':', 1)[1]}")
            elif line.startswith("WARN:"):
                log_cb(f"   ⚠ {line.split(':', 1)[1]}")
            elif line.startswith("ERROR:"):
                log_cb(f"   ❌ OCR: {line.split(':', 1)[1]}")
            elif line.startswith("DONE:"):
                pass
        proc.wait()
        _MANGA_TR_PROC[0] = None
        if _MANGA_STOP[0]:
            return None
        if proc.returncode not in (0, None) or not os.path.isfile(out_json):
            return None
        with open(out_json, "r", encoding="utf-8") as f:
            return json.load(f).get("pages", [])
    except Exception as e:
        log_cb(f"   ❌ Lỗi OCR chương: {e}")
        return None
    finally:
        _MANGA_TR_PROC[0] = None
        try:
            import shutil as _sh
            _sh.rmtree(td, ignore_errors=True)
        except Exception:
            pass


# Block credit/watermark của nhóm scan (URL, discord, tên staff QC/translator...)
# — dịch mấy dòng này chỉ sinh miếng vá trắng đè bậy lên tranh; bỏ qua = giữ nguyên.
_MANGA_TR_SKIP_RE = re.compile(
    r"(?i)(https?:|www\.|\.com\b|\.net\b|\.gg\b|discord|patreon|scans\b|"
    r"scanlat|\bstudio\b|translat|proofread|typeset|cleaner|redraw|"
    r"\bqc\b|raw provider|\bcredits?\b)")

def _manga_tr_skip_block(text):
    return bool(_MANGA_TR_SKIP_RE.search(text or ""))


def _manga_translate_worker(chapters, lang, out_fmt, write_script, helper, ocr_py, root):
    def log_cb(m):
        app.after(0, lambda: log(m))

    font_path = _find_unicode_font()
    if not font_path:
        log_cb("⚠ Không thấy font Unicode — chữ Việt có thể thiếu dấu.")
    out_root = manga_tr_out_var.get().strip() or os.path.join(root, "_vi")
    done_ch = 0
    try:
        for ch_name, imgs in chapters:
            if _MANGA_STOP[0]:
                break
            log_color(f"📖 Chương: {ch_name} ({len(imgs)} trang)", "#9ad27e")
            pages = _manga_tr_ocr_chapter(helper, ocr_py, imgs, lang, log_cb)
            if _MANGA_STOP[0]:
                break
            if pages is None:
                log_cb(f"   ❌ Bỏ qua chương {ch_name} (OCR lỗi).")
                continue
            # Gom toàn bộ text của chương → dịch 1 lần (giữ ngữ cảnh, ít gọi API).
            # Block credit/URL bị bỏ qua: không dịch + không vá (giữ nguyên tranh).
            flat, index = [], []   # index[k] = (page_i, block_i)
            n_skip = 0
            for pi, pg in enumerate(pages):
                for bi, blk in enumerate(pg.get("blocks", [])):
                    if _manga_tr_skip_block(blk["text"]):
                        n_skip += 1
                        continue
                    flat.append(blk["text"])
                    index.append((pi, bi))
            if not flat:
                log_cb(f"   ⚠ Không OCR ra chữ nào ở chương {ch_name}.")
                continue
            log_cb(f"   🌐 Dịch {len(flat)} cụm thoại..."
                   + (f" (bỏ qua {n_skip} block credit/watermark)" if n_skip else ""))
            translated = _translate_segments(
                flat, _translate_default_context(),
                progress_cb=lambda d, t: update_progress(d, t), log_cb=log_cb)
            if _MANGA_STOP[0]:
                break
            # map kết quả về đúng CHỈ SỐ block ("" = bỏ qua → render không vá)
            per_page = {pi: [""] * len(pg.get("blocks", []))
                        for pi, pg in enumerate(pages)}
            for k, (pi, bi) in enumerate(index):
                per_page[pi][bi] = translated[k]
            ch_out_dir = os.path.join(out_root, ch_name)
            out_imgs = []
            for pi, pg in enumerate(pages):
                if _MANGA_STOP[0]:
                    break
                blocks = pg.get("blocks", [])
                vis = per_page.get(pi, [])
                base = os.path.basename(pg["image"])
                op = os.path.join(ch_out_dir, base)
                if _manga_tr_render_page(pg["image"], blocks, vis, op,
                                         font_path, log_cb):
                    out_imgs.append(op)
            # file script đối chiếu
            if write_script and flat:
                try:
                    sp = os.path.join(ch_out_dir, "_script_dich.txt")
                    os.makedirs(ch_out_dir, exist_ok=True)
                    with open(sp, "w", encoding="utf-8") as f:
                        for k, (pi, bi) in enumerate(index):
                            f.write(f"[Trang {pi+1}] {flat[k]}\n   → {translated[k]}\n\n")
                    log_cb(f"   📝 Script: {sp}")
                except Exception as e:
                    log_cb(f"   ⚠ Lỗi ghi script: {e}")
            # đóng gói PDF/CBZ nếu chọn
            if out_imgs and out_fmt == "PDF mỗi chương":
                _manga_imgs_to_pdf(out_imgs, ch_out_dir + ".pdf", log_cb)
            elif out_imgs and out_fmt == "CBZ mỗi chương":
                _manga_imgs_to_cbz(out_imgs, ch_out_dir + ".cbz", log_cb)
            done_ch += 1
            log_color(f"   ✅ Xong chương {ch_name} → {ch_out_dir}", "#9ad27e")
        if _MANGA_STOP[0]:
            log_color(f"⏹ Đã dừng. Dịch xong {done_ch} chương.", "#ffcf6e")
        else:
            log_color(f"🎉 Dịch truyện hoàn tất: {done_ch} chương → {out_root}", "#9ad27e")
            app.after(0, show_fireworks)
            try:
                app.after(0, lambda: os.startfile(out_root)
                          if os.path.isdir(out_root) else None)
            except Exception:
                pass
    except Exception as e:
        log_cb(f"❌ Lỗi dịch truyện: {e}")
    finally:
        _MANGA_TR_RUNNING[0] = False
        _MANGA_TR_PROC[0] = None
        app.after(0, lambda: _manga_tr_set_running(False))
        app.after(0, lambda: update_progress(0, 1))


