# WAV fireworks ở module-level để play_fireworks_sound() dùng độc lập.
_FIREWORKS_WAV_B64 = (
    ""
)


def play_fireworks_sound():
    """Phát âm thanh fireworks (không hiện visual), không phụ thuộc show_fireworks()."""
    def _do():
        try:
            import winsound, base64 as _b64, tempfile
            wav = _FIREWORKS_WAV_B64
            if not wav:
                return
            wav_data = _b64.b64decode(wav)
            tmp = tempfile.NamedTemporaryFile(suffix=".wav", delete=False)
            tmp.write(wav_data); tmp.flush(); tmp.close()
            winsound.PlaySound(tmp.name, winsound.SND_FILENAME)
            try: os.unlink(tmp.name)
            except Exception: pass
        except Exception:
            pass
    threading.Thread(target=_do, daemon=True).start()


def _notify_windows(title, body):
    """Bắn toast notification Windows (PowerShell WinRT, không cần lib ngoài).
    Chỉ dùng khi app không ở foreground — gọi qua _notify_if_background().
    Mọi lỗi nuốt im lặng (thông báo không bao giờ được làm hỏng luồng chính)."""
    try:
        import html as _html
        t, b = _html.escape(title), _html.escape(body)
        ps = (
            "[Windows.UI.Notifications.ToastNotificationManager, "
            "Windows.UI.Notifications, ContentType = WindowsRuntime] > $null\n"
            "[Windows.Data.Xml.Dom.XmlDocument, "
            "Windows.Data.Xml.Dom.XmlDocument, ContentType = WindowsRuntime] > $null\n"
            "$x = New-Object Windows.Data.Xml.Dom.XmlDocument\n"
            "$x.LoadXml('<toast><visual><binding template=\"ToastGeneric\">"
            f"<text>{t}</text><text>{b}</text>"
            "</binding></visual></toast>')\n"
            "[Windows.UI.Notifications.ToastNotificationManager]::"
            "CreateToastNotifier('SRT TTS Studio').Show("
            "[Windows.UI.Notifications.ToastNotification]::new($x))"
        )
        subprocess.Popen(
            ["powershell", "-NoProfile", "-NonInteractive", "-Command", ps],
            creationflags=CREATE_NO_WINDOW,
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass


def _notify_if_background(body="✅ Hoàn tất!"):
    """Toast khi cửa sổ đang thu nhỏ / mất focus (job nền xong mà người dùng
    đang làm việc khác). App ở foreground → pháo hoa + âm thanh là đủ."""
    try:
        if app.state() == "iconic" or app.focus_displayof() is None:
            _notify_windows("SRT TTS Studio", body)
    except Exception:
        pass


def _notify_webhook():
    """📨 POST thông báo hoàn tất tới webhook (Discord/Telegram/tự dựng) nếu
    NOTIFY_WEBHOOK_URL được cấu hình — batch đêm/watch folder khỏi ngồi canh.
    JSON gửi cả "content" (Discord) lẫn "text" (Telegram sendMessage — dán URL
    kèm ?chat_id=...). Chạy thread riêng, mọi lỗi nuốt — không được chặn app."""
    url = (globals().get("NOTIFY_WEBHOOK_URL") or "").strip()
    if not url:
        return

    parts = ["✅ SRT TTS Studio: hoàn tất!"]
    try:
        rep = _LAST_MERGE_REPORT
        if rep.get("lines"):
            parts.append(f"{rep['lines']}/{rep.get('total', '?')} dòng merge")
    except Exception:
        pass
    try:
        if FAIL_COUNT:
            parts.append(f"{FAIL_COUNT} FAIL")
    except Exception:
        pass
    msg_text = " — ".join(parts)

    def _post():
        try:
            body = json.dumps({"content": msg_text, "text": msg_text}).encode("utf-8")
            req = urllib.request.Request(url, data=body)
            req.add_header("content-type", "application/json")
            with urllib.request.urlopen(req, timeout=15):
                pass
        except Exception:
            pass
    threading.Thread(target=_post, daemon=True).start()


def show_fireworks():
    """Hiển thị overlay pháo hoa toàn màn hình trong 3 giây, kèm âm thanh."""
    _notify_if_background()
    _notify_webhook()

    def _play_sound():
        try:
            import winsound
            import base64
            import tempfile
            wav_data = base64.b64decode(_FIREWORKS_WAV_B64)
            tmp = tempfile.NamedTemporaryFile(suffix=".wav", delete=False)
            tmp.write(wav_data)
            tmp.flush()
            tmp.close()
            winsound.PlaySound(tmp.name, winsound.SND_FILENAME)
            try:
                os.unlink(tmp.name)
            except Exception:
                pass
        except Exception:
            pass

    threading.Thread(target=_play_sound, daemon=True).start()

    sw = app.winfo_screenwidth()
    sh = app.winfo_screenheight()

    overlay = tk.Toplevel(app)
    overlay.overrideredirect(True)
    overlay.attributes("-topmost", True)
    overlay.attributes("-transparentcolor", "black")
    overlay.geometry(f"{sw}x{sh}+0+0")
    overlay.configure(bg="black")

    canvas = tk.Canvas(overlay, width=sw, height=sh,
                       bg="black", highlightthickness=0)
    canvas.pack()

    COLORS = ["#ff4444", "#ff9900", "#ffff00", "#44ff44",
              "#44ccff", "#cc44ff", "#ff44cc", "#ffffff",
              "#ff6688", "#aaffaa", "#ffcc00", "#00ffcc"]

    class Particle:
        __slots__ = ("x", "y", "vx", "vy", "color", "life", "max_life", "size")
        def __init__(self, x, y, vx, vy, color, life, size=3):
            self.x, self.y = x, y
            self.vx, self.vy = vx, vy
            self.color = color
            self.life = self.max_life = life
            self.size = size

    class Rocket:
        def __init__(self):
            self.x = random.randint(sw // 6, sw * 5 // 6)
            self.y = sh
            self.tx = random.randint(sw // 6, sw * 5 // 6)
            self.ty = random.randint(int(sh * 0.1), int(sh * 0.5))
            dist = math.hypot(self.tx - self.x, self.ty - self.y)
            speed = random.uniform(18, 28)
            self.vx = (self.tx - self.x) / dist * speed
            self.vy = (self.ty - self.y) / dist * speed
            self.color = random.choice(COLORS)
            self.exploded = False
            self.trail = []

        def update(self):
            if self.exploded:
                return False
            self.trail.append((self.x, self.y))
            if len(self.trail) > 6:
                self.trail.pop(0)
            self.x += self.vx
            self.y += self.vy
            self.vy += 0.5
            if self.vy >= 0 or math.hypot(self.x - self.tx, self.y - self.ty) < 20:
                self.exploded = True
            return True

    particles = []
    rockets = []
    start_ms = [None]
    DURATION_MS = 3000

    def _explode(rx, ry, color):
        n = random.randint(60, 100)
        for _ in range(n):
            angle = random.uniform(0, math.pi * 2)
            speed = random.uniform(2, 9)
            vx = math.cos(angle) * speed
            vy = math.sin(angle) * speed
            life = random.randint(25, 45)
            size = random.uniform(2, 4)
            c = color if random.random() > 0.3 else random.choice(COLORS)
            particles.append(Particle(rx, ry, vx, vy, c, life, size))

    def _animate():
        now = int(overlay.tk.call("clock", "milliseconds"))
        if start_ms[0] is None:
            start_ms[0] = now

        elapsed = now - start_ms[0]
        if elapsed >= DURATION_MS:
            try:
                overlay.destroy()
            except Exception:
                pass
            return

        canvas.delete("all")

        if random.random() < 0.25:
            rockets.append(Rocket())

        for r in rockets[:]:
            alive = r.update()
            if not alive or r.exploded:
                _explode(r.x, r.y, r.color)
                rockets.remove(r)
                continue
            for i, (tx, ty) in enumerate(r.trail):
                alpha_size = max(1, i)
                canvas.create_oval(
                    tx - alpha_size, ty - alpha_size,
                    tx + alpha_size, ty + alpha_size,
                    fill=r.color, outline="")
            canvas.create_oval(
                r.x - 3, r.y - 3, r.x + 3, r.y + 3,
                fill="white", outline="")

        for p in particles[:]:
            p.x += p.vx
            p.y += p.vy
            p.vy += 0.15
            p.vx *= 0.97
            p.life -= 1
            if p.life <= 0:
                particles.remove(p)
                continue
            ratio = p.life / p.max_life
            sz = max(1, p.size * ratio)
            canvas.create_oval(
                p.x - sz, p.y - sz, p.x + sz, p.y + sz,
                fill=p.color, outline="")

        fade = min(1.0, (DURATION_MS - elapsed) / 500)
        g_val = int(255 * fade)
        b_val = int(200 * fade)
        text_color = f"#{g_val:02x}ff{b_val:02x}"
        canvas.create_text(
            sw // 2, sh // 2,
            text="✓ DONE!",
            font=("Arial", 52, "bold"),
            fill=text_color)

        overlay.after(30, _animate)

    overlay.after(10, _animate)


