# ── MRU giọng: 5 voice dùng gần nhất ghim đầu dropdown ───────────────────────
# Edge có hàng trăm voice — khỏi cuộn tìm lại. Lưu qua phiên trong ui_prefs.json
# (khóa "_mru_voices", xử lý riêng trong _ui_prefs_save/load vì là list thường).
_MRU_VOICES = []   # [(provider, voice)] — mới nhất đứng trước, tối đa 5

def _mru_voice_add(provider, voice):
    key = (provider, voice)
    try:
        _MRU_VOICES.remove(key)
    except ValueError:
        pass
    _MRU_VOICES.insert(0, key)
    del _MRU_VOICES[5:]

def _voice_menu_values(provider):
    """Danh sách voice cho dropdown: MRU của provider này ghim lên đầu."""
    voices = VOICE_LISTS.get(provider, [])
    mru = [v for p, v in _MRU_VOICES if p == provider and v in voices]
    return mru + [v for v in voices if v not in mru]


def open_voice_search_dialog():
    """🔎 Tìm giọng trong danh sách provider hiện tại (Edge ~hàng trăm giọng):
    gõ để lọc realtime, double-click hoặc nút Chọn để áp dụng."""
    voices = VOICE_LISTS.get(TTS_PROVIDER, [])
    if not voices:
        log("Không có danh sách giọng cho provider hiện tại.")
        return
    win = ctk.CTkToplevel(app)
    win.title(f"🔎 Tìm giọng — {TTS_PROVIDER} ({len(voices)} giọng)")
    win.geometry("440x500")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    v_filter = ctk.StringVar(value="")
    ent = ctk.CTkEntry(win, textvariable=v_filter, font=("Arial", 13),
                       placeholder_text="Gõ để lọc: vi / female / ja-JP ...")
    ent.pack(fill="x", padx=12, pady=(12, 6))

    lb = tk.Listbox(win, font=("Consolas", 11), activestyle="dotbox",
                    bg="#1d1e1e", fg="#e8e8e8", selectbackground="#1F6AA5",
                    highlightthickness=0, borderwidth=0)
    lb.pack(fill="both", expand=True, padx=12, pady=4)

    def _refresh(*_a):
        q = v_filter.get().strip().lower()
        lb.delete(0, "end")
        for v in voices:
            if q in v.lower():
                lb.insert("end", v)
    v_filter.trace_add("write", _refresh)
    _refresh()

    def _choose(_e=None):
        sel = lb.curselection()
        if not sel:
            return
        v = lb.get(sel[0])
        voice_var.set(v)
        set_voice(v)
        win.destroy()
    lb.bind("<Double-Button-1>", _choose)
    ctk.CTkButton(win, text="✔ Chọn giọng này", command=_choose, height=38,
                  fg_color="#2fa572", hover_color="#37b87f",
                  font=("Arial", 13, "bold")).pack(fill="x", padx=12, pady=(4, 12))
    ent.focus_set()


def set_voice(v):
    global VOICE
    VOICE = v
    _mru_voice_add(TTS_PROVIDER, v)
    try:
        voice_menu.configure(values=_voice_menu_values(TTS_PROVIDER))
    except Exception:
        pass
    log(f"VOICE -> {v}")


def set_provider(provider):
    global TTS_PROVIDER, VOICE
    TTS_PROVIDER = provider
    voices = _voice_menu_values(provider)   # MRU đầu tiên = voice dùng gần nhất
    voice_menu.configure(values=voices)
    if voices:
        VOICE = voices[0]
        voice_var.set(voices[0])
    if provider == "Edge TTS":
        voice_row2.pack_forget()
    else:
        voice_row2.pack(fill="x", padx=2, pady=(0, 4))
    log(f"Provider -> {provider}  |  Voice -> {VOICE}")


# =========================
# DỊCH PHỤ ĐỀ / PDF SANG TIẾNG VIỆT (LLM: Claude / Gemini / OpenAI)
# =========================

_TR_MARK_RE = re.compile(r"\[\[(\d+)\]\]\s*(.*)", re.S)


def _translate_active_key():
    """Trả về (provider, api_key, model) đang dùng. Raise nếu thiếu key."""
    provider = TRANSLATE_PROVIDER or "Claude"
    key_map = {
        "Claude": ANTHROPIC_API_KEY,
        "Gemini": GEMINI_API_KEY,
        "OpenAI": OPENAI_API_KEY,
        "Groq": GROQ_API_KEY,
        "DeepSeek": DEEPSEEK_API_KEY,
    }
    api_key = (key_map.get(provider) or "").strip()
    if not api_key:
        raise RuntimeError(
            f"Chưa nhập API key cho {provider}. Vào ⚙ Cài đặt để nhập.")
    model = (TRANSLATE_MODEL or "").strip() or _TRANSLATE_DEFAULT_MODEL[provider]
    return provider, api_key, model


def _llm_call_claude(api_key, model, system, user):
    body = json.dumps({
        "model": model,
        "max_tokens": 8192,
        "system": system,
        "messages": [{"role": "user", "content": user}],
    }).encode("utf-8")
    req = urllib.request.Request("https://api.anthropic.com/v1/messages", data=body)
    req.add_header("x-api-key", api_key)
    req.add_header("anthropic-version", "2023-06-01")
    req.add_header("content-type", "application/json")
    with urllib.request.urlopen(req, timeout=180) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    return "".join(b.get("text", "") for b in data.get("content", []))


def _llm_call_gemini(api_key, model, system, user):
    url = (f"https://generativelanguage.googleapis.com/v1beta/models/"
           f"{model}:generateContent?key={urllib.parse.quote(api_key)}")
    body = json.dumps({
        "systemInstruction": {"parts": [{"text": system}]},
        "contents": [{"role": "user", "parts": [{"text": user}]}],
        "generationConfig": {"temperature": 0.3, "maxOutputTokens": 8192},
    }).encode("utf-8")
    req = urllib.request.Request(url, data=body)
    req.add_header("content-type", "application/json")
    with urllib.request.urlopen(req, timeout=180) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    cands = data.get("candidates", [])
    if not cands:
        raise RuntimeError(f"Gemini không trả kết quả: {str(data)[:200]}")
    parts = cands[0].get("content", {}).get("parts", [])
    return "".join(p.get("text", "") for p in parts)


def _llm_call_openai(api_key, model, system, user,
                     url="https://api.openai.com/v1/chat/completions"):
    """Chat-completions chuẩn OpenAI — Groq/DeepSeek dùng chung, chỉ khác url."""
    body = json.dumps({
        "model": model,
        "temperature": 0.3,
        "messages": [
            {"role": "system", "content": system},
            {"role": "user", "content": user},
        ],
    }).encode("utf-8")
    req = urllib.request.Request(url, data=body)
    req.add_header("Authorization", f"Bearer {api_key}")
    req.add_header("content-type", "application/json")
    with urllib.request.urlopen(req, timeout=180) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    return data["choices"][0]["message"]["content"]


def _llm_call(provider, api_key, model, system, user):
    if provider == "Claude":
        return _llm_call_claude(api_key, model, system, user)
    if provider == "Gemini":
        return _llm_call_gemini(api_key, model, system, user)
    if provider in _OPENAI_COMPAT_URL:   # OpenAI / Groq / DeepSeek
        return _llm_call_openai(api_key, model, system, user,
                                url=_OPENAI_COMPAT_URL[provider])
    raise RuntimeError(f"Provider không hợp lệ: {provider}")


def _abortable_llm_call(provider, api_key, model, system, user):
    """Gọi LLM trong thread phụ và poll cờ TRANSLATE_STOP mỗi 0.15s.
    Cho phép Dừng hẳn ngay giữa lúc đang chờ API (không phải đợi hết batch).
    Trả về (raw, aborted). aborted=True nếu bị dừng → bỏ qua kết quả call này."""
    box = {}
    def _c():
        try:
            box["raw"] = _llm_call(provider, api_key, model, system, user)
        except Exception as e:
            box["err"] = e
    th = threading.Thread(target=_c, daemon=True)
    th.start()
    while th.is_alive():
        if TRANSLATE_STOP:
            return None, True   # bỏ call đang chạy dở (thread daemon tự kết thúc)
        time.sleep(0.15)
    if "err" in box:
        raise box["err"]
    return box.get("raw", ""), False


# Ngôn ngữ đích của bước dịch (cloud LLM). Mặc định Tiếng Việt — chọn ngôn ngữ
# khác là mở đường dub NGƯỢC (video Việt → Anh/Nhật/...; Edge có giọng ~70 thứ
# tiếng). Provider Offline (NLLB/envit5) chỉ dịch sang tiếng Việt — bị bỏ qua.
_TRANSLATE_TARGETS = {
    "Tiếng Việt": "tiếng Việt",
    "English": "English (tiếng Anh)",
    "中文": "tiếng Trung giản thể (中文)",
    "日本語": "tiếng Nhật (日本語)",
    "한국어": "tiếng Hàn (한국어)",
    "Français": "tiếng Pháp (français)",
    "Español": "tiếng Tây Ban Nha (español)",
    "ไทย": "tiếng Thái (ไทย)",
    "Bahasa Indonesia": "tiếng Indonesia",
}

def _translate_target():
    """Tên ngôn ngữ đích hiện chọn (label); lỗi/chưa có UI → Tiếng Việt."""
    try:
        t = translate_target_var.get()
        return t if t in _TRANSLATE_TARGETS else "Tiếng Việt"
    except Exception:
        return "Tiếng Việt"


def _translate_system_prompt(context):
    target = _translate_target()
    tdesc = _TRANSLATE_TARGETS[target]
    if target == "Tiếng Việt":
        sys_p = (
            "Bạn là dịch giả phụ đề phim chuyên nghiệp người Việt. "
            "Dịch sang tiếng Việt TỰ NHIÊN, đúng văn phong nói của người Việt, "
            "không dịch word-by-word, giữ đúng sắc thái (trang trọng/suồng sã/đùa/mỉa mai). "
            "Chọn đại từ xưng hô (tôi/anh/em/cậu/tớ/ông/bà...) cho hợp ngữ cảnh và nhất quán. "
            "Giữ nguyên tên riêng, thuật ngữ không cần dịch."
        )
    else:
        sys_p = (
            "Bạn là dịch giả phụ đề phim chuyên nghiệp. "
            f"Dịch sang {tdesc} TỰ NHIÊN, đúng văn phong hội thoại của người bản ngữ, "
            "không dịch word-by-word, giữ đúng sắc thái (trang trọng/suồng sã/đùa/mỉa mai), "
            "xưng hô/kính ngữ nhất quán theo chuẩn ngôn ngữ đích. "
            "Giữ nguyên tên riêng, thuật ngữ không cần dịch."
        )
    if context.strip():
        sys_p += f"\n\nNgữ cảnh / quan hệ nhân vật / xưng hô do người dùng cung cấp:\n{context.strip()}"
    # Tên riêng/thuật ngữ trong Từ điển phát âm → buộc giữ NGUYÊN khi dịch:
    # tên nhất quán xuyên suốt phim (LLM hay dịch trôi nổi mỗi batch một kiểu)
    # và khớp với cách đọc TTS đã định nghĩa cho chính các từ đó.
    try:
        if GLOSSARY:
            _terms = ", ".join(sorted(GLOSSARY.keys())[:60])
            sys_p += ("\n\nDanh sách tên riêng/thuật ngữ PHẢI GIỮ NGUYÊN "
                      f"không dịch, viết đúng chính tả như sau: {_terms}")
    except Exception:
        pass
    sys_p += (
        "\n\nĐầu vào gồm nhiều dòng, mỗi dòng có dạng [[n]] nội_dung. "
        f"Hãy dịch phần nội_dung của TỪNG dòng sang {tdesc} và trả về ĐÚNG định dạng "
        "[[n]] bản_dịch, đúng số dòng, đúng thứ tự, KHÔNG thêm giải thích, "
        "KHÔNG gộp dòng, KHÔNG bỏ dòng. Giữ nguyên số n của mỗi dòng."
    )
    return sys_p


def _parse_marked(text, n_expected):
    """Phân tích đầu ra [[n]] ... → dict {idx0: translation}. idx tính từ 0."""
    out = {}
    # tách theo marker [[number]]
    chunks = re.split(r"\[\[(\d+)\]\]", text)
    # chunks: ['', '1', ' a', '2', ' b', ...]
    i = 1
    while i < len(chunks) - 0:
        if i + 1 <= len(chunks) - 1:
            try:
                num = int(chunks[i])
            except ValueError:
                i += 2
                continue
            val = chunks[i + 1].strip()
            if 1 <= num <= n_expected:
                out[num - 1] = val
            i += 2
        else:
            break
    return out


def _find_translate_helper():
    """Tìm translate_helper.py theo thứ tự ưu tiên (giống các helper khác)."""
    name = 'translate_helper.py'
    search = [
        getattr(sys, '_MEIPASS', None),
        os.path.dirname(__file__) if '__file__' in globals() else None,
        os.path.dirname(sys.argv[0]),
        os.path.dirname(sys.executable),
    ]
    for d in search:
        if d:
            p = os.path.join(d, name)
            if os.path.isfile(p):
                return p
    return None


def _translate_segments_local(segments, progress_cb=None, log_cb=None):
    """Dịch offline qua translate_helper.py (voxcpm_env python + transformers)."""
    model_dir = (LOCAL_TRANSLATE_MODEL_DIR or "").strip()
    if not model_dir:
        raise RuntimeError("Chưa chọn model offline. Vào ⚙ Cài đặt → 'Thư mục model offline'.")
    helper = _find_translate_helper()
    if not helper:
        raise RuntimeError("Không tìm thấy translate_helper.py cạnh app/exe.")
    # env: ưu tiên env dịch riêng (TRANSLATE_ENV_OVERRIDE) → voxcpm_env
    py = ""
    if TRANSLATE_ENV_OVERRIDE and os.path.isfile(TRANSLATE_ENV_OVERRIDE):
        py = TRANSLATE_ENV_OVERRIDE
    if not py:
        py = _find_voxcpm_python(model_dir if os.path.isdir(model_dir) else os.getcwd())
    if not py:
        py = _find_voxcpm_python((voxcpm_ckpt_var.get() or "").strip() or os.getcwd())
    if not py:
        raise RuntimeError("Không tìm thấy python để dịch (cần torch+transformers). "
                           "Đặt ở ⚙ Cài đặt → 'Python env dịch (riêng)' hoặc 'voxcpm_env python.exe'.")

    import tempfile
    tin = os.path.join(tempfile.gettempdir(), '_tr_in.json')
    tout = os.path.join(tempfile.gettempdir(), '_tr_out.json')
    with open(tin, 'w', encoding='utf-8') as f:
        json.dump({'segments': segments}, f, ensure_ascii=False)

    src_lang = (LOCAL_TRANSLATE_SRC_LANG or 'eng_Latn').strip() or 'eng_Latn'
    cmd = [py, helper, '--model', model_dir, '--input', tin, '--output', tout,
           '--src-lang', src_lang, '--tgt-lang', 'vie_Latn']
    if log_cb:
        log_cb(f"🖥️ Dịch offline: {os.path.basename(model_dir.rstrip(os.sep))} "
               f"(nguồn: {src_lang}) — {len(segments)} dòng/đoạn")
        log_cb("   (lần đầu có thể tải/nạp model, vui lòng đợi...)")

    global _TRANSLATE_PROC
    # stdin=PIPE để gửi lệnh PAUSE/RESUME/STOP cho helper
    proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT,
                            text=True, encoding='utf-8', errors='replace',
                            creationflags=CREATE_NO_WINDOW)
    _TRANSLATE_PROC = proc
    # Nếu người dùng đã bấm Tạm dừng trước khi proc kịp khởi động → áp dụng ngay
    if TRANSLATE_PAUSED:
        _translate_send_proc("PAUSE")
    last_err = ""
    try:
        for line in proc.stdout:
            line = line.strip()
            if not line:
                continue
            if line.startswith('PROGRESS:'):
                parts = line.split(':')
                try:
                    if progress_cb:
                        progress_cb(int(parts[1]), int(parts[2]))
                except Exception:
                    pass
            elif line.startswith('AUTODETECT:'):
                if log_cb:
                    log_cb(f"🔎 Tự động nhận diện ngôn ngữ nguồn: {line.split(':', 1)[1]}")
            elif line == 'STOPPED':
                if log_cb:
                    log_cb("⏹ Đã dừng (offline) — giữ phần đã dịch.")
            elif line.startswith('LOAD_ERR') or line.startswith('IMPORT_ERR') or line.startswith('BATCH_ERR'):
                last_err = line
                if log_cb:
                    log_cb(f"⚠️ {line}")
            # các dòng log model khác (Loading.../tải về) bỏ qua
        proc.wait()
    finally:
        _TRANSLATE_PROC = None
    if proc.returncode != 0:
        if last_err:
            raise RuntimeError(last_err)
        raise RuntimeError(f"translate_helper lỗi (mã {proc.returncode}). "
                           f"Kiểm tra thư mục model offline có đúng là model DỊCH "
                           f"(NLLB/envit5), KHÔNG phải VoxCPM/whisper.")
    with open(tout, encoding='utf-8') as f:
        translations = json.load(f).get('translations', [])
    for _p in (tin, tout):
        try:
            os.remove(_p)
        except Exception:
            pass
    # đảm bảo đủ độ dài (an toàn)
    if len(translations) < len(segments):
        translations = list(translations) + list(segments[len(translations):])
    return translations[:len(segments)]


def _translate_segments(segments, context, progress_cb=None, log_cb=None):
    """Dịch list[str] → list[str] cùng độ dài. Online (LLM) hoặc offline (local)."""
    if (TRANSLATE_PROVIDER or "") == "Offline":
        if context.strip() and log_cb:
            log_cb("ℹ️ Model offline không dùng ô ngữ cảnh/xưng hô "
                   "(chỉ áp dụng cho Claude/Gemini/OpenAI).")
        if _translate_target() != "Tiếng Việt" and log_cb:
            log_cb("ℹ️ Dịch Offline chỉ hỗ trợ đích TIẾNG VIỆT — "
                   "muốn dịch sang ngôn ngữ khác hãy dùng Claude/Gemini/OpenAI.")
        return _translate_segments_local(segments, progress_cb, log_cb)
    if _translate_target() != "Tiếng Việt" and log_cb:
        log_cb(f"🌍 Ngôn ngữ đích: {_translate_target()} — nhớ chọn GIỌNG ĐỌC "
               "cùng ngôn ngữ ở tab Giọng nói nếu định TTS bản dịch.")
    provider, api_key, model = _translate_active_key()
    if log_cb:
        log_cb(f"🌐 Dịch bằng {provider} ({model}) — {len(segments)} dòng/đoạn...")
    system = _translate_system_prompt(context)
    result = [None] * len(segments)
    total = len(segments)
    done = 0
    for start in range(0, total, _TRANSLATE_BATCH):
        # Tạm dừng: chờ RESUME/STOP
        while TRANSLATE_PAUSED and not TRANSLATE_STOP:
            time.sleep(0.2)
        # Dừng hẳn: thoát, phần chưa dịch giữ nguyên gốc
        if TRANSLATE_STOP:
            if log_cb:
                log_cb(f"⏹ Đã dừng. Dịch được {done}/{total}.")
            break
        batch = segments[start:start + _TRANSLATE_BATCH]
        user = "\n".join(f"[[{j+1}]] {t}" for j, t in enumerate(batch))
        try:
            raw, aborted = _abortable_llm_call(provider, api_key, model, system, user)
            if aborted:
                break
            parsed = _parse_marked(raw, len(batch))
        except Exception as e:
            if log_cb:
                log_cb(f"⚠️ Lỗi batch {start//_TRANSLATE_BATCH+1}: {e} — thử lại từng dòng")
            parsed = {}
        # điền kết quả, dòng nào thiếu → dịch lẻ
        _aborted_inner = False
        for j, src in enumerate(batch):
            if TRANSLATE_STOP:
                _aborted_inner = True
                break
            tr = parsed.get(j)
            if tr is None or tr == "":
                try:
                    one, aborted = _abortable_llm_call(provider, api_key, model, system,
                                                       f"[[1]] {src}")
                    if aborted:
                        _aborted_inner = True
                        break
                    tr = _parse_marked(one, 1).get(0) or src
                except Exception as e:
                    if log_cb:
                        log_cb(f"⚠️ Không dịch được dòng {start+j+1}: {e}")
                    tr = src  # giữ nguyên bản gốc để không mất nội dung
            result[start + j] = tr
            done += 1
            if progress_cb:
                progress_cb(done, total)
        if _aborted_inner or TRANSLATE_STOP:
            if log_cb:
                log_cb(f"⏹ Đã dừng. Dịch được {done}/{total}.")
            break
    # Phần chưa dịch (do dừng) → giữ nguyên bản gốc để không mất nội dung
    for k in range(total):
        if result[k] is None:
            result[k] = segments[k]
    return result


def _translate_default_context():
    """Lấy context xưng hô từ ô nhập (nếu UI đã tạo)."""
    try:
        return translate_context_var.get()
    except Exception:
        return ""


def _make_translate_progress_cb():
    """Tạo callback tiến trình: cập nhật thanh tiến trình + log chữ trong logbox
    (giới hạn mỗi mốc 10% để khỏi tràn log). Dùng chung cho cả AI online và offline."""
    state = {"last": -1}
    def _cb(d, t):
        update_progress(d, t)
        if not t:
            return
        pct = d * 100 // t
        milestone = pct // 10
        if d >= t or milestone > state["last"]:
            state["last"] = milestone
            app.after(0, lambda dd=d, tt=t, pp=pct: log(f"   ⏳ Đã dịch {dd}/{tt} ({pp}%)"))
    return _cb


def _reveal_output(path):
    """Mở File Explorer và chọn file output vừa lưu."""
    try:
        subprocess.Popen(["explorer", "/select,", os.path.abspath(path)])
    except Exception:
        try:
            os.startfile(os.path.dirname(os.path.abspath(path)))
        except Exception:
            pass


def _translate_send_proc(cmd):
    """Gửi lệnh điều khiển (PAUSE/RESUME/STOP) tới subprocess dịch offline đang chạy."""
    p = _TRANSLATE_PROC
    if p is not None and p.poll() is None and p.stdin:
        try:
            p.stdin.write(cmd + "\n")
            p.stdin.flush()
        except Exception:
            pass


def _set_translate_buttons(state):
    """Bật/tắt cả 3 nút Dịch (SRT / PDF / Word-TXT) cùng lúc."""
    for _bn in ("btn_translate_srt", "btn_translate_pdf", "btn_translate_doc"):
        b = globals().get(_bn)
        if b is not None:
            try:
                b.configure(state=state)
            except Exception:
                pass


def _translate_set_controls(running):
    """running=True: bật Tạm dừng + Dừng (tắt Tiếp tục). False: tắt cả 3."""
    try:
        if running:
            btn_tr_pause.configure(state="normal")
            btn_tr_resume.configure(state="disabled")
            btn_tr_stop.configure(state="normal")
        else:
            btn_tr_pause.configure(state="disabled")
            btn_tr_resume.configure(state="disabled")
            btn_tr_stop.configure(state="disabled")
    except Exception:
        pass


def _translate_pause():
    global TRANSLATE_PAUSED
    TRANSLATE_PAUSED = True
    _translate_send_proc("PAUSE")
    btn_tr_pause.configure(state="disabled")
    btn_tr_resume.configure(state="normal")
    log("⏸ Tạm dừng dịch.")


def _translate_resume():
    global TRANSLATE_PAUSED
    TRANSLATE_PAUSED = False
    _translate_send_proc("RESUME")
    btn_tr_pause.configure(state="normal")
    btn_tr_resume.configure(state="disabled")
    log("▶ Tiếp tục dịch.")


def _translate_stop():
    global TRANSLATE_STOP, TRANSLATE_PAUSED
    TRANSLATE_STOP = True
    TRANSLATE_PAUSED = False
    _translate_send_proc("STOP")
    btn_tr_pause.configure(state="disabled")
    btn_tr_resume.configure(state="disabled")
    btn_tr_stop.configure(state="disabled")
    log("⏹ Đang dừng dịch... (lưu phần đã dịch)")


def _read_text_smart(path):
    """Đọc file text, tự nhận diện encoding (UTF-16/UTF-8-BOM/UTF-8/CP1258).
    Sửa lỗi 'srt.parse' với file SRT mã hóa UTF-16 (ký tự kèm byte \\x00)."""
    with open(path, "rb") as f:
        raw = f.read()
    if raw[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return raw.decode("utf-16")
    if raw[:3] == b"\xef\xbb\xbf":
        return raw.decode("utf-8-sig")
    # không BOM nhưng có null byte → nhiều khả năng UTF-16 không dấu BOM
    if b"\x00" in raw[:4096]:
        for enc in ("utf-16-le", "utf-16-be"):
            try:
                return raw.decode(enc)
            except Exception:
                pass
    for enc in ("utf-8", "cp1258", "latin-1"):
        try:
            return raw.decode(enc)
        except Exception:
            pass
    return raw.decode("utf-8", errors="replace")


def _find_unicode_font():
    """Tìm 1 font TTF có glyph tiếng Việt trong Windows\\Fonts."""
    fonts_dir = os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts")
    for name in ("arial.ttf", "segoeui.ttf", "times.ttf", "tahoma.ttf", "calibri.ttf"):
        p = os.path.join(fonts_dir, name)
        if os.path.isfile(p):
            return p
    return None


def _write_translated_doc(base, chunks, translated, bilingual, fmt, log_cb=None):
    """Ghi kết quả dịch ra base+.{txt|pdf|docx}. Trả về đường dẫn thật.
    Thiếu thư viện fpdf/docx → tự lùi về .txt (không mất nội dung)."""
    def _pairs():
        for src, tr in zip(chunks, translated):
            yield (src, tr)

    if fmt == "pdf":
        try:
            from fpdf import FPDF
            font_path = _find_unicode_font()
            if not font_path:
                raise RuntimeError("không tìm thấy font Unicode")
            pdf = FPDF()
            pdf.set_auto_page_break(auto=True, margin=15)
            pdf.add_page()
            pdf.add_font("uni", "", font_path)
            for src, tr in _pairs():
                if bilingual:
                    pdf.set_font("uni", size=10)
                    pdf.set_text_color(120, 120, 120)
                    pdf.multi_cell(0, 6, src)
                    pdf.set_text_color(0, 0, 0)
                pdf.set_font("uni", size=12)
                pdf.multi_cell(0, 7, tr)
                pdf.ln(3)
            out_path = base + ".pdf"
            pdf.output(out_path)
            return out_path
        except Exception as e:
            if log_cb:
                log_cb(f"⚠️ Không tạo được PDF ({e}). Lưu .txt thay thế. "
                       f"(Cài thư viện: pip install fpdf2)")
            fmt = "txt"

    if fmt == "docx":
        try:
            from docx import Document
            doc = Document()
            for src, tr in _pairs():
                if bilingual:
                    p = doc.add_paragraph()
                    r = p.add_run(src)
                    r.italic = True
                doc.add_paragraph(tr)
            out_path = base + ".docx"
            doc.save(out_path)
            return out_path
        except Exception as e:
            if log_cb:
                log_cb(f"⚠️ Không tạo được DOCX ({e}). Lưu .txt thay thế. "
                       f"(Cài thư viện: pip install python-docx)")
            fmt = "txt"

    # mặc định / fallback: .txt
    out_path = base + ".txt"
    with open(out_path, "w", encoding="utf-8") as f:
        for src, tr in _pairs():
            if bilingual:
                f.write(src + "\n" + tr + "\n\n")
            else:
                f.write(tr + "\n\n")
    return out_path


# === Thư mục output cho Dịch thuật (rỗng = lưu cạnh file gốc, như cũ) ===
TRANSLATE_OUTPUT_DIR = ""

def _translate_redirect(default_path):
    """Nếu đã chọn thư mục output cho dịch -> đổi sang đó; nếu không giữ nguyên."""
    try:
        if TRANSLATE_OUTPUT_DIR and os.path.isdir(TRANSLATE_OUTPUT_DIR):
            return os.path.join(TRANSLATE_OUTPUT_DIR, os.path.basename(default_path))
    except Exception:
        pass
    return default_path

def choose_translate_output_folder():
    global TRANSLATE_OUTPUT_DIR
    d = filedialog.askdirectory(
        title="Chọn thư mục lưu file dịch (Cancel = để cạnh file gốc)")
    if d:
        TRANSLATE_OUTPUT_DIR = d
        log(f"[Dịch] Thư mục output: {d}")

def open_translate_output_folder():
    try:
        folder = TRANSLATE_OUTPUT_DIR if (TRANSLATE_OUTPUT_DIR and os.path.isdir(TRANSLATE_OUTPUT_DIR)) else OUTPUT_DIR
        os.startfile(folder)
        log(f"[Dịch] Mở thư mục: {folder}")
        if not TRANSLATE_OUTPUT_DIR:
            log("[Dịch] (Chưa chọn thư mục output — file dịch đang lưu CẠNH file gốc)")
    except Exception as e:
        log(f"[Dịch] Không mở được thư mục: {e}")


def translate_srt():
    """Dịch 1 file phụ đề (.srt/.ass/.vtt) sang tiếng Việt → <tên>_vi.srt
    (giữ timestamp; ass/vtt được convert sang SRT trước)."""
    path = filedialog.askopenfilename(
        title="Chọn file phụ đề cần dịch sang tiếng Việt",
        filetypes=[("Subtitle files", "*.srt *.ass *.ssa *.vtt"),
                   ("SRT files", "*.srt")])
    if not path:
        return
    if os.path.splitext(path)[1].lower() in (".ass", ".ssa", ".vtt"):
        try:
            path = _convert_subtitle_to_srt(path)
            log(f"🔄 Đã chuyển sang SRT: {os.path.basename(path)}")
        except Exception as e:
            log(f"❌ Không chuyển được sang SRT: {e}")
            return
    context = _translate_default_context()
    bilingual = bool(translate_bilingual_var.get())

    def _worker():
        global TRANSLATE_STOP, TRANSLATE_PAUSED
        TRANSLATE_STOP = False
        TRANSLATE_PAUSED = False
        try:
            app.after(0, lambda: _set_translate_buttons("disabled"))
            app.after(0, lambda: _translate_set_controls(True))
            subs = list(srt.parse(_read_text_smart(path)))
            if not subs:
                app.after(0, lambda: log("❌ File SRT rỗng / không đọc được."))
                return
            sources = [clean_text(s.content) for s in subs]
            app.after(0, lambda: log(f"📜 Dịch SRT: {os.path.basename(path)} ({len(subs)} dòng)"))
            translated = _translate_segments(
                sources, context,
                progress_cb=_make_translate_progress_cb(),
                log_cb=lambda m: app.after(0, lambda mm=m: log(mm)))
            for s, src, tr in zip(subs, sources, translated):
                s.content = (f"{src}\n{tr}" if bilingual else tr)
            out_path = _translate_redirect(os.path.splitext(path)[0] + "_vi.srt")
            with open(out_path, "w", encoding="utf-8") as f:
                f.write(srt.compose(subs))
            if TRANSLATE_STOP:
                app.after(0, lambda: log(f"⏹ Đã dừng. Lưu phần đã dịch (phần còn lại giữ gốc): {out_path}"))
            else:
                app.after(0, lambda: log(f"✅ Đã lưu: {out_path}"))
                app.after(0, show_fireworks)
            app.after(0, lambda: _reveal_output(out_path))
            # Pipeline gộp: Dịch xong → nạp file _vi.srt và lồng tiếng luôn
            if not TRANSLATE_STOP and translate_then_tts_var.get():
                app.after(500, lambda p=out_path: _chain_translate_to_tts(p))
        except Exception as e:
            err = str(e)
            app.after(0, lambda: log(f"❌ Lỗi dịch SRT: {err}"))
        finally:
            app.after(0, lambda: _set_translate_buttons("normal"))
            app.after(0, lambda: _translate_set_controls(False))

    threading.Thread(target=_worker, daemon=True).start()


def _chain_translate_to_tts(srt_path):
    """Nạp file SRT vừa dịch vào pipeline TTS và chạy luôn (chạy trên main thread)."""
    global SRT_FILE, current_index
    try:
        if translate_bilingual_var.get():
            log("⚠ Song ngữ đang bật — TTS sẽ đọc CẢ 2 ngôn ngữ. "
                "Tắt 'Song ngữ' nếu chỉ muốn đọc bản dịch.")
        SRT_FILE = srt_path
        current_index = 0
        load_subtitles(force_select=False)
        if not subtitles_cache:
            log("❌ Không nạp được file SRT đã dịch — dừng pipeline.")
            return
        set_mode("srt")
        log(f"🔗 Dịch xong → bắt đầu lồng tiếng: {os.path.basename(srt_path)}")
        start_tts()
    except Exception as e:
        log(f"❌ Không tự chạy được TTS sau dịch: {e}")


def translate_pdf():
    """Trích text PDF → dịch sang tiếng Việt → <tên>_vi.{txt|pdf|docx}."""
    path = filedialog.askopenfilename(
        title="Chọn file PDF cần dịch sang tiếng Việt",
        filetypes=[("PDF files", "*.pdf")])
    if not path:
        return
    context = _translate_default_context()
    bilingual = bool(translate_bilingual_var.get())
    out_fmt = (translate_pdf_format_var.get() or "txt").strip().lower()

    def _worker():
        global TRANSLATE_STOP, TRANSLATE_PAUSED
        TRANSLATE_STOP = False
        TRANSLATE_PAUSED = False
        import tempfile
        try:
            app.after(0, lambda: _set_translate_buttons("disabled"))
            app.after(0, lambda: _translate_set_controls(True))
            py = _find_pdf_python()
            helper = _find_pdf_helper()
            if not py:
                app.after(0, lambda: log("❌ Không tìm thấy Python có pypdf (pip install pypdf)."))
                return
            if not helper:
                app.after(0, lambda: log("❌ Không tìm thấy pdf_helper.py."))
                return
            tmp_json = os.path.join(tempfile.gettempdir(), "_pdf_tr_chunks.json")
            app.after(0, lambda: log(f"📄 Trích text PDF: {os.path.basename(path)}..."))
            r = subprocess.run([py, helper, "--input", path, "--output", tmp_json],
                               capture_output=True, text=True, encoding="utf-8",
                               errors="replace", timeout=180, creationflags=CREATE_NO_WINDOW)
            if r.returncode != 0 or not r.stdout.strip().startswith("DONE:"):
                err = (r.stderr.strip()[:300] or r.stdout.strip())
                app.after(0, lambda: log(f"❌ Lỗi đọc PDF: {err}"))
                return
            with open(tmp_json, encoding="utf-8") as f:
                chunks = json.load(f).get("chunks", [])
            try:
                os.remove(tmp_json)
            except Exception:
                pass
            chunks = [c for c in chunks if c.strip()]
            if not chunks:
                app.after(0, lambda: log("❌ PDF không có text (có thể là PDF scan)."))
                return
            app.after(0, lambda: log(f"📄 Dịch {len(chunks)} đoạn..."))
            translated = _translate_segments(
                chunks, context,
                progress_cb=_make_translate_progress_cb(),
                log_cb=lambda m: app.after(0, lambda mm=m: log(mm)))
            base = _translate_redirect(os.path.splitext(path)[0] + "_vi")
            out_path = _write_translated_doc(base, chunks, translated, bilingual, out_fmt,
                                             log_cb=lambda m: app.after(0, lambda mm=m: log(mm)))
            if TRANSLATE_STOP:
                app.after(0, lambda: log(f"⏹ Đã dừng. Lưu phần đã dịch (phần còn lại giữ gốc): {out_path}"))
            else:
                app.after(0, lambda: log(f"✅ Đã lưu: {out_path}"))
                app.after(0, show_fireworks)
            app.after(0, lambda: _reveal_output(out_path))
        except Exception as e:
            err = str(e)
            app.after(0, lambda: log(f"❌ Lỗi dịch PDF: {err}"))
        finally:
            app.after(0, lambda: _set_translate_buttons("normal"))
            app.after(0, lambda: _translate_set_controls(False))

    threading.Thread(target=_worker, daemon=True).start()


def translate_doc():
    """Dịch file Word (.docx) hoặc TXT sang tiếng Việt → <tên>_vi.{txt|pdf|docx}."""
    path = filedialog.askopenfilename(
        title="Chọn file Word (.docx) hoặc TXT cần dịch sang tiếng Việt",
        filetypes=[("Word / Text", "*.docx *.txt"), ("Word", "*.docx"),
                   ("Text", "*.txt"), ("All", "*.*")])
    if not path:
        return
    context = _translate_default_context()
    bilingual = bool(translate_bilingual_var.get())
    out_fmt = (translate_pdf_format_var.get() or "txt").strip().lower()

    def _worker():
        global TRANSLATE_STOP, TRANSLATE_PAUSED
        TRANSLATE_STOP = False
        TRANSLATE_PAUSED = False
        try:
            app.after(0, lambda: _set_translate_buttons("disabled"))
            app.after(0, lambda: _translate_set_controls(True))
            ext = os.path.splitext(path)[1].lower()
            if ext == ".docx":
                try:
                    from docx import Document
                except Exception:
                    app.after(0, lambda: log("❌ Thiếu thư viện python-docx (pip install python-docx)."))
                    return
                chunks = [p.text for p in Document(path).paragraphs if p.text.strip()]
            else:  # .txt và các file text khác
                text = _read_text_smart(path)
                chunks = [ln for ln in text.splitlines() if ln.strip()]
            if not chunks:
                app.after(0, lambda: log("❌ File không có nội dung text để dịch."))
                return
            app.after(0, lambda: log(f"📝 Dịch {os.path.basename(path)} ({len(chunks)} đoạn)..."))
            translated = _translate_segments(
                chunks, context,
                progress_cb=_make_translate_progress_cb(),
                log_cb=lambda m: app.after(0, lambda mm=m: log(mm)))
            base = _translate_redirect(os.path.splitext(path)[0] + "_vi")
            out_path = _write_translated_doc(base, chunks, translated, bilingual, out_fmt,
                                             log_cb=lambda m: app.after(0, lambda mm=m: log(mm)))
            if TRANSLATE_STOP:
                app.after(0, lambda: log(f"⏹ Đã dừng. Lưu phần đã dịch (phần còn lại giữ gốc): {out_path}"))
            else:
                app.after(0, lambda: log(f"✅ Đã lưu: {out_path}"))
                app.after(0, show_fireworks)
            app.after(0, lambda: _reveal_output(out_path))
        except Exception as e:
            err = str(e)
            app.after(0, lambda: log(f"❌ Lỗi dịch Word/TXT: {err}"))
        finally:
            app.after(0, lambda: _set_translate_buttons("normal"))
            app.after(0, lambda: _translate_set_controls(False))

    threading.Thread(target=_worker, daemon=True).start()


