def _animate_progress():
    """Trượt thanh tiến trình tới _progress_target mượt và liên tục (tốc độ
    không đổi nhỏ, ~60fps) để thanh bò đều, không giật cục từng đoạn."""
    cur = progress_var.get()
    tgt = _progress_target[0]
    diff = tgt - cur

    if abs(diff) <= 0.0015:
        progress_var.set(tgt)
        progress_label.configure(text=f"{int(round(tgt*100))}%")
        _progress_anim_id[0] = None
        if tgt >= 1.0:
            _progress_hide_id[0] = app.after(1200, _hide_progress_bar)
        return

    # Ease-out mượt nhất: mỗi khung tiến một phần nhỏ của quãng còn lại
    # (chuyển động liên tục, chậm dần khi tới đích) + sàn tối thiểu để
    # không bao giờ đứng yên. Chạy ~120fps (8ms) cho thật mượt.
    step = diff * 0.08
    floor = 0.0012
    if abs(step) < floor:
        step = floor if diff > 0 else -floor
    nxt = cur + step
    if (diff > 0 and nxt > tgt) or (diff < 0 and nxt < tgt):
        nxt = tgt
    progress_var.set(nxt)
    progress_label.configure(text=f"{int(round(nxt*100))}%")
    _progress_anim_id[0] = app.after(8, _animate_progress)


# ── Taskbar progress Windows (ITaskbarList3 qua ctypes thuần — verify trên máy) ──
# Thanh tiến độ xanh trên icon taskbar: thu nhỏ app vẫn liếc được tiến độ.
# Lazy-init ở lần update đầu; mọi lỗi COM → tắt vĩnh viễn trong phiên (im lặng).
# CHỈ gọi từ main thread (bên trong _update của update_progress).
_TASKBAR = {"tried": False, "ptr": None, "setval": None,
            "setstate": None, "hwnd": None}

def _taskbar_init():
    if _TASKBAR["tried"]:
        return _TASKBAR["setval"] is not None
    _TASKBAR["tried"] = True
    try:
        import ctypes as _ct
        from ctypes import wintypes as _wt

        class _GUID(_ct.Structure):
            _fields_ = [("d1", _ct.c_ulong), ("d2", _ct.c_ushort),
                        ("d3", _ct.c_ushort), ("d4", _ct.c_ubyte * 8)]

        def _g(s):
            g = _GUID()
            _ct.oledll.ole32.CLSIDFromString(_ct.c_wchar_p(s), _ct.byref(g))
            return g

        _ct.oledll.ole32.CoInitialize(None)
        ptr = _ct.c_void_p()
        _ct.oledll.ole32.CoCreateInstance(
            _ct.byref(_g("{56FDF344-FD6D-11d0-958A-006097C9A090}")), None, 1,
            _ct.byref(_g("{EA1AFB91-9E28-4B86-90E9-9E9F8A5EEFAF}")),
            _ct.byref(ptr))
        vtbl = _ct.cast(ptr, _ct.POINTER(_ct.POINTER(_ct.c_void_p))).contents
        hr_init = _ct.WINFUNCTYPE(_ct.HRESULT, _ct.c_void_p)(vtbl[3])
        setval = _ct.WINFUNCTYPE(_ct.HRESULT, _ct.c_void_p, _wt.HWND,
                                 _ct.c_ulonglong, _ct.c_ulonglong)(vtbl[9])
        setstate = _ct.WINFUNCTYPE(_ct.HRESULT, _ct.c_void_p, _wt.HWND,
                                   _ct.c_int)(vtbl[10])
        hr_init(ptr)
        hwnd = _ct.windll.user32.GetParent(app.winfo_id())
        _TASKBAR.update({"ptr": ptr, "setval": setval,
                         "setstate": setstate, "hwnd": hwnd})
        return True
    except Exception:
        return False

def _taskbar_progress(value):
    """value 0..1 → thanh taskbar; value >= 0.999 hoặc âm → xóa thanh."""
    try:
        if not _taskbar_init():
            return
        if 0.0 <= value < 0.999:
            _TASKBAR["setval"](_TASKBAR["ptr"], _TASKBAR["hwnd"],
                               int(value * 1000), 1000)
        else:
            _TASKBAR["setstate"](_TASKBAR["ptr"], _TASKBAR["hwnd"], 0)
    except Exception:
        pass


# Ước lượng thời gian còn lại (ETA) cho thanh tiến trình: cửa sổ trượt các
# mẫu (thời điểm, giá trị) gần nhất → tốc độ trung bình → ETA. Reset khi giá
# trị tụt mạnh (job mới / chạy lại). Chỉ đọc/ghi trên main thread (_update).
_ETA_SAMPLES = []   # [(time.monotonic(), value 0..1)]
_ETA_LAST_V  = [0.0]

def _eta_format(sec):
    sec = int(sec)
    if sec >= 3600:
        return f"còn ~{sec // 3600}g{(sec % 3600) // 60:02d}p"
    if sec >= 60:
        return f"còn ~{sec // 60}p{sec % 60:02d}s"
    return f"còn ~{sec}s"

def update_progress(current, total):

    if total <= 0:
        return

    value = max(0.0, min(1.0, current / total))

    def _update():
        # Đang hoạt động → hủy lịch ẩn cũ (nếu có) và hiện thanh
        if _progress_hide_id[0] is not None:
            try:
                app.after_cancel(_progress_hide_id[0])
            except Exception:
                pass
            _progress_hide_id[0] = None
        _show_progress_bar()

        # ── ETA ──
        now = time.monotonic()
        if value < _ETA_LAST_V[0] - 0.05 or value >= 1.0:
            _ETA_SAMPLES.clear()        # job mới / restart / xong → tính lại
        _ETA_LAST_V[0] = value
        _ETA_SAMPLES.append((now, value))
        if len(_ETA_SAMPLES) > 30:
            del _ETA_SAMPLES[:-30]
        eta = ""
        if len(_ETA_SAMPLES) >= 3 and value < 0.999:
            t0, v0 = _ETA_SAMPLES[0]
            dv, dt = value - v0, now - t0
            if dv > 1e-6 and dt > 2.0:   # đủ dữ liệu mới hiện (tránh số nhảy loạn)
                eta = _eta_format((1.0 - value) * dt / dv)
        progress_bar.eta_text = eta
        _taskbar_progress(value)

        # Đặt đích mới rồi để _animate_progress trượt dần thành nhiều đoạn nhỏ.
        _progress_target[0] = value
        if _progress_anim_id[0] is None:
            _animate_progress()

    app.after(0, _update)


_log_err_tag_counter = [0]

def _blink_log_tag(tag, c1="#ff3b30", c2="#ffffff", total_ms=5000, step_ms=300, end_color=None):
    """Nhấp nháy dòng log giữa c1 và c2 trong total_ms, kết thúc giữ end_color (mặc định c1)."""
    if end_color is None:
        end_color = c1
    state = {"n": 0}
    def _tick():
        try:
            on = (state["n"] % 2 == 0)
            logbox._textbox.tag_config(tag, foreground=(c1 if on else c2))
        except Exception:
            return
        state["n"] += 1
        if state["n"] * step_ms >= total_ms:
            try:
                logbox._textbox.tag_config(tag, foreground=end_color)
            except Exception:
                pass
            return
        app.after(step_ms, _tick)
    _tick()


def _append_log(text):
    _file_log(text)
    is_err = any(m in text for m in _ERROR_LOG_MARKERS)
    logbox.configure(state="normal")
    if is_err:
        _log_err_tag_counter[0] += 1
        tag = f"errln{_log_err_tag_counter[0]}"
        try:
            logbox.insert("end", text + "\n", tag)
            logbox._textbox.tag_config(tag, foreground="#ff3b30")
        except Exception:
            logbox.insert("end", text + "\n")
            tag = None
        logbox.see("end")
        logbox.configure(state="disabled")
        if tag:
            _blink_log_tag(tag)
    else:
        logbox.insert("end", text + "\n")
        logbox.see("end")
        logbox.configure(state="disabled")


def clean_text(text):
    text = re.sub(r"<.*?>", "", text)
    text = re.sub(r"\{.*?\}", "", text)
    text = text.replace("\n", " ")
    return text.strip()


def _srt_lint():
    """Khám SRT đang nạp — phát hiện lỗi timing/nội dung TRƯỚC khi đốt thời gian
    TTS (merge chỉ báo tràn khe SAU khi đã gen xong). → [(icon, dòng_1based, msg)].
    Dùng cùng công thức ước thời lượng với QC (0.3 + ký_tự×0.09) và ngưỡng
    _DUB_MAX_SPEED của merge để cảnh báo khớp với hành vi thật."""
    issues = []
    n = len(subtitles_cache)
    for i, sub in enumerate(subtitles_cache):
        text = clean_text(sub.content)
        start = sub.start.total_seconds()
        end = sub.end.total_seconds()
        if end < start:
            issues.append(("❌", i + 1, "timestamp ngược (end < start)"))
        if not text:
            issues.append(("⚠", i + 1, "dòng trống (sẽ bị bỏ qua)"))
            continue
        if len(text) > 400:
            issues.append(("⚠", i + 1,
                           f"text rất dài ({len(text)} ký tự) — nên tách dòng"))
        if i + 1 < n:
            slot = subtitles_cache[i + 1].start.total_seconds() - start
            expected = 0.3 + len(text) * 0.09
            if slot <= 0:
                issues.append(("❌", i + 1,
                               "chồng mốc thời gian với dòng sau — chắc chắn đè giọng"))
            elif expected > slot * _DUB_MAX_SPEED:
                issues.append(("❌", i + 1,
                               f"khe {slot:.1f}s quá hẹp cho {len(text)} ký tự — "
                               f"sẽ tràn dù tăng tốc {_DUB_MAX_SPEED}x"))
            elif expected > slot:
                issues.append(("⚠", i + 1,
                               f"khe {slot:.1f}s hơi hẹp ({len(text)} ký tự) — "
                               "giọng sẽ bị tăng tốc khi merge"))
    # Dòng LẶP liên tiếp ≥3 lần (hallucination của whisper STT) — TTS sẽ đọc
    # lặp y hệt, tốn slot. Lặp đúng 2 lần có thể là chủ ý kịch ("Không! Không!")
    # nên không báo. srt_autofix sẽ gộp các run ≥3 này.
    i = 0
    while i < n:
        t0 = clean_text(subtitles_cache[i].content)
        j = i
        while (t0 and j + 1 < n
               and clean_text(subtitles_cache[j + 1].content) == t0):
            j += 1
        if t0 and j - i + 1 >= 3:
            issues.append(("⚠", i + 1,
                           f"lặp giống hệt {j - i + 1} dòng liên tiếp "
                           f"(dòng {i + 1}–{j + 1}, thường do STT ảo giác) — "
                           "🔧 Sửa SRT sẽ gộp lại"))
        i = j + 1
    return issues


def srt_lint_report():
    """In báo cáo Khám SRT đầy đủ vào logbox (nút 🩺)."""
    if not subtitles_cache:
        log("[Khám SRT] Chưa Load SRT.")
        return
    issues = _srt_lint()
    log("━━━ KHÁM SRT ━━━")
    if not issues:
        log(f"✅ {len(subtitles_cache)} dòng — không thấy vấn đề timing/nội dung.")
        return
    bad = sum(1 for s, _i, _m in issues if s == "❌")
    warn = len(issues) - bad
    for s, i, m in issues[:40]:
        log(f"  {s} Dòng {i}: {m}")
    if len(issues) > 40:
        log(f"  …(+{len(issues) - 40} mục nữa)")
    log(f"Tổng: {bad} lỗi ❌ (nên sửa SRT trước khi chạy), {warn} cảnh báo ⚠ "
        f"(merge sẽ tự tăng tốc/xử lý) / {len(subtitles_cache)} dòng.")


def _srt_split_point(txt):
    """Vị trí tách đôi câu dài: ranh giới câu (.!?;,) gần giữa nhất, chừa mỗi
    nửa ≥ 50 ký tự. None nếu không có chỗ tách hợp lý."""
    mid = len(txt) // 2
    best = None
    for m in re.finditer(r"[.!?;,]\s+", txt):
        pos = m.end()
        if 50 <= pos <= len(txt) - 50:
            if best is None or abs(pos - mid) < abs(best - mid):
                best = pos
    return best


def srt_autofix():
    """🔧 Dọn & sửa SRT đang nạp → <tên>_fixed.srt rồi nạp lại. Tự sửa được:
    sắp lại thứ tự theo thời gian, timestamp ngược (end<start), bỏ dòng trống,
    2 dòng trùng/lùi mốc bắt đầu (+0.1s), tách đôi dòng >400 ký tự tại ranh
    giới câu (chia khe theo tỷ lệ độ dài). KHÔNG tự sửa được: câu tràn khe
    (text dài hơn khe dù tăng tốc 2x) — phải rút gọn text/sửa timing tay."""
    global SRT_FILE, current_index
    if not subtitles_cache or not SRT_FILE:
        log("[Sửa SRT] ❌ Chưa Load SRT.")
        return
    import datetime as _dt
    items = []
    n_empty = 0
    for s in subtitles_cache:
        if not clean_text(s.content):
            n_empty += 1
            continue
        items.append({"start": s.start.total_seconds(),
                      "end": s.end.total_seconds(),
                      "content": s.content})
    if not items:
        log("[Sửa SRT] ❌ SRT không còn dòng nào có nội dung.")
        return
    _starts0 = [it["start"] for it in items]
    items.sort(key=lambda it: it["start"])
    n_sort = 1 if [it["start"] for it in items] != _starts0 else 0
    n_rev = 0
    for it in items:
        if it["end"] < it["start"]:
            it["end"] = it["start"] + 0.3 + len(clean_text(it["content"])) * 0.09
            n_rev += 1
    n_dup = 0
    for k in range(1, len(items)):
        if items[k]["start"] <= items[k - 1]["start"]:
            items[k]["start"] = items[k - 1]["start"] + 0.1
            if items[k]["end"] <= items[k]["start"]:
                items[k]["end"] = items[k]["start"] + 1.0
            n_dup += 1
    # Gộp run ≥3 dòng GIỐNG HỆT liên tiếp (whisper STT ảo giác): giữ dòng đầu,
    # end kéo tới cuối run → TTS đọc 1 lần trong nguyên khe. Lặp 2 lần có thể
    # là chủ ý kịch nên không đụng (khớp ngưỡng cảnh báo của _srt_lint).
    merged = []
    n_dupline = 0
    k = 0
    while k < len(items):
        t0 = clean_text(items[k]["content"])
        j = k
        while (t0 and j + 1 < len(items)
               and clean_text(items[j + 1]["content"]) == t0):
            j += 1
        if t0 and j - k + 1 >= 3:
            it = dict(items[k])
            it["end"] = max(it["end"], items[j]["end"])
            merged.append(it)
            n_dupline += j - k
        else:
            merged.extend(items[k:j + 1])
        k = j + 1
    items = merged
    out = []
    n_split = 0
    for it in items:
        txt = clean_text(it["content"])
        if len(txt) > 400:
            cut = _srt_split_point(txt)
            if cut:
                a, b = txt[:cut].strip(), txt[cut:].strip()
                dur = max(0.5, it["end"] - it["start"])
                mid = it["start"] + dur * (len(a) / max(1, len(txt)))
                out.append({"start": it["start"], "end": mid, "content": a})
                out.append({"start": mid, "end": it["end"], "content": b})
                n_split += 1
                continue
        out.append(it)
    total = n_sort + n_rev + n_empty + n_dup + n_dupline + n_split
    if total == 0:
        log("[Sửa SRT] ✅ Không có gì để tự sửa. (Câu tràn khe — nếu có — phải sửa tay.)")
        return
    subs_out = [srt.Subtitle(index=k + 1,
                             start=_dt.timedelta(seconds=it["start"]),
                             end=_dt.timedelta(seconds=it["end"]),
                             content=it["content"])
                for k, it in enumerate(out)]
    out_path = os.path.splitext(SRT_FILE)[0] + "_fixed.srt"
    try:
        with open(out_path, "w", encoding="utf-8") as f:
            f.write(srt.compose(subs_out))
    except Exception as e:
        log(f"[Sửa SRT] ❌ Không ghi được file: {e}")
        return
    log("━━━ SỬA SRT ━━━")
    if n_sort:  log("  • Đã sắp lại thứ tự dòng theo thời gian bắt đầu")
    if n_rev:   log(f"  • Sửa {n_rev} timestamp ngược (end < start)")
    if n_empty: log(f"  • Bỏ {n_empty} dòng trống")
    if n_dup:   log(f"  • Tách {n_dup} cặp dòng trùng/lùi mốc bắt đầu (+0.1s)")
    if n_dupline: log(f"  • Gộp {n_dupline} dòng lặp giống hệt liên tiếp (STT ảo giác)")
    if n_split: log(f"  • Tách đôi {n_split} dòng > 400 ký tự tại ranh giới câu")
    log(f"[Sửa SRT] 💾 {os.path.basename(out_path)} — đang nạp lại file đã sửa...")
    SRT_FILE = out_path
    current_index = 0
    load_subtitles(force_select=False)   # tự chạy khám nhanh trên file mới
    set_mode("srt")


_SRT_AI_RUNNING = [False]     # tự khóa khi đang chạy (pattern nút Dịch)
_SRT_AI_BATCH = 25            # số dòng gửi LLM mỗi call


def _srt_overflow_lines(include_warn=False):
    """Các dòng cần rút gọn trong SRT đang nạp. Mặc định chỉ nhóm ❌ TRÀN KHE
    (text dài hơn khe dù merge tăng tốc _DUB_MAX_SPEED — nhóm srt_autofix chịu
    thua, budget = vừa khe ở tốc độ tối đa). include_warn=True lấy CẢ nhóm ⚠
    hơi hẹp (sẽ bị atempo khi merge) và budget mọi dòng = vừa khe ở tốc độ 1.0×
    → bản dub không dòng nào bị tăng tốc, giọng tự nhiên.
    → [(idx0, text, max_chars)]; max_chars theo công thức QC 0.3 + n×0.09,
    chừa 10% dự phòng."""
    out = []
    n = len(subtitles_cache)
    speed = 1.0 if include_warn else _DUB_MAX_SPEED
    for i, sub in enumerate(subtitles_cache):
        if i + 1 >= n:
            break   # dòng cuối không có khe kế tiếp — lint cũng bỏ qua
        text = clean_text(sub.content)
        if not text:
            continue
        slot = subtitles_cache[i + 1].start.total_seconds() - sub.start.total_seconds()
        if slot <= 0:
            continue   # chồng mốc thời gian — việc của srt_autofix, không phải rút gọn
        expected = 0.3 + len(text) * 0.09
        if expected > slot * speed:
            maxc = int((slot * speed - 0.3) / 0.09 * 0.9)
            out.append((i, text, max(12, maxc)))
    return out


def srt_ai_shorten():
    """✂ Rút gọn AI: dùng LLM dịch (Claude/Gemini/OpenAI — key ở ⚙ Cài đặt) viết
    lại các dòng tràn khe thành câu ngắn hơn giữ nguyên nghĩa + ngôn ngữ, ghi
    <tên>_ai.srt rồi nạp lại. Luôn bật, tự khóa khi chạy, KHÔNG đăng ký set_mode."""
    if _SRT_AI_RUNNING[0]:
        log("[Rút gọn AI] Đang chạy — đợi xong đã.")
        return
    if not subtitles_cache or not SRT_FILE:
        log("[Rút gọn AI] ❌ Chưa Load SRT.")
        return
    if (TRANSLATE_PROVIDER or "") == "Offline":
        log("[Rút gọn AI] ❌ Provider Offline không viết lại câu được — chọn "
            "Claude/Gemini/OpenAI ở dropdown Dịch (trang Dịch) rồi thử lại.")
        return
    try:
        provider, api_key, model = _translate_active_key()
    except Exception as e:
        log(f"[Rút gọn AI] ❌ {e}")
        return
    n_warn_extra = len(_srt_overflow_lines(include_warn=True)) - len(_srt_overflow_lines())
    include_warn = False
    if n_warn_extra > 0:
        include_warn = msg.askyesno(
            "✂ Rút gọn AI",
            f"Gồm cả {n_warn_extra} dòng ⚠ hơi hẹp (đọc vừa nhưng sẽ bị TĂNG TỐC "
            "khi merge)?\n\n• Có — rút gọn để mọi dòng đọc tốc độ tự nhiên 1.0× "
            "(khuyên dùng cho bản dub chất lượng)\n• Không — chỉ sửa các dòng ❌ "
            "tràn khe (thay đổi ít nội dung nhất)")
    targets = _srt_overflow_lines(include_warn=include_warn)
    if not targets:
        log("[Rút gọn AI] ✅ Không có dòng nào tràn khe — không cần rút gọn.")
        return
    log(f"[Rút gọn AI] ✂ {len(targets)} dòng "
        f"{'(gồm cả ⚠ hơi hẹp, mục tiêu tốc độ 1.0×)' if include_warn else 'tràn khe'} "
        f"→ viết lại ngắn hơn bằng {provider}…")
    _SRT_AI_RUNNING[0] = True
    # chụp trạng thái trên main thread — worker không đụng subtitles_cache/Tk var
    snap = [{"start": s.start, "end": s.end, "content": s.content}
            for s in subtitles_cache]
    src_path = SRT_FILE

    def _worker():
        system = (
            "Bạn là biên tập viên phụ đề lồng tiếng. Với mỗi dòng được đánh dấu [[n]], "
            "hãy VIẾT LẠI NGẮN HƠN sao cho không vượt quá số ký tự tối đa ghi kèm, "
            "giữ nguyên ý chính, giữ nguyên tên riêng và số liệu, giữ nguyên NGÔN NGỮ "
            "gốc của câu (không dịch sang ngôn ngữ khác). Ưu tiên bỏ từ đệm, rút gọn "
            "cách diễn đạt. Chỉ trả về các dòng dạng: [[n]] câu-đã-rút-gọn — không "
            "giải thích gì thêm."
        )
        results = {}       # idx0 → text mới (chỉ nhận khi thật sự ngắn hơn)
        n_call_fail = 0
        done = 0
        try:
            for bs in range(0, len(targets), _SRT_AI_BATCH):
                batch = targets[bs:bs + _SRT_AI_BATCH]
                user = "\n".join(
                    f"[[{k + 1}]] (tối đa {maxc} ký tự) {text}"
                    for k, (_i, text, maxc) in enumerate(batch))
                raw = None
                for _try in range(2):
                    try:
                        raw = _llm_call(provider, api_key, model, system, user)
                        break
                    except Exception as e:
                        if _try == 0:
                            time.sleep(2)
                        else:
                            n_call_fail += len(batch)
                            app.after(0, lambda e=e, nb=len(batch): log(
                                f"[Rút gọn AI] ⚠ Lỗi gọi API — giữ nguyên {nb} dòng: {e}"))
                if raw:
                    parsed = _parse_marked(raw, len(batch))
                    for k, (i, text, _maxc) in enumerate(batch):
                        new = (parsed.get(k) or "").strip()
                        if new and len(new) < len(text):
                            results[i] = new
                done += len(batch)
                update_progress(done, len(targets))

            # đếm dòng vẫn còn tràn sau khi rút gọn (LLM đôi khi chưa đủ ngắn)
            still = []
            for (i, text, maxc) in targets:
                if len(results.get(i, text)) > int(maxc / 0.9):
                    still.append(i + 1)

            subs_out = []
            for k, it in enumerate(snap):
                content = results.get(k, it["content"])
                subs_out.append(srt.Subtitle(index=k + 1, start=it["start"],
                                             end=it["end"], content=content))
            out_path = os.path.splitext(src_path)[0] + "_ai.srt"
            with open(out_path, "w", encoding="utf-8") as f:
                f.write(srt.compose(subs_out))

            def _apply():
                global SRT_FILE, current_index
                log("━━━ RÚT GỌN AI ━━━")
                log(f"  • Viết lại được {len(results)}/{len(targets)} dòng tràn khe")
                if n_call_fail:
                    log(f"  • ⚠ {n_call_fail} dòng bỏ qua vì lỗi API")
                if still:
                    _s = ", ".join(str(x) for x in still[:15])
                    log(f"  • ⚠ {len(still)} dòng vẫn hơi dài (sẽ bị tăng tốc khi merge): "
                        f"dòng {_s}{'…' if len(still) > 15 else ''}")
                log(f"[Rút gọn AI] 💾 {os.path.basename(out_path)} — đang nạp lại…")
                SRT_FILE = out_path
                current_index = 0
                load_subtitles(force_select=False)
                set_mode("srt")
            app.after(0, _apply)
        except Exception as e:
            app.after(0, lambda e=e: log(f"[Rút gọn AI] ❌ Lỗi: {e}"))
        finally:
            _SRT_AI_RUNNING[0] = False
            update_progress(0, 1)

    threading.Thread(target=_worker, daemon=True).start()


def open_srt_replace_dialog():
    """🔁 Tìm & thay trong SRT đang nạp (thường / regex, phân biệt hoa-thường
    tùy chọn) → ghi <tên>_edit.srt và nạp lại; hỏi xóa audio các dòng bị đổi
    để đọc lại (dịch sai tên nhân vật cả tập → sửa 1 phát). Chạy tức thì trên
    main thread — không LLM, không khóa."""
    if not subtitles_cache or not SRT_FILE:
        msg.showinfo("🔁 Tìm & thay", "Hãy Load SRT trước.")
        return
    win = ctk.CTkToplevel(app)
    win.title("🔁 Tìm & thay trong SRT")
    win.geometry("620x330")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    row1 = ctk.CTkFrame(win, fg_color="transparent")
    row1.pack(fill="x", padx=14, pady=(14, 4))
    ctk.CTkLabel(row1, text="Tìm:", font=("Arial", 12), width=80,
                 anchor="w").pack(side="left")
    v_find = ctk.StringVar(value="")
    ctk.CTkEntry(row1, textvariable=v_find).pack(side="left", expand=True, fill="x")

    row2 = ctk.CTkFrame(win, fg_color="transparent")
    row2.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row2, text="Thay bằng:", font=("Arial", 12), width=80,
                 anchor="w").pack(side="left")
    v_repl = ctk.StringVar(value="")
    ctk.CTkEntry(row2, textvariable=v_repl).pack(side="left", expand=True, fill="x")

    row3 = ctk.CTkFrame(win, fg_color="transparent")
    row3.pack(fill="x", padx=14, pady=4)
    v_regex = ctk.BooleanVar(value=False)
    ctk.CTkCheckBox(row3, text="Regex", variable=v_regex,
                    font=("Arial", 12), width=90).pack(side="left")
    v_case = ctk.BooleanVar(value=True)
    ctk.CTkCheckBox(row3, text="Phân biệt HOA/thường", variable=v_case,
                    font=("Arial", 12)).pack(side="left", padx=(10, 0))

    lbl_prev = ctk.CTkLabel(win, text="", font=("Arial", 11), justify="left",
                            wraplength=580, anchor="w")
    lbl_prev.pack(fill="x", padx=16, pady=(6, 2))

    def _compile():
        pat = v_find.get()
        if not pat:
            return None
        flags = 0 if v_case.get() else re.IGNORECASE
        try:
            return re.compile(pat if v_regex.get() else re.escape(pat), flags)
        except re.error as e:
            lbl_prev.configure(text=f"❌ Regex lỗi: {e}")
            return None

    def _changes():
        rx = _compile()
        if rx is None:
            return None
        repl = v_repl.get()
        out = []
        for i, s in enumerate(subtitles_cache):
            try:
                new = rx.sub(repl, s.content)
            except re.error as e:
                lbl_prev.configure(text=f"❌ Chuỗi thay lỗi: {e}")
                return None
            if new != s.content:
                out.append((i, s.content, new))
        return out

    def _preview():
        ch = _changes()
        if ch is None:
            return
        if not ch:
            lbl_prev.configure(text="Không dòng nào khớp.")
            return
        nums = ", ".join(str(i) for i, _o, _n in ch[:15])
        i0, o0, n0 = ch[0]
        _cut = lambda t: (t[:70] + "…") if len(t) > 70 else t
        lbl_prev.configure(text=(
            f"✅ {len(ch)} dòng sẽ đổi (dòng {nums}{'…' if len(ch) > 15 else ''})\n"
            f"VD dòng {i0}:  {_cut(clean_text(o0))}\n"
            f"        →  {_cut(clean_text(n0))}"))

    def _apply():
        global SRT_FILE, current_index
        ch = _changes()
        if ch is None:
            return
        if not ch:
            lbl_prev.configure(text="Không dòng nào khớp — chưa ghi file.")
            return
        new_map = {i: n for i, _o, n in ch}
        subs_out = [srt.Subtitle(index=k + 1, start=s.start, end=s.end,
                                 content=new_map.get(k, s.content))
                    for k, s in enumerate(subtitles_cache)]
        out_path = os.path.splitext(SRT_FILE)[0] + "_edit.srt"
        try:
            with open(out_path, "w", encoding="utf-8") as f:
                f.write(srt.compose(subs_out))
        except Exception as e:
            lbl_prev.configure(text=f"❌ Không ghi được file: {e}")
            return
        log(f"🔁 [Tìm & thay] Đổi {len(ch)} dòng → {os.path.basename(out_path)} — nạp lại…")
        SRT_FILE = out_path
        current_index = 0
        load_subtitles(force_select=False)
        set_mode("srt")
        win.destroy()
        # audio các dòng vừa đổi đang là bản đọc text CŨ → mời xóa để đọc lại
        if OUTPUT_DIR and os.path.isdir(OUTPUT_DIR):
            _have = [i for i, _o, _n in ch if os.path.isfile(
                os.path.join(OUTPUT_DIR, f"line_{i:04d}.mp3"))]
            if _have and msg.askyesno(
                    "🔁 Tìm & thay",
                    f"{len(_have)} dòng vừa đổi đã có audio (đọc theo text CŨ).\n"
                    "Xóa audio các dòng đó để đọc lại?\n"
                    "(Sau đó bấm '🧩 Tạo lại dòng thiếu' hoặc TTS/Resume.)"):
                n_del = 0
                for i in _have:
                    try:
                        os.remove(os.path.join(OUTPUT_DIR, f"line_{i:04d}.mp3"))
                        n_del += 1
                    except Exception:
                        pass
                log(f"🔁 [Tìm & thay] Đã xóa {n_del} audio cũ — bấm '🧩 Tạo lại "
                    "dòng thiếu' (hoặc TTS/Resume) để đọc lại.")

    row4 = ctk.CTkFrame(win, fg_color="transparent")
    row4.pack(fill="x", padx=14, pady=(8, 12))
    ctk.CTkButton(row4, text="🔍 Xem trước", command=_preview, height=36,
                  width=130).pack(side="left", padx=4)
    ctk.CTkButton(row4, text="✅ Thay & lưu (_edit.srt)", command=_apply,
                  fg_color="#2fa572", hover_color="#37b87f", height=36
                  ).pack(side="left", expand=True, fill="x", padx=4)


def open_srt_table_editor():
    """📝 Bảng phụ đề: toàn bộ SRT trong 1 cửa sổ — trạng thái từng dòng
    (lint ❌/⚠ · audio ✅ có/🔴 lỗi QC · ✏ đã sửa), sửa text, ▶ nghe, 🔁 đọc
    lại từng dòng, 💾 lưu ra <tên>_edit.srt (+ mời xóa audio dòng đã sửa).
    Dùng ttk.Treeview (ảo hóa) nên SRT nghìn dòng vẫn mượt."""
    if not subtitles_cache or not SRT_FILE:
        msg.showinfo("📝 Bảng phụ đề", "Hãy Load SRT trước.")
        return
    import tkinter.ttk as _ttk

    texts = [s.content for s in subtitles_cache]   # bản làm việc
    edited = set()

    lint_map = {}
    try:
        for icon, ln, _m in _srt_lint():
            i = ln - 1
            if lint_map.get(i) != "❌":
                lint_map[i] = icon
    except Exception:
        pass
    bad_idx = set()
    try:
        for _p, _i, _r, _f in _qc_scan_bad_files():
            if _p == "line_":
                bad_idx.add(_i)
    except Exception:
        pass

    def _status(i):
        s = "✏" if i in edited else ""
        s += lint_map.get(i, "")
        if i in bad_idx:
            s += "🔴"
        elif OUTPUT_DIR and os.path.isfile(
                os.path.join(OUTPUT_DIR, f"line_{i:04d}.mp3")):
            s += "✅"
        return s

    win = ctk.CTkToplevel(app)
    win.title(f"📝 Bảng phụ đề — {os.path.basename(SRT_FILE)}")
    win.geometry("980x640")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    style = _ttk.Style(win)
    try:
        style.theme_use("clam")
    except Exception:
        pass
    style.configure("Srt.Treeview", background="#141a26",
                    fieldbackground="#141a26", foreground="#e6edf3",
                    rowheight=24, font=("Arial", 10), borderwidth=0)
    style.configure("Srt.Treeview.Heading", background="#1f2735",
                    foreground="#e6edf3", font=("Arial", 10, "bold"))
    style.map("Srt.Treeview", background=[("selected", "#1f3a6e")])

    frame_top = tk.Frame(win, bg="#141a26")
    frame_top.pack(fill="both", expand=True, padx=10, pady=(10, 4))
    tree = _ttk.Treeview(frame_top, columns=("time", "st", "text"),
                         show="headings", style="Srt.Treeview")
    tree.heading("time", text="Thời gian")
    tree.column("time", width=150, stretch=False)
    tree.heading("st", text="TT")
    tree.column("st", width=56, stretch=False, anchor="center")
    tree.heading("text", text="Nội dung (chọn dòng để sửa ở ô dưới)")
    tree.column("text", width=690)
    vsb = _ttk.Scrollbar(frame_top, orient="vertical", command=tree.yview)
    tree.configure(yscrollcommand=vsb.set)
    tree.pack(side="left", fill="both", expand=True)
    vsb.pack(side="left", fill="y")

    def _fmt_t(td):
        s = td.total_seconds()
        return f"{int(s // 60):02d}:{s % 60:05.2f}"

    def _row_vals(i):
        return (f"{_fmt_t(subtitles_cache[i].start)} → {_fmt_t(subtitles_cache[i].end)}",
                _status(i), clean_text(texts[i])[:200])

    for i in range(len(texts)):
        tree.insert("", "end", iid=str(i), values=_row_vals(i))

    edit_row = ctk.CTkFrame(win, fg_color="transparent")
    edit_row.pack(fill="x", padx=10, pady=4)
    lbl_cur = ctk.CTkLabel(edit_row, text="Dòng —", width=110,
                           font=("Arial", 12, "bold"), anchor="w")
    lbl_cur.pack(side="left")
    edit_box = ctk.CTkTextbox(edit_row, height=64, wrap="word")
    edit_box.pack(side="left", expand=True, fill="x", padx=6)
    try:
        _attach_telex_input(edit_box, quick_tts_telex_var)
    except Exception:
        pass

    cur = [-1]

    def _load_sel(_e=None):
        sel = tree.selection()
        if not sel:
            return
        i = int(sel[0])
        cur[0] = i
        lbl_cur.configure(text=f"Dòng {i}")
        edit_box.delete("1.0", "end")
        edit_box.insert("1.0", texts[i])
    tree.bind("<<TreeviewSelect>>", _load_sel)

    def _update_line():
        i = cur[0]
        if i < 0:
            return
        new = edit_box.get("1.0", "end").strip()
        if new and new != texts[i].strip():
            texts[i] = new
            edited.add(i)
            tree.item(str(i), values=_row_vals(i))

    def _play_cur():
        i = cur[0]
        if i < 0:
            return
        p = os.path.join(OUTPUT_DIR or "", f"line_{i:04d}.mp3")
        if OUTPUT_DIR and os.path.isfile(p):
            _play_audio_file(p)
        else:
            lbl_cur.configure(text=f"Dòng {i} (chưa có audio)")

    _regen_busy = [False]

    def _regen_cur():
        i = cur[0]
        if i < 0 or _regen_busy[0]:
            return
        if not OUTPUT_DIR:
            msg.showinfo("📝 Bảng phụ đề", "Chưa chọn Output Folder.")
            return
        _update_line()
        text = clean_text(texts[i])
        if not text:
            return
        _regen_busy[0] = True
        lbl_cur.configure(text=f"Dòng {i} ⏳…")

        def _w(i=i, text=text):
            try:
                asyncio.run(regenerate_line(i, text))
            except Exception as e:
                log(f"📝 [Bảng] ❌ Lỗi đọc lại dòng {i}: {e}")
            finally:
                _regen_busy[0] = False

                def _done():
                    try:
                        if win.winfo_exists():
                            lbl_cur.configure(text=f"Dòng {i} ✅")
                            tree.item(str(i), values=_row_vals(i))
                    except Exception:
                        pass
                app.after(0, _done)
        threading.Thread(target=_w, daemon=True).start()

    def _save_all():
        global SRT_FILE, current_index
        _update_line()
        if not edited:
            msg.showinfo("📝 Bảng phụ đề", "Chưa sửa dòng nào — không có gì để lưu.")
            return
        subs_out = [srt.Subtitle(index=k + 1, start=s.start, end=s.end,
                                 content=texts[k])
                    for k, s in enumerate(subtitles_cache)]
        out_path = os.path.splitext(SRT_FILE)[0] + "_edit.srt"
        try:
            with open(out_path, "w", encoding="utf-8") as f:
                f.write(srt.compose(subs_out))
        except Exception as e:
            msg.showerror("📝 Bảng phụ đề", f"Không ghi được file: {e}")
            return
        n_edit = len(edited)
        log(f"📝 [Bảng] Sửa {n_edit} dòng → {os.path.basename(out_path)} — nạp lại…")
        # audio các dòng đã sửa (chưa 🔁 trong bảng) đang đọc text cũ
        _stale = [i for i in sorted(edited) if OUTPUT_DIR and os.path.isfile(
            os.path.join(OUTPUT_DIR, f"line_{i:04d}.mp3"))]
        SRT_FILE = out_path
        current_index = 0
        load_subtitles(force_select=False)
        set_mode("srt")
        win.destroy()
        if _stale and msg.askyesno(
                "📝 Bảng phụ đề",
                f"{len(_stale)} dòng vừa sửa đã có audio (có thể đang đọc text cũ).\n"
                "Xóa audio các dòng đó để đọc lại? (Dòng đã 🔁 trong bảng thì "
                "chọn No.)"):
            n_del = 0
            for i in _stale:
                try:
                    os.remove(os.path.join(OUTPUT_DIR, f"line_{i:04d}.mp3"))
                    n_del += 1
                except Exception:
                    pass
            log(f"📝 [Bảng] Đã xóa {n_del} audio cũ — bấm '🧩 Tạo lại dòng thiếu' "
                "hoặc TTS/Resume để đọc lại.")

    btn_row = ctk.CTkFrame(win, fg_color="transparent")
    btn_row.pack(fill="x", padx=10, pady=(4, 10))
    ctk.CTkButton(btn_row, text="✏ Cập nhật dòng", command=_update_line,
                  width=130).pack(side="left", padx=3)
    ctk.CTkButton(btn_row, text="▶ Nghe", command=_play_cur,
                  width=90).pack(side="left", padx=3)
    ctk.CTkButton(btn_row, text="⏹", command=_qt_preview_close,
                  width=40).pack(side="left", padx=3)
    ctk.CTkButton(btn_row, text="🔁 Đọc lại dòng", command=_regen_cur,
                  width=130, fg_color="#b3771d",
                  hover_color="#d18a22").pack(side="left", padx=3)
    ctk.CTkButton(btn_row, text="💾 Lưu file (_edit.srt)", command=_save_all,
                  fg_color="#2fa572", hover_color="#37b87f"
                  ).pack(side="left", expand=True, fill="x", padx=3)
    ctk.CTkButton(btn_row, text="Đóng", command=win.destroy,
                  width=80).pack(side="left", padx=3)


def open_srt_shift_dialog():
    """⏱ Dời toàn bộ thời gian một file SRT ±N ms → <tên>_shifted.srt."""
    win = ctk.CTkToplevel(app)
    win.title("⏱ Dời thời gian SRT")
    win.geometry("560x250")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    ctk.CTkLabel(win, text="Dời toàn bộ phụ đề sớm/muộn N mili-giây (sub lệch tiếng)",
                 font=("Arial", 13, "bold")).pack(pady=(12, 6))
    row1 = ctk.CTkFrame(win, fg_color="transparent")
    row1.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row1, text="File SRT:", font=("Arial", 12), width=70,
                 anchor="w").pack(side="left")
    v_file = ctk.StringVar(value=SRT_FILE or "")
    ctk.CTkEntry(row1, textvariable=v_file).pack(side="left", expand=True,
                                                 fill="x", padx=(0, 6))
    def _browse():
        p = filedialog.askopenfilename(title="Chọn file SRT",
                                       filetypes=[("SRT files", "*.srt")])
        if p:
            v_file.set(p)
    ctk.CTkButton(row1, text="Browse", width=80, command=_browse).pack(side="left")

    row2 = ctk.CTkFrame(win, fg_color="transparent")
    row2.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row2, text="Dời (ms):", font=("Arial", 12), width=70,
                 anchor="w").pack(side="left")
    v_ms = ctk.StringVar(value="500")
    ctk.CTkEntry(row2, textvariable=v_ms, width=100,
                 justify="center").pack(side="left")
    ctk.CTkLabel(row2, text="(+500 = phụ đề muộn hơn nửa giây; -500 = sớm hơn)",
                 font=("Arial", 11), text_color="#888").pack(side="left", padx=8)

    def _apply():
        path = v_file.get().strip()
        if not path or not os.path.isfile(path):
            msg.showerror("Dời SRT", "Chưa chọn file SRT hợp lệ.")
            return
        try:
            ms = int(float(v_ms.get().strip()))
        except ValueError:
            msg.showerror("Dời SRT", "Số mili-giây không hợp lệ.")
            return
        import datetime as _dt
        try:
            subs = list(srt.parse(_read_text_smart(path)))
            delta = _dt.timedelta(milliseconds=ms)
            zero = _dt.timedelta(0)
            for s in subs:
                s.start = max(zero, s.start + delta)
                s.end = max(zero, s.end + delta)
            out_path = os.path.splitext(path)[0] + "_shifted.srt"
            with open(out_path, "w", encoding="utf-8") as f:
                f.write(srt.compose(subs))
            log(f"⏱ Đã dời {ms:+d} ms toàn bộ {len(subs)} dòng → {os.path.basename(out_path)}")
            win.destroy()
            try:
                _reveal_output(out_path)
            except Exception:
                pass
        except Exception as e:
            msg.showerror("Dời SRT", f"Lỗi: {e}")

    ctk.CTkButton(win, text="⏱ Dời & lưu file mới", command=_apply, height=40,
                  fg_color="#2fa572", hover_color="#37b87f",
                  font=("Arial", 14, "bold")).pack(fill="x", padx=14, pady=(10, 12))


# ── Chuyển .ass/.ssa/.vtt → .srt (thuần stdlib) ─────────────────────────────
# Anime/fansub dùng .ass, YouTube xuất .vtt — convert ngay lúc Load để mọi
# pipeline phía sau (TTS/dịch/wizard) vẫn chỉ làm việc với SRT như cũ.

def _ass_time_to_td(s):
    """'H:MM:SS.cc' (centi-giây) → timedelta."""
    import datetime as _dt
    m = re.match(r"(\d+):(\d\d):(\d\d)[.,](\d{1,2})", s.strip())
    if not m:
        raise ValueError(f"ASS time: {s!r}")
    h, mi, se, cs = m.groups()
    return _dt.timedelta(hours=int(h), minutes=int(mi), seconds=int(se),
                         milliseconds=int(cs.ljust(2, "0")) * 10)


def _vtt_time_to_td(s):
    """'[HH:]MM:SS.mmm' → timedelta."""
    import datetime as _dt
    m = re.match(r"(?:(\d+):)?(\d\d):(\d\d)[.,](\d{3})", s.strip())
    if not m:
        raise ValueError(f"VTT time: {s!r}")
    h, mi, se, ms = m.groups()
    return _dt.timedelta(hours=int(h or 0), minutes=int(mi), seconds=int(se),
                         milliseconds=int(ms))


def _parse_ass_events(content):
    """[Events] của ASS/SSA → [(start_td, end_td, text)]. Bỏ tag {\\...},
    \\N/\\n → xuống dòng, bỏ dòng trống/vẽ hình (\\p1)."""
    fmt = None
    out = []
    in_events = False
    for ln in content.splitlines():
        st = ln.strip()
        low = st.lower()
        if low.startswith("[events]"):
            in_events = True
            continue
        if in_events and st.startswith("[") and not low.startswith("[events]"):
            break                     # sang section khác — Events kết thúc
        if not in_events:
            continue
        if low.startswith("format:"):
            fmt = [x.strip().lower() for x in st.split(":", 1)[1].split(",")]
        elif low.startswith("dialogue:") and fmt:
            parts = st.split(":", 1)[1].strip().split(",", len(fmt) - 1)
            if len(parts) < len(fmt):
                continue
            d = dict(zip(fmt, parts))
            text = d.get("text", "")
            if re.search(r"\\p[1-9]", text):
                continue              # vector drawing, không phải chữ
            text = re.sub(r"\{[^}]*\}", "", text)
            text = (text.replace("\\N", "\n").replace("\\n", "\n")
                        .replace("\\h", " ").strip())
            if not text:
                continue
            try:
                out.append((_ass_time_to_td(d["start"]),
                            _ass_time_to_td(d["end"]), text))
            except Exception:
                continue
    return out


def _parse_vtt_events(content):
    """WEBVTT → [(start_td, end_td, text)]. Bỏ header/NOTE/STYLE, cue-settings
    sau timestamp và tag <v>/<c>/<i>… trong text."""
    out = []
    content = content.replace("\r\n", "\n").replace("\r", "\n")
    for block in re.split(r"\n{2,}", content):
        block = block.strip()
        if (not block or block.startswith("WEBVTT")
                or block.startswith("NOTE") or block.startswith("STYLE")
                or block.startswith("REGION")):
            continue
        lines = block.splitlines()
        ts_i = next((i for i, l in enumerate(lines) if "-->" in l), None)
        if ts_i is None:
            continue
        m = re.match(r"\s*(\S+)\s+-->\s+(\S+)", lines[ts_i])
        if not m:
            continue
        try:
            st_td = _vtt_time_to_td(m.group(1))
            en_td = _vtt_time_to_td(m.group(2))
        except Exception:
            continue
        text = "\n".join(lines[ts_i + 1:])
        text = re.sub(r"<[^>]*>", "", text).strip()   # <v Name>/<c>/<i>…
        if text:
            out.append((st_td, en_td, text))
    return out


def _convert_subtitle_to_srt(path):
    """.ass/.ssa/.vtt → <tên>_conv.srt (UTF-8, sắp theo thời gian). Trả về
    đường dẫn file SRT mới; raise nếu không parse được sự kiện nào."""
    ext = os.path.splitext(path)[1].lower()
    content = _read_text_smart(path)
    if ext in (".ass", ".ssa"):
        events = _parse_ass_events(content)
    elif ext == ".vtt":
        events = _parse_vtt_events(content)
    else:
        return path
    if not events:
        raise ValueError(f"Không tìm thấy dòng phụ đề nào trong {os.path.basename(path)}")
    events.sort(key=lambda e: e[0])
    subs = [srt.Subtitle(index=k + 1, start=a, end=b, content=t)
            for k, (a, b, t) in enumerate(events)]
    out_path = os.path.splitext(path)[0] + "_conv.srt"
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(srt.compose(subs))
    return out_path


_VN_DIACRITICS = ("ăâđêôơưĂÂĐÊÔƠƯáàảãạắằẳẵặấầẩẫậéèẻẽẹếềểễệíìỉĩị"
                  "óòỏõọốồổỗộớờởỡợúùủũụứừửữựýỳỷỹỵ")


def _detect_srt_lang(texts):
    """Đoán ngôn ngữ thô của SRT từ script Unicode + dấu tiếng Việt (thuần
    stdlib, đủ cho cảnh báo). → 'vi'/'latin'/'zh'/'ja'/'ko'/'ru'/'th'/''."""
    sample = " ".join(texts)[:4000]
    han = kana = hangul = thai = cyr = lat = 0
    for c in sample:
        o = ord(c)
        if 0x4E00 <= o <= 0x9FFF:
            han += 1
        elif 0x3040 <= o <= 0x30FF:
            kana += 1
        elif 0xAC00 <= o <= 0xD7AF:
            hangul += 1
        elif 0x0E00 <= o <= 0x0E7F:
            thai += 1
        elif 0x0400 <= o <= 0x04FF:
            cyr += 1
        elif o < 0x250 and c.isalpha():
            lat += 1
    total = han + kana + hangul + thai + cyr + lat
    if total < 20:
        return ""
    if kana > 5:
        return "ja"       # có kana chắc chắn là tiếng Nhật (Hán tự dùng chung)
    if hangul > 5:
        return "ko"
    if thai > 5:
        return "th"
    if han > max(10, total * 0.3):
        return "zh"
    if cyr > total * 0.3:
        return "ru"
    if lat > total * 0.5:
        n_vn = sum(1 for c in sample if c in _VN_DIACRITICS)
        return "vi" if n_vn >= 3 else "latin"
    return ""


def _voice_lang_hint():
    """Ngôn ngữ giọng đang cấu hình: 5 engine local + các provider VN đều đọc
    tiếng Việt; Edge lấy prefix locale từ tên voice (vi-VN-… → 'vi')."""
    if VOXCPM_ENABLED or VIENEU_ENABLED or F5TTS_ENABLED or OMNIVOICE_ENABLED:
        return "vi"
    if TTS_PROVIDER != "Edge TTS":
        return "vi"
    m = re.match(r"([a-z]{2,3})-[A-Za-z]", VOICE or "")
    return m.group(1).lower() if m else ""


def _warn_voice_lang_mismatch():
    """⚠ 1 dòng logbox khi ngôn ngữ SRT có vẻ lệch với giọng đang chọn — chặn
    lỗi 'chạy 1000 dòng tiếng Anh bằng giọng vi-VN' trước khi đốt thời gian.
    Chỉ cảnh báo, không chặn (người dùng có thể cố ý, hoặc sẽ Dịch trước)."""
    try:
        texts = [clean_text(s.content) for s in subtitles_cache[:60]]
        srt_lang = _detect_srt_lang([t for t in texts if t][:20])
        if not srt_lang:
            return
        v_lang = _voice_lang_hint()
        if not v_lang:
            return
        if srt_lang == "vi" and v_lang != "vi":
            log(f"⚠ SRT có vẻ TIẾNG VIỆT nhưng giọng đang chọn là '{VOICE}' — "
                "đổi giọng vi-* (hoặc engine local) trước khi chạy TTS?")
        elif srt_lang != "vi" and v_lang == "vi":
            _name = {"latin": "không phải tiếng Việt (chữ Latin — EN/FR/…)",
                     "zh": "tiếng Trung", "ja": "tiếng Nhật", "ko": "tiếng Hàn",
                     "ru": "tiếng Nga", "th": "tiếng Thái"}.get(srt_lang, srt_lang)
            log(f"⚠ SRT có vẻ {_name} nhưng giọng đang chọn đọc TIẾNG VIỆT — "
                "cân nhắc Dịch sang tiếng Việt (trang Dịch) trước khi TTS.")
    except Exception:
        pass


def load_subtitles(force_select=True):
    global subtitles_cache
    global SRT_FILE

    if force_select or not SRT_FILE:

        selected = filedialog.askopenfilename(
            title="Select Subtitle File (SRT / ASS / VTT)",
            filetypes=[("Subtitle files", "*.srt *.ass *.ssa *.vtt"),
                       ("SRT files", "*.srt")]
        )

        if not selected:
            return

        SRT_FILE = selected

    if not os.path.exists(SRT_FILE):
        msg.showerror("Error", f"Missing {SRT_FILE}")
        return

    # .ass/.ssa/.vtt → convert sang SRT rồi làm việc trên file SRT như cũ
    _sub_ext = os.path.splitext(SRT_FILE)[1].lower()
    if _sub_ext in (".ass", ".ssa", ".vtt"):
        try:
            _conv = _convert_subtitle_to_srt(SRT_FILE)
            log(f"🔄 Đã chuyển {os.path.basename(SRT_FILE)} → {os.path.basename(_conv)}")
            SRT_FILE = _conv
        except Exception as e:
            msg.showerror("Error", f"Không chuyển được {_sub_ext} sang SRT: {e}")
            return

    subtitles_cache = list(srt.parse(_read_text_smart(SRT_FILE)))

    subtitle_list.configure(state="normal")
    subtitle_list.delete("1.0", "end")

    for i, sub in enumerate(subtitles_cache):

        text = clean_text(sub.content)

        subtitle_list.insert(
            "end",
            f"[{i}] {text}\n\n"
        )

    subtitle_list.configure(state="disabled")

    log(f"Loaded {len(subtitles_cache)} subtitles")
    try:
        _iss = _srt_lint()
        if _iss:
            _bad = sum(1 for s, _i, _m in _iss if s == "❌")
            log(f"🩺 Khám SRT: {_bad} lỗi, {len(_iss) - _bad} cảnh báo — "
                "nhấn '🩺 Khám SRT' để xem chi tiết.")
    except Exception:
        pass
    _warn_voice_lang_mismatch()
    _casting_sidecar_load()
    try:
        _GENDER_HINTS.clear()   # hint giới tính thuộc SRT cũ — index không còn đúng
    except Exception:
        pass
    _session_save()

    # Chỉ chuyển mode khi người dùng chủ động chọn file (không gọi khi load nội bộ)
    if force_select:
        set_mode("srt")


