def _parse_volume(raw, default=1.0):
    """Đọc giá trị âm lượng (hệ số nhân, 1.0 = giữ nguyên). Chấp nhận
    '1.0', '0.5', '150%', '0' ..."""
    try:
        raw = (raw or "").strip()
        if not raw:
            return default
        if raw.endswith("%"):
            return max(0.0, float(raw[:-1].strip()) / 100.0)
        return max(0.0, float(raw))
    except Exception:
        return default


def _ff_sub_filterpath(path):
    """Escape đường dẫn Windows cho filter subtitles= của ffmpeg
    (C:\\a\\b.srt → 'C\\:/a/b.srt' — slash xuôi + escape dấu hai chấm/nháy)."""
    p = os.path.abspath(path).replace("\\", "/")
    p = p.replace(":", "\\:").replace("'", "\\'")
    return f"'{p}'"


def _mux_demucs_music(vid, ffmpeg_path):
    """🎼 Tách NHẠC NỀN SẠCH (bỏ lời thoại gốc) khỏi audio của video bằng demucs
    (audio_enhancer.py --separate --keep music --stereo, chạy trong voxcpm_env).
    Trả về (đường_dẫn_wav_nhạc_nền, [thư_mục_tạm]) — path rỗng nếu thất bại →
    caller tự fallback về trộn+ducking thường (fail-open, mux không được chết
    vì thiếu env). Chạy trong worker thread của mux; proc gắn vào _VIDEOTOOL_PROC
    để nút ⏹ Dừng kill được cả bước demucs."""
    global _VIDEOTOOL_PROC
    import tempfile as _tempfile
    tmps = []
    def _warn(m):
        app.after(0, lambda m=m: log(f"[Ghép Audio] ⚠ {m} — bỏ tách nhạc, dùng trộn+ducking."))
    try:
        ckpt = ""
        try:
            ckpt = voxcpm_ckpt_var.get().strip()
        except Exception:
            pass
        voxcpm_py = _find_voxcpm_python(ckpt)
        if not voxcpm_py:
            _warn("Không tìm thấy voxcpm_env python (demucs nằm trong đó)")
            return "", tmps
        enhancer = None
        _dirs = [getattr(sys, "_MEIPASS", None)]
        try:
            _dirs.append(os.path.dirname(os.path.abspath(__file__))
                         if "__file__" in globals() else None)
        except Exception:
            pass
        _dirs += [os.path.dirname(os.path.abspath(sys.argv[0])),
                  os.path.dirname(sys.executable)]
        for _d in _dirs:
            if _d and os.path.isfile(os.path.join(_d, "audio_enhancer.py")):
                enhancer = os.path.join(_d, "audio_enhancer.py")
                break
        if not enhancer:
            _warn("Không tìm thấy audio_enhancer.py")
            return "", tmps
        tmpdir = _tempfile.mkdtemp(prefix="mux_demucs_")
        tmps.append(tmpdir)
        orig_wav = os.path.join(tmpdir, "orig.wav")
        music_wav = os.path.join(tmpdir, "music.wav")
        # demucs htdemucs huấn luyện ở 44.1kHz — extract đúng sr đó
        r = subprocess.run([ffmpeg_path, "-y", "-v", "quiet", "-i", vid, "-vn",
                            "-ac", "2", "-ar", "44100", orig_wav],
                           capture_output=True, timeout=1800,
                           creationflags=CREATE_NO_WINDOW)
        if r.returncode != 0 or not os.path.isfile(orig_wav):
            _warn("Không extract được audio gốc từ video")
            return "", tmps
        proc = subprocess.Popen(
            [voxcpm_py, enhancer, "--input", orig_wav, "--output", music_wav,
             "--separate", "--keep", "music", "--stereo"],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            text=True, encoding="utf-8", errors="replace",
            creationflags=CREATE_NO_WINDOW)
        _VIDEOTOOL_PROC = proc
        for raw in proc.stdout:
            line = raw.strip()
            if line.startswith("PCT:"):
                try:
                    _, n_s, m_s = line.split(":")
                    update_progress(int(n_s), int(m_s))
                except Exception:
                    pass
            elif line.startswith("ERROR:"):
                app.after(0, lambda l=line: log(f"[Ghép Audio] 🎼 {l}"))
        proc.wait()
        _VIDEOTOOL_PROC = None
        if VIDEOTOOL_STOP:
            return "", tmps
        if proc.returncode == 0 and os.path.isfile(music_wav) \
                and os.path.getsize(music_wav) > 1024:
            app.after(0, lambda: log("[Ghép Audio] 🎼 Tách nhạc nền xong — mix nhạc sạch + giọng đọc."))
            return music_wav, tmps
        _warn(f"demucs lỗi (exit {proc.returncode}) — thiếu model htdemucs? "
              "(cần cache ~/.cache/torch/hub hoặc mạng lần đầu)")
        return "", tmps
    except Exception as e:
        _warn(f"Lỗi tách nhạc: {e}")
        return "", tmps


def _run_mux_thread():
    global MUX_VIDEO_FILE, MUX_AUDIO_FILE, MUX_OUTPUT_DIR, _VIDEOTOOL_PROC, _VIDEOTOOL_OUT
    global VIDEOTOOL_PAUSED, VIDEOTOOL_STOP
    VIDEOTOOL_PAUSED = False
    VIDEOTOOL_STOP   = False

    vid = MUX_VIDEO_FILE
    aud = MUX_AUDIO_FILE
    if not vid or not os.path.isfile(vid):
        app.after(0, lambda: log("[Ghép Audio] ❌ Chưa chọn video hợp lệ"))
        app.after(0, lambda: set_mode(_mux_ready_mode()))
        return
    if not aud or not os.path.isfile(aud):
        app.after(0, lambda: log("[Ghép Audio] ❌ Chưa chọn audio hợp lệ"))
        app.after(0, lambda: set_mode(_mux_ready_mode()))
        return

    vid_vol = _parse_volume(mux_video_vol_var.get(), 1.0)
    aud_vol = _parse_volume(mux_audio_vol_var.get(), 1.0)
    keep_orig = bool(mux_keep_orig_var.get())

    # Thời lượng video để hiển thị progress
    info, _err = _get_mediainfo(vid)
    duration_s = info.get("duration_s", 0) if info else 0
    has_video_audio = bool(info and info.get("audio_codec"))

    # Kiểm tra ffmpeg tồn tại TRƯỚC KHI set_mode để tránh treo UI
    ffmpeg_ok, ffmpeg_path, ffmpeg_guide = _check_ffmpeg_exists()
    if not ffmpeg_ok:
        for line in ffmpeg_guide.splitlines():
            app.after(0, lambda l=line: log(l))
        app.after(0, lambda: set_mode(_mux_ready_mode()))
        return

    base     = os.path.splitext(os.path.basename(vid))[0]
    out_path = os.path.join(MUX_OUTPUT_DIR or os.path.dirname(os.path.abspath(vid)),
                            f"{base}_dubbed.mp4")

    # 🎼 Tách nhạc nền (demucs) trước khi mix — thay ducking bằng nhạc sạch
    music_wav = ""
    _demucs_tmps = []
    if keep_orig and has_video_audio and bool(mux_demucs_var.get()):
        app.after(0, lambda: log("[Ghép Audio] 🎼 Tách nhạc nền khỏi audio gốc "
                                 "(demucs — video dài có thể mất vài phút)..."))
        app.after(0, lambda: set_mode("muxing"))
        update_progress(1, 100)
        music_wav, _demucs_tmps = _mux_demucs_music(vid, ffmpeg_path)
        if VIDEOTOOL_STOP:
            for _t in _demucs_tmps:
                shutil.rmtree(_t, ignore_errors=True)
            app.after(0, lambda: log("[Ghép Audio] ⏹ Đã dừng theo yêu cầu."))
            app.after(0, lambda: set_mode(_mux_ready_mode()))
            return

    # Xây filter_complex cho audio
    # input 0 = video (kèm audio gốc nếu có), input 1 = audio final,
    # input 2 = nhạc nền sạch (chỉ khi tách demucs thành công)
    if keep_orig and has_video_audio and music_wav:
        # Nhạc nền đã sạch lời thoại → mix thẳng với giọng đọc, không cần ducking
        filt = (
            f"[2:a]volume={vid_vol}[a0];"
            f"[1:a]volume={aud_vol}[a1];"
            f"[a0][a1]amix=inputs=2:duration=longest:normalize=0[aout]"
        )
        mode_desc = (f"nhạc nền sạch demucs×{vid_vol} + giọng đọc×{aud_vol} "
                     "(đã bỏ lời thoại gốc)")
        amap = "[aout]"
    elif keep_orig and has_video_audio:
        duck = bool(mux_duck_var.get())
        if duck:
            # Ducking: hạ tiếng gốc khi giọng đọc đang nói (dùng giọng đọc làm
            # tín hiệu sidechain), trả lại đầy đủ khi gốc chỉ còn nhạc/SFX →
            # giọng lồng luôn nổi rõ mà vẫn nghe được nhạc nền dưới các quãng nghỉ.
            filt = (
                f"[0:a]volume={vid_vol}[a0];"
                f"[1:a]volume={aud_vol}[a1];"
                f"[a1]asplit=2[a1mix][a1key];"
                f"[a0][a1key]sidechaincompress="
                f"threshold=0.015:ratio=12:attack=20:release=350:makeup=1[a0d];"
                f"[a0d][a1mix]amix=inputs=2:duration=longest:normalize=0[aout]"
            )
            mode_desc = (f"trộn + ducking (gốc×{vid_vol} tự hạ khi có giọng×{aud_vol})")
        else:
            # Trộn audio gốc (video) + audio final ở âm lượng cố định
            filt = (
                f"[0:a]volume={vid_vol}[a0];"
                f"[1:a]volume={aud_vol}[a1];"
                f"[a0][a1]amix=inputs=2:duration=longest:normalize=0[aout]"
            )
            mode_desc = f"trộn (video×{vid_vol} + audio×{aud_vol})"
        amap = "[aout]"
    else:
        # Chỉ dùng audio final (thay thế audio gốc)
        filt = f"[1:a]volume={aud_vol}[aout]"
        amap = "[aout]"
        if keep_orig and not has_video_audio:
            app.after(0, lambda: log("[Ghép Audio] ⚠ Video không có audio gốc — chỉ dùng audio final"))
        mode_desc = f"thay thế (audio×{aud_vol})"

    # Gắn cứng phụ đề (wizard lồng tiếng set MUX_BURN_SRT): filter video phải
    # nằm CÙNG filter_complex (ffmpeg cấm trộn -vf với -filter_complex) và
    # buộc re-encode video (không -c:v copy được khi có filter).
    burn_srt = MUX_BURN_SRT if (MUX_BURN_SRT and os.path.isfile(MUX_BURN_SRT)) else ""
    if burn_srt:
        filt = f"[0:v]subtitles={_ff_sub_filterpath(burn_srt)}[vout];" + filt
        vmap = "[vout]"
        # Burn sub buộc re-encode video. Dùng GPU NVENC nếu có (CPU không bị 100%,
        # nhanh hơn nhiều); chỉ fallback libx264 (CPU) khi không có GPU NVIDIA.
        if DETECTED_GPU:
            vcodec = ["-c:v", "h264_nvenc", "-preset", "p5", "-rc", "vbr", "-cq", "23", "-b:v", "0"]
            _enc_note = f"GPU NVENC ({DETECTED_GPU})"
        else:
            vcodec = ["-c:v", "libx264", "-crf", "20", "-preset", "veryfast"]
            _enc_note = "CPU libx264"
        app.after(0, lambda: log(f"[Ghép Audio] 📝 Gắn phụ đề cứng: {os.path.basename(burn_srt)} "
                                 f"(re-encode video bằng {_enc_note})"))
    else:
        vmap = "0:v:0"
        vcodec = ["-c:v", "copy"]

    app.after(0, lambda: log(f"[Ghép Audio] Chế độ: {mode_desc}"))
    app.after(0, lambda: log(f"[Ghép Audio] Output: {out_path}"))
    app.after(0, lambda: set_mode("muxing"))
    _VIDEOTOOL_OUT = out_path
    update_progress(1, 100)

    cmd = [
        ffmpeg_path, "-y",
        "-i", vid,
        "-i", aud,
    ] + (["-i", music_wav] if music_wav else []) + [
        "-filter_complex", filt,
        "-map", vmap,
        "-map", amap,
    ] + vcodec + [
        "-c:a", "aac", "-b:a", "192k",
        "-movflags", "+faststart",
        out_path
    ]

    try:
        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            creationflags=CREATE_NO_WINDOW
        )
        _VIDEOTOOL_PROC = proc

        _last_pct = [-1]
        _last_log_pct = [-1]

        for line in proc.stdout:
            line = line.rstrip()
            m = re.search(r"time=(\d+):(\d+):([\d.]+)", line)
            if m and duration_s > 0:
                elapsed = int(m.group(1)) * 3600 + int(m.group(2)) * 60 + float(m.group(3))
                pct = max(1, min(99, int(elapsed / duration_s * 100)))
                if pct != _last_pct[0]:
                    _last_pct[0] = pct
                    update_progress(pct, 100)
                if pct // 10 != _last_log_pct[0]:
                    _last_log_pct[0] = pct // 10
                    app.after(0, lambda p=pct: log(f"[Ghép Audio] ⏳ {p}%"))

        proc.wait()
        _VIDEOTOOL_PROC = None

        if VIDEOTOOL_STOP:
            try:
                if os.path.isfile(out_path):
                    os.remove(out_path)
            except Exception:
                pass
            app.after(0, lambda: log("[Ghép Audio] ⏹ Đã dừng theo yêu cầu."))
            app.after(0, lambda: set_mode(_mux_ready_mode()))
        elif proc.returncode == 0 and os.path.isfile(out_path):
            new_mb = os.path.getsize(out_path) / (1024 * 1024)
            update_progress(100, 100)
            app.after(0, lambda: log(f"[Ghép Audio] ✅ Hoàn tất! → {os.path.basename(out_path)} ({new_mb:.1f} MB)"))
            app.after(0, show_fireworks)
            app.after(0, lambda: set_mode("mux_done"))
            app.after(200, open_mux_folder)
        else:
            app.after(0, lambda: log(f"[Ghép Audio] ❌ ffmpeg lỗi (exit {proc.returncode})"))
            app.after(0, lambda: set_mode(_mux_ready_mode()))

    except Exception as exc:
        app.after(0, lambda exc=exc: log(f"[Ghép Audio] ❌ Exception: {exc}"))
        app.after(0, lambda: set_mode(_mux_ready_mode()))
    finally:
        _VIDEOTOOL_PROC = None
        for _t in _demucs_tmps:
            shutil.rmtree(_t, ignore_errors=True)


def start_mux_video():
    if not MUX_VIDEO_FILE:
        msg.showerror("Ghép Audio", "Chưa chọn video. Nhấn 'Chọn Video (Ghép)' trước.")
        return
    if not MUX_AUDIO_FILE:
        msg.showerror("Ghép Audio", "Chưa chọn audio. Nhấn 'Chọn Audio (Ghép)' trước.")
        return
    threading.Thread(target=_run_mux_thread, daemon=True).start()


def open_mux_folder():
    d = MUX_OUTPUT_DIR or (os.path.dirname(os.path.abspath(MUX_VIDEO_FILE)) if MUX_VIDEO_FILE else "")
    if d and os.path.isdir(d):
        os.startfile(d)
    else:
        log("[Ghép Audio] Thư mục output chưa xác định.")


# =========================
# 🖼 AUDIO → VIDEO — ảnh nền + audio (+ phụ đề) → MP4 đăng YouTube
# =========================
# Pattern translate-button: nút luôn bật, tự khóa qua _A2V_RUNNING; Stop kill
# thẳng proc ffmpeg. Encoder GPU-aware như bước burn-in của Mux.
_A2V_RUNNING = [False]
_A2V_PROC = [None]

def _a2v_browse(var, kind):
    if kind == "audio":
        p = filedialog.askopenfilename(
            title="Chọn file audio",
            initialdir=OUTPUT_DIR if os.path.isdir(OUTPUT_DIR or "") else None,
            filetypes=[("Audio", "*.mp3 *.wav *.m4a *.opus *.aac *.flac"),
                       ("All files", "*.*")])
    elif kind == "image":
        p = filedialog.askopenfilename(
            title="Chọn ảnh nền",
            filetypes=[("Ảnh", "*.jpg *.jpeg *.png *.bmp *.webp"),
                       ("All files", "*.*")])
    else:
        p = filedialog.askopenfilename(
            title="Chọn phụ đề (SRT)",
            initialdir=OUTPUT_DIR if os.path.isdir(OUTPUT_DIR or "") else None,
            filetypes=[("SRT", "*.srt"), ("All files", "*.*")])
    if p:
        var.set(p)


def _a2v_stop():
    p = _A2V_PROC[0]
    if p:
        try:
            p.kill()
            log("[Audio→Video] ⏹ Đã dừng.")
        except Exception:
            pass
    else:
        log("[Audio→Video] Không có tiến trình nào đang chạy.")


def start_audio_to_video():
    if _A2V_RUNNING[0]:
        log("[Audio→Video] Đang chạy — đợi xong đã.")
        return
    aud = a2v_audio_var.get().strip()
    if not aud or not os.path.isfile(aud):
        log("[Audio→Video] ❌ Chưa chọn file audio hợp lệ.")
        return
    img = a2v_img_var.get().strip()
    if img and not os.path.isfile(img):
        log("[Audio→Video] ❌ Không thấy file ảnh nền.")
        return
    srt_p = a2v_srt_var.get().strip()
    if srt_p and not os.path.isfile(srt_p):
        log("[Audio→Video] ❌ Không thấy file phụ đề.")
        return
    ffmpeg_ok, ffmpeg_path, guide = _check_ffmpeg_exists()
    if not ffmpeg_ok:
        for l in guide.splitlines():
            log(l)
        return
    out_path = os.path.splitext(aud)[0] + "_video.mp4"

    def _run():
        _A2V_RUNNING[0] = True
        try:
            dur = _probe_duration_sec(aud)
            log(f"[Audio→Video] {os.path.basename(aud)} ({_fmt_dur(dur)}) "
                f"→ {os.path.basename(out_path)}"
                + (" | ảnh nền" if img else " | nền màu tối")
                + (" | burn phụ đề" if srt_p else ""))
            # scale/pad về 720p chẵn pixel (libx264 kỵ kích thước lẻ)
            vf = ("scale=1280:720:force_original_aspect_ratio=decrease,"
                  "pad=1280:720:(ow-iw)/2:(oh-ih)/2:color=black")
            if srt_p:
                vf += f",subtitles={_ff_sub_filterpath(srt_p)}"
            if globals().get("DETECTED_GPU"):
                vcodec = ["-c:v", "h264_nvenc", "-preset", "p5",
                          "-rc", "vbr", "-cq", "26", "-b:v", "0"]
            else:
                vcodec = ["-c:v", "libx264", "-tune", "stillimage",
                          "-preset", "veryfast", "-crf", "23"]
            if img:
                src = ["-loop", "1", "-framerate", "15", "-i", img]
            else:
                src = ["-f", "lavfi", "-i", "color=c=0x141a26:s=1280x720:r=15"]
            cmd = ([ffmpeg_path, "-y"] + src + ["-i", aud, "-vf", vf]
                   + vcodec
                   + ["-c:a", "aac", "-b:a", "192k", "-pix_fmt", "yuv420p",
                      "-shortest", "-movflags", "+faststart", out_path])
            proc = subprocess.Popen(
                cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, encoding="utf-8", errors="replace",
                creationflags=CREATE_NO_WINDOW)
            RUNNING_PROCESSES.append(proc)
            _A2V_PROC[0] = proc
            for line in proc.stdout:
                m = re.search(r"time=(\d+):(\d+):([\d.]+)", line)
                if m and dur > 0:
                    el = (int(m.group(1)) * 3600 + int(m.group(2)) * 60
                          + float(m.group(3)))
                    update_progress(min(el, dur), dur)
            proc.wait()
            try:
                RUNNING_PROCESSES.remove(proc)
            except ValueError:
                pass
            if proc.returncode == 0 and os.path.isfile(out_path):
                update_progress(1, 1)
                mb = os.path.getsize(out_path) / 2**20
                log(f"[Audio→Video] ✅ Xong: {os.path.basename(out_path)} ({mb:.1f} MB)")
                app.after(0, show_fireworks)
                try:
                    _reveal_output(out_path)
                except Exception:
                    pass
            else:
                log(f"[Audio→Video] ❌ ffmpeg lỗi (exit {proc.returncode}) — "
                    "xem file log để biết chi tiết.")
        except Exception as e:
            log(f"[Audio→Video] ❌ {e}")
        finally:
            _A2V_PROC[0] = None
            _A2V_RUNNING[0] = False

    threading.Thread(target=_run, daemon=True).start()


def _find_whisper_python():
    """Tìm python có faster-whisper (voxcpm_env) để chạy srt_align_helper.py."""
    # 0. User override từ Settings
    if VOXCPM_ENV_OVERRIDE and os.path.isfile(VOXCPM_ENV_OVERRIDE):
        return VOXCPM_ENV_OVERRIDE
    # 1. Theo thư mục model VoxCPM người dùng đã chọn
    ckpt = ""
    try:
        ckpt = voxcpm_ckpt_var.get().strip()
    except Exception:
        ckpt = ""
    if ckpt:
        p = _find_voxcpm_python(ckpt)
        if p:
            return p
    # 2. Đường dẫn quen thuộc
    for cand in (
        r"E:\VoxCPM-1.5-VN\voxcpm_env\Scripts\python.exe",
        os.path.join(os.path.dirname(sys.executable), "voxcpm_env", "Scripts", "python.exe"),
    ):
        if os.path.isfile(cand):
            return cand
    return None


def _find_srt_align_helper():
    name = 'srt_align_helper.py'
    search = [
        getattr(sys, '_MEIPASS', None),
        os.path.dirname(__file__) if '__file__' in globals() else None,
        os.path.dirname(sys.argv[0]),
        os.path.dirname(sys.executable),
    ]
    for d in search:
        if d:
            p = os.path.join(d, name)
            if os.path.isfile(p):
                return p
    return None


def _run_srt_align(srt_in):
    """Căn lại timing SRT theo giọng nói thật (VAD). Trả về đường dẫn SRT mới
    (đã căn) nếu thành công, ngược lại trả về srt_in gốc."""
    if not (VIDEOCR_VIDEO and os.path.isfile(srt_in)):
        return srt_in

    py = _find_whisper_python()
    if not py:
        log("[VideoOCR] ⚠ Không tìm thấy voxcpm_env (faster-whisper) — bỏ qua căn giọng, giữ SRT gốc")
        return srt_in

    helper = _find_srt_align_helper()
    if not helper:
        log("[VideoOCR] ⚠ Không tìm thấy srt_align_helper.py — giữ SRT gốc")
        return srt_in

    base, ext = os.path.splitext(srt_in)
    srt_out = base + "_aligned" + ext

    cmd = [
        py, helper,
        "--video",   VIDEOCR_VIDEO,
        "--srt_in",  srt_in,
        "--srt_out", srt_out,
    ]
    env = os.environ.copy()
    env["PYTHONIOENCODING"] = "utf-8"

    log("[VideoOCR] 🎙 Căn timing theo giọng nói thật (VAD)...")
    try:
        proc = subprocess.Popen(
            cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            env=env, creationflags=CREATE_NO_WINDOW,
        )
        RUNNING_PROCESSES.append(proc)
        ok = False
        for raw in proc.stdout:
            line = raw.decode("utf-8", errors="replace").strip()
            if not line:
                continue
            if line.startswith("DONE:"):
                srt_out = line[5:]
                ok = True
            elif line.startswith("ERROR:"):
                log(f"[VideoOCR]   ❌ Căn giọng lỗi: {line[6:]}")
            elif line.startswith("PROGRESS:"):
                log(f"[VideoOCR]   {line[9:]}")
            else:
                log(f"    {line}")
        proc.wait()
        if proc in RUNNING_PROCESSES:
            RUNNING_PROCESSES.remove(proc)

        if ok and os.path.isfile(srt_out):
            log(f"[VideoOCR] ✅ SRT đã căn giọng: {srt_out}")
            return srt_out
        log("[VideoOCR] ⚠ Căn giọng không thành công — giữ SRT gốc")
        return srt_in
    except Exception as exc:
        log(f"[VideoOCR] ⚠ Căn giọng exception: {exc} — giữ SRT gốc")
        return srt_in


def load_pdf():
    global PDF_FILE

    selected = filedialog.askopenfilename(
        title="Chọn file PDF",
        filetypes=[("PDF files", "*.pdf"), ("All files", "*.*")]
    )
    if not selected:
        return

    PDF_FILE = selected
    log(f"[PDF] Load: {os.path.basename(PDF_FILE)}")

    def _worker():
        import json as _json
        import tempfile

        py = _find_pdf_python()
        helper = _find_pdf_helper()

        if not py:
            app.after(0, lambda: log("[PDF] Không tìm thấy Python có pypdf.\n"
                                     "      Cài pypdf: pip install pypdf"))
            return
        if not helper:
            app.after(0, lambda: log("[PDF] Không tìm thấy pdf_helper.py cạnh app."))
            return

        tmp_json = os.path.join(tempfile.gettempdir(), '_pdf_chunks.json')
        try:
            result = subprocess.run(
                [py, helper, '--input', PDF_FILE, '--output', tmp_json],
                capture_output=True, text=True, encoding='utf-8', errors='replace',
                timeout=120, creationflags=CREATE_NO_WINDOW,
            )
            stdout = result.stdout.strip()
            if result.returncode != 0 or not stdout.startswith('DONE:'):
                err = result.stderr.strip()[:300] or stdout
                app.after(0, lambda: log(f"[PDF] Lỗi: {err}"))
                return

            parts = stdout.split(':')
            page_count = int(parts[1]) if len(parts) > 1 else '?'

            with open(tmp_json, encoding='utf-8') as f:
                data = _json.load(f)
            chunks = data.get('chunks', [])

            def _on_done():
                global PDF_CHUNKS
                PDF_CHUNKS = chunks
                subtitle_list.configure(state='normal')
                subtitle_list.delete('1.0', 'end')
                for i, chunk in enumerate(chunks):
                    subtitle_list.insert('end', f'[{i}] {chunk}\n\n')
                subtitle_list.configure(state='disabled')
                log(f"[PDF] {page_count} trang → {len(chunks)} đoạn")
                set_mode('pdf')

            app.after(0, _on_done)
        except Exception as e:
            err = str(e)
            app.after(0, lambda: log(f"[PDF] Lỗi: {err}"))
        finally:
            try:
                os.remove(tmp_json)
            except Exception:
                pass

    threading.Thread(target=_worker, daemon=True).start()


def _epub_extract_text(path):
    """Bóc text từ .epub bằng stdlib (zip chứa xhtml — không cần lib ngoài).
    Đọc theo đúng thứ tự SPINE trong content.opf (container.xml → opf →
    manifest/spine); opf hỏng → fallback sort tên file. Trả về text thuần."""
    import zipfile
    import html as _html
    with zipfile.ZipFile(path) as z:
        names = z.namelist()
        ordered = []
        try:
            container = z.read("META-INF/container.xml").decode("utf-8", "replace")
            m = re.search(r'full-path="([^"]+)"', container)
            opf_path = m.group(1)
            opf = z.read(opf_path).decode("utf-8", "replace")
            opf_dir = os.path.dirname(opf_path)
            # manifest: id → href
            man = dict(re.findall(
                r'<item[^>]*\bid="([^"]+)"[^>]*\bhref="([^"]+)"', opf))
            man.update(dict(
                (i, h) for h, i in re.findall(
                    r'<item[^>]*\bhref="([^"]+)"[^>]*\bid="([^"]+)"', opf)))
            for idref in re.findall(r'<itemref[^>]*\bidref="([^"]+)"', opf):
                href = man.get(idref)
                if not href:
                    continue
                full = (opf_dir + "/" + href) if opf_dir else href
                full = full.replace("\\", "/")
                if full in names:
                    ordered.append(full)
        except Exception:
            ordered = []
        if not ordered:   # opf không đọc được → mọi file html theo tên
            ordered = sorted(n for n in names
                             if n.lower().endswith((".xhtml", ".html", ".htm")))
        parts = []
        for n in ordered:
            if not n.lower().endswith((".xhtml", ".html", ".htm")):
                continue
            try:
                raw = z.read(n).decode("utf-8", "replace")
            except Exception:
                continue
            raw = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", " ", raw)
            raw = re.sub(r"(?i)<br[^>]*>", "\n", raw)
            raw = re.sub(r"(?i)</(p|div|h[1-6]|li|tr)>", "\n\n", raw)
            raw = re.sub(r"<[^>]+>", " ", raw)
            raw = _html.unescape(raw)
            raw = re.sub(r"[ \t]+", " ", raw)
            raw = re.sub(r"\n{3,}", "\n\n", raw).strip()
            if raw:
                parts.append(raw)
    return "\n\n".join(parts)


def load_doc_tts():
    """Nạp file Word (.docx) / EPUB / TXT vào pipeline PDF_CHUNKS để Đọc (TTS)
    — dùng chung toàn bộ chức năng với Đọc PDF (TTS)."""
    global PDF_FILE
    selected = filedialog.askopenfilename(
        title="Chọn file Word (.docx) / EPUB / TXT để đọc (TTS)",
        filetypes=[("Word / EPUB / Text", "*.docx *.epub *.txt"),
                   ("Word", "*.docx"), ("EPUB (ebook)", "*.epub"),
                   ("Text", "*.txt"), ("All files", "*.*")]
    )
    if not selected:
        return
    PDF_FILE = selected
    log(f"[DOC] Load: {os.path.basename(selected)}")

    def _worker():
        global PDF_CHUNKS
        try:
            ext = os.path.splitext(selected)[1].lower()
            if ext == ".docx":
                try:
                    from docx import Document
                except Exception:
                    app.after(0, lambda: log("[DOC] Thiếu python-docx (pip install python-docx)."))
                    return
                text = "\n\n".join(p.text for p in Document(selected).paragraphs if p.text.strip())
            elif ext == ".epub":
                text = _epub_extract_text(selected)
            else:  # .txt / text khác
                text = _read_text_smart(selected)
            chunks = _split_text_chunks(text)
            if not chunks:
                app.after(0, lambda: log("[DOC] File không có nội dung text để đọc."))
                return

            def _on_done():
                global PDF_CHUNKS
                PDF_CHUNKS = chunks
                subtitle_list.configure(state='normal')
                subtitle_list.delete('1.0', 'end')
                for i, chunk in enumerate(chunks):
                    subtitle_list.insert('end', f'[{i}] {chunk}\n\n')
                subtitle_list.configure(state='disabled')
                log(f"[DOC] {os.path.basename(selected)} → {len(chunks)} đoạn")
                set_mode('pdf')
            app.after(0, _on_done)
        except Exception as e:
            err = str(e)
            app.after(0, lambda: log(f"[DOC] Lỗi: {err}"))

    threading.Thread(target=_worker, daemon=True).start()


async def _wait_net_recovery(label=""):
    """📶 Rớt mạng giữa batch: thay vì dừng hẳn (sáng dậy thấy chạy 30%), chờ
    mạng quay lại — poll check_internet() 30s/lần, tối đa 30 phút — rồi tự chạy
    tiếp (skip-existing lo phần resume). Stop vẫn nhạy (kiểm mỗi giây).
    → True nếu mạng đã về, False nếu bị Dừng / hết 30 phút."""
    log(f"{label}📶 Mất mạng — tự chờ kết nối trở lại (tối đa 30 phút; "
        "bấm Dừng nếu muốn hủy)…")
    _loop = asyncio.get_event_loop()
    for _try in range(60):                    # 60 lượt × ~30s ≈ 30 phút
        for _ in range(30):
            if stop_requested:
                return False
            await asyncio.sleep(1)
        if await _loop.run_in_executor(None, check_internet):
            _net_was_online[0] = True         # cập nhật ngay cache của monitor
            log(f"{label}📶 ✅ Mạng đã trở lại — tự tiếp tục batch "
                "(các dòng đã có audio sẽ được skip).")
            return True
    log(f"{label}❌ Chờ 30 phút vẫn chưa có mạng — dừng tiến trình.")
    return False


def _pdf_range(total):
    """Đọc 2 ô 'Từ đoạn / đến' → (lo, hi) 0-based, kẹp trong [0, total-1].
    Rỗng / nhập lỗi = toàn bộ. Cho phép đọc riêng 1 chương của tài liệu dài."""
    lo, hi = 0, total - 1
    try:
        s = pdf_from_var.get().strip()
        if s:
            lo = max(0, min(int(float(s)), total - 1))
    except Exception:
        pass
    try:
        s = pdf_to_var.get().strip()
        if s:
            hi = max(0, min(int(float(s)), total - 1))
    except Exception:
        pass
    if lo > hi:
        lo, hi = hi, lo
    return lo, hi


async def _generate_pdf_tts():
    global current_index, paused, stop_requested, FAIL_COUNT

    if not PDF_CHUNKS:
        log("[PDF] Chưa load file PDF")
        app.after(0, lambda: set_mode("pdf"))
        return

    FAIL_COUNT = 0

    if RVC_ENABLED and not _check_rvc_preflight():
        return

    app.after(0, _hide_quota_banner)
    app.after(0, lambda: set_mode("tts_running"))

    total = len(PDF_CHUNKS)
    update_progress(current_index, total)

    # 📖 Phạm vi đọc (Từ đoạn / đến) — đọc riêng 1 chương của tài liệu dài
    _rlo, _rhi = _pdf_range(total)
    if (_rlo, _rhi) != (0, total - 1):
        log(f"[PDF] 📖 Chỉ đọc đoạn {_rlo} → {_rhi} (theo ô 'Từ đoạn/đến')")

    # 📊 Reset thống kê + ước khối lượng/phí/thời gian cho phần CÒN THIẾU
    _batch_stats_reset()
    _est_lines = 0
    _est_chars = 0
    for _ei in range(max(current_index, _rlo), min(total, _rhi + 1)):
        _et = (PDF_CHUNKS[_ei] or "").strip()
        if _et and not os.path.exists(
                os.path.join(OUTPUT_DIR, f"pdf_line_{_ei:04d}.mp3")):
            _est_lines += 1
            _est_chars += len(_et)
    _log_cost_estimate(_est_lines, _est_chars, label="[PDF] ")
    _log_eta_estimate(_est_lines)
    _warn_low_disk(OUTPUT_DIR, _est_chars * 4500, label="[PDF] ")

    # ⚡ Nhánh song song: chỉ Edge TTS không RVC (xem chú thích _TTS_PARALLEL_N)
    if TTS_PROVIDER == "Edge TTS" and not RVC_ENABLED and _TTS_PARALLEL_N > 1:
        _st = await _generate_pdf_tts_parallel()
        # 📶 rớt mạng → chờ hồi phục rồi chạy lại (skip-existing = resume)
        while _st["netdown"] and not stop_requested \
                and await _wait_net_recovery("[PDF] "):
            _st = await _generate_pdf_tts_parallel()
        if stop_requested:
            log("PROCESS STOPPED")
            return
        if _st["netdown"]:
            log("❌ PDF TTS: Mất kết nối Internet — dừng tiến trình. "
                "Khôi phục mạng rồi nhấn Resume để tiếp tục.")
            app.after(0, lambda: set_mode("tts_stopped"))
            return
        if _st["quota"]:
            _provider = TTS_PROVIDER
            app.after(0, lambda p=_provider: _show_quota_banner(p))
            app.after(0, lambda: set_mode("tts_stopped"))
            return
        log("[PDF] TTS DONE")
        _log_batch_stats()
        app.after(0, show_fireworks)
        update_progress(total, total)
        current_index = 0
        app.after(0, lambda: set_mode("pdf_tts_done"))
        app.after(200, open_output_folder)
        _maybe_auto_retry_fail()
        return

    while current_index < total:
        if stop_requested:
            log("PROCESS STOPPED")
            return

        # 📖 Ngoài phạm vi 'Từ đoạn/đến' → bỏ qua (không tính FAIL/thiếu)
        if not (_rlo <= current_index <= _rhi):
            current_index += 1
            continue

        # Kiểm tra internet mỗi đoạn PDF (dùng cache monitor, không ping thêm).
        if not _net_was_online[0]:
            if await _wait_net_recovery("[PDF] "):
                continue     # mạng đã về → đọc tiếp từ đoạn hiện tại
            log("❌ PDF TTS: Mất kết nối Internet — dừng tiến trình. "
                "Khôi phục mạng rồi nhấn Resume để tiếp tục.")
            app.after(0, lambda: set_mode("tts_stopped"))
            return

        while paused:
            await asyncio.sleep(0.5)

        text = PDF_CHUNKS[current_index].strip()
        if not text:
            current_index += 1
            continue

        if not _is_speakable(text):
            log(f"⏭ [PDF] Đoạn {current_index}: không có nội dung đọc được — bỏ qua")
            current_index += 1
            continue

        filename = os.path.join(OUTPUT_DIR, f"pdf_line_{current_index:04d}.mp3")

        if os.path.exists(filename):
            log(f"[PDF] SKIP {current_index}")
            current_index += 1
            continue

        # ♻ đoạn trùng → copy audio đã pass QC, khỏi gọi API (trừ khi RVC bật)
        if not RVC_ENABLED:
            _cf = _tts_cache_get(text)
            if _cf:
                try:
                    shutil.copy2(_cf, filename)
                    log(f"♻ [PDF] OK {current_index} (đoạn trùng — dùng lại audio)")
                    _BATCH_STATS["cache"] += 1
                    current_index += 1
                    update_progress(current_index, total)
                    continue
                except Exception:
                    pass

        preview = text[:60] + ("..." if len(text) > 60 else "")
        log(f"[PDF] {current_index + 1}/{total}: {preview}")

        ok = False
        _bad = False
        _reason = ""
        _detail = ""
        for _qc_attempt in range(_QC_MAX_RETRIES + 1):
            _gen_text = (_sanitize_tts_text(text)
                         if _qc_attempt == _QC_MAX_RETRIES else text)
            try:
                ok = await save_tts(_gen_text, filename)
            except QuotaExhaustedError as qe:
                log(f"HẾT QUOTA: {qe}")
                _provider = TTS_PROVIDER
                app.after(0, lambda p=_provider: _show_quota_banner(p))
                app.after(0, lambda: set_mode("tts_stopped"))
                return
            if not ok:
                break
            _loop = asyncio.get_event_loop()
            _bad, _reason, _detail = await _loop.run_in_executor(
                None, _audio_quality_check, filename, text)
            if not _bad:
                break
            if _qc_attempt < _QC_MAX_RETRIES:
                log(f"  ⚠ [PDF] Dòng {current_index}: audio {_reason} ({_detail}) — "
                    f"tạo lại lần {_qc_attempt + 1}/{_QC_MAX_RETRIES}")
                _BATCH_STATS["retry"] += 1
                try:
                    os.remove(filename)
                except Exception:
                    pass

        if ok and not _bad:
            log(f"[PDF] OK {current_index}")
            _BATCH_STATS["gen"] += 1
            if not RVC_ENABLED:
                _tts_cache_put(text, filename)
            if RVC_ENABLED and os.path.exists(filename):
                try:
                    log(f"  RVC convert {current_index}...")
                    _loop = asyncio.get_event_loop()
                    await _loop.run_in_executor(None, _apply_rvc_sync, filename)
                    log(f"  RVC OK")
                    _rbad, _rreason, _rdetail = await _loop.run_in_executor(
                        None, _audio_quality_check, filename, text)
                    if _rbad:
                        _rename_bad_audio(filename, current_index, _rreason, _rdetail, "RVC")
                        log(f"[PDF] FAIL {current_index}")
                        FAIL_COUNT += 1
                except Exception as _rvc_err:
                    log(f"❌ RVC thất bại tại dòng {current_index}: {_rvc_err}")
                    log("  • Thử đổi Algo sang rmvpe hoặc harvest")
                    log("  • Thử chuyển Device sang CPU")
                    log(f"[PDF] FAIL {current_index}")
                    FAIL_COUNT += 1
        elif ok and _bad:
            _rename_bad_audio(filename, current_index, _reason, _detail, "PDF")
            log(f"[PDF] FAIL {current_index}")
            FAIL_COUNT += 1
        else:
            log(f"[PDF] FAIL {current_index}")
            FAIL_COUNT += 1

        current_index += 1
        update_progress(current_index, total)

        try:
            _dmin = float(delay_min_var.get())
            _dmax = float(delay_max_var.get())
            if _dmin < 0: _dmin = 0.0
            if _dmax < _dmin: _dmax = _dmin
        except ValueError:
            _dmin, _dmax = TTS_DELAY_MIN, TTS_DELAY_MAX
        _pdf_delay = random.uniform(_dmin, _dmax)
        log(f"⏱ chờ {_pdf_delay:.2f}s")
        await asyncio.sleep(_pdf_delay)

    log("[PDF] TTS DONE")
    _log_batch_stats()
    app.after(0, show_fireworks)
    update_progress(total, total)
    current_index = 0
    app.after(0, lambda: set_mode("pdf_tts_done"))
    app.after(200, open_output_folder)
    _maybe_auto_retry_fail()


def start_pdf_tts():
    global paused, stop_requested, current_index

    if not PDF_CHUNKS:
        log("[PDF] Chưa load file PDF!")
        return

    paused = False
    stop_requested = False
    current_index = 0

    if VOXCPM_ENABLED:
        # VoxCPM chạy local — không cần internet
        threading.Thread(target=_run_voxcpm_batch_pdf, daemon=True).start()
        return

    if VIENEU_ENABLED:
        # VieNeu chạy local (lần đầu cần internet để tải model)
        threading.Thread(target=_run_vieneu_batch_pdf, daemon=True).start()
        return

    if F5TTS_ENABLED:
        # F5-TTS chạy local — không cần internet
        threading.Thread(target=_run_f5tts_batch_pdf, daemon=True).start()
        return

    if OMNIVOICE_ENABLED:
        # OmniVoice chạy local (lần đầu cần internet để tải model)
        threading.Thread(target=_run_omnivoice_batch_pdf, daemon=True).start()
        return

    # Edge TTS / các provider online → cần internet
    if not _require_internet("PDF TTS"):
        return

    threading.Thread(
        target=lambda: asyncio.run(_generate_pdf_tts()),
        daemon=True
    ).start()


# Heading chương trong tài liệu (audiobook): chunk NGẮN bắt đầu bằng
# "Chương/Chapter/Phần/Hồi/Tập N" → mốc chapter khi xuất .m4b.
_DOC_CHAPTER_RE = re.compile(
    r"^\s*(chương|chapter|phần|part|hồi|tập)\s+([0-9]+|[IVXLC]+)\b",
    re.IGNORECASE)


def _doc_chapter_title(chunk):
    """Tên chương nếu chunk là heading (ngắn + khớp _DOC_CHAPTER_RE), else None."""
    t = (chunk or "").strip()
    if not t or len(t) > 100:
        return None
    return t[:80] if _DOC_CHAPTER_RE.match(t) else None


def merge_pdf_audio():
    if not PDF_CHUNKS:
        log("[PDF] Chưa load PDF để merge")
        return

    files = []
    file_idxs = []   # chunk index song song files — để dò heading chương (m4b)
    for i in range(len(PDF_CHUNKS)):
        f = os.path.join(OUTPUT_DIR, f"pdf_line_{i:04d}.mp3")
        if os.path.exists(f):
            files.append(f)
            file_idxs.append(i)

    if not files:
        log("[PDF] Không có file MP3 nào để merge")
        return

    log(f"[PDF] Merge {len(files)}/{len(PDF_CHUNKS)} files...")

    # ⏸ Khoảng nghỉ giữa đoạn (audiobook nghe có nhịp thở) — đọc var trên main
    # thread trước khi vào worker; 0/rỗng = tắt, kẹp 0..5000ms.
    try:
        gap_ms = max(0, min(int(float(pdf_gap_var.get().strip() or "0")), 5000))
    except Exception:
        gap_ms = 0
    try:
        make_m4b = bool(pdf_m4b_var.get())
    except Exception:
        make_m4b = False
    chunks_snap = list(PDF_CHUNKS)   # chụp trên main thread cho worker

    import time as _time
    ts = int(_time.time())
    output_path = os.path.join(OUTPUT_DIR, f"pdf_output_{ts}.mp3")
    list_path = os.path.join(OUTPUT_DIR, "_pdf_concat.txt")
    gap_path = os.path.join(OUTPUT_DIR, "_pdf_gap.mp3")

    def _make_gap_file():
        """File lặng gap_ms khớp sample-rate/kênh với dòng đầu (concat -c copy
        cần stream đồng nhất). Trả về True nếu tạo được."""
        try:
            pr = subprocess.run(
                [get_ffprobe(), "-v", "quiet", "-select_streams", "a:0",
                 "-show_entries", "stream=sample_rate,channels",
                 "-of", "csv=p=0", files[0]],
                capture_output=True, text=True, timeout=30,
                creationflags=CREATE_NO_WINDOW)
            parts = (pr.stdout or "").strip().split(",")
            sr = int(parts[0]) if parts and parts[0].isdigit() else 24000
            ch = int(parts[1]) if len(parts) > 1 and parts[1].isdigit() else 1
            r = subprocess.run(
                [FFMPEG, "-y", "-v", "quiet", "-f", "lavfi",
                 "-i", f"anullsrc=r={sr}:cl={'mono' if ch == 1 else 'stereo'}",
                 "-t", f"{gap_ms / 1000.0:.3f}", "-c:a", "libmp3lame",
                 "-b:a", "64k", gap_path],
                capture_output=True, timeout=60, creationflags=CREATE_NO_WINDOW)
            return r.returncode == 0 and os.path.isfile(gap_path)
        except Exception:
            return False

    def _build_m4b(use_gap):
        """📚 Xuất thêm .m4b có CHAPTER MARKERS từ heading 'Chương N…' trong
        chunks — người nghe tua theo chương trên mọi player. Probe thời lượng
        từng file (+gap) để tính mốc; ghi ffmetadata rồi encode AAC. Lỗi ở
        bước này chỉ log ⚠ — file mp3 merge vẫn còn nguyên."""
        meta_path = os.path.join(OUTPUT_DIR, "_m4b_meta.txt")
        try:
            app.after(0, lambda: log("[PDF] 📚 Xuất .m4b có chương "
                                     "(đo thời lượng từng đoạn — hơi lâu)…"))
            marks = []
            t = 0.0
            for pos, (fp, ci) in enumerate(zip(files, file_idxs)):
                title = (_doc_chapter_title(chunks_snap[ci])
                         if ci < len(chunks_snap) else None)
                if title:
                    marks.append((t, title))
                t += _probe_duration_sec(fp) or 0.0
                if use_gap and pos < len(files) - 1:
                    t += gap_ms / 1000.0
            if not marks or marks[0][0] > 0.5:
                marks.insert(0, (0.0, "Mở đầu"))
            with open(meta_path, "w", encoding="utf-8") as mf:
                mf.write(";FFMETADATA1\n")
                for k, (st, title) in enumerate(marks):
                    end = marks[k + 1][0] if k + 1 < len(marks) else t
                    safe = re.sub(r"[=;#\\\n]", " ", title).strip()
                    mf.write("[CHAPTER]\nTIMEBASE=1/1000\n"
                             f"START={int(st * 1000)}\nEND={int(end * 1000)}\n"
                             f"title={safe}\n")
            m4b_path = os.path.splitext(output_path)[0] + ".m4b"
            r = subprocess.run(
                [FFMPEG, "-y", "-v", "error", "-i", output_path,
                 "-i", meta_path, "-map_metadata", "1",
                 "-c:a", "aac", "-b:a", "96k", m4b_path],
                capture_output=True, timeout=3600,
                creationflags=CREATE_NO_WINDOW)
            if r.returncode == 0 and os.path.isfile(m4b_path):
                app.after(0, lambda: log(
                    f"[PDF] 📚 {os.path.basename(m4b_path)} — "
                    f"{len(marks)} chương, tua theo chương được trên mọi player."))
            else:
                app.after(0, lambda: log("[PDF] ⚠ Encode .m4b lỗi — file mp3 vẫn OK."))
        except Exception as e:
            app.after(0, lambda e=e: log(f"[PDF] ⚠ Lỗi xuất .m4b: {e} — file mp3 vẫn OK."))
        finally:
            try:
                os.remove(meta_path)
            except Exception:
                pass

    def _do_merge():
        try:
            update_progress(5, 100)
            use_gap = gap_ms > 0 and _make_gap_file()
            if gap_ms > 0 and not use_gap:
                app.after(0, lambda: log("[PDF] ⚠ Không tạo được file lặng — merge không khoảng nghỉ"))
            elif use_gap:
                app.after(0, lambda: log(f"[PDF] ⏸ Chèn {gap_ms}ms nghỉ giữa các đoạn"))
            n = len(files)
            gap_safe = gap_path.replace("\\", "/")
            with open(list_path, "w", encoding="utf-8") as lf:
                for i, fp in enumerate(files, 1):
                    safe = fp.replace("\\", "/")
                    if use_gap and i > 1:
                        lf.write(f"file '{gap_safe}'\n")
                    lf.write(f"file '{safe}'\n")
                    # 5% → 50% trong lúc dựng danh sách file
                    update_progress(5 + int(45 * i / n), 100)

            update_progress(55, 100)
            result = subprocess.run(
                [FFMPEG, "-y", "-f", "concat", "-safe", "0",
                 "-i", list_path, "-c", "copy", output_path],
                capture_output=True,
                creationflags=CREATE_NO_WINDOW
            )
            if result.returncode == 0:
                out_name = os.path.basename(output_path)
                update_progress(100, 100)
                app.after(0, lambda: log(f"[PDF] Merge OK → {out_name}"))
                if make_m4b:
                    _build_m4b(use_gap)
                app.after(0, show_fireworks)
                app.after(200, open_output_folder)
            else:
                err = (result.stderr or b"").decode("utf-8", errors="replace")
                app.after(0, lambda: log(f"[PDF] Merge FAIL: {err[:200]}"))
        except Exception as e:
            app.after(0, lambda e=e: log(f"[PDF] Merge lỗi: {e}"))
        finally:
            for _p in (list_path, gap_path):
                try:
                    os.remove(_p)
                except Exception:
                    pass

    threading.Thread(target=_do_merge, daemon=True).start()


# =========================
# 🎙 PODCAST 2 GIỌNG TỪ TÀI LIỆU (kiểu NotebookLM)
# =========================
# Tài liệu (PDF/docx/EPUB/TXT) → LLM dịch (Claude/Gemini/OpenAI) viết kịch bản
# hội thoại A (MC) / B (chuyên gia) → đọc bằng 2 hồ sơ giọng qua pipeline PDF
# (pdf_line_NNNN.mp3, gen theo NHÓM speaker nên chỉ đổi engine 2 lần) → tự
# Merge Audio (có "Nghỉ giữa đoạn"). Kịch bản lưu .txt để xem/sửa; chạy lại =
# resume (skip pdf_line đã có). Pattern nút Dịch: khóa _PODCAST_RUNNING; TTS
# phase dùng set_mode("tts_running") như Phân vai để nút ⏹ chung hoạt động.
_PODCAST_RUNNING = [False]
_PODCAST_CHUNK_CHARS = 5000   # ký tự tài liệu / lượt gọi LLM
_PODCAST_MAX_CHUNKS = 8       # trần — tài liệu dài hơn sẽ chỉ lấy phần đầu

_PODCAST_SYS = (
    "Bạn là biên kịch podcast tiếng Việt. Chuyển nội dung tài liệu thành cuộc "
    "trò chuyện tự nhiên, dễ nghe giữa hai người dẫn:\n"
    "A = MC dẫn dắt chương trình: tò mò, đặt câu hỏi, phản ứng ngắn, chuyển ý.\n"
    "B = chuyên gia: giải thích rõ ràng, thân thiện, có ví dụ đời thường.\n"
    "Quy tắc: văn NÓI (không văn viết), câu ngắn, không markdown, không liệt kê "
    "gạch đầu dòng, không nói 'tài liệu viết rằng', mỗi lượt thoại 1–3 câu, hai "
    "người thay phiên tự nhiên.\n"
    "CHỈ trả về các dòng đúng định dạng sau, không thêm gì khác:\n"
    "A: <lời thoại>\n"
    "B: <lời thoại>")


def _podcast_extract_text(path):
    """Bóc text từ PDF/docx/EPUB/TXT (chạy trong worker thread). Raise nếu lỗi."""
    ext = os.path.splitext(path)[1].lower()
    if ext == ".pdf":
        py = _find_pdf_python()
        helper = _find_pdf_helper()
        if not py or not helper:
            raise RuntimeError("Thiếu pdf_helper.py / Python có pypdf để đọc PDF.")
        import tempfile as _tf
        tmp_json = os.path.join(_tf.gettempdir(), "_podcast_pdf.json")
        try:
            r = subprocess.run([py, helper, "--input", path, "--output", tmp_json],
                               capture_output=True, text=True, encoding="utf-8",
                               errors="replace", timeout=180,
                               creationflags=CREATE_NO_WINDOW)
            if r.returncode != 0 or not (r.stdout or "").strip().startswith("DONE:"):
                raise RuntimeError((r.stderr or r.stdout or "pdf_helper lỗi")[:200])
            with open(tmp_json, encoding="utf-8") as f:
                return "\n\n".join(json.load(f).get("chunks", []))
        finally:
            try:
                os.remove(tmp_json)
            except Exception:
                pass
    if ext == ".docx":
        from docx import Document
        return "\n\n".join(p.text for p in Document(path).paragraphs if p.text.strip())
    if ext == ".epub":
        return _epub_extract_text(path)
    return _read_text_smart(path)


def _podcast_gen_script(provider, api_key, model, text, extra):
    """Sinh kịch bản hội thoại → [(speaker 'A'/'B', line)]. Gọi LLM theo từng
    phần tài liệu, mang 4 lượt thoại cuối sang phần sau để giữ mạch."""
    chunks = [text[i:i + _PODCAST_CHUNK_CHARS]
              for i in range(0, len(text), _PODCAST_CHUNK_CHARS)]
    if len(chunks) > _PODCAST_MAX_CHUNKS:
        log(f"🎙 [Podcast] ⚠ Tài liệu dài ({len(chunks)} phần) — chỉ dùng "
            f"{_PODCAST_MAX_CHUNKS} phần đầu.")
        chunks = chunks[:_PODCAST_MAX_CHUNKS]
    lines = []
    for k, ch in enumerate(chunks):
        if _PODCAST_RUNNING[0] is False:
            break
        parts = [f"PHẦN TÀI LIỆU ({k + 1}/{len(chunks)}):\n{ch}"]
        if lines:
            tail = "\n".join(f"{s}: {t}" for s, t in lines[-4:])
            parts.append("Hội thoại đã có (nối tiếp mạch, KHÔNG lặp lại):\n" + tail)
        if k == 0:
            parts.append("Đây là phần ĐẦU — mở đầu bằng lời chào và giới thiệu chủ đề.")
        if k == len(chunks) - 1:
            parts.append("Đây là phần CUỐI — kết bằng tóm tắt ngắn và lời chào tạm biệt.")
        if extra:
            parts.append(f"Yêu cầu thêm của người dùng: {extra}")
        raw = None
        for _try in range(2):
            try:
                raw = _llm_call(provider, api_key, model, _PODCAST_SYS,
                                "\n\n".join(parts))
                break
            except Exception as e:
                if _try == 0:
                    time.sleep(2)
                else:
                    log(f"🎙 [Podcast] ⚠ Lỗi gọi API phần {k + 1}: {e} — bỏ qua phần này.")
        got = re.findall(r"(?m)^\s*([AB])\s*[:：]\s*(.+?)\s*$", raw or "")
        lines.extend((s, t) for s, t in got if t.strip())
        update_progress(k + 1, len(chunks))
    return lines


def _podcast_worker(src, prof_a, prof_b, out_dir, extra, auto_merge,
                    provider, api_key, model, voice_snap):
    global PDF_FILE, PDF_CHUNKS, current_index, FAIL_COUNT, OUTPUT_DIR
    try:
        log_color("━━━ 🎙 PODCAST 2 GIỌNG ━━━", "#7c5cff")
        log(f"🎙 [Podcast] Đọc tài liệu: {os.path.basename(src)}")
        try:
            text = _podcast_extract_text(src)
        except Exception as e:
            log(f"🎙 [Podcast] ❌ Không đọc được tài liệu: {e}")
            return
        text = (text or "").strip()
        if len(text) < 200:
            log("🎙 [Podcast] ❌ Tài liệu quá ngắn / không có text để làm podcast.")
            return
        log(f"🎙 [Podcast] ✍ Viết kịch bản hội thoại bằng {provider} "
            f"({max(1, min(len(text) // _PODCAST_CHUNK_CHARS + 1, _PODCAST_MAX_CHUNKS))} phần)…")
        lines = _podcast_gen_script(provider, api_key, model, text, extra)
        if len(lines) < 4:
            log("🎙 [Podcast] ❌ LLM không trả được kịch bản hợp lệ — thử lại / đổi model.")
            return
        try:
            os.makedirs(out_dir, exist_ok=True)
            script_path = os.path.join(out_dir, "podcast_script.txt")
            with open(script_path, "w", encoding="utf-8") as f:
                f.write("\n".join(f"{s}: {t}" for s, t in lines))
            log(f"🎙 [Podcast] 📝 Kịch bản {len(lines)} lượt thoại → {script_path}")
        except Exception as e:
            log(f"🎙 [Podcast] ❌ Không ghi được vào thư mục output: {e}")
            return

        # Nạp vào pipeline PDF + hiện danh sách
        OUTPUT_DIR = out_dir
        PDF_FILE = src
        PDF_CHUNKS = [t for _s, t in lines]
        current_index = 0
        FAIL_COUNT = 0
        def _show_list():
            subtitle_list.configure(state="normal")
            subtitle_list.delete("1.0", "end")
            for i, (s, t) in enumerate(lines):
                subtitle_list.insert("end", f"[{i}] {s}: {t}\n\n")
            subtitle_list.configure(state="disabled")
        app.after(0, _show_list)
        app.after(0, lambda: set_mode("tts_running"))

        # Gen theo NHÓM speaker — chỉ đổi hồ sơ giọng 2 lần
        done = fail = 0
        total = len(lines)
        processed = 0
        _stopped = False
        for prof, spk in ((prof_a, "A"), (prof_b, "B")):
            idxs = [i for i, (s, _t) in enumerate(lines) if s == spk]
            if not idxs:
                continue
            log(f"🎙 [Podcast] 🎭 Giọng {spk} = '{prof}' ({len(idxs)} lượt thoại)…")
            if not _apply_profile_blocking(prof):
                fail += len(idxs)
                processed += len(idxs)
                continue
            for i in idxs:
                if stop_requested:
                    log("🎙 [Podcast] ⏹ Đã dừng theo yêu cầu — chạy lại sẽ resume.")
                    _stopped = True
                    return
                target = os.path.join(out_dir, f"pdf_line_{i:04d}.mp3")
                if not os.path.isfile(target):   # resume: dòng đã có thì bỏ qua
                    try:
                        asyncio.run(regenerate_pdf_line(i, lines[i][1]))
                    except Exception as e:
                        log(f"🎙 [Podcast] ❌ Lỗi lượt {i}: {e}")
                if os.path.isfile(target):
                    done += 1
                else:
                    fail += 1
                processed += 1
                update_progress(processed, total)
        log(f"🎙 [Podcast] ━━━ TTS xong: {done} OK, {fail} lỗi / {total} lượt ━━━")
        if done and not fail and auto_merge:
            log("🎙 [Podcast] 🔗 Tự ghép thành 1 file (Merge Audio)…")
            app.after(500, merge_pdf_audio)   # tự mở thư mục + pháo hoa khi xong
        elif done:
            log("🎙 [Podcast] 💡 Bấm 'Merge Audio' (trang Tài liệu) để ghép thành "
                "1 file — chỉnh 'Nghỉ giữa đoạn' cho nhịp tự nhiên."
                + (" (🧩 Tạo lại dòng thiếu để vá lượt lỗi trước.)" if fail else ""))
    finally:
        _PODCAST_RUNNING[0] = False
        # Trả lại cấu hình giọng trước khi chạy (đã đổi qua 2 hồ sơ)
        if voice_snap:
            app.after(0, lambda: _voice_profile_apply(voice_snap))
        app.after(0, lambda: set_mode("pdf_tts_done" if PDF_CHUNKS else "reset"))


def open_podcast_dialog():
    """🎙 Dialog tạo podcast 2 giọng từ tài liệu."""
    if _PODCAST_RUNNING[0]:
        log("🎙 [Podcast] Đang chạy — vui lòng đợi xong.")
        return
    if _CURRENT_MODE in _RUNNING_MODES or _MULTIVOICE_RUNNING[0] or _QC_REGEN_RUNNING[0]:
        log("🎙 [Podcast] Đang có tiến trình khác chạy — đợi xong đã.")
        return
    profiles = sorted(_voice_profiles_load().keys())
    if len(profiles) < 2:
        msg.showinfo("Podcast 2 giọng",
                     "Cần ít nhất 2 hồ sơ giọng (MC + chuyên gia). Tạo ở tab "
                     "Giọng nói → '💾 Lưu giọng hiện tại'.")
        return
    try:
        provider, api_key, model = _translate_active_key()
    except Exception as e:
        msg.showerror("Podcast 2 giọng", str(e))
        return
    if (TRANSLATE_PROVIDER or "") == "Offline":
        msg.showinfo("Podcast 2 giọng",
                     "Provider Offline không viết kịch bản được — chọn "
                     "Claude/Gemini/OpenAI ở trang Dịch.")
        return

    win = ctk.CTkToplevel(app)
    win.title("🎙 Podcast 2 giọng từ tài liệu")
    win.geometry("640x360")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    ctk.CTkLabel(win, text="Tài liệu → kịch bản hội thoại MC (A) + chuyên gia (B) → "
                           "đọc 2 giọng → 1 file podcast",
                 font=("Arial", 12, "bold")).pack(pady=(12, 6))

    row1 = ctk.CTkFrame(win, fg_color="transparent")
    row1.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row1, text="Tài liệu:", font=("Arial", 12), width=95,
                 anchor="w").pack(side="left")
    v_src = ctk.StringVar(value="")
    ctk.CTkEntry(row1, textvariable=v_src).pack(side="left", expand=True,
                                                fill="x", padx=(0, 6))
    def _browse():
        p = filedialog.askopenfilename(
            title="Chọn tài liệu làm podcast",
            filetypes=[("Tài liệu", "*.pdf *.docx *.epub *.txt"),
                       ("All files", "*.*")])
        if p:
            v_src.set(p)
    ctk.CTkButton(row1, text="Browse", width=80, command=_browse).pack(side="left")

    row2 = ctk.CTkFrame(win, fg_color="transparent")
    row2.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row2, text="Giọng MC (A):", font=("Arial", 12), width=95,
                 anchor="w").pack(side="left")
    v_a = ctk.StringVar(value=profiles[0])
    ctk.CTkOptionMenu(row2, variable=v_a, values=profiles, width=200).pack(side="left", padx=(0, 14))
    ctk.CTkLabel(row2, text="Chuyên gia (B):", font=("Arial", 12)).pack(side="left", padx=(0, 4))
    v_b = ctk.StringVar(value=profiles[1] if len(profiles) > 1 else profiles[0])
    ctk.CTkOptionMenu(row2, variable=v_b, values=profiles, width=200).pack(side="left")

    row3 = ctk.CTkFrame(win, fg_color="transparent")
    row3.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row3, text="Yêu cầu thêm:", font=("Arial", 12), width=95,
                 anchor="w").pack(side="left")
    v_extra = ctk.StringVar(value="")
    _extra_entry = ctk.CTkEntry(
        row3, textvariable=v_extra,
        placeholder_text="vd: giọng vui vẻ, tập trung phần chương 2, xưng 'mình'…")
    _extra_entry.pack(side="left", expand=True, fill="x")

    v_merge = ctk.BooleanVar(value=True)
    ctk.CTkCheckBox(win, text="Tự ghép thành 1 file khi đọc xong (Merge Audio)",
                    variable=v_merge, font=("Arial", 12)).pack(anchor="w",
                                                               padx=16, pady=(6, 2))
    ctk.CTkLabel(win, text="Output: thư mục <tài liệu>_podcast cạnh file. Kịch bản lưu "
                           "podcast_script.txt.\nChạy lại cùng tài liệu = resume "
                           "(lượt thoại đã đọc được bỏ qua).",
                 font=("Arial", 11), text_color="#999",
                 justify="left").pack(padx=16, anchor="w")

    def _start():
        src = v_src.get().strip()
        if not src or not os.path.isfile(src):
            msg.showerror("Podcast 2 giọng", "Chưa chọn file tài liệu hợp lệ.")
            return
        if v_a.get() == v_b.get():
            msg.showerror("Podcast 2 giọng", "Hai giọng A và B phải khác nhau.")
            return
        out_dir = os.path.splitext(src)[0] + "_podcast"
        snap = None
        try:
            snap = _voice_profile_capture()   # main thread — trả giọng lại sau
        except Exception:
            pass
        _PODCAST_RUNNING[0] = True
        win.destroy()
        threading.Thread(
            target=_podcast_worker,
            args=(src, v_a.get(), v_b.get(), out_dir, v_extra.get().strip(),
                  bool(v_merge.get()), provider, api_key, model, snap),
            daemon=True).start()

    ctk.CTkButton(win, text="🎙 Tạo Podcast", command=_start,
                  fg_color="#7c5cff", hover_color="#8f72ff", height=42,
                  font=("Arial", 14, "bold")).pack(fill="x", padx=14, pady=(10, 14))


# =========================
# Third-party TTS providers (sync, chạy trong executor)
# =========================

def _check_http_quota(exc: urllib.error.HTTPError, provider: str):
    """Raise QuotaExhaustedError nếu HTTP status hoặc body báo hết quota."""
    if exc.code in (402, 429):
        raise QuotaExhaustedError(f"{provider}: HTTP {exc.code} — hết quota / rate limit")
    try:
        body = exc.read().decode("utf-8", errors="replace")
    except Exception:
        body = ""
    if _is_quota_error(body) or _is_quota_error(str(exc.reason or "")):
        raise QuotaExhaustedError(f"{provider}: {body[:200]}")


def _download_audio_with_retry(url, filename, provider, initial_wait=0.0, retries=5, retry_delay=2.0):
    """Download audio từ URL; retry khi 404 (server chưa render xong).
    initial_wait: chờ trước lần thử đầu (FPT.AI cần ~1-2s render).
    retries: số lần retry tối đa khi gặp 404.
    retry_delay: giây chờ giữa các lần retry.
    """
    if initial_wait > 0:
        time.sleep(initial_wait)
    for attempt in range(retries + 1):
        try:
            with urllib.request.urlopen(url, timeout=30) as resp:
                with open(filename, "wb") as f:
                    f.write(resp.read())
            return
        except urllib.error.HTTPError as e:
            if e.code == 404 and attempt < retries:
                time.sleep(retry_delay)
                continue
            _check_http_quota(e, provider)
            raise
    raise RuntimeError(f"{provider}: audio URL vẫn 404 sau {retries} lần retry")


def _save_tts_fptai_sync(text, filename, voice, api_key):
    """FPT.AI TTS — POST text → nhận async URL → poll download (retry 404)."""
    url = "https://api.fpt.ai/hmi/tts/v5"
    req = urllib.request.Request(url, data=text.encode("utf-8"))
    req.add_header("api-key", api_key)
    req.add_header("voice", voice)
    req.add_header("format", "mp3")
    req.add_header("speed", "0")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            result = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        _check_http_quota(e, "FPT.AI")
        raise
    err_code = result.get("error", 1)
    msg = result.get("message", "")
    if err_code != 0:
        if err_code in (4, 5, 6) or _is_quota_error(msg):
            raise QuotaExhaustedError(f"FPT.AI: {msg}")
        raise RuntimeError(f"FPT.AI error {err_code}: {msg}")
    async_url = result.get("async", "")
    if not async_url:
        raise RuntimeError("FPT.AI: không nhận được async URL")
    # initial_wait=1.5s, retry tối đa 6 lần × 2s = chờ tối đa ~13.5s
    _download_audio_with_retry(async_url, filename, "FPT.AI",
                               initial_wait=1.5, retries=6, retry_delay=2.0)
    return True


def _save_tts_vbee_sync(text, filename, voice, api_key):
    """Vbee TTS — nhập API key theo dạng app_id:api_token (hoặc chỉ api_token)."""
    parts = api_key.split(":", 1)
    app_id = parts[0].strip() if len(parts) == 2 else ""
    token = parts[-1].strip()
    url = "https://vbee.vn/api/v1/tts/speech_synthesis"
    payload = json.dumps({
        "input_text": text,
        "voice_code": voice,
        "app_id": app_id,
    }).encode("utf-8")
    req = urllib.request.Request(url, data=payload)
    req.add_header("Content-Type", "application/json")
    req.add_header("Authorization", f"Bearer {token}")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            result = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        _check_http_quota(e, "Vbee")
        raise
    err_msg = str(result.get("message") or result.get("error") or "")
    if _is_quota_error(err_msg):
        raise QuotaExhaustedError(f"Vbee: {err_msg}")
    audio_url = result.get("audio_url") or (result.get("data") or {}).get("url", "")
    if not audio_url:
        raise RuntimeError(f"Vbee: không nhận được audio URL — {result}")
    _download_audio_with_retry(audio_url, filename, "Vbee",
                               initial_wait=0, retries=3, retry_delay=2.0)
    return True


def _save_tts_zaloai_sync(text, filename, voice, api_key):
    """Zalo AI TTS — voice = '1 - Nữ miền Nam' → speakerId = 1."""
    speaker_id = voice.split(" - ")[0].strip() if " - " in voice else voice
    url = "https://api.zalo.ai/v1/tts/synthesize"
    data = urllib.parse.urlencode({
        "input": text,
        "speakerId": speaker_id,
        "speed": "1.0",
    }).encode("utf-8")
    req = urllib.request.Request(url, data=data)
    req.add_header("apikey", api_key)
    req.add_header("Content-Type", "application/x-www-form-urlencoded")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            result = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        _check_http_quota(e, "Zalo AI")
        raise
    err_msg = str(result.get("message") or result.get("error_message") or "")
    if result.get("error_code", 0) not in (0, None) and _is_quota_error(err_msg):
        raise QuotaExhaustedError(f"Zalo AI: {err_msg}")
    audio_url = (result.get("data") or {}).get("url", "")
    if not audio_url:
        raise RuntimeError(f"Zalo AI: không nhận được audio URL — {result}")
    _download_audio_with_retry(audio_url, filename, "Zalo AI",
                               initial_wait=0, retries=3, retry_delay=2.0)
    return True


def _save_tts_everai_sync(text, filename, voice, api_key):
    """EverAI TTS — trả về audio bytes trực tiếp hoặc URL."""
    url = "https://api.ever.ai/v1/tts/generate"
    payload = json.dumps({
        "text": text,
        "voice": voice,
        "format": "mp3",
    }).encode("utf-8")
    req = urllib.request.Request(url, data=payload)
    req.add_header("Authorization", f"Bearer {api_key}")
    req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            content_type = resp.headers.get("Content-Type", "")
            raw = resp.read()
    except urllib.error.HTTPError as e:
        _check_http_quota(e, "EverAI")
        raise
    if "audio" in content_type or "octet-stream" in content_type:
        with open(filename, "wb") as f:
            f.write(raw)
    else:
        result = json.loads(raw.decode("utf-8"))
        err_msg = str(result.get("message") or result.get("error") or "")
        if _is_quota_error(err_msg):
            raise QuotaExhaustedError(f"EverAI: {err_msg}")
        audio_url = result.get("url") or result.get("audio_url") or (result.get("data") or {}).get("url", "")
        if not audio_url:
            raise RuntimeError(f"EverAI: không nhận được audio URL — {result}")
        _download_audio_with_retry(audio_url, filename, "EverAI",
                                   initial_wait=0, retries=3, retry_delay=2.0)
    return True


def _save_tts_minimax_sync(text, filename, voice, api_key):
    """MiniMax TTS — API key dạng group_id:api_token.
    Response trả data.audio là hex-encoded MP3, giải mã trực tiếp."""
    parts = api_key.split(":", 1)
    group_id = parts[0].strip() if len(parts) == 2 else ""
    token = parts[-1].strip()
    url = f"https://api.minimax.chat/v1/t2a_v2?GroupId={group_id}"
    payload = json.dumps({
        "model": "speech-01-turbo",
        "text": text,
        "stream": False,
        "voice_setting": {
            "voice_id": voice,
            "speed": 1.0,
            "vol": 1.0,
            "pitch": 0,
        },
        "audio_setting": {
            "sample_rate": 32000,
            "bitrate": 128000,
            "format": "mp3",
        },
    }).encode("utf-8")
    req = urllib.request.Request(url, data=payload)
    req.add_header("Authorization", f"Bearer {token}")
    req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            result = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        _check_http_quota(e, "MiniMax")
        raise
    base_resp = result.get("base_resp") or {}
    status_code = base_resp.get("status_code", -1)
    status_msg = base_resp.get("status_msg", "")
    if status_code not in (0, None):
        if status_code in (1001, 1002) or _is_quota_error(status_msg):
            raise QuotaExhaustedError(f"MiniMax: {status_msg}")
        raise RuntimeError(f"MiniMax error {status_code}: {status_msg}")
    audio_hex = (result.get("data") or {}).get("audio", "")
    if not audio_hex:
        raise RuntimeError(f"MiniMax: không nhận được audio — {result}")
    with open(filename, "wb") as f:
        f.write(bytes.fromhex(audio_hex))
    return True




def _edge_rate():
    """Tốc độ Edge TTS từ edge_rate_var, chuẩn hóa '+N%' — sai format → +10%."""
    v = edge_rate_var.get().strip().replace(" ", "")
    m = re.fullmatch(r"([+-]?)(\d{1,3})%", v)
    if m:
        return f"{m.group(1) or '+'}{m.group(2)}%"
    return "+10%"


def _edge_pitch():
    """Cao độ Edge TTS từ edge_pitch_var, chuẩn hóa '+NHz' — sai format → +0Hz."""
    v = edge_pitch_var.get().strip().replace(" ", "")
    m = re.fullmatch(r"([+-]?)(\d{1,3})(hz)", v, re.IGNORECASE)
    if m:
        return f"{m.group(1) or '+'}{m.group(2)}Hz"
    return "+0Hz"


# Cắt khoảng lặng > 0.15s ở đầu/cuối audio TTS (Edge thường chừa 0.1–0.3s lặng
# mỗi đầu; cộng dồn nghìn dòng làm voice lệch mốc phụ đề + chiếm khe vô ích →
# bị atempo tăng tốc oan khi merge). areverse 2 lần để cắt được cả đuôi.
_TRIM_SIL_AF = (
    "silenceremove=start_periods=1:start_threshold=-45dB:start_silence=0.15,"
    "areverse,"
    "silenceremove=start_periods=1:start_threshold=-45dB:start_silence=0.15,"
    "areverse"
)

def _trim_edge_silence(filepath):
    """Cắt lặng đầu/cuối in-place (gọi sau khi provider TTS ghi file xong).
    File ra quá nhỏ (audio toàn lặng → silenceremove cắt sạch) thì GIỮ file
    gốc để QC novoice xử lý như cũ. Mọi lỗi → giữ file gốc, không chặn TTS."""
    if not trim_silence_var.get():
        return
    tmp = filepath + ".trim.mp3"
    try:
        r = subprocess.run(
            [get_ffmpeg(), "-y", "-i", filepath, "-af", _TRIM_SIL_AF,
             "-q:a", "2", tmp],
            creationflags=CREATE_NO_WINDOW, capture_output=True, timeout=60)
        if (r.returncode == 0 and os.path.isfile(tmp)
                and os.path.getsize(tmp) > 1000):
            os.replace(tmp, filepath)
            return
    except Exception:
        pass
    try:
        if os.path.isfile(tmp):
            os.remove(tmp)
    except Exception:
        pass


async def save_tts(text, filename):
    text = _apply_glossary(text)  # tiền xử lý TTS: từ điển phát âm + đọc số kiểu Việt
    for attempt in range(3):
        try:
            if TTS_PROVIDER == "Edge TTS":
                communicate = edge_tts.Communicate(
                    text=text,
                    voice=VOICE,
                    rate=_edge_rate(),
                    pitch=_edge_pitch()
                )
                await communicate.save(filename)
            else:
                api_key = api_key_var.get().strip()
                if not api_key:
                    log("ERROR: Chưa nhập API key!")
                    return False
                loop = asyncio.get_event_loop()
                if TTS_PROVIDER == "FPT.AI":
                    await loop.run_in_executor(None, _save_tts_fptai_sync, text, filename, VOICE, api_key)
                elif TTS_PROVIDER == "Vbee":
                    await loop.run_in_executor(None, _save_tts_vbee_sync, text, filename, VOICE, api_key)
                elif TTS_PROVIDER == "Zalo AI":
                    await loop.run_in_executor(None, _save_tts_zaloai_sync, text, filename, VOICE, api_key)
                elif TTS_PROVIDER == "EverAI":
                    await loop.run_in_executor(None, _save_tts_everai_sync, text, filename, VOICE, api_key)
                elif TTS_PROVIDER == "MiniMax":
                    await loop.run_in_executor(None, _save_tts_minimax_sync, text, filename, VOICE, api_key)
                else:
                    return False
            # Cắt lặng đầu/cuối (executor để không chặn event loop khi chạy song song)
            await asyncio.get_event_loop().run_in_executor(
                None, _trim_edge_silence, filename)
            return True
        except QuotaExhaustedError:
            raise  # không retry — quota hết là hết, propagate lên generate_tts
        except Exception as e:
            log(f"Retry {attempt+1}: {e}")
            await asyncio.sleep(2)
    return False


