def _reset_rvc_instance():
    pass  # không còn cache instance — subprocess stateless


def _audio_quality_check(filepath, text="", mean_threshold=-40.0,
                         sec_per_char=0.09, base_pad=0.3,
                         long_factor=3.0, long_pad=1.5, long_floor=5.0,
                         short_factor=0.30, short_min_chars=12):
    """Kiểm tra chất lượng audio TTS bằng 1 lần gọi ffmpeg volumedetect:
      1. Im lặng / không có giọng  → mean_volume < mean_threshold (-40 dB)
      2. Quá dài so với text       → hallucination / đọc lặp / runaway
      3. Quá ngắn so với text      → bị cắt / thiếu nội dung

    So sánh độ dài: audio TTS tiếng Việt bình thường ~0.08 s/ký tự
    (median đo thực tế). Kỳ vọng = base_pad + n_ký_tự * sec_per_char.
      - "toolong"  khi dur > long_floor VÀ dur > kỳ_vọng*long_factor + long_pad
      - "tooshort" khi n_ký_tự >= short_min_chars VÀ dur < kỳ_vọng*short_factor

    Trả về (is_bad: bool, reason: str, detail: str).
    reason ∈ {"", "novoice", "toolong", "tooshort"}.
    """
    try:
        ffmpeg = get_ffmpeg()
        result = subprocess.run(
            [ffmpeg, "-i", filepath, "-af", "volumedetect", "-f", "null", "-"],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=30, creationflags=CREATE_NO_WINDOW,
        )
        out = result.stderr
        mm = re.search(r"mean_volume:\s*([-\d.]+)\s*dB", out)
        mean_db = float(mm.group(1)) if mm else 0.0
        dm = re.search(r"Duration:\s*(\d+):(\d+):([\d.]+)", out)
        dur = (float(dm.group(1)) * 3600 + float(dm.group(2)) * 60
               + float(dm.group(3))) if dm else 0.0

        # 1) im lặng / không có giọng
        if mm and mean_db < mean_threshold:
            return True, "novoice", f"mean={mean_db:.1f} dB"

        # 2 & 3) so sánh độ dài audio với độ dài text
        nchar = len((text or "").strip())
        if nchar >= 2 and dur > 0:
            expected = base_pad + nchar * sec_per_char
            if dur > long_floor and dur > expected * long_factor + long_pad:
                return True, "toolong", (f"{dur:.1f}s cho {nchar} ký tự "
                                         f"(kỳ vọng ~{expected:.1f}s)")
            if nchar >= short_min_chars and dur < expected * short_factor:
                return True, "tooshort", (f"{dur:.1f}s cho {nchar} ký tự "
                                          f"(kỳ vọng ~{expected:.1f}s)")
        return False, "", f"mean={mean_db:.1f} dB, dur={dur:.1f}s"
    except Exception:
        return False, "", ""


_BAD_AUDIO_SUFFIX = {"novoice": "_novoice", "toolong": "_toolong",
                     "tooshort": "_tooshort"}
_BAD_AUDIO_DESC = {
    "novoice":  "không có giọng",
    "toolong":  "quá dài (có thể bị lặp / đọc sai)",
    "tooshort": "quá ngắn (thiếu nội dung so với phụ đề)",
}


def _rename_bad_audio(filepath, idx, reason, detail, label=""):
    """Đổi tên file audio lỗi thêm hậu tố theo loại lỗi (_novoice / _toolong /
    _tooshort). Vì tên gốc không còn tồn tại, lần Resume sau sẽ tự tạo lại dòng đó.
    Trả về đường dẫn mới nếu thành công, None nếu thất bại.
    """
    suffix = _BAD_AUDIO_SUFFIX.get(reason, "_bad")
    desc = _BAD_AUDIO_DESC.get(reason, "lỗi")
    base, ext = os.path.splitext(filepath)
    new_path = base + suffix + ext
    try:
        if os.path.exists(new_path):
            os.remove(new_path)
        os.rename(filepath, new_path)
        tag = f"[{label}] " if label else ""
        log(f"⚠ {tag}Dòng {idx}: audio {desc} ({detail}) → {os.path.basename(new_path)}")
        return new_path
    except Exception as e:
        log(f"⚠ Dòng {idx}: audio {desc} nhưng không đổi tên được: {e}")
        return None


def _sanitize_tts_text(text):
    """Chuẩn hóa các pattern dễ làm TTS đọc lặp / runaway / cắt giữa chừng.
    Chỉ dùng khi TẠO LẠI một dòng đã sinh audio lỗi — giữ nguyên nội dung
    đọc được, chỉ bỏ các ký hiệu gây nhiễu cho engine TTS:
      - "..." / "…" (nhiều dấu chấm) → ", "  (engine hay đọc lặp ở dấu lửng)
      - gạch đầu dòng hội thoại "- " → bỏ
      - gộp khoảng trắng thừa
    """
    t = re.sub(r"\.{2,}", ", ", text)        # "..." → ", "
    t = t.replace("…", ", ")                  # ký tự ellipsis
    t = re.sub(r"(^|\s)[-–—]\s+", r"\1", t)  # gạch đầu dòng hội thoại
    t = re.sub(r"\s{2,}", " ", t).strip()
    t = re.sub(r"(,\s*){2,}", ", ", t)        # gộp ", , ," → ", "
    return t or text                          # tránh trả chuỗi rỗng


# =========================
# QC DASHBOARD — báo cáo audio lỗi + regenerate hàng loạt
# =========================
# _rename_bad_audio đã đổi tên các file lỗi thành line_XXXX_<reason>.mp3 —
# dashboard quét thư mục output nên hoạt động với MỌI luồng (SRT/PDF, mọi engine),
# kể cả sau khi đóng mở lại app.
_QC_BAD_RE = re.compile(r"^(line_|pdf_line_)(\d{4})_(novoice|toolong|tooshort)\.mp3$")

def open_todo_panel():
    """📋 Việc cần làm — gộp MỌI vấn đề còn tồn sau batch vào 1 chỗ kèm nút xử
    lý từng mục: dòng audio lỗi (QC) → 🔁, dòng thiếu file → 🧩, dòng tràn/hẹp
    khe → ✂/🔧. Thuần trình bày trên dữ liệu scan sẵn có — không pipeline mới."""
    rows = []   # (icon, mô_tả, nhãn_nút | None, hàm | None)
    try:
        bad = _qc_scan_bad_files()
    except Exception:
        bad = []
    if bad:
        _rs = {}
        for _p, _i, reason, _f in bad:
            _rs[reason] = _rs.get(reason, 0) + 1
        detail = ", ".join(f"{v} {k}" for k, v in sorted(_rs.items()))
        rows.append(("🔴", f"{len(bad)} dòng audio LỖI ({detail})",
                     "🔁 Regen dòng lỗi", qc_regen_bad_lines))
        rows.append(("", "   …hoặc nghe từng dòng trước khi quyết định",
                     "🎧 Nghe dòng lỗi", open_qc_listen_dialog))
    try:
        missing = _scan_missing_lines()
    except Exception:
        missing = []
    if missing:
        rows.append(("🟠", f"{len(missing)} dòng THIẾU file audio (FAIL khi batch)",
                     "🧩 Tạo lại dòng thiếu", qc_retry_missing_lines))
    if subtitles_cache:
        try:
            iss = _srt_lint()
        except Exception:
            iss = []
        n_bad = sum(1 for s, _i, _m in iss if s == "❌")
        n_warn = len(iss) - n_bad
        n_over = len(_srt_overflow_lines())
        if n_over:
            rows.append(("🔴", f"{n_over} dòng TRÀN khe thời gian (sẽ lỗi khi merge)",
                         "✂ Rút gọn AI", srt_ai_shorten))
        if n_bad - n_over > 0 or n_warn:
            rows.append(("🟡", f"SRT còn {max(0, n_bad - n_over)} lỗi + {n_warn} cảnh "
                               "báo khác (xem 🩺)", "🔧 Sửa SRT tự động", srt_autofix))

    win = ctk.CTkToplevel(app)
    win.title("📋 Việc cần làm")
    win.geometry("640x340")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    if not rows:
        ctk.CTkLabel(win, text="✅ Sạch sẽ!\nKhông còn dòng lỗi, dòng thiếu hay "
                               "vấn đề SRT nào tồn đọng.",
                     font=("Arial", 14, "bold"), justify="center").pack(expand=True)
        ctk.CTkButton(win, text="Đóng", command=win.destroy,
                      width=100).pack(pady=(0, 14))
        return

    ctk.CTkLabel(win, text="Các việc còn tồn sau batch — bấm nút bên phải để xử lý từng mục:",
                 font=("Arial", 12, "bold")).pack(pady=(12, 6), padx=14, anchor="w")
    body = ctk.CTkScrollableFrame(win)
    body.pack(fill="both", expand=True, padx=12, pady=4)
    for icon, desc, btxt, fn in rows:
        r = ctk.CTkFrame(body, fg_color="transparent")
        r.pack(fill="x", pady=3)
        ctk.CTkLabel(r, text=f"{icon} {desc}", font=("Arial", 12), anchor="w",
                     wraplength=420, justify="left").pack(side="left",
                                                          expand=True, fill="x")
        if btxt and fn:
            def _go(fn=fn):
                win.destroy()
                fn()
            ctk.CTkButton(r, text=btxt, width=170, command=_go).pack(side="left", padx=4)
    ctk.CTkLabel(win, text="💡 Xử lý xong mở lại panel này để kiểm tra còn gì không.",
                 font=("Arial", 10), text_color="#888").pack(pady=(2, 10))


def _qc_scan_bad_files():
    """Quét OUTPUT_DIR tìm audio bị QC đánh dấu lỗi → [(prefix, idx, reason, path)]."""
    bad = []
    try:
        for fn in os.listdir(OUTPUT_DIR):
            m = _QC_BAD_RE.match(fn)
            if m:
                bad.append((m.group(1), int(m.group(2)), m.group(3),
                            os.path.join(OUTPUT_DIR, fn)))
    except Exception:
        pass
    return sorted(bad, key=lambda x: (x[0], x[1]))

def qc_show_report():
    """In tổng kết QC vào logbox: dòng audio lỗi (QC rename) + dòng FAIL thiếu file."""
    bad = _qc_scan_bad_files()
    miss = _scan_missing_lines()
    log("━━━ BÁO CÁO CHẤT LƯỢNG AUDIO (QC) ━━━")
    if not bad and not miss:
        log("✅ Không có file audio lỗi hay dòng thiếu trong thư mục output.")
        return
    by_reason = {}
    for prefix, idx, reason, _path in bad:
        by_reason.setdefault(reason, []).append((prefix, idx))
    for reason in ("novoice", "toolong", "tooshort"):
        items = by_reason.get(reason, [])
        if not items:
            continue
        nums = ", ".join((("PDF " if p == "pdf_line_" else "") + str(i))
                         for p, i in items)
        log(f"  • {len(items)} dòng {_BAD_AUDIO_DESC[reason]}: {nums}")
    if bad:
        log(f"Tổng cộng {len(bad)} dòng lỗi — nhấn '🔁 Regen dòng lỗi' để tạo lại tất cả.")
    if miss:
        nums = ", ".join((("PDF " if p == "pdf_line_" else "") + str(i))
                         for p, i, _t in miss[:40])
        if len(miss) > 40:
            nums += ", …"
        log(f"  • {len(miss)} dòng FAIL chưa có file audio: {nums}")
        log("    → nhấn '🧩 Tạo lại dòng thiếu' (nếu vừa Stop giữa chừng thì TTS/Resume nhanh hơn).")

_QC_REGEN_RUNNING = [False]

def qc_regen_bad_lines():
    """Tạo lại toàn bộ các dòng audio lỗi (đi qua đúng pipeline regenerate_line /
    regenerate_pdf_line: engine hiện tại + QC + retry). Tự khóa khi đang chạy."""
    global stop_requested
    if _QC_REGEN_RUNNING[0]:
        log("[QC] Đang chạy regenerate — vui lòng đợi xong.")
        return
    # Không chạy chồng lên các tiến trình ghi cùng OUTPUT_DIR khác
    if _MULTIVOICE_RUNNING[0] or _QUEUE_RUNNING[0]:
        log("[QC] ❌ Đang có tiến trình khác chạy (Phân vai / Hàng đợi) — đợi xong rồi thử lại.")
        return
    bad = _qc_scan_bad_files()
    if not bad:
        log("[QC] ✅ Không có dòng lỗi để tạo lại.")
        return
    need_srt = any(p == "line_" for p, _i, _r, _f in bad)
    need_pdf = any(p == "pdf_line_" for p, _i, _r, _f in bad)
    if need_srt and not subtitles_cache:
        log("[QC] ❌ Có dòng SRT lỗi nhưng chưa Load SRT — hãy Load đúng file SRT trước.")
        return
    if need_pdf and not PDF_CHUNKS:
        log("[QC] ❌ Có đoạn PDF lỗi nhưng chưa nạp tài liệu — hãy Load lại PDF/Word trước.")
        return

    def _run():
        global stop_requested
        _QC_REGEN_RUNNING[0] = True
        stop_requested = False
        _stopped = False
        # Khóa UI + bật nút Stop để người dùng có thể dừng giữa chừng
        app.after(0, lambda: set_mode("tts_running"))
        try:
            done = fail = 0
            total = len(bad)
            log(f"[QC] Bắt đầu tạo lại {total} dòng lỗi...")
            for n, (prefix, idx, _reason, path) in enumerate(bad, 1):
                if stop_requested:
                    log("[QC] PROCESS STOPPED")
                    _stopped = True
                    break
                if prefix == "line_":
                    if idx >= len(subtitles_cache):
                        log(f"[QC] ⚠ Dòng {idx}: vượt quá số dòng SRT đang nạp — bỏ qua")
                        fail += 1
                        continue
                    text = clean_text(subtitles_cache[idx].content)
                    target = os.path.join(OUTPUT_DIR, f"line_{idx:04d}.mp3")
                else:
                    if idx >= len(PDF_CHUNKS):
                        log(f"[QC] ⚠ Đoạn PDF {idx}: vượt quá số đoạn đang nạp — bỏ qua")
                        fail += 1
                        continue
                    text = PDF_CHUNKS[idx].strip()
                    target = os.path.join(OUTPUT_DIR, f"pdf_line_{idx:04d}.mp3")
                try:
                    os.remove(path)
                except Exception:
                    pass
                try:
                    if prefix == "line_":
                        asyncio.run(regenerate_line(idx, text))
                    else:
                        asyncio.run(regenerate_pdf_line(idx, text))
                except Exception as e:
                    log(f"[QC] ❌ Lỗi khi tạo lại dòng {idx}: {e}")
                if os.path.isfile(target):
                    done += 1
                else:
                    fail += 1
                update_progress(n, total)
            log(f"[QC] ━━━ Hoàn tất: {done} OK, {fail} lỗi / {total} dòng ━━━")
            if done and not fail and not _stopped:
                app.after(0, show_fireworks)
        finally:
            _QC_REGEN_RUNNING[0] = False
            app.after(0, lambda s=_stopped: set_mode("tts_stopped" if s else "tts_done"))

    threading.Thread(target=_run, daemon=True).start()


def _scan_missing_lines():
    """Tìm các dòng FAIL khi chạy batch: text có nội dung nhưng file mp3 KHÔNG
    tồn tại trong OUTPUT_DIR (FAIL → file không được tạo, hoặc file bị xóa tay).
    → [(prefix, idx, text)].
    - Chỉ xét loại (SRT/PDF) đã có ít nhất 1 file audio cùng prefix trong
      OUTPUT_DIR — tránh quét nhầm cache cũ (vd PDF_CHUNKS còn sót từ tài liệu
      trước trong khi đang làm SRT ở thư mục khác).
    - Bỏ qua các dòng đã có file _novoice/_toolong/_tooshort (đã có
      '🔁 Regen dòng lỗi' xử lý riêng).
    - Bỏ qua dòng text rỗng (batch không tạo file cho dòng rỗng)."""
    try:
        existing = set(os.listdir(OUTPUT_DIR))
    except Exception:
        return []
    bad_idx = {(p, i) for p, i, _r, _f in _qc_scan_bad_files()}
    missing = []
    _line_re = re.compile(r"^line_\d{4}\.mp3$")
    _pdf_re = re.compile(r"^pdf_line_\d{4}\.mp3$")
    if subtitles_cache and any(_line_re.match(fn) for fn in existing):
        for i, sub in enumerate(subtitles_cache):
            t = clean_text(sub.content)
            if not t or not _is_speakable(t):   # dòng rỗng / không đọc được → batch cố tình bỏ qua
                continue
            if f"line_{i:04d}.mp3" not in existing and ("line_", i) not in bad_idx:
                missing.append(("line_", i, t))
    if PDF_CHUNKS and any(_pdf_re.match(fn) for fn in existing):
        for i, chunk in enumerate(PDF_CHUNKS):
            t = (chunk or "").strip()
            if not t or not _is_speakable(t):
                continue
            if f"pdf_line_{i:04d}.mp3" not in existing and ("pdf_line_", i) not in bad_idx:
                missing.append(("pdf_line_", i, t))
    return missing


def qc_retry_missing_lines():
    """Tạo lại các dòng FAIL (thiếu file audio) qua đúng pipeline regenerate_line /
    regenerate_pdf_line (engine hiện tại + QC + retry). Tự khóa khi đang chạy —
    cùng pattern với qc_regen_bad_lines. Với engine local, mỗi dòng là một lượt
    subprocess riêng nên chậm hơn batch: nếu vừa Stop giữa chừng cả đoạn dài,
    TTS/Resume (skip file đã có) sẽ nhanh hơn."""
    global stop_requested
    if _QC_REGEN_RUNNING[0]:
        log("[QC] Đang chạy regenerate — vui lòng đợi xong.")
        return
    if _MULTIVOICE_RUNNING[0] or _QUEUE_RUNNING[0]:
        log("[QC] ❌ Đang có tiến trình khác chạy (Phân vai / Hàng đợi) — đợi xong rồi thử lại.")
        return
    missing = _scan_missing_lines()
    if not missing:
        log("[QC] ✅ Không thấy dòng thiếu audio (so với SRT/PDF đang nạp).")
        return

    def _run():
        global stop_requested
        _QC_REGEN_RUNNING[0] = True
        stop_requested = False
        _stopped = False
        app.after(0, lambda: set_mode("tts_running"))
        try:
            done = fail = 0
            total = len(missing)
            log(f"[QC] Bắt đầu tạo lại {total} dòng thiếu audio...")
            for n, (prefix, idx, text) in enumerate(missing, 1):
                if stop_requested:
                    log("[QC] PROCESS STOPPED")
                    _stopped = True
                    break
                target = os.path.join(OUTPUT_DIR, f"{prefix}{idx:04d}.mp3")
                try:
                    if prefix == "line_":
                        asyncio.run(regenerate_line(idx, text))
                    else:
                        asyncio.run(regenerate_pdf_line(idx, text))
                except Exception as e:
                    log(f"[QC] ❌ Lỗi khi tạo lại dòng {idx}: {e}")
                if os.path.isfile(target):
                    done += 1
                else:
                    fail += 1
                update_progress(n, total)
            log(f"[QC] ━━━ Hoàn tất: {done} OK, {fail} lỗi / {total} dòng thiếu ━━━")
            if done and not fail and not _stopped:
                app.after(0, show_fireworks)
        finally:
            _QC_REGEN_RUNNING[0] = False
            app.after(0, lambda s=_stopped: set_mode("tts_stopped" if s else "tts_done"))

    threading.Thread(target=_run, daemon=True).start()


def _maybe_auto_retry_fail():
    """Checkbox 'Tự tạo lại dòng FAIL khi xong' bật + có FAIL → tự chạy
    qc_retry_missing_lines() ngay sau batch (đỡ phải bấm 🧩 tay). KHÔNG chạy
    trong các chuỗi wizard/hàng đợi/phân vai — chúng tự xử lý FAIL theo cách riêng."""
    try:
        if not auto_retry_fail_var.get() or FAIL_COUNT <= 0:
            return
    except Exception:
        return
    if (_AUTODUB_RUNNING[0] or _QUEUE_RUNNING[0]
            or _MULTIVOICE_RUNNING[0] or _QC_REGEN_RUNNING[0]):
        return
    log(f"🧩 Tự động tạo lại {FAIL_COUNT} dòng FAIL (checkbox đang bật)...")
    app.after(800, qc_retry_missing_lines)


def open_qc_listen_dialog():
    """🎧 Nghe & xử lý từng dòng audio lỗi: list file QC-rename + nút ▶ nghe +
    🔁 regen ngay tại chỗ (qua regenerate_line/pdf đầy đủ, khóa _QC_REGEN_RUNNING).
    Quyết định 'regen hay sửa text' nhanh hơn nhiều so với mò file trong thư mục."""
    bad = _qc_scan_bad_files()
    if not bad:
        log("[QC] ✅ Không có file audio lỗi trong thư mục output.")
        return
    win = ctk.CTkToplevel(app)
    win.title("🎧 Nghe & xử lý dòng lỗi (QC)")
    win.geometry("620x480")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    ctk.CTkLabel(win, text=f"{len(bad)} dòng audio bị QC đánh dấu lỗi",
                 font=("Arial", 13, "bold")).pack(pady=(10, 2))
    ctk.CTkLabel(win, text="▶ nghe thử — 🔁 tạo lại dòng đó ngay (đúng engine + QC).\n"
                           "Regen cần SRT/PDF tương ứng đang được nạp.",
                 font=("Arial", 11), justify="left").pack(pady=(0, 6))

    lst = ctk.CTkScrollableFrame(win)
    lst.pack(fill="both", expand=True, padx=10, pady=4)

    def _regen_one(prefix, idx, path, status_lbl):
        if (_QC_REGEN_RUNNING[0] or _MULTIVOICE_RUNNING[0]
                or _QUEUE_RUNNING[0]):
            log("[QC] Đang có tiến trình regen/batch khác — đợi xong rồi thử lại.")
            return
        if prefix == "line_":
            if idx >= len(subtitles_cache):
                log(f"[QC] ❌ Dòng {idx}: chưa Load đúng file SRT.")
                return
            text = clean_text(subtitles_cache[idx].content)
        else:
            if idx >= len(PDF_CHUNKS):
                log(f"[QC] ❌ Đoạn PDF {idx}: chưa nạp đúng tài liệu.")
                return
            text = PDF_CHUNKS[idx].strip()
        status_lbl.configure(text="⏳")

        def _run():
            global stop_requested
            _QC_REGEN_RUNNING[0] = True
            stop_requested = False
            try:
                try:
                    os.remove(path)
                except Exception:
                    pass
                try:
                    if prefix == "line_":
                        asyncio.run(regenerate_line(idx, text))
                    else:
                        asyncio.run(regenerate_pdf_line(idx, text))
                except Exception as e:
                    log(f"[QC] ❌ Lỗi regen dòng {idx}: {e}")
                target = os.path.join(OUTPUT_DIR, f"{prefix}{idx:04d}.mp3")
                ok = os.path.isfile(target)
                log(f"[QC] {'✅' if ok else '❌'} Regen dòng {idx}"
                    + ("" if ok else " — vẫn lỗi, xem log."))
                app.after(0, lambda: status_lbl.configure(
                    text="✅" if ok else "❌"))
            finally:
                _QC_REGEN_RUNNING[0] = False

        threading.Thread(target=_run, daemon=True).start()

    for prefix, idx, reason, path in bad:
        row = ctk.CTkFrame(lst, fg_color="transparent")
        row.pack(fill="x", pady=2)
        dur = _probe_duration_sec(path)
        name = ("PDF " if prefix == "pdf_line_" else "Dòng ") + str(idx)
        ctk.CTkLabel(row, text=f"{name} — {reason} ({dur:.1f}s)",
                     font=("Arial", 12), anchor="w").pack(
            side="left", expand=True, fill="x", padx=(4, 6))
        status = ctk.CTkLabel(row, text="", width=30, font=("Arial", 12))
        ctk.CTkButton(row, text="▶", width=40,
                      command=lambda p=path: _play_audio_file(p)
                      ).pack(side="left", padx=2)
        ctk.CTkButton(row, text="🔁", width=40,
                      fg_color="#b3771d", hover_color="#d18a22",
                      command=lambda pr=prefix, i=idx, p=path, s=status:
                          _regen_one(pr, i, p, s)
                      ).pack(side="left", padx=2)
        status.pack(side="left", padx=(4, 2))


def _check_rvc_preflight():
    """Kiểm tra các thành phần RVC trước khi bắt đầu tiến trình.
    Trả về True nếu hợp lệ, False + log lỗi nếu không.
    """
    _model = rvc_model_var.get().strip()
    if not _model:
        log("❌ RVC Voice Clone: Chưa chọn file Model (.pth) — tiến trình bị hủy")
        log("  • Nhấn Browse ở ô Model (.pth) để chọn file model RVC")
        log("  • File model thường có đuôi .pth, ví dụ: my_voice.pth")
        return False
    if not os.path.isfile(_model):
        log(f"❌ RVC Voice Clone: Không tìm thấy file Model: {_model}")
        log("  • Kiểm tra lại đường dẫn file model (.pth)")
        log("  • File có thể đã bị di chuyển hoặc xóa — Browse lại để chọn đúng file")
        return False
    _index = rvc_index_var.get().strip()
    if _index and not os.path.isfile(_index):
        log(f"❌ RVC Voice Clone: Không tìm thấy file Index: {_index}")
        log("  • Kiểm tra lại đường dẫn file Index (.index)")
        log("  • Để trống ô Index nếu không dùng file index")
        return False
    _base = getattr(sys, '_MEIPASS', os.path.dirname(os.path.abspath(__file__)))
    _helper = os.path.join(_base, 'rvc_helper.py')
    if not os.path.exists(_helper):
        _helper = os.path.join(os.path.dirname(sys.executable), 'rvc_helper.py')
    if not os.path.exists(_helper):
        log("❌ RVC Voice Clone: Không tìm thấy rvc_helper.py")
        log("  • Đảm bảo rvc_helper.py nằm cùng thư mục với app hoặc exe")
        return False
    _srch = (os.path.dirname(sys.executable) if getattr(sys, 'frozen', False)
             else os.path.dirname(os.path.abspath(__file__)))
    _s = _srch
    for _ in range(3):
        if os.path.exists(os.path.join(_s, 'rvc_env', 'Scripts', 'python.exe')):
            return True
        _p = os.path.dirname(_s)
        if _p == _s:
            break
        _s = _p
    log("❌ RVC Voice Clone: Không tìm thấy rvc_env\\Scripts\\python.exe")
    log("  • Đảm bảo thư mục rvc_env\\ nằm cạnh app/exe")
    log("  • rvc_env cần Python 3.10 với infer_rvc_python + fairseq đã cài")
    return False


def _apply_rvc_sync(filename):
    model_path = rvc_model_var.get().strip()
    index_path = rvc_index_var.get().strip()

    if not model_path:
        raise RuntimeError("RVC: Chưa chọn file model (.pth)")
    if not os.path.exists(model_path):
        raise RuntimeError(f"RVC: Không tìm thấy model: {model_path}")

    try:
        pitch = int(rvc_pitch_var.get())
    except ValueError:
        pitch = 0

    device = rvc_device_var.get()
    # "auto": có GPU NVIDIA → cuda:0, không thì cpu (giống cơ chế tự dò của VoxCPM/VieNeu)
    if device == "auto":
        device = "cuda:0" if DETECTED_GPU else "cpu"
        log(f"RVC: Device tự động → {device}"
            + (f" ({DETECTED_GPU})" if DETECTED_GPU else " (không thấy GPU NVIDIA)"))

    # Tìm rvc_helper.py cạnh script hoặc exe
    _base = getattr(sys, '_MEIPASS', os.path.dirname(os.path.abspath(__file__)))
    helper = os.path.join(_base, 'rvc_helper.py')
    if not os.path.exists(helper):
        helper = os.path.join(os.path.dirname(sys.executable), 'rvc_helper.py')
    if not os.path.exists(helper):
        raise RuntimeError("RVC: Không tìm thấy rvc_helper.py cạnh app")

    rvc_out = filename + ".rvc_out.wav"

    # Find rvc_env (Python 3.10) which has infer_rvc_python + fairseq compatible.
    # Search up to 3 parent directories to handle dev, onefile (dist/), and
    # onedir (dist/SRT_TTS_Studio/) layouts.
    _search_root = (
        os.path.dirname(sys.executable) if getattr(sys, 'frozen', False)
        else os.path.dirname(os.path.abspath(__file__))
    )
    _rvc_env_py = None
    _search = _search_root
    for _ in range(3):
        _candidate = os.path.join(_search, 'rvc_env', 'Scripts', 'python.exe')
        if os.path.exists(_candidate):
            _rvc_env_py = _candidate
            break
        _parent = os.path.dirname(_search)
        if _parent == _search:
            break
        _search = _parent
    _rvc_python = [_rvc_env_py] if _rvc_env_py else ['py', '-3.10']

    # Tìm rmvpe.pt và hubert_base.pt: thử cạnh helper, rồi dist/, rồi project root
    def _find_model_file(name):
        candidates = [
            os.path.join(os.path.dirname(helper), name),
            os.path.join(_search_root, 'dist', name),
            os.path.join(_search_root, name),
        ]
        for c in candidates:
            if os.path.exists(c):
                return c
        return ""

    rmvpe_path  = _find_model_file("rmvpe.pt")
    hubert_path = _find_model_file("hubert_base.pt")

    algo = rvc_algo_var.get().strip() or "rmvpe"

    cmd = _rvc_python + [helper,
           '--input', filename,
           '--output', rvc_out,
           '--model', model_path,
           '--pitch', str(pitch),
           '--algo', algo]
    if rmvpe_path:
        cmd += ['--rmvpe_path', rmvpe_path]
    if hubert_path:
        cmd += ['--hubert_path', hubert_path]
    if index_path and os.path.exists(index_path):
        cmd += ['--index', index_path, '--index_influence', '0.75']
    if device == 'cpu':
        cmd += ['--cpu']

    result = subprocess.run(cmd, capture_output=True, text=True, timeout=180,
                            creationflags=CREATE_NO_WINDOW)
    if result.returncode != 0:
        err = (result.stderr or result.stdout or "unknown error")
        raise RuntimeError(f"RVC error: {err}")

    if not os.path.exists(rvc_out):
        raise RuntimeError("RVC: Helper chạy xong nhưng không tạo được file output")

    cmd2 = [FFMPEG, "-y", "-i", rvc_out, "-q:a", "2", filename]
    r2 = subprocess.run(cmd2, capture_output=True, creationflags=CREATE_NO_WINDOW)
    try:
        os.remove(rvc_out)
    except Exception:
        pass
    if r2.returncode != 0:
        raise RuntimeError(f"RVC ffmpeg lỗi: {r2.stderr.decode(errors='replace')[:200]}")


# =========================
# TTS
# =========================

# ── Edge TTS song song ────────────────────────────────────────────────────────
# Edge TTS là API mạng miễn phí, mỗi dòng chủ yếu là chờ network → chạy đồng
# thời _TTS_PARALLEL_N dòng nhanh hơn nhiều lần với SRT dài. CHỈ áp dụng cho
# Edge TTS không kèm RVC: provider trả phí giữ tuần tự (tôn trọng rate-limit),
# RVC giữ tuần tự (subprocess nặng, không chạy chồng). Giữ nguyên QC + retry
# per-line, FAIL + continue, Pause/Stop, delay chống throttle (tính theo slot).
_TTS_PARALLEL_N = 4

# ♻ Cache audio dòng trùng: phim bộ có rất nhiều thoại lặp ("Vâng", "Cảm ơn"...).
# Dòng có cùng (provider, voice, rate, pitch, text-sau-tiền-xử-lý) thì copy lại
# file đã gen + pass QC thay vì gọi API lần nữa — nhanh hơn và tiết kiệm quota.
# KHÔNG dùng khi RVC bật (file bị convert in-place sau QC → copy sẽ dính double
# convert). Entry chỉ được ghi sau khi audio pass QC; path chết được isfile-guard.
#
# Cache BỀN qua phiên: ngoài dict RAM, mỗi entry còn được copy vào
# <_CONFIG_DIR>/tts_cache/<key>.mp3 — nên phim BỘ tái dùng câu trùng giữa các TẬP
# (qua nhiều lần mở app), không chỉ trong 1 batch. Disk cache bị giới hạn dung
# lượng (_TTS_CACHE_MAX_MB) bằng prune theo mtime cũ nhất, chạy 1 lần khi resolve
# thư mục. Toàn bộ I/O bọc try/except — lỗi cache không bao giờ chặn TTS.
_TTS_CACHE = {}
_TTS_CACHE_MAX_MB = 2048          # trần dung lượng disk cache (~2 GB)
_TTS_CACHE_DIR_CACHED = [None]    # None=chưa thử, ""=thử & thất bại, str=ok

def _tts_cache_key(text):
    base = "|".join((TTS_PROVIDER, VOICE, _edge_rate(), _edge_pitch(),
                     _apply_glossary(text)))
    return hashlib.sha1(base.encode("utf-8")).hexdigest()

def _tts_cache_dir():
    """Thư mục disk cache (lazy-create dưới _CONFIG_DIR); None nếu không dùng được."""
    d = _TTS_CACHE_DIR_CACHED[0]
    if d is not None:
        return d or None
    try:
        path = os.path.join(os.path.dirname(_SETTINGS_FILE), "tts_cache")
        os.makedirs(path, exist_ok=True)
        _TTS_CACHE_DIR_CACHED[0] = path
        _tts_cache_prune(path)    # giữ dung lượng trong trần — chạy 1 lần
        return path
    except Exception:
        _TTS_CACHE_DIR_CACHED[0] = ""
        return None

def _tts_cache_prune(path):
    """Nếu vượt trần, xóa file cũ nhất (theo mtime) xuống còn ~75% trần."""
    try:
        files = []
        total = 0
        for n in os.listdir(path):
            p = os.path.join(path, n)
            try:
                st = os.stat(p)
            except OSError:
                continue
            files.append((st.st_mtime, st.st_size, p))
            total += st.st_size
        cap = _TTS_CACHE_MAX_MB * 1024 * 1024
        if total <= cap:
            return
        target = int(cap * 0.75)
        for _mt, sz, p in sorted(files):       # cũ nhất trước
            if total <= target:
                break
            try:
                os.remove(p)
                total -= sz
            except OSError:
                pass
    except Exception:
        pass

def _tts_cache_get(text):
    """Path audio đã cache cho text (RAM trước rồi disk), đã xác minh tồn tại; hoặc None."""
    key = _tts_cache_key(text)
    f = _TTS_CACHE.get(key)
    if f and os.path.isfile(f):
        return f
    try:
        d = _tts_cache_dir()
        if d:
            p = os.path.join(d, key + ".mp3")
            if os.path.isfile(p):
                _TTS_CACHE[key] = p      # nạp lại vào RAM cho lần sau
                return p
    except Exception:
        pass
    return None

def _tts_cache_put(text, filename):
    """Lưu file vừa pass QC vào cache RAM + disk (bền qua phiên)."""
    key = _tts_cache_key(text)
    _TTS_CACHE[key] = filename
    try:
        d = _tts_cache_dir()
        if d:
            p = os.path.join(d, key + ".mp3")
            if not os.path.isfile(p):
                shutil.copy2(filename, p)
    except Exception:
        pass


# ── Thống kê batch + ước phí + lịch sử tốc độ (các luồng provider) ────────────
# _BATCH_STATS: reset đầu batch, cộng dồn tại các điểm OK/♻/retry, in ở epilogue.
# _SPEED_HISTORY: giây/dòng trung bình (EMA) per engine — lưu qua phiên trong
# ui_prefs.json (khóa "_speed_history") để batch sau ước được thời gian NGAY từ
# đầu. Phạm vi: các luồng provider (Edge/FPT/...); engine local chưa hook.
_BATCH_STATS = {"t0": 0.0, "gen": 0, "cache": 0, "retry": 0}
_SPEED_HISTORY = {}   # key engine → giây/dòng (EMA 50/50)

def _batch_stats_reset():
    _BATCH_STATS.update({"t0": time.monotonic(), "gen": 0, "cache": 0, "retry": 0})

def _speed_hist_key():
    if VOXCPM_ENABLED:
        return "voxcpm"
    if VIENEU_ENABLED:
        return "vieneu"
    if F5TTS_ENABLED:
        return "f5tts"
    if OMNIVOICE_ENABLED:
        return "omnivoice"
    k = TTS_PROVIDER + ("+rvc" if RVC_ENABLED else "")
    if TTS_PROVIDER == "Edge TTS" and not RVC_ENABLED:
        k += f"x{_TTS_PARALLEL_N}"   # song song — tốc độ khác hẳn tuần tự
    return k

def _fmt_dur(sec):
    sec = int(sec)
    if sec >= 3600:
        return f"{sec // 3600}g{(sec % 3600) // 60:02d}p"
    if sec >= 60:
        return f"{sec // 60}p{sec % 60:02d}s"
    return f"{sec}s"

def _log_batch_stats():
    """In khối 📊 cuối batch + cập nhật lịch sử tốc độ cho ước tính lần sau."""
    el = time.monotonic() - _BATCH_STATS["t0"]
    done = _BATCH_STATS["gen"] + _BATCH_STATS["cache"]
    if done <= 0 or el <= 0:
        return
    speed = done / (el / 60.0)
    log(f"📊 Batch: {_BATCH_STATS['gen']} dòng gen"
        + (f" + {_BATCH_STATS['cache']} dòng ♻ cache" if _BATCH_STATS["cache"] else "")
        + f" trong {_fmt_dur(el)} (~{speed:.1f} dòng/phút)"
        + (f"; {_BATCH_STATS['retry']} lượt QC retry" if _BATCH_STATS["retry"] else "")
        + (f"; {FAIL_COUNT} FAIL" if FAIL_COUNT else "; 0 FAIL"))
    if FAIL_COUNT:
        log("💡 Bấm '📋 Việc cần làm' (trang SRT) để xem mọi việc tồn đọng kèm nút xử lý.")
    # EMA tốc độ chỉ tính trên dòng GEN thật (cache hit nhanh bất thường)
    if _BATCH_STATS["gen"] >= 5:
        spl = el / max(1, _BATCH_STATS["gen"])
        key = _speed_hist_key()
        old = _SPEED_HISTORY.get(key)
        _SPEED_HISTORY[key] = spl if old is None else (old + spl) / 2.0

def _log_eta_estimate(n_lines):
    """Đầu batch: ước thời gian từ tốc độ lịch sử của engine này (nếu có)."""
    try:
        spl = _SPEED_HISTORY.get(_speed_hist_key())
        if spl and n_lines > 0:
            log(f"⏳ Ước tính ~{_fmt_dur(spl * n_lines)} cho {n_lines} dòng "
                "(theo tốc độ lần chạy trước)")
    except Exception:
        pass

# ── Ước phí provider trả phí ──────────────────────────────────────────────────
# Đơn giá người dùng tự khai trong tts_prices.json (VND / 1000 ký tự) cạnh
# settings.json — giá hợp đồng mỗi người mỗi khác nên không hardcode. File
# template tự sinh lần đầu. Edge TTS miễn phí → chỉ báo số ký tự.
_TTS_PRICES_FILE = os.path.join(
    os.path.dirname(_SETTINGS_FILE) or ".", "tts_prices.json")

def _tts_price_per_1k(provider):
    try:
        if not os.path.isfile(_TTS_PRICES_FILE):
            with open(_TTS_PRICES_FILE, "w", encoding="utf-8") as f:
                json.dump({p: 0 for p in
                           ("FPT.AI", "Vbee", "Zalo AI", "EverAI", "MiniMax")},
                          f, ensure_ascii=False, indent=2)
            return 0.0
        with open(_TTS_PRICES_FILE, "r", encoding="utf-8") as f:
            return float(json.load(f).get(provider, 0) or 0)
    except Exception:
        return 0.0

def _warn_low_disk(path, need_bytes, label=""):
    """Cảnh báo sớm khi ổ đích sắp đầy (hết đĩa giữa batch đêm = toi cả hàng).
    Chỉ cảnh báo, không chặn — ước lượng thô, người dùng tự quyết."""
    try:
        free = shutil.disk_usage(os.path.abspath(path)).free
        if free < need_bytes:
            log(f"{label}⚠ Ổ đĩa đích sắp đầy: còn {free / 2**30:.1f} GB, "
                f"ước cần ~{need_bytes / 2**30:.1f} GB — nên giải phóng trước khi chạy dài!")
    except Exception:
        pass


def _log_cost_estimate(n_lines, n_chars, label=""):
    """Đầu batch: báo khối lượng + ước phí (nếu đã khai đơn giá)."""
    if n_lines <= 0:
        return
    msg_ = f"{label}🧾 Khối lượng: {n_lines} dòng / {n_chars:,} ký tự"
    if TTS_PROVIDER != "Edge TTS":
        price = _tts_price_per_1k(TTS_PROVIDER)
        if price > 0:
            msg_ += f" — ước phí ~{n_chars / 1000.0 * price:,.0f}đ ({TTS_PROVIDER})"
        else:
            msg_ += (f" — {TTS_PROVIDER} TRẢ PHÍ (khai đơn giá VND/1000 ký tự "
                     f"trong {os.path.basename(_TTS_PRICES_FILE)} để hiện ước phí)")
    log(msg_)

async def _tts_par_one(idx, text, sem, state, dmin, dmax,
                       prefix="line_", label=""):
    """Sinh 1 dòng (QC + retry, giống vòng tuần tự) trong chế độ song song.
    prefix/label phân biệt luồng SRT ("line_") và PDF/Doc ("pdf_line_", "[PDF] ")."""
    global FAIL_COUNT
    async with sem:
        # asyncio chạy 1 thread nên FAIL_COUNT/state không cần lock
        if stop_requested or state["abort"]:
            return
        while paused and not stop_requested:
            await asyncio.sleep(0.3)
        if stop_requested or state["abort"]:
            return
        if not _net_was_online[0]:
            state["netdown"] = True
            state["abort"] = True
            return
        filename = os.path.join(OUTPUT_DIR, f"{prefix}{idx:04d}.mp3")
        # ♻ dòng trùng → copy audio đã pass QC, khỏi gọi API
        _cf = _tts_cache_get(text)
        if _cf:
            try:
                shutil.copy2(_cf, filename)
                log(f"♻ {label}OK {idx} (dòng trùng — dùng lại audio)")
                _BATCH_STATS["cache"] += 1
                state["done"] += 1
                update_progress(state["pre_done"] + state["done"], state["total"])
                return
            except Exception:
                pass
        log(f"{label}Generating {filename}")
        ok = False
        _bad = False
        _reason = ""
        _detail = ""
        for _qc_attempt in range(_QC_MAX_RETRIES + 1):
            _gen_text = (_sanitize_tts_text(text)
                         if _qc_attempt == _QC_MAX_RETRIES else text)
            try:
                ok = await save_tts(_gen_text, filename)
            except QuotaExhaustedError as qe:
                log(f"HẾT QUOTA: {qe}")
                state["quota"] = True
                state["abort"] = True
                return
            if not ok:
                break
            _loop = asyncio.get_event_loop()
            _bad, _reason, _detail = await _loop.run_in_executor(
                None, _audio_quality_check, filename, text)
            if not _bad:
                break
            if _qc_attempt < _QC_MAX_RETRIES:
                log(f"  ⚠ Dòng {idx}: audio {_reason} ({_detail}) — "
                    f"tạo lại lần {_qc_attempt + 1}/{_QC_MAX_RETRIES}")
                _BATCH_STATS["retry"] += 1
                try:
                    os.remove(filename)
                except Exception:
                    pass
        if ok and not _bad:
            log(f"{label}OK {idx}")
            _BATCH_STATS["gen"] += 1
            _tts_cache_put(text, filename)
        elif ok and _bad:
            _rename_bad_audio(filename, idx, _reason, _detail,
                              label.strip(" []") if label else "")
            log(f"{label}FAIL {idx}")
            FAIL_COUNT += 1
        else:
            log(f"{label}FAIL {idx}")
            FAIL_COUNT += 1
        state["done"] += 1
        update_progress(state["pre_done"] + state["done"], state["total"])
        # delay chống throttle giữ NGUYÊN theo slot (mỗi luồng vẫn nghỉ giữa
        # 2 dòng của nó) — tốc độ tổng = N slot chạy xen kẽ
        await asyncio.sleep(random.uniform(dmin, dmax))


async def _generate_tts_parallel():
    """Driver song song cho Edge TTS: gom các dòng còn thiếu rồi gather."""
    total = len(subtitles_cache)
    items = []
    skipped = 0
    for i in range(current_index, total):
        text = clean_text(subtitles_cache[i].content)
        if not text:
            continue
        if not _is_speakable(text):
            log(f"⏭ Dòng {i}: không có nội dung đọc được — bỏ qua")
            continue
        if os.path.exists(os.path.join(OUTPUT_DIR, f"line_{i:04d}.mp3")):
            skipped += 1
            continue
        items.append((i, text))
    if skipped:
        log(f"SKIP {skipped} dòng đã có audio")
    state = {"done": 0, "abort": False, "netdown": False, "quota": False,
             "total": total, "pre_done": total - len(items)}
    if not items:
        return state
    try:
        dmin = max(0.0, float(delay_min_var.get()))
        dmax = max(dmin, float(delay_max_var.get()))
    except ValueError:
        dmin, dmax = TTS_DELAY_MIN, TTS_DELAY_MAX
    log(f"⚡ Edge TTS song song ×{_TTS_PARALLEL_N} — {len(items)} dòng cần tạo")
    sem = asyncio.Semaphore(_TTS_PARALLEL_N)
    await asyncio.gather(*[
        _tts_par_one(i, t, sem, state, dmin, dmax) for i, t in items])
    return state


async def _generate_pdf_tts_parallel():
    """Driver song song cho PDF/Doc TTS (Edge) — như _generate_tts_parallel
    nhưng nguồn là PDF_CHUNKS và file pdf_line_NNNN.mp3."""
    total = len(PDF_CHUNKS)
    _rlo, _rhi = _pdf_range(total)   # 📖 phạm vi 'Từ đoạn/đến'
    items = []
    skipped = 0
    for i in range(max(current_index, _rlo), min(total, _rhi + 1)):
        text = (PDF_CHUNKS[i] or "").strip()
        if not text:
            continue
        if not _is_speakable(text):
            log(f"⏭ [PDF] Đoạn {i}: không có nội dung đọc được — bỏ qua")
            continue
        if os.path.exists(os.path.join(OUTPUT_DIR, f"pdf_line_{i:04d}.mp3")):
            skipped += 1
            continue
        items.append((i, text))
    if skipped:
        log(f"[PDF] SKIP {skipped} đoạn đã có audio")
    state = {"done": 0, "abort": False, "netdown": False, "quota": False,
             "total": total, "pre_done": total - len(items)}
    if not items:
        return state
    try:
        dmin = max(0.0, float(delay_min_var.get()))
        dmax = max(dmin, float(delay_max_var.get()))
    except ValueError:
        dmin, dmax = TTS_DELAY_MIN, TTS_DELAY_MAX
    log(f"⚡ [PDF] Edge TTS song song ×{_TTS_PARALLEL_N} — {len(items)} đoạn cần tạo")
    sem = asyncio.Semaphore(_TTS_PARALLEL_N)
    await asyncio.gather(*[
        _tts_par_one(i, t, sem, state, dmin, dmax,
                     prefix="pdf_line_", label="[PDF] ") for i, t in items])
    return state


async def generate_tts():

    global current_index
    global paused
    global stop_requested
    global FAIL_COUNT

    load_subtitles(force_select=False)

    if not subtitles_cache:
        return

    FAIL_COUNT = 0

    if RVC_ENABLED and not _check_rvc_preflight():
        return

    app.after(0, _hide_quota_banner)
    app.after(0, lambda: set_mode("tts_running"))

    total = len(subtitles_cache)

    update_progress(current_index, total)

    # 📊 Reset thống kê + ước khối lượng/phí/thời gian cho phần CÒN THIẾU
    _batch_stats_reset()
    _est_lines = 0
    _est_chars = 0
    for _ei in range(current_index, total):
        _et = clean_text(subtitles_cache[_ei].content)
        if _et and not os.path.exists(
                os.path.join(OUTPUT_DIR, f"line_{_ei:04d}.mp3")):
            _est_lines += 1
            _est_chars += len(_et)
    _log_cost_estimate(_est_lines, _est_chars)
    _log_eta_estimate(_est_lines)
    # ~2.2 KB audio / ký tự (mp3 q:a 2) × 2 slack (wav tạm, retry, file lỗi)
    _warn_low_disk(OUTPUT_DIR, _est_chars * 4500)

    # ⚡ Nhánh song song: chỉ Edge TTS không RVC (xem chú thích _TTS_PARALLEL_N)
    if TTS_PROVIDER == "Edge TTS" and not RVC_ENABLED and _TTS_PARALLEL_N > 1:
        _st = await _generate_tts_parallel()
        # 📶 rớt mạng → chờ hồi phục rồi chạy lại (skip-existing = resume)
        while _st["netdown"] and not stop_requested \
                and await _wait_net_recovery():
            _st = await _generate_tts_parallel()
        if stop_requested:
            log("PROCESS STOPPED")
            return
        if _st["netdown"]:
            log("❌ TTS: Mất kết nối Internet — dừng tiến trình. "
                "Khôi phục mạng rồi nhấn Resume để tiếp tục.")
            app.after(0, lambda: set_mode("tts_stopped"))
            return
        if _st["quota"]:
            _provider = TTS_PROVIDER
            app.after(0, lambda p=_provider: _show_quota_banner(p))
            app.after(0, lambda: set_mode("tts_stopped"))
            return
        log("TTS DONE")
        _log_batch_stats()
        app.after(0, show_fireworks)
        update_progress(total, total)
        current_index = 0
        app.after(0, lambda: set_mode("tts_done"))
        app.after(200, open_output_folder)
        _maybe_auto_retry_fail()
        return

    while current_index < total:

        if stop_requested:
            log("PROCESS STOPPED")
            return

        # Kiểm tra internet mỗi dòng (dùng cache monitor, không ping thêm).
        # Mất mạng → tự chờ hồi phục (tối đa 30 phút) rồi đọc tiếp; hết kiên
        # nhẫn / bấm Dừng mới dừng hẳn (Resume thủ công vẫn hoạt động như cũ).
        if not _net_was_online[0]:
            if await _wait_net_recovery():
                continue
            log("❌ TTS: Mất kết nối Internet — dừng tiến trình. "
                "Khôi phục mạng rồi nhấn Resume để tiếp tục.")
            app.after(0, lambda: set_mode("tts_stopped"))
            return

        while paused:
            await asyncio.sleep(0.5)

        sub = subtitles_cache[current_index]

        text = clean_text(sub.content)

        if not text:
            current_index += 1
            continue

        # Dòng không có ký tự đọc được (toàn dấu câu / ký hiệu / nốt nhạc) → bỏ qua,
        # nếu gen thì TTS chỉ ra im lặng (novoice) và phí 3 lượt retry.
        if not _is_speakable(text):
            log(f"⏭ Dòng {current_index}: không có nội dung đọc được — bỏ qua")
            current_index += 1
            continue

        filename = os.path.join(
            OUTPUT_DIR,
            f"line_{current_index:04d}.mp3"
        )

        # Skip existing files when resuming
        if os.path.exists(filename):
            log(f"SKIP {current_index}")
            current_index += 1
            continue

        # ♻ dòng trùng → copy audio đã pass QC, khỏi gọi API (trừ khi RVC bật)
        if not RVC_ENABLED:
            _cf = _tts_cache_get(text)
            if _cf:
                try:
                    shutil.copy2(_cf, filename)
                    log(f"♻ OK {current_index} (dòng trùng — dùng lại audio)")
                    _BATCH_STATS["cache"] += 1
                    current_index += 1
                    update_progress(current_index, total)
                    continue
                except Exception:
                    pass

        log(f"Generating {filename}")

        # Tạo audio + kiểm tra chất lượng. Nếu im lặng / quá dài (lặp) / quá ngắn
        # (bị cắt) thì xóa và tạo lại tối đa _QC_MAX_RETRIES lần (TTS không tất định
        # nên lần tạo lại thường ra audio đúng).
        ok = False
        _bad = False
        _reason = ""
        _detail = ""
        for _qc_attempt in range(_QC_MAX_RETRIES + 1):
            # Edge TTS không tất định: tạo lại CÙNG text thường tự ra audio đúng
            # (đã kiểm chứng). Chỉ ở lần thử CUỐI mới dùng text chuẩn hóa
            # (bỏ "...", gạch hội thoại) như phương án chót.
            _gen_text = (_sanitize_tts_text(text)
                         if _qc_attempt == _QC_MAX_RETRIES else text)
            try:
                ok = await save_tts(_gen_text, filename)
            except QuotaExhaustedError as qe:
                log(f"HẾT QUOTA: {qe}")
                _provider = TTS_PROVIDER
                app.after(0, lambda p=_provider: _show_quota_banner(p))
                app.after(0, lambda: set_mode("tts_stopped"))
                return
            if not ok:
                break
            _loop = asyncio.get_event_loop()
            _bad, _reason, _detail = await _loop.run_in_executor(
                None, _audio_quality_check, filename, text)
            if not _bad:
                break
            if _qc_attempt < _QC_MAX_RETRIES:
                log(f"  ⚠ Dòng {current_index}: audio {_reason} ({_detail}) — "
                    f"tạo lại lần {_qc_attempt + 1}/{_QC_MAX_RETRIES}")
                _BATCH_STATS["retry"] += 1
                try:
                    os.remove(filename)
                except Exception:
                    pass

        if ok and not _bad:
            log(f"OK {current_index}")
            _BATCH_STATS["gen"] += 1
            if not RVC_ENABLED:
                _tts_cache_put(text, filename)
            if RVC_ENABLED and os.path.exists(filename):
                try:
                    log(f"  RVC convert {current_index}...")
                    _loop = asyncio.get_event_loop()
                    await _loop.run_in_executor(None, _apply_rvc_sync, filename)
                    log(f"  RVC OK")
                    # QC lại output RVC: RVC giữ nguyên độ dài nên chủ yếu bắt
                    # trường hợp RVC ra file im lặng (model lỗi mà không raise).
                    _rbad, _rreason, _rdetail = await _loop.run_in_executor(
                        None, _audio_quality_check, filename, text)
                    if _rbad:
                        _rename_bad_audio(filename, current_index, _rreason, _rdetail, "RVC")
                        log(f"FAIL {current_index}")
                        FAIL_COUNT += 1
                except Exception as _rvc_err:
                    log(f"❌ RVC thất bại tại dòng {current_index}: {_rvc_err}")
                    log("  • Kiểm tra file model (.pth) có đúng đường dẫn không")
                    log("  • Đảm bảo rvc_env\\Scripts\\python.exe tồn tại")
                    log("  • Thử đổi Algo sang rmvpe hoặc harvest")
                    log("  • Thử chuyển Device sang CPU")
                    log(f"FAIL {current_index}")
                    FAIL_COUNT += 1
        elif ok and _bad:
            # Hết lượt thử mà audio vẫn lỗi → đổi tên đánh dấu, Resume sẽ tạo lại
            _rename_bad_audio(filename, current_index, _reason, _detail)
            log(f"FAIL {current_index}")
            FAIL_COUNT += 1
        else:
            log(f"FAIL {current_index}")
            FAIL_COUNT += 1

        current_index += 1

        update_progress(current_index, total)

        try:
            _dmin = float(delay_min_var.get())
            _dmax = float(delay_max_var.get())
            if _dmin < 0: _dmin = 0.0
            if _dmax < _dmin: _dmax = _dmin
        except ValueError:
            _dmin, _dmax = TTS_DELAY_MIN, TTS_DELAY_MAX
        _delay = random.uniform(_dmin, _dmax)
        log(f"⏱ chờ {_delay:.2f}s")
        await asyncio.sleep(_delay)

    log("TTS DONE")
    _log_batch_stats()
    app.after(0, show_fireworks)

    update_progress(total, total)

    current_index = 0

    app.after(0, lambda: set_mode("tts_done"))
    app.after(200, open_output_folder)
    _maybe_auto_retry_fail()


def _voxcpm_transcribe_audio():
    """STT audio mẫu VoxCPM → điền vào Nội dung mẫu (dùng Whisper local)."""
    ref_path = voxcpm_ref_var.get().strip()
    if not ref_path or not os.path.exists(ref_path):
        log("STT: Chưa chọn file Audio mẫu")
        return

    ckpt_dir = voxcpm_ckpt_var.get().strip()
    voxcpm_py = _find_voxcpm_python(ckpt_dir) if ckpt_dir else None
    if not voxcpm_py:
        log("STT: Không tìm thấy voxcpm_env python (cần để chạy Whisper)")
        return

    # Tìm whisper_stt.py
    _helper_dirs = []
    if hasattr(sys, '_MEIPASS'):
        _helper_dirs.append(sys._MEIPASS)
    try:
        _helper_dirs.append(os.path.dirname(os.path.abspath(__file__)))
    except Exception:
        pass
    try:
        _helper_dirs.append(os.path.dirname(os.path.abspath(sys.argv[0])))
    except Exception:
        pass
    _helper_dirs.append(os.path.dirname(sys.executable))
    stt_helper = None
    for _d in _helper_dirs:
        _c = os.path.join(_d, 'whisper_stt.py')
        if os.path.exists(_c):
            stt_helper = _c
            break
    if not stt_helper:
        log(f"STT: Không tìm thấy whisper_stt.py")
        return

    def _run():
        log("STT: Đang nhận dạng (Whisper large-v3)...")
        proc = None
        try:
            proc = subprocess.Popen(
                [voxcpm_py, stt_helper, "--audio", ref_path, "--model", "large-v3", "--lang", "vi"],
                stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                text=True, encoding="utf-8", errors="replace",
                creationflags=CREATE_NO_WINDOW,
            )
            RUNNING_PROCESSES.append(proc)
            update_progress(2, 100)   # hiện thanh tiến trình ngay khi bắt đầu

            # whisper_stt.py phát PROGRESS:done_ms:total_ms ra stderr → kéo thanh;
            # các dòng stderr khác giữ lại để báo lỗi nếu cần.
            _err_lines = []
            def _read_err():
                for ln in proc.stderr:
                    ln = ln.strip()
                    if not ln:
                        continue
                    if ln.startswith("PROGRESS:"):
                        try:
                            _, n, m = ln.split(":")
                            pct = 5 + int(90 * int(n) / max(int(m), 1))
                            update_progress(pct, 100)
                        except Exception:
                            pass
                    else:
                        _err_lines.append(ln)
            _terr = threading.Thread(target=_read_err, daemon=True)
            _terr.start()

            stdout = proc.stdout.read()
            proc.wait(timeout=120)
            _terr.join(timeout=2)
            if proc in RUNNING_PROCESSES:
                RUNNING_PROCESSES.remove(proc)

            transcript = (stdout or "").strip()
            if proc.returncode != 0 or not transcript:
                err = _err_lines[-1] if _err_lines else "không có output"
                log(f"STT lỗi: {err}")
                return
            update_progress(100, 100)
            app.after(0, lambda t=transcript: voxcpm_reftext_var.set(t))
            log(f"STT OK: {transcript}")
        except subprocess.TimeoutExpired:
            if proc:
                proc.kill()
            log("STT: Timeout sau 120s")
        except Exception as e:
            log(f"STT lỗi: {e}")

    threading.Thread(target=_run, daemon=True).start()


def _vieneu_transcribe_audio():
    """STT audio mẫu VieNeu → điền vào Nội dung mẫu (dùng Whisper local).
    Whisper cài trong voxcpm_env → ưu tiên python đó; fallback vieneu_env."""
    ref_path = vieneu_ref_var.get().strip()
