def _run_voxcpm_batch():
    """Chạy VoxCPM batch generation trong daemon thread."""
    global current_index, stop_requested, FAIL_COUNT

    load_subtitles(force_select=False)
    if not subtitles_cache:
        return

    FAIL_COUNT = 0

    # ── VoxCPM pre-flight: kiểm tra trước khi bắt đầu ───────────────────────
    ckpt_dir = voxcpm_ckpt_var.get().strip()
    if not ckpt_dir:
        log("❌ VoxCPM Clone: Chưa nhập đường dẫn thư mục Model — tiến trình bị hủy")
        log("  • Nhấn Browse ở ô Model để chọn thư mục chứa model VoxCPM")
        log("  • Ví dụ: E:\\VoxCPM-1.5-VN\\VoxCPM\\pretrained\\VoxCPM-1.5-VN")
        return
    if not os.path.isdir(ckpt_dir):
        log(f"❌ VoxCPM Clone: Không tìm thấy thư mục Model: {ckpt_dir}")
        log("  • Kiểm tra lại đường dẫn thư mục model")
        log("  • Thư mục có thể đã bị đổi tên hoặc di chuyển — Browse lại để chọn đúng")
        return

    ref_audio = voxcpm_ref_var.get().strip()
    if ref_audio and not os.path.isfile(ref_audio):
        log(f"❌ VoxCPM Clone: Không tìm thấy file Audio mẫu: {ref_audio}")
        log("  • Kiểm tra lại đường dẫn file Audio mẫu")
        log("  • File có thể đã bị di chuyển hoặc xóa — Browse lại để chọn đúng file")
        log("  • Để trống ô Audio mẫu nếu không dùng giọng tham chiếu")
        return
    ref_text  = voxcpm_reftext_var.get().strip()

    try:
        steps = int(voxcpm_steps_var.get())
    except ValueError:
        steps = 10
    try:
        cfg = float(voxcpm_cfg_var.get())
    except ValueError:
        cfg = 2.0

    # Tìm voxcpm_env python
    voxcpm_py = _find_voxcpm_python(ckpt_dir)
    if not voxcpm_py:
        log("❌ VoxCPM Clone: Không tìm thấy voxcpm_env\\Scripts\\python.exe — tiến trình bị hủy")
        log("  • Đảm bảo thư mục voxcpm_env\\ nằm gần thư mục model hoặc cạnh app/exe")
        log("  • Có thể cấu hình python tùy chỉnh trong ⚙ Cài đặt → voxcpm_env_override")
        return

    # Tìm voxcpm_helper.py — thử nhiều vị trí
    _helper_dirs = []
    if hasattr(sys, '_MEIPASS'):
        _helper_dirs.append(sys._MEIPASS)
    try:
        _helper_dirs.append(os.path.dirname(os.path.abspath(__file__)))
    except Exception:
        pass
    try:
        _helper_dirs.append(os.path.dirname(os.path.abspath(sys.argv[0])))
    except Exception:
        pass
    _helper_dirs.append(os.path.dirname(sys.executable))
    helper = None
    for _d in _helper_dirs:
        _c = os.path.join(_d, 'voxcpm_helper.py')
        if os.path.exists(_c):
            helper = _c
            break
    if not helper:
        log(f"❌ VoxCPM Clone: Không tìm thấy voxcpm_helper.py — tiến trình bị hủy")
        log("  • Đảm bảo voxcpm_helper.py nằm cùng thư mục với app hoặc exe")
        return
    # ── Kết thúc VoxCPM pre-flight ───────────────────────────────────────────

    app.after(0, lambda: set_mode("tts_running"))

    # Ghi texts ra JSON tạm
    items = []
    for i, sub in enumerate(subtitles_cache):
        text = clean_text(sub.content)
        if text and _is_speakable(text):
            items.append({"index": i, "text": text})
        elif text:
            log(f"⏭ Dòng {i}: không có nội dung đọc được — bỏ qua")
    _text_by_idx = {it["index"]: it["text"] for it in items}

    texts_file = os.path.join(OUTPUT_DIR, "_voxcpm_texts.json")
    try:
        with open(texts_file, 'w', encoding='utf-8') as f:
            import json as _json
            _json.dump(_glossary_items(items), f, ensure_ascii=False, indent=2)
    except Exception as e:
        log(f"VoxCPM: Lỗi ghi texts file: {e}")
        app.after(0, lambda: set_mode("tts_stopped"))
        return

    total = len(subtitles_cache)
    log(f"VoxCPM: bắt đầu generate {len(items)}/{total} dòng...")

    cmd = [voxcpm_py, helper,
           '--texts-json', texts_file,
           '--output-dir', OUTPUT_DIR,
           '--ckpt-dir', ckpt_dir,
           '--timesteps', str(steps),
           '--cfg-value', str(cfg)]
    if ref_audio and os.path.exists(ref_audio):
        cmd += ['--reference', ref_audio]
        if ref_text:
            cmd += ['--reference-text', ref_text]

    try:
        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, encoding='utf-8', errors='replace',
            creationflags=CREATE_NO_WINDOW,
        )
        RUNNING_PROCESSES.append(proc)
    except Exception as e:
        log(f"VoxCPM: Lỗi khởi chạy subprocess: {e}")
        app.after(0, lambda: set_mode("tts_stopped"))
        return

    done_count = 0
    try:
        for line in proc.stdout:
            if stop_requested:
                proc.terminate()
                log("VoxCPM STOPPED")
                app.after(0, lambda: set_mode("tts_stopped"))
                return

            line = line.rstrip()
            if line.startswith("DONE:"):
                try:
                    idx = int(line.split(":")[1])
                except (IndexError, ValueError):
                    continue
                wav_path = os.path.join(OUTPUT_DIR, f"line_{idx:04d}.wav")
                mp3_path = os.path.join(OUTPUT_DIR, f"line_{idx:04d}.mp3")
                if os.path.exists(wav_path):
                    r = subprocess.run(
                        [FFMPEG, "-y", "-i", wav_path, "-q:a", "2", mp3_path],
                        capture_output=True, creationflags=CREATE_NO_WINDOW,
                    )
                    try:
                        os.remove(wav_path)
                    except Exception:
                        pass
                    if r.returncode == 0:
                        _bad, _reason, _detail = _audio_quality_check(
                            mp3_path, _text_by_idx.get(idx, ""))
                        if _bad:
                            _rename_bad_audio(mp3_path, idx, _reason, _detail)
                            FAIL_COUNT += 1
                        else:
                            log(f"OK {idx}")
                    else:
                        log(f"❌ VoxCPM FFMPEG lỗi line {idx}")
                        log(f"FAIL {idx}")
                        FAIL_COUNT += 1
                else:
                    log(f"❌ VoxCPM không tạo được audio dòng {idx}")
                    log(f"FAIL {idx}")
                    FAIL_COUNT += 1
                done_count += 1
                _p = done_count / max(len(items), 1)
                app.after(0, lambda p=_p, i=done_count, t=len(items):
                          update_progress(i, t))
            elif line.startswith("WARN:"):
                log(f"⚠ VoxCPM {line}")
            elif line.startswith("["):
                log(f"  {line}")
            elif line == "ALL_DONE":
                break
            elif line.startswith("ERROR:"):
                # Trích idx từ ERROR:{idx}:... để log FAIL N giống provider TTS
                try:
                    _parts = line.split(":", 2)
                    _fail_idx = int(_parts[1])
                    log(f"❌ VoxCPM {line}")
                    log(f"FAIL {_fail_idx}")
                    FAIL_COUNT += 1
                    done_count += 1
                    _p = done_count / max(len(items), 1)
                    app.after(0, lambda p=_p, i=done_count, t=len(items):
                              update_progress(i, t))
                except (IndexError, ValueError):
                    log(f"VoxCPM {line}")
    except Exception as e:
        log(f"VoxCPM stream error: {e}")

    proc.wait()
    try:
        RUNNING_PROCESSES.remove(proc)
    except ValueError:
        pass
    try:
        os.remove(texts_file)
    except Exception:
        pass

    if proc.returncode != 0 and not stop_requested:
        log(f"VoxCPM kết thúc với lỗi (code={proc.returncode})")
        app.after(0, lambda: set_mode("tts_stopped"))
        return

    log("VoxCPM DONE")
    app.after(0, show_fireworks)
    update_progress(total, total)
    current_index = 0
    app.after(0, lambda: set_mode("tts_done"))
    app.after(200, open_output_folder)


