# ── F5-TTS-Vietnamese backend ────────────────────────────────────────────────
def _f5tts_find_helper():
    """Tìm f5tts_helper.py — sys._MEIPASS → exe dir → script dir."""
    _dirs = []
    if hasattr(sys, '_MEIPASS'):
        _dirs.append(sys._MEIPASS)
    try:
        _dirs.append(os.path.dirname(os.path.abspath(__file__)))
    except Exception:
        pass
    try:
        _dirs.append(os.path.dirname(os.path.abspath(sys.argv[0])))
    except Exception:
        pass
    _dirs.append(os.path.dirname(sys.executable))
    for _d in _dirs:
        _c = os.path.join(_d, 'f5tts_helper.py')
        if os.path.exists(_c):
            return _c
    return None


def _f5tts_preflight():
    """Kiểm tra F5-TTS trước khi chạy. Trả về (ok, model_dir, f5tts_py, helper).
    Model dir BẮT BUỘC (chứa checkpoint .pt + vocab.txt); audio mẫu BẮT BUỘC."""
    model_dir = f5tts_model_var.get().strip()
    if not model_dir:
        log("❌ F5-TTS: Chưa nhập thư mục Model — tiến trình bị hủy")
        log("  • Browse ô Model để chọn thư mục chứa model_last.pt + vocab.txt")
        return False, "", None, None
    if not os.path.isdir(model_dir):
        log(f"❌ F5-TTS: Đường dẫn Model không tồn tại: {model_dir}")
        log("  • Browse lại thư mục model đúng (chứa model_last.pt + vocab.txt)")
        return False, "", None, None

    ref_audio = f5tts_ref_var.get().strip()
    if not ref_audio:
        log("❌ F5-TTS: Chưa chọn file Audio mẫu — F5-TTS bắt buộc cần audio mẫu để nhân bản giọng")
        log("  • Browse ô Audio mẫu để chọn file WAV/MP3 giọng cần nhân bản (5-15s)")
        return False, "", None, None
    if not os.path.isfile(ref_audio):
        log(f"❌ F5-TTS: Không tìm thấy file Audio mẫu: {ref_audio}")
        log("  • Browse lại để chọn đúng file audio mẫu")
        return False, "", None, None

    f5tts_py = _find_f5tts_python(model_dir)
    if not f5tts_py:
        log("❌ F5-TTS: Không tìm thấy f5tts_env\\Scripts\\python.exe — tiến trình bị hủy")
        log("  • Đảm bảo thư mục f5tts_env\\ nằm cạnh app/exe")
        log("  • Có thể cấu hình python tùy chỉnh trong ⚙ Cài đặt → f5tts_env python.exe")
        return False, "", None, None

    helper = _f5tts_find_helper()
    if not helper:
        log("❌ F5-TTS: Không tìm thấy f5tts_helper.py — tiến trình bị hủy")
        log("  • Đảm bảo f5tts_helper.py nằm cùng thư mục với app hoặc exe")
        return False, "", None, None
    return True, model_dir, f5tts_py, helper


def _f5tts_build_cmd(f5tts_py, helper, texts_file, out_dir, model_dir):
    """Dựng lệnh gọi f5tts_helper.py với các tham số UI hiện tại."""
    speed = (f5tts_speed_var.get() or "1.0").strip()
    try:
        float(speed)
    except ValueError:
        speed = "1.0"
    cmd = [f5tts_py, helper,
           '--texts-json', texts_file,
           '--output-dir', out_dir,
           '--model-dir', model_dir,
           '--reference', f5tts_ref_var.get().strip(),
           '--speed', speed,
           '--device', 'auto']
    ref_text = f5tts_reftext_var.get().strip()
    if ref_text:
        cmd += ['--reference-text', ref_text]
    return cmd


def _run_f5tts_batch():
    """Chạy F5-TTS batch generation cho SRT trong daemon thread."""
    global current_index, stop_requested, FAIL_COUNT

    load_subtitles(force_select=False)
    if not subtitles_cache:
        return

    FAIL_COUNT = 0

    ok, model_dir, f5tts_py, helper = _f5tts_preflight()
    if not ok:
        return

    app.after(0, lambda: set_mode("tts_running"))

    items = []
    for i, sub in enumerate(subtitles_cache):
        text = clean_text(sub.content)
        if text and _is_speakable(text):
            items.append({"index": i, "text": text})
        elif text:
            log(f"⏭ Dòng {i}: không có nội dung đọc được — bỏ qua")
    _text_by_idx = {it["index"]: it["text"] for it in items}

    texts_file = os.path.join(OUTPUT_DIR, "_f5tts_texts.json")
    try:
        with open(texts_file, 'w', encoding='utf-8') as f:
            import json as _json
            _json.dump(_glossary_items(items), f, ensure_ascii=False, indent=2)
    except Exception as e:
        log(f"F5-TTS: Lỗi ghi texts file: {e}")
        app.after(0, lambda: set_mode("tts_stopped"))
        return

    total = len(subtitles_cache)
    log(f"F5-TTS: bắt đầu generate {len(items)}/{total} dòng...")

    cmd = _f5tts_build_cmd(f5tts_py, helper, texts_file, OUTPUT_DIR, model_dir)

    try:
        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, encoding='utf-8', errors='replace',
            creationflags=CREATE_NO_WINDOW,
        )
        RUNNING_PROCESSES.append(proc)
    except Exception as e:
        log(f"F5-TTS: Lỗi khởi chạy subprocess: {e}")
        app.after(0, lambda: set_mode("tts_stopped"))
        return

    done_count = 0
    try:
        for line in proc.stdout:
            if stop_requested:
                proc.terminate()
                log("F5-TTS STOPPED")
                app.after(0, lambda: set_mode("tts_stopped"))
                return

            line = line.rstrip()
            if line.startswith("DONE:"):
                try:
                    idx = int(line.split(":")[1])
                except (IndexError, ValueError):
                    continue
                wav_path = os.path.join(OUTPUT_DIR, f"line_{idx:04d}.wav")
                mp3_path = os.path.join(OUTPUT_DIR, f"line_{idx:04d}.mp3")
                if os.path.exists(wav_path):
                    r = subprocess.run(
                        [FFMPEG, "-y", "-i", wav_path, "-q:a", "2", mp3_path],
                        capture_output=True, creationflags=CREATE_NO_WINDOW,
                    )
                    try:
                        os.remove(wav_path)
                    except Exception:
                        pass
                    if r.returncode == 0:
                        _bad, _reason, _detail = _audio_quality_check(
                            mp3_path, _text_by_idx.get(idx, ""))
                        if _bad:
                            _rename_bad_audio(mp3_path, idx, _reason, _detail)
                            FAIL_COUNT += 1
                        else:
                            log(f"OK {idx}")
                    else:
                        log(f"❌ F5-TTS FFMPEG lỗi line {idx}")
                        log(f"FAIL {idx}")
                        FAIL_COUNT += 1
                else:
                    log(f"❌ F5-TTS không tạo được audio dòng {idx}")
                    log(f"FAIL {idx}")
                    FAIL_COUNT += 1
                done_count += 1
                app.after(0, lambda i=done_count, t=len(items): update_progress(i, t))
            elif line.startswith("WARN:"):
                log(f"⚠ F5-TTS {line}")
            elif line.startswith("["):
                log(f"  {line}")
            elif line == "ALL_DONE":
                break
            elif line.startswith("ERROR:"):
                try:
                    _parts = line.split(":", 2)
                    _fail_idx = int(_parts[1])
                    log(f"❌ F5-TTS {line}")
                    log(f"FAIL {_fail_idx}")
                    FAIL_COUNT += 1
                    done_count += 1
                    app.after(0, lambda i=done_count, t=len(items): update_progress(i, t))
                except (IndexError, ValueError):
                    log(f"F5-TTS {line}")
            elif line.strip():
                log(f"  F5-TTS: {line}")
    except Exception as e:
        log(f"F5-TTS stream error: {e}")

    proc.wait()
    try:
        RUNNING_PROCESSES.remove(proc)
    except ValueError:
        pass
    try:
        os.remove(texts_file)
    except Exception:
        pass

    if proc.returncode != 0 and not stop_requested:
        log(f"F5-TTS kết thúc với lỗi (code={proc.returncode})")
        app.after(0, lambda: set_mode("tts_stopped"))
        return

    log("F5-TTS DONE")
    app.after(0, show_fireworks)
    update_progress(total, total)
    current_index = 0
    app.after(0, lambda: set_mode("tts_done"))
    app.after(200, open_output_folder)


