# =========================
# Lồng tiếng theo timeline — khớp khe thời gian, KHÔNG đè giọng
# =========================

# Ép mỗi câu vừa khít khe thời gian của nó để giọng câu này kết thúc
# trước khi câu kế tiếp bắt đầu → không còn đè/chồng giọng.
_DUB_MAX_SPEED = 2.0    # tăng tốc tối đa (giữ độ rõ); câu vẫn dài hơn sẽ được cảnh báo
_DUB_GAP_MS    = 50     # khe hở an toàn giữa 2 câu (ms)
_DUB_CENTER_MAX_S = 0.8 # dịch tối đa khi căn giữa câu ngắn vào khe lặng (giây)
_LINEVOL_TARGET_DB = -20.0  # mean_volume đích khi "Cân âm lượng các dòng" bật
_LINEVOL_MAX_GAIN  = 12.0   # giới hạn ± gain (dB) — tránh khuếch đại file gần câm

# Kết quả phân tích của lần merge gần nhất (wizard lồng tiếng đọc để tổng kết)
_LAST_MERGE_REPORT = {}


def _write_synced_srt(synced_lines):
    """Ghi final_synced.srt — timestamp theo AUDIO THẬT sau merge (đã tính câu
    bị tăng tốc + căn giữa khe lặng). SRT gốc lệch giọng vài trăm ms ở các câu
    đó; dùng file này để burn-in / phát hành kèm video lồng tiếng thì chữ khớp
    tiếng tuyệt đối. Path được ghi vào _LAST_MERGE_REPORT['synced_srt']."""
    try:
        import datetime as _dt
        subs_out = []
        for n, (i, st, du) in enumerate(synced_lines, 1):
            if du <= 0:
                du = 1.5     # probe lỗi → thời lượng an toàn
            subs_out.append(srt.Subtitle(
                index=n,
                start=_dt.timedelta(seconds=st),
                end=_dt.timedelta(seconds=st + du),
                content=clean_text(subtitles_cache[i].content)))
        p = os.path.join(OUTPUT_DIR, "final_synced.srt")
        with open(p, "w", encoding="utf-8") as f:
            f.write(srt.compose(subs_out))
        _LAST_MERGE_REPORT["synced_srt"] = p
        log("📝 SRT khớp audio thật → final_synced.srt")
    except Exception as e:
        log(f"⚠ Không ghi được final_synced.srt: {e}")

# Định dạng output cho Merge FFmpeg: tên file + codec args
_MERGE_FORMATS = {
    "mp3":  ("final.mp3",  '-c:a libmp3lame -q:a 2'),
    "wav":  ("final.wav",  '-c:a pcm_s16le'),
    "m4a":  ("final.m4a",  '-c:a aac -b:a 192k'),
    "opus": ("final.opus", '-c:a libopus -b:a 128k'),
}


def _probe_duration_sec(path):
    """Thời lượng audio (giây) qua ffprobe; 0.0 nếu lỗi."""
    try:
        probe = subprocess.run(
            [FFPROBE, "-v", "error", "-show_entries", "format=duration",
             "-of", "default=noprint_wrappers=1:nokey=1", path],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            text=True, timeout=30, creationflags=CREATE_NO_WINDOW
        )
        return float(probe.stdout.strip())
    except Exception:
        return 0.0


def _probe_mean_volume(path):
    """mean_volume (dB) của file audio qua ffmpeg volumedetect; None nếu lỗi."""
    try:
        r = subprocess.run(
            [get_ffmpeg(), "-i", path, "-af", "volumedetect", "-f", "null", "-"],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=30, creationflags=CREATE_NO_WINDOW)
        m = re.search(r"mean_volume:\s*(-?[\d.]+)\s*dB", r.stderr or "")
        return float(m.group(1)) if m else None
    except Exception:
        return None


def _atempo_chain(factor):
    """Chuỗi filter atempo cho hệ số tốc độ bất kỳ (>1 = nhanh hơn).
    Mỗi tầng atempo chỉ nhận 0.5–2.0 nên phải nối nhiều tầng cho hệ số lớn."""
    if factor <= 0:
        return "atempo=1.0"
    parts = []
    f = float(factor)
    while f > 2.0:
        parts.append("atempo=2.0")
        f /= 2.0
    while f < 0.5:
        parts.append("atempo=0.5")
        f /= 0.5
    parts.append(f"atempo={f:.6f}")
    return ",".join(parts)


def merge_ffmpeg():

    if not subtitles_cache:
        load_subtitles()

    inputs = []
    filters = []
    mixes = []

    real_index = 0
    n_sub   = len(subtitles_cache)
    gap_sec = _DUB_GAP_MS / 1000.0

    stretched = []   # các dòng (1-based) bị tăng tốc cho khớp khe
    overflow  = []   # các dòng vẫn dài hơn khe dù đã tăng tốc tối đa
    centered  = []   # các dòng ngắn được căn giữa khe lặng
    leveled   = []   # các dòng được cân âm lượng về _LINEVOL_TARGET_DB
    synced_lines = []  # (idx, start_s THẬT, duration_s THẬT) → final_synced.srt

    center_on = bool(merge_center_var.get())
    linevol_on = bool(merge_linevol_var.get())
    out_name, codec_args = _MERGE_FORMATS.get(
        merge_format_var.get(), _MERGE_FORMATS["mp3"])

    log("Phân tích thời lượng để khớp timeline (chống đè giọng)...")

    for i, sub in enumerate(subtitles_cache):

        # Dùng tên file tương đối để tránh giới hạn 8191 ký tự của Windows cmd
        rel_name = f"line_{i:04d}.mp3"
        abs_path = os.path.join(OUTPUT_DIR, rel_name)

        if not os.path.exists(abs_path):
            continue

        start_sec = sub.start.total_seconds()
        start_ms  = int(start_sec * 1000)

        # Khe thời gian = tới lúc câu KẾ TIẾP bắt đầu (giữ đúng mốc timeline gốc)
        next_start = None
        if i + 1 < n_sub:
            next_start = subtitles_cache[i + 1].start.total_seconds()

        # Probe MỌI dòng (không chỉ dòng có khe) — cần cho final_synced.srt
        actual = _probe_duration_sec(abs_path)
        factor = 1.0
        if next_start is not None:
            slot = next_start - start_sec
            if slot <= 0:
                # Phụ đề gốc đã chồng mốc thời gian — không nén được
                overflow.append(i + 1)
            else:
                target = max(0.20, slot - gap_sec)
                if actual > target + 0.02:
                    raw = actual / target
                    factor = min(raw, _DUB_MAX_SPEED)
                    stretched.append(i + 1)
                    if raw > _DUB_MAX_SPEED + 1e-3:
                        overflow.append(i + 1)
                elif (center_on and actual > 0
                      and target - actual > 0.3):
                    # Câu ngắn hơn khe nhiều → đẩy vào giữa khe lặng cho
                    # tự nhiên (giới hạn dịch tối đa _DUB_CENTER_MAX_S giây
                    # để không lệch xa mốc phụ đề gốc)
                    start_ms += int(min((target - actual) / 2.0,
                                        _DUB_CENTER_MAX_S) * 1000)
                    centered.append(i + 1)

        # Timing THẬT của câu sau merge (start đã cộng căn giữa, duration đã
        # chia hệ số tăng tốc) — dùng để ghi final_synced.srt
        synced_lines.append((i, start_ms / 1000.0,
                             (actual / factor) if factor > 1.001 else actual))

        inputs.append(f'-i "{rel_name}"')

        # Chuỗi filter từng dòng: [atempo] → [volume cân dòng] → afade ×2 → adelay
        fparts = []
        if factor > 1.001:
            fparts.append(_atempo_chain(factor))
        if linevol_on:
            # Cân mọi dòng về cùng mean_volume — Phân vai trộn nhiều engine/giọng
            # (mỗi cái một âm lượng) không còn chỗ to chỗ nhỏ theo nhân vật.
            _mv = _probe_mean_volume(abs_path)
            if _mv is not None and _mv < -5.0:   # đo được + không phải file lỗi
                _gain = max(-_LINEVOL_MAX_GAIN,
                            min(_LINEVOL_MAX_GAIN, _LINEVOL_TARGET_DB - _mv))
                if abs(_gain) >= 1.0:
                    fparts.append(f"volume={_gain:.1f}dB")
                    leveled.append(i + 1)
        # Fade 30ms đầu/cuối từng dòng — chống tiếng "click/tạch" khi các dòng
        # ghép sát nhau (mp3 cắt giữa waveform ≠ 0). st fade-out tính theo
        # thời lượng SAU atempo. Dòng quá ngắn (<0.15s) bỏ qua.
        _post_dur = (actual / factor) if factor > 1.001 else actual
        if _post_dur and _post_dur > 0.15:
            fparts.append("afade=t=in:st=0:d=0.03")
            fparts.append(f"afade=t=out:st={max(0.0, _post_dur - 0.035):.3f}:d=0.03")
        fparts.append(f"adelay={start_ms}:all=1")
        filters.append(
            f'[{real_index}:a]' + ",".join(fparts) + f'[a{real_index}]'
        )

        mixes.append(f'[a{real_index}]')

        real_index += 1

        if real_index % 50 == 0:
            log(f"  ...đã phân tích {real_index} câu")

    if real_index == 0:
        log("No mp3 files found")
        return

    if stretched:
        log(f"⏩ Đã tăng tốc {len(stretched)} câu cho khớp khe thời gian (chống đè giọng).")
    if centered:
        log(f"🎯 Đã căn giữa {len(centered)} câu ngắn vào khe lặng (tự nhiên hơn).")
    if leveled:
        log(f"🔉 Đã cân âm lượng {len(leveled)} dòng về {_LINEVOL_TARGET_DB:.0f} dB "
            "(đều giọng giữa các dòng/nhân vật).")
    if overflow:
        dedup   = sorted(set(overflow))
        preview = ", ".join(str(x) for x in dedup[:20])
        more    = "" if len(dedup) <= 20 else f" …(+{len(dedup) - 20})"
        log(f"⚠️ {len(dedup)} câu vẫn dài hơn khe dù đã tăng tốc {_DUB_MAX_SPEED}x — "
            f"nên sửa timing/nội dung phụ đề ở các dòng: {preview}{more}")

    # Lưu kết quả phân tích cho báo cáo tổng kết (wizard lồng tiếng)
    _LAST_MERGE_REPORT.clear()
    _LAST_MERGE_REPORT.update({
        "lines": real_index, "total": n_sub,
        "stretched": len(stretched), "centered": len(centered),
        "leveled": len(leveled),
        "overflow": sorted(set(overflow)),
    })

    filter_text = ";\n".join(filters)
    filter_text += (
        f';\n{"".join(mixes)}'
        f'amix=inputs={real_index}:normalize=0'
    )
    if bool(merge_loudnorm_var.get()):
        # Chuẩn hóa loudness final về -16 LUFS (chuẩn YouTube/podcast) — nối
        # thẳng sau amix trong cùng chain nên không cần label trung gian.
        filter_text += ',loudnorm=I=-16:TP=-1.5:LRA=11'
        log("🔊 Loudnorm: chuẩn hóa âm lượng final về -16 LUFS (chuẩn YouTube).")

    filter_path = os.path.join(OUTPUT_DIR, "filter.txt")

    with open(filter_path, "w", encoding="utf-8") as f:
        f.write(filter_text)

    # Ghi lệnh ra .bat và chạy .bat — tránh giới hạn độ dài command line Windows
    bat_cmd = (
        f'"{FFMPEG}" {" ".join(inputs)} '
        f'-filter_complex_script "filter.txt" '
        f'{codec_args} "{out_name}" -y'
    )

    bat_path = os.path.join(OUTPUT_DIR, "run_ffmpeg.bat")

    with open(bat_path, "w", encoding="utf-8") as f:
        f.write(bat_cmd)

    log(f"RUNNING FFMPEG... ({real_index} inputs)")

    # Tổng duration để tính tiến trình (giây)
    total_duration = subtitles_cache[-1].end.total_seconds() if subtitles_cache else 0

    process = subprocess.Popen(
        [bat_path],
        cwd=OUTPUT_DIR,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        encoding="utf-8",
        errors="ignore",
        creationflags=CREATE_NO_WINDOW
    )

    RUNNING_PROCESSES.append(process)

    ffmpeg_output = []

    for line in process.stdout:

        line = line.strip()

        if not line:
            continue

        ffmpeg_output.append(line)

        # Parse time= để cập nhật progress bar
        time_match = re.search(r"time=(\d+):(\d+):(\d+)\.(\d+)", line)
        if time_match and total_duration > 0:
            h, m, s, cs = map(int, time_match.groups())
            current_sec = h * 3600 + m * 60 + s + cs / 100
            update_progress(current_sec, total_duration)

        if (
            "time=" in line
            or "speed=" in line
            or "error" in line.lower()
        ):
            log(line)

    process.wait()

    result_code = process.returncode

    try:
        RUNNING_PROCESSES.remove(process)
    except:
        pass

    if result_code == 0:
        update_progress(1, 1)
        log(f"DONE -> {out_name}")
        _write_synced_srt(synced_lines)
        app.after(0, show_fireworks)
        app.after(200, open_output_folder)
    else:
        log("FFMPEG ERROR")
        log("\n".join(ffmpeg_output[-20:]))


def start_merge():
    threading.Thread(
        target=merge_ffmpeg,
        daemon=True
    ).start()


# =========================
# Open Subtitle Edit
# =========================

def open_subtitle_edit():

    global SRT_FILE

    if not SRT_FILE:
        msg.showerror("Error", "Load SRT first")
        return

    possible_paths = []
    if SUBTITLE_EDIT_PATH:
        possible_paths.append(SUBTITLE_EDIT_PATH)
    possible_paths += [
        "SubtitleEdit.exe",
        r"C:\Program Files\Subtitle Edit\SubtitleEdit.exe",
        r"C:\Program Files (x86)\Subtitle Edit\SubtitleEdit.exe",
    ]

    for exe in possible_paths:

        if os.path.exists(exe):

            log(f"Opening Subtitle Edit: {exe}")

            import ctypes
            ctypes.windll.shell32.ShellExecuteW(
                None, "open", exe, f'"{SRT_FILE}"', None, 1
            )

            return

    msg.showwarning(
        "Subtitle Edit Not Found",
        "Cannot find SubtitleEdit.exe"
    )


# =========================
# Retry Line
# =========================

def _voxcpm_generate_one_sync(index, text, out_prefix="line_"):
    """Tạo 1 dòng bằng VoxCPM → {out_prefix}{index:04d}.mp3 trong OUTPUT_DIR
    (dùng cho regenerate_line / regenerate_pdf_line).
    out_prefix="line_" cho SRT, "pdf_line_" cho PDF.
    Trả về (ok: bool, err: str).
    """
    import json as _json
    ckpt_dir = voxcpm_ckpt_var.get().strip()
    voxcpm_py = _find_voxcpm_python(ckpt_dir) if ckpt_dir else None
    if not voxcpm_py:
        return False, "Không tìm thấy voxcpm_env python"
    helper = None
    for _d in [getattr(sys, "_MEIPASS", None), os.path.dirname(__file__),
               os.path.dirname(sys.argv[0]), os.path.dirname(sys.executable)]:
        if _d and os.path.isfile(os.path.join(_d, "voxcpm_helper.py")):
            helper = os.path.join(_d, "voxcpm_helper.py")
            break
    if not helper:
        return False, "Không tìm thấy voxcpm_helper.py"

    tmp_json = os.path.join(OUTPUT_DIR, f"_regen_vox_{index}.json")
    try:
        with open(tmp_json, "w", encoding="utf-8") as f:
            _json.dump([{"index": index, "text": _apply_glossary(text)}], f, ensure_ascii=False)
        ref_audio = voxcpm_ref_var.get().strip() or None
        ref_text  = voxcpm_reftext_var.get().strip() or None
        cmd = [voxcpm_py, helper, "--texts-json", tmp_json,
               "--output-dir", OUTPUT_DIR, "--ckpt-dir", ckpt_dir,
               "--timesteps", voxcpm_steps_var.get(),
               "--cfg-value", voxcpm_cfg_var.get()]
        if ref_audio:
            cmd += ["--reference", ref_audio]
        if ref_text:
            cmd += ["--reference-text", ref_text]
        proc = subprocess.run(cmd, capture_output=True, text=True,
                              encoding="utf-8", errors="replace",
                              creationflags=CREATE_NO_WINDOW)
    finally:
        try:
            os.remove(tmp_json)
        except Exception:
            pass

    gen_wav = os.path.join(OUTPUT_DIR, f"line_{index:04d}.wav")
    if not os.path.isfile(gen_wav):
        return False, f"VoxCPM không tạo được wav. {(proc.stderr or '')[-200:]}"
    mp3_path = os.path.join(OUTPUT_DIR, f"{out_prefix}{index:04d}.mp3")
    r = subprocess.run([FFMPEG, "-y", "-i", gen_wav, "-q:a", "2", mp3_path],
                       capture_output=True, creationflags=CREATE_NO_WINDOW)
    try:
        os.remove(gen_wav)
    except Exception:
        pass
    if r.returncode != 0 or not os.path.isfile(mp3_path):
        return False, "ffmpeg wav→mp3 lỗi"
    return True, ""


