def _backup_before_regen(filename):
    """Bản hiện có → .old.mp3 trước khi regen ghi đè (TTS không tất định — bản
    mới chưa chắc hay hơn; có .old là có đường lùi). Chỉ kích hoạt ở regen tay:
    casting/QC-regen xóa file trước khi gọi, retry-missing thì file không tồn
    tại → tự khỏi backup. Đuôi .old.mp3 không khớp _QC_BAD_RE / line_NNNN.mp3
    nên không lọt vào QC-scan, missing-scan hay merge."""
    try:
        if os.path.isfile(filename):
            bak = filename[:-4] + ".old.mp3"
            shutil.copy2(filename, bak)
            log(f"💾 Bản cũ → {os.path.basename(bak)} (nghe lại nếu bản mới tệ hơn)")
    except Exception:
        pass


async def regenerate_line(index, text):
    """Tạo lại 1 dòng — áp dụng đầy đủ VoxCPM / RVC + kiểm tra chất lượng (QC)
    + retry giống các luồng generate chính, để dòng regen nhất quán với batch.
    """
    filename = os.path.join(OUTPUT_DIR, f"line_{index:04d}.mp3")
    _backup_before_regen(filename)
    log(f"REGENERATE {index}")
    _loop = asyncio.get_event_loop()

    # ── VoxCPM ────────────────────────────────────────────────────────────────
    if VOXCPM_ENABLED:
        _ck = voxcpm_ckpt_var.get().strip()
        if not _ck or not os.path.isdir(_ck):
            log(f"❌ VoxCPM: thư mục Model trống/không tồn tại — bỏ qua dòng {index}")
            log(f"FAILED {index}")
            return
        _rf = voxcpm_ref_var.get().strip()
        if _rf and not os.path.isfile(_rf):
            log(f"❌ VoxCPM: không tìm thấy Audio mẫu: {_rf}")
            log(f"FAILED {index}")
            return
        _vok, _verr = await _loop.run_in_executor(
            None, _voxcpm_generate_one_sync, index, text)
        if not _vok:
            log(f"❌ VoxCPM regen lỗi: {_verr}")
            log(f"FAILED {index}")
            return
        _bad, _reason, _detail = await _loop.run_in_executor(
            None, _audio_quality_check, filename, text)
        if _bad:
            _rename_bad_audio(filename, index, _reason, _detail, "VoxCPM")
            log(f"FAILED {index}")
        else:
            log(f"DONE {index}")
        return

    # ── VieNeu-TTS ─────────────────────────────────────────────────────────────
    if VIENEU_ENABLED:
        _vok, _verr = await _loop.run_in_executor(
            None, _vieneu_generate_one_sync, index, text)
        if not _vok:
            log(f"❌ VieNeu regen lỗi: {_verr}")
            log(f"FAILED {index}")
            return
        _bad, _reason, _detail = await _loop.run_in_executor(
            None, _audio_quality_check, filename, text)
        if _bad:
            _rename_bad_audio(filename, index, _reason, _detail, "VieNeu")
            log(f"FAILED {index}")
        else:
            log(f"DONE {index}")
        return

    # ── F5-TTS-Vietnamese ──────────────────────────────────────────────────────
    if F5TTS_ENABLED:
        _vok, _verr = await _loop.run_in_executor(
            None, _f5tts_generate_one_sync, index, text)
        if not _vok:
            log(f"❌ F5-TTS regen lỗi: {_verr}")
            log(f"FAILED {index}")
            return
        _bad, _reason, _detail = await _loop.run_in_executor(
            None, _audio_quality_check, filename, text)
        if _bad:
            _rename_bad_audio(filename, index, _reason, _detail, "F5-TTS")
            log(f"FAILED {index}")
        else:
            log(f"DONE {index}")
        return

    # ── OmniVoice Vietnamese ────────────────────────────────────────────────────
    if OMNIVOICE_ENABLED:
        _vok, _verr = await _loop.run_in_executor(
            None, _omnivoice_generate_one_sync, index, text)
        if not _vok:
            log(f"❌ OmniVoice regen lỗi: {_verr}")
            log(f"FAILED {index}")
            return
        _bad, _reason, _detail = await _loop.run_in_executor(
            None, _audio_quality_check, filename, text)
        if _bad:
            _rename_bad_audio(filename, index, _reason, _detail, "OmniVoice")
            log(f"FAILED {index}")
        else:
            log(f"DONE {index}")
        return

    # ── Provider TTS (Edge/FPT/…) + RVC tùy chọn ───────────────────────────────
    if RVC_ENABLED and not _check_rvc_preflight():
        log(f"FAILED {index}")
        return

    ok = False
    _bad = False
    _reason = ""
    _detail = ""
    for _qc_attempt in range(_QC_MAX_RETRIES + 1):
        _gen_text = (_sanitize_tts_text(text)
                     if _qc_attempt == _QC_MAX_RETRIES else text)
        try:
            ok = await save_tts(_gen_text, filename)
        except QuotaExhaustedError as qe:
            log(f"HẾT QUOTA: {qe}")
            log(f"FAILED {index}")
            return
        if not ok:
            break
        _bad, _reason, _detail = await _loop.run_in_executor(
            None, _audio_quality_check, filename, text)
        if not _bad:
            break
        if _qc_attempt < _QC_MAX_RETRIES:
            log(f"  ⚠ Dòng {index}: audio {_reason} ({_detail}) — "
                f"tạo lại lần {_qc_attempt + 1}/{_QC_MAX_RETRIES}")
            try:
                os.remove(filename)
            except Exception:
                pass

    if ok and not _bad:
        if RVC_ENABLED and os.path.exists(filename):
            try:
                log(f"  RVC convert {index}...")
                await _loop.run_in_executor(None, _apply_rvc_sync, filename)
                log(f"  RVC OK")
                _rbad, _rreason, _rdetail = await _loop.run_in_executor(
                    None, _audio_quality_check, filename, text)
                if _rbad:
                    _rename_bad_audio(filename, index, _rreason, _rdetail, "RVC")
                    log(f"FAILED {index}")
                    return
            except Exception as _rvc_err:
                log(f"❌ RVC thất bại tại dòng {index}: {_rvc_err}")
                log(f"FAILED {index}")
                return
        log(f"DONE {index}")
    elif ok and _bad:
        _rename_bad_audio(filename, index, _reason, _detail)
        log(f"FAILED {index}")
    else:
        log(f"FAILED {index}")


