# =========================
# MULTI-VOICE CASTING — gán hồ sơ giọng theo dải dòng SRT
# =========================
# CASTING_RULES: list các {"from":int0based, "to":int0based, "profile":str}
# Dòng nào không khớp rule nào → dùng cấu hình giọng đang chọn trên UI.
CASTING_RULES = []
_MULTIVOICE_RUNNING = [False]

def _casting_sidecar_path():
    """Đường dẫn file luật phân vai đi kèm SRT đang nạp: <tên>.cast.json."""
    if not SRT_FILE:
        return ""
    return os.path.splitext(SRT_FILE)[0] + ".cast.json"


def _casting_sidecar_save():
    """Lưu CASTING_RULES cạnh SRT — công gán vai cả buổi không mất khi đóng app."""
    p = _casting_sidecar_path()
    if not p:
        return
    try:
        if CASTING_RULES:
            with open(p, "w", encoding="utf-8") as f:
                json.dump({"rules": CASTING_RULES}, f, ensure_ascii=False, indent=1)
            log(f"[Phân vai] 💾 Luật đã lưu kèm SRT: {os.path.basename(p)}")
        elif os.path.isfile(p):
            os.remove(p)   # xóa hết luật = xóa luôn sidecar
    except Exception as e:
        log(f"[Phân vai] ⚠ Không lưu được luật kèm SRT: {e}")


def _casting_sidecar_load():
    """Nạp luật phân vai từ sidecar của SRT vừa load (nếu có). Luật cũ trong
    RAM thuộc SRT khác nên bị thay; không có sidecar → giữ nguyên như cũ."""
    p = _casting_sidecar_path()
    if not p or not os.path.isfile(p):
        return
    try:
        with open(p, "r", encoding="utf-8") as f:
            data = json.load(f)
        n = len(subtitles_cache)
        rules = []
        for r in (data.get("rules") or []):
            try:
                a = max(0, min(int(r["from"]), n - 1))
                b = max(0, min(int(r["to"]), n - 1))
                prof = str(r["profile"])
            except (KeyError, ValueError, TypeError):
                continue
            if prof:
                rules.append({"from": min(a, b), "to": max(a, b),
                              "profile": prof})
        if rules:
            CASTING_RULES.clear()
            CASTING_RULES.extend(rules)
            log(f"🎭 Đã nạp {len(rules)} luật phân vai kèm SRT "
                f"({os.path.basename(p)}) — xem/sửa ở nút 🎭 Phân vai.")
    except Exception as e:
        log(f"⚠ Không đọc được luật phân vai kèm SRT: {e}")


def _casting_resolve(idx):
    """Trả về tên hồ sơ cho dòng idx (rule khớp sau cùng thắng), None nếu không có."""
    name = None
    for r in CASTING_RULES:
        if r["from"] <= idx <= r["to"]:
            name = r["profile"]
    return name

def _apply_profile_blocking(profile_name, timeout=15):
    """Áp dụng 1 hồ sơ giọng trên main thread (chờ xong) — gọi từ worker thread."""
    p = _voice_profiles_load().get(profile_name)
    if not p:
        log(f"[Phân vai] ❌ Không tìm thấy hồ sơ: {profile_name}")
        return False
    ev = threading.Event()
    def _do():
        try:
            _voice_profile_apply(p)
        finally:
            ev.set()
    app.after(0, _do)
    if not ev.wait(timeout=timeout):
        # Hết thời gian chờ mà chưa áp dụng xong → KHÔNG chạy tiếp với engine
        # có thể sai, báo lỗi để dòng đó tính là fail thay vì sinh nhầm giọng.
        log(f"[Phân vai] ❌ Quá thời gian áp dụng hồ sơ '{profile_name}' ({timeout}s).")
        return False
    return True

def run_multivoice_batch():
    """Lồng tiếng đa giọng: mỗi dải dòng đọc bằng hồ sơ giọng riêng.
    Gom dòng theo hồ sơ để hạn chế số lần đổi engine, mỗi dòng đi qua
    regenerate_line (engine + QC + retry đầy đủ)."""
    if _MULTIVOICE_RUNNING[0]:
        log("[Phân vai] Đang chạy — vui lòng đợi xong.")
        return
    if not subtitles_cache:
        load_subtitles(force_select=False)
    if not subtitles_cache:
        log("[Phân vai] ❌ Chưa Load SRT.")
        return
    if not CASTING_RULES:
        log("[Phân vai] ❌ Chưa có luật phân vai nào — bấm '🎭 Phân vai' để thêm.")
        return

    total = len(subtitles_cache)
    # idx → profile (None = giọng UI hiện tại). Gom theo profile, giữ thứ tự xuất hiện.
    plan = {}
    order = []
    for idx in range(total):
        prof = _casting_resolve(idx)
        plan.setdefault(prof, []).append(idx)
        if prof not in order:
            order.append(prof)

    def _run():
        _MULTIVOICE_RUNNING[0] = True
        _stopped = False
        app.after(0, lambda: set_mode("tts_running"))
        try:
            done = fail = skipped = 0
            processed = 0
            for prof in order:
                idxs = plan[prof]
                if prof is not None:
                    log(f"[Phân vai] 🎭 Đổi sang hồ sơ '{prof}' cho {len(idxs)} dòng...")
                    if not _apply_profile_blocking(prof):
                        log(f"[Phân vai] ⚠ Bỏ qua {len(idxs)} dòng (hồ sơ lỗi).")
                        fail += len(idxs)
                        processed += len(idxs)
                        update_progress(processed, total)
                        continue
                else:
                    log(f"[Phân vai] 🎙 {len(idxs)} dòng dùng giọng đang chọn trên UI.")
                for idx in idxs:
                    if stop_requested:
                        log("[Phân vai] PROCESS STOPPED")
                        _stopped = True
                        return
                    text = clean_text(subtitles_cache[idx].content)
                    if not text:
                        skipped += 1
                        processed += 1
                        update_progress(processed, total)
                        continue
                    target = os.path.join(OUTPUT_DIR, f"line_{idx:04d}.mp3")
                    try:
                        if os.path.isfile(target):
                            os.remove(target)
                    except Exception:
                        pass
                    try:
                        asyncio.run(regenerate_line(idx, text))
                    except Exception as e:
                        log(f"[Phân vai] ❌ Lỗi dòng {idx}: {e}")
                    if os.path.isfile(target):
                        done += 1
                    else:
                        fail += 1
                    processed += 1
                    update_progress(processed, total)
            log(f"[Phân vai] ━━━ Hoàn tất: {done} OK, {fail} lỗi, "
                f"{skipped} rỗng / {total} dòng ━━━")
            log("[Phân vai] 💡 Bấm 'Merge FFmpeg' để ghép thành final.")
            if done and not fail:
                app.after(0, show_fireworks)
        finally:
            _MULTIVOICE_RUNNING[0] = False
            app.after(0, lambda s=_stopped: set_mode("tts_stopped" if s else "tts_done"))

    threading.Thread(target=_run, daemon=True).start()


# ── 🤖 Tự phân vai bằng LLM ───────────────────────────────────────────────────
# Gửi toàn bộ SRT cho LLM (Claude/Gemini/OpenAI — dùng lại key dịch), nhờ nó nhận
# diện nhân vật nào nói dòng nào rồi gán mỗi nhân vật một HỒ SƠ GIỌNG phù hợp từ
# danh sách hiện có → tự sinh CASTING_RULES. Người dùng xem/sửa lại trước khi chạy.
# Decoupled như nút dịch: tự khóa bằng _AUTOCAST_RUNNING, không đụng set_mode.
_AUTOCAST_RUNNING = [False]
_AUTOCAST_BATCH = 80

def _autocast_build_rules(line_profiles, total):
    """Gộp các dòng liên tiếp cùng hồ sơ thành luật {from,to,profile}.
    Dòng không có hồ sơ → bỏ (dùng giọng UI hiện tại khi chạy)."""
    rules = []
    i = 0
    while i < total:
        prof = line_profiles.get(i)
        if not prof:
            i += 1
            continue
        j = i
        while j + 1 < total and line_profiles.get(j + 1) == prof:
            j += 1
        rules.append({"from": i, "to": j, "profile": prof})
        i = j + 1
    return rules

def _autocast_extract_json(raw):
    """Trích object JSON đầu tiên trong text LLM trả về (bỏ rào ```json)."""
    m = re.search(r"\{.*\}", raw or "", re.DOTALL)
    if not m:
        raise ValueError("Không tìm thấy JSON trong kết quả LLM.")
    return json.loads(m.group(0))

_AUTOCAST_SYS = (
    "Bạn là trợ lý phân vai lồng tiếng phim. Với một đoạn phụ đề (mỗi dòng có số "
    "thứ tự dạng [n]), hãy xác định NHÂN VẬT đang nói ở mỗi dòng, rồi gán cho mỗi "
    "nhân vật MỘT hồ sơ giọng phù hợp nhất chọn TRONG danh sách cho sẵn (suy luận "
    "giới tính/độ tuổi từ tên hồ sơ). Chỉ trả về JSON thuần, không giải thích.")

def _auto_cast_worker(provider, api_key, model, lines, profiles):
    speakers = {}        # tên nhân vật → tên hồ sơ
    line_profiles = {}   # idx → tên hồ sơ
    total = len(lines)
    try:
        for start in range(0, total, _AUTOCAST_BATCH):
            if not _AUTOCAST_RUNNING[0]:
                break
            chunk = lines[start:start + _AUTOCAST_BATCH]
            # Phân vai lai: kèm giới tính đo từ ÂM THANH (🚻) nếu đã chạy —
            # LLM tách nhân vật, âm thanh giữ cho đúng giới.
            numbered = "\n".join(
                f"[{start + k}"
                + (f"|{_GENDER_HINTS[start + k]}" if (start + k) in _GENDER_HINTS else "")
                + f"] {t}"
                for k, t in enumerate(chunk) if t)
            known = json.dumps(speakers, ensure_ascii=False)
            user = (
                "Danh sách hồ sơ giọng (chỉ chọn trong danh sách này): "
                + json.dumps(profiles, ensure_ascii=False) + "\n"
                "Nhân vật đã gán giọng ở phần trước (GIỮ NGUYÊN, tái dùng): "
                + known + "\n\nPhụ đề:\n" + numbered + "\n\n"
                "Trả về JSON đúng định dạng:\n"
                '{ "speakers": { "<tên nhân vật>": "<tên hồ sơ trong danh sách>" }, '
                '"lines": { "<số dòng>": "<tên nhân vật>" } }\n'
                '- "speakers" gồm mọi nhân vật xuất hiện ở đoạn này.\n'
                '- "lines" gán mỗi số dòng cho đúng một tên nhân vật.\n'
                '- Lời dẫn/độc thoại không rõ người nói → nhân vật "Người kể".\n'
                '- Một số dòng có kèm GIỚI TÍNH đo từ âm thanh gốc, dạng '
                '[số|nam] hoặc [số|nữ] — hãy dựa vào đó: dòng |nam phải thuộc '
                'nhân vật nam (hồ sơ giọng nam) và ngược lại.')
            try:
                raw = _llm_call(provider, api_key, model, _AUTOCAST_SYS, user)
                obj = _autocast_extract_json(raw)
            except Exception as e:
                log(f"🤖 ⚠ Bỏ qua đoạn dòng {start}: {e}")
                continue
            for name, prof in (obj.get("speakers") or {}).items():
                if prof in profiles:
                    speakers[name] = prof
            for k, name in (obj.get("lines") or {}).items():
                try:
                    idx = int(k)
                except (ValueError, TypeError):
                    continue
                prof = speakers.get(name)
                if prof in profiles:
                    line_profiles[idx] = prof
            done = min(start + _AUTOCAST_BATCH, total)
            update_progress(done, total)
        rules = _autocast_build_rules(line_profiles, total)
        n_sp = len(speakers)
        n_ln = len(line_profiles)
        app.after(0, lambda: _autocast_apply(rules, n_sp, n_ln))
    except Exception as e:
        app.after(0, lambda e=e: log(f"❌ Tự phân vai thất bại: {e}"))
    finally:
        _AUTOCAST_RUNNING[0] = False

def _autocast_apply(rules, n_speakers, n_lines):
    if not rules:
        log("🤖 [Tự phân vai] LLM không gán được dòng nào cho hồ sơ hiện có. "
            "Thử đặt tên hồ sơ gợi ý giới tính/tuổi (vd: nam_tre, nu_gia).")
        return
    CASTING_RULES.clear()
    CASTING_RULES.extend(rules)
    log(f"🤖 [Tự phân vai] Đã tạo {len(rules)} luật từ {n_speakers} nhân vật "
        f"({n_lines} dòng được gán). Xem/sửa lại rồi bấm '🎬 Lưu & Chạy'.")
    open_casting_dialog()

def start_auto_cast():
    """Khởi động tự phân vai (gọi từ nút trong dialog phân vai)."""
    if _AUTOCAST_RUNNING[0] or _MULTIVOICE_RUNNING[0]:
        log("[Tự phân vai] Đang chạy — vui lòng đợi xong.")
        return
    if not subtitles_cache:
        load_subtitles(force_select=False)
    if not subtitles_cache:
        msg.showinfo("Tự phân vai", "Hãy Load SRT trước.")
        return
    profiles = sorted(_voice_profiles_load().keys())
    if len(profiles) < 2:
        msg.showinfo("Tự phân vai",
                     "Cần ít nhất 2 hồ sơ giọng để phân vai. Tạo thêm ở tab "
                     "Giọng nói → '💾 Lưu giọng hiện tại'.")
        return
    try:
        provider, api_key, model = _translate_active_key()
    except Exception as e:
        msg.showerror("Tự phân vai", str(e))
        return
    lines = [clean_text(s.content) for s in subtitles_cache]
    _AUTOCAST_RUNNING[0] = True
    update_progress(0, len(lines))
    log(f"🤖 [Tự phân vai] Phân tích {len(lines)} dòng bằng {provider} "
        f"({model})... (có thể mất chút thời gian với SRT dài)")
    if _GENDER_HINTS:
        log(f"🤖 [Tự phân vai] 🚻 Dùng {len(_GENDER_HINTS)} hint giới tính từ lần "
            "đo âm thanh — nhân vật sẽ được gán đúng giới. (Chạy 🚻 trước 🤖 = "
            "phân vai chính xác nhất.)")
    threading.Thread(target=_auto_cast_worker,
                     args=(provider, api_key, model, lines, profiles),
                     daemon=True).start()

def open_casting_dialog():
    """Cửa sổ quản lý luật phân vai: từ dòng – đến dòng – hồ sơ giọng."""
    if not subtitles_cache:
        msg.showinfo("Phân vai", "Hãy Load SRT trước để biết tổng số dòng.")
        return
    profiles = sorted(_voice_profiles_load().keys())
    if not profiles:
        msg.showinfo("Phân vai",
                     "Chưa có hồ sơ giọng nào. Vào tab Giọng nói → cấu hình → "
                     "'💾 Lưu giọng hiện tại' để tạo hồ sơ trước.")
        return
    total = len(subtitles_cache)
    win = ctk.CTkToplevel(app)
    win.title("🎭 Phân vai đa giọng (Multi-voice)")
    win.geometry("560x520")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    ctk.CTkLabel(win, text=f"SRT đang nạp: {total} dòng (đánh số 0..{total-1})",
                 font=("Arial", 13, "bold")).pack(pady=(10, 2))
    ctk.CTkLabel(win, text="Mỗi luật: từ dòng – đến dòng (gồm cả hai) → hồ sơ giọng.\n"
                           "Dòng không thuộc luật nào sẽ dùng giọng đang chọn trên tab Giọng nói.",
                 font=("Arial", 11), justify="left").pack(pady=(0, 6))

    rows_frame = ctk.CTkScrollableFrame(win, height=300)
    rows_frame.pack(fill="both", expand=True, padx=10, pady=4)
    _rule_widgets = []

    def _add_rule_row(frm=0, to=0, profile=None):
        row = ctk.CTkFrame(rows_frame, fg_color="transparent")
        row.pack(fill="x", pady=3)
        ctk.CTkLabel(row, text="Từ", font=("Arial", 12)).pack(side="left", padx=(2, 2))
        v_from = ctk.StringVar(value=str(frm))
        ctk.CTkEntry(row, textvariable=v_from, width=60).pack(side="left", padx=(0, 6))
        ctk.CTkLabel(row, text="Đến", font=("Arial", 12)).pack(side="left", padx=(0, 2))
        v_to = ctk.StringVar(value=str(to))
        ctk.CTkEntry(row, textvariable=v_to, width=60).pack(side="left", padx=(0, 6))
        v_prof = ctk.StringVar(value=profile or profiles[0])
        ctk.CTkOptionMenu(row, variable=v_prof, values=profiles, width=170).pack(side="left", padx=(0, 6))
        def _del():
            row.destroy()
            _rule_widgets.remove(entry)
        ctk.CTkButton(row, text="✕", width=30, fg_color="#8a3344",
                      hover_color="#a04055", command=_del).pack(side="left")
        entry = (v_from, v_to, v_prof)
        _rule_widgets.append(entry)

    # Nạp lại các luật đã có
    for r in CASTING_RULES:
        _add_rule_row(r["from"], r["to"], r["profile"])
    if not CASTING_RULES:
        _add_rule_row(0, max(0, total - 1), profiles[0])

    btn_row = ctk.CTkFrame(win, fg_color="transparent")
    btn_row.pack(fill="x", padx=10, pady=(4, 8))
    ctk.CTkButton(btn_row, text="➕ Thêm luật", command=lambda: _add_rule_row(0, 0, profiles[0]),
                  width=120).pack(side="left", padx=4)

    def _auto_cast_click():
        win.destroy()
        start_auto_cast()
    ctk.CTkButton(btn_row, text="🤖 Tự phân vai (AI)", command=_auto_cast_click,
                  fg_color="#7c5cff", hover_color="#8f72ff", width=160).pack(side="left", padx=4)

    def _save_rules():
        new_rules = []
        for v_from, v_to, v_prof in _rule_widgets:
            try:
                a = int(v_from.get()); b = int(v_to.get())
            except ValueError:
                continue
            a = max(0, min(a, total - 1))
            b = max(0, min(b, total - 1))
            if a > b:
                a, b = b, a
            new_rules.append({"from": a, "to": b, "profile": v_prof.get()})
        CASTING_RULES.clear()
        CASTING_RULES.extend(new_rules)
        log(f"[Phân vai] Đã lưu {len(new_rules)} luật phân vai.")
        _casting_sidecar_save()   # đi kèm SRT — mở lại app không mất
        return new_rules

    def _save_and_close():
        _save_rules()
        win.destroy()

    def _save_and_run():
        _save_rules()
        win.destroy()
        run_multivoice_batch()

    ctk.CTkButton(btn_row, text="💾 Lưu", command=_save_and_close, width=100).pack(side="left", padx=4)
    ctk.CTkButton(btn_row, text="🎬 Lưu & Chạy lồng tiếng", command=_save_and_run,
                  fg_color="#2fa572", hover_color="#37b87f", width=190).pack(side="left", padx=4)

    btn_row2 = ctk.CTkFrame(win, fg_color="transparent")
    btn_row2.pack(fill="x", padx=10, pady=(0, 8))
    def _gender_cast_click():
        win.destroy()
        open_gender_cast_dialog()
    ctk.CTkButton(btn_row2, text="🚻 Tự phân vai Nam/Nữ theo âm thanh gốc (video/audio)",
                  command=_gender_cast_click, fg_color="#3f6ea5",
                  hover_color="#4f83bf").pack(side="left", padx=4, fill="x", expand=True)


# ── 🚻 Phân vai nam/nữ theo ÂM THANH GỐC ─────────────────────────────────────
# Đo cao độ giọng (F0) từng dòng trên audio gốc của video theo timestamp SRT
# (ffmpeg extract PCM 8kHz + autocorrelation thuần Python — không thêm dep),
# rồi PHÂN CỤM TƯƠNG ĐỐI trong chính video đó (cụm F0 thấp = nam, cao = nữ)
# thay vì ngưỡng Hz tuyệt đối — giọng nam cao / nữ trầm vẫn tách đúng miễn là
# video có cả hai giới. Dòng có F0 sát biên 2 cụm (±12% điểm giữa) kế thừa vai
# của dòng gán được gần trước đó (tính liên tục hội thoại). Đã kiểm chứng bằng
# Edge TTS nam/nữ VN + EN (2026-07-02): VN 4/4 đúng, gộp cả EN 7/8.
# Decoupled như nút Dịch: tự khóa _GENDERCAST_RUNNING, không đụng set_mode.
_GENDERCAST_RUNNING = [False]
# idx0 → "nam"/"nữ" từ lần đo F0 gần nhất — 🤖 Tự phân vai (AI) dùng làm hint
# để LLM gán nhân vật đúng giới ("phân vai lai"). Xóa khi load SRT khác.
_GENDER_HINTS = {}


def _f0_extract_pcm(ffmpeg, media, start_s, dur_s, sr=8000):
    """PCM s16 mono sr Hz của đoạn [start, start+dur] trong media → list int."""
    import struct as _struct
    try:
        proc = subprocess.run(
            [ffmpeg, "-v", "quiet", "-ss", f"{start_s:.3f}", "-t", f"{dur_s:.3f}",
             "-i", media, "-vn", "-ac", "1", "-ar", str(sr), "-f", "s16le", "-"],
            capture_output=True, timeout=30, creationflags=CREATE_NO_WINDOW)
        raw = proc.stdout
        n = len(raw) // 2
        return list(_struct.unpack(f"<{n}h", raw[:n * 2])) if n else []
    except Exception:
        return []


def _f0_frame(samples, sr, lo_hz=60, hi_hz=350):
    """F0 một frame bằng autocorrelation chuẩn hóa → (f0|None, độ_tin)."""
    n = len(samples)
    if n < 200:
        return None, 0.0
    mean = sum(samples) / n
    x = [s - mean for s in samples]
    e0 = sum(v * v for v in x)
    if e0 < 1e-6:
        return None, 0.0
    lag_min = max(2, int(sr / hi_hz))
    lag_max = min(n - 2, int(sr / lo_hz))
    best_lag, best_r = None, 0.0
    for lag in range(lag_min, lag_max):
        num = 0.0
        e1 = 0.0
        for i in range(n - lag):
            num += x[i] * x[i + lag]
            e1 += x[i + lag] * x[i + lag]
        if e1 < 1e-6:
            continue
        r = num / ((e0 * e1) ** 0.5)
        if r > best_r:
            best_r, best_lag = r, lag
    if best_lag is None or best_r < 0.55:
        return None, best_r
    return sr / best_lag, best_r


def _f0_of_segment(samples, sr=8000):
    """Median F0 (Hz) qua ≤12 frame voiced rải giữa đoạn; None nếu không đo được
    (nhạc nền/im lặng). Bỏ frame min/max khi đủ mẫu để chặn lỗi bắt nhầm bội âm."""
    n = len(samples)
    flen = int(sr * 0.045)
    if n < flen * 2:
        return None
    f0s = []
    for k in range(12):
        pos = int(n * (0.1 + 0.8 * k / 11))
        if pos + flen > n:
            break
        f0, _r = _f0_frame(samples[pos:pos + flen], sr)
        if f0:
            f0s.append(f0)
    if len(f0s) < 2:
        return None
    f0s.sort()
    if len(f0s) >= 5:
        f0s = f0s[1:-1]
    return f0s[len(f0s) // 2]


def _f0_cluster2(vals):
    """2-means 1 chiều (sắp xếp + chọn điểm cắt tối thiểu SSE) → (tâm_thấp, tâm_cao)."""
    v = sorted(vals)
    best = None
    for cut in range(1, len(v)):
        a, b = v[:cut], v[cut:]
        ma, mb = sum(a) / len(a), sum(b) / len(b)
        sse = sum((x - ma) ** 2 for x in a) + sum((x - mb) ** 2 for x in b)
        if best is None or sse < best[0]:
            best = (sse, ma, mb)
    return best[1], best[2]


def _gender_cast_worker(media, prof_nam, prof_nu, segs, total):
    """segs: [(idx, start_s, dur_s)] đã chụp trên main thread."""
    try:
        ffmpeg = get_ffmpeg()
        f0map = {}
        for k, (idx, start_s, dur_s) in enumerate(segs):
            if not _GENDERCAST_RUNNING[0]:
                app.after(0, lambda: log("[Nam/Nữ] Đã dừng."))
                return
            pcm = _f0_extract_pcm(ffmpeg, media, start_s, dur_s)
            f0 = _f0_of_segment(pcm)
            if f0:
                f0map[idx] = f0
            update_progress(k + 1, len(segs))
        if len(f0map) < 6:
            app.after(0, lambda: log(
                f"[Nam/Nữ] ❌ Chỉ đo được cao độ giọng ở {len(f0map)} dòng — audio "
                "quá nhiễu/nhạc nền to, không đủ dữ liệu phân cụm."))
            return
        lo, hi = _f0_cluster2(list(f0map.values()))
        if hi - lo < 30:
            app.after(0, lambda: log(
                f"[Nam/Nữ] ❌ Hai cụm cao độ quá gần nhau ({lo:.0f}Hz / {hi:.0f}Hz) — "
                "có vẻ video chỉ có MỘT giọng, không phân nam/nữ được."))
            return
        mid = (lo + hi) / 2
        band = 0.12 * mid
        line_profiles = {}
        last = None
        n_sure = n_inherit = 0
        for idx, _s, _d in segs:
            f0 = f0map.get(idx)
            if f0 is None:
                continue   # không đo được → giữ giọng UI hiện tại
            if f0 < mid - band:
                prof = prof_nam; n_sure += 1
            elif f0 > mid + band:
                prof = prof_nu; n_sure += 1
            elif last:
                prof = last; n_inherit += 1   # sát biên → kế thừa dòng trước
            else:
                prof = prof_nam if abs(f0 - lo) < abs(f0 - hi) else prof_nu
                n_sure += 1
            line_profiles[idx] = prof
            last = prof
        rules = _autocast_build_rules(line_profiles, total)
        n_nam = sum(1 for p in line_profiles.values() if p == prof_nam)
        n_nu = len(line_profiles) - n_nam
        # Lưu hint giới tính cho 🤖 Tự phân vai (AI) — "phân vai lai"
        _GENDER_HINTS.clear()
        _GENDER_HINTS.update({i: ("nam" if p == prof_nam else "nữ")
                              for i, p in line_profiles.items()})

        def _apply():
            CASTING_RULES.clear()
            CASTING_RULES.extend(rules)
            log(f"🚻 [Nam/Nữ] Cụm giọng: nam ~{lo:.0f}Hz / nữ ~{hi:.0f}Hz. "
                f"Gán {n_nam} dòng nam, {n_nu} dòng nữ ({n_inherit} dòng sát biên "
                f"kế thừa dòng trước) → {len(rules)} luật. Xem/sửa rồi bấm "
                "'🎬 Lưu & Chạy'.")
            open_casting_dialog()
        app.after(0, _apply)
    except Exception as e:
        app.after(0, lambda e=e: log(f"[Nam/Nữ] ❌ Lỗi: {e}"))
    finally:
        _GENDERCAST_RUNNING[0] = False


def open_gender_cast_dialog():
    """Dialog: chọn file video/audio gốc + hồ sơ giọng nam + hồ sơ giọng nữ."""
    if _GENDERCAST_RUNNING[0]:
        log("[Nam/Nữ] Đang chạy — vui lòng đợi xong.")
        return
    if not subtitles_cache:
        msg.showinfo("Phân vai Nam/Nữ", "Hãy Load SRT trước.")
        return
    profiles = sorted(_voice_profiles_load().keys())
    if len(profiles) < 2:
        msg.showinfo("Phân vai Nam/Nữ",
                     "Cần ít nhất 2 hồ sơ giọng (1 nam + 1 nữ). Tạo ở tab "
                     "Giọng nói → '💾 Lưu giọng hiện tại'.")
        return
    win = ctk.CTkToplevel(app)
    win.title("🚻 Phân vai Nam/Nữ theo âm thanh gốc")
    win.geometry("620x280")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    ctk.CTkLabel(win, text="Đo cao độ giọng từng dòng trên audio GỐC của video theo "
                           "timestamp SRT,\nrồi tự gán hồ sơ giọng nam/nữ. "
                           "SRT phải khớp thời gian với file này.",
                 font=("Arial", 12), justify="left").pack(pady=(12, 6))

    row1 = ctk.CTkFrame(win, fg_color="transparent")
    row1.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row1, text="Video/Audio gốc:", font=("Arial", 12), width=120,
                 anchor="w").pack(side="left")
    v_media = ctk.StringVar(value=MUX_VIDEO_FILE or "")
    ctk.CTkEntry(row1, textvariable=v_media).pack(side="left", expand=True,
                                                  fill="x", padx=(0, 6))
    def _browse():
        p = filedialog.askopenfilename(
            title="Chọn video/audio gốc",
            filetypes=[("Video/Audio", "*.mp4 *.mkv *.avi *.webm *.mov *.mp3 *.wav *.m4a *.aac *.flac"),
                       ("All files", "*.*")])
        if p:
            v_media.set(p)
    ctk.CTkButton(row1, text="Browse", width=80, command=_browse).pack(side="left")

    row2 = ctk.CTkFrame(win, fg_color="transparent")
    row2.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row2, text="Giọng NAM:", font=("Arial", 12), width=120,
                 anchor="w").pack(side="left")
    _nam_guess = next((p for p in profiles if "nam" in p.lower()), profiles[0])
    v_nam = ctk.StringVar(value=_nam_guess)
    ctk.CTkOptionMenu(row2, variable=v_nam, values=profiles, width=220).pack(side="left")

    row3 = ctk.CTkFrame(win, fg_color="transparent")
    row3.pack(fill="x", padx=14, pady=4)
    ctk.CTkLabel(row3, text="Giọng NỮ:", font=("Arial", 12), width=120,
                 anchor="w").pack(side="left")
    _nu_guess = next((p for p in profiles if ("nu" in p.lower() or "nữ" in p.lower())
                      and p != _nam_guess),
                     profiles[1] if profiles[1] != _nam_guess else profiles[0])
    v_nu = ctk.StringVar(value=_nu_guess)
    ctk.CTkOptionMenu(row3, variable=v_nu, values=profiles, width=220).pack(side="left")

    def _run():
        media = v_media.get().strip()
        if not media or not os.path.isfile(media):
            msg.showerror("Phân vai Nam/Nữ", "Chưa chọn file video/audio hợp lệ.")
            return
        if v_nam.get() == v_nu.get():
            msg.showerror("Phân vai Nam/Nữ", "Hồ sơ nam và nữ phải khác nhau.")
            return
        ffmpeg_ok, _p, guide = _check_ffmpeg_exists()
        if not ffmpeg_ok:
            for line in guide.splitlines():
                log(line)
            return
        # chụp segment trên main thread (subtitles_cache có thể bị load lại)
        segs = []
        n = len(subtitles_cache)
        for i, sub in enumerate(subtitles_cache):
            if not clean_text(sub.content):
                continue
            start_s = sub.start.total_seconds()
            end_s = sub.end.total_seconds()
            if i + 1 < n:
                end_s = min(end_s, subtitles_cache[i + 1].start.total_seconds())
            dur = min(max(end_s - start_s, 0.0), 4.0)
            if dur < 0.25:
                continue
            segs.append((i, start_s, dur))
        if not segs:
            msg.showerror("Phân vai Nam/Nữ", "SRT không có dòng nào đủ dài để đo.")
            return
        _GENDERCAST_RUNNING[0] = True
        update_progress(0, len(segs))
        log(f"🚻 [Nam/Nữ] Đo cao độ giọng {len(segs)} dòng trên "
            f"{os.path.basename(media)}… (~{max(1, len(segs) // 240)} phút)")
        threading.Thread(target=_gender_cast_worker,
                         args=(media, v_nam.get(), v_nu.get(), segs, n),
                         daemon=True).start()
        win.destroy()

    row4 = ctk.CTkFrame(win, fg_color="transparent")
    row4.pack(fill="x", padx=14, pady=(10, 8))
    ctk.CTkButton(row4, text="🚻 Phân tích & gán vai", command=_run,
                  fg_color="#2fa572", hover_color="#37b87f",
                  height=36).pack(side="left", expand=True, fill="x", padx=4)
    ctk.CTkButton(row4, text="Đóng", command=win.destroy, width=90,
                  height=36).pack(side="left", padx=4)


def ask_pdf_chunk_edit():
    """Hỏi số đoạn PDF (0-based, phân tách bằng dấu phẩy) rồi tạo lại từng đoạn."""
    if not PDF_CHUNKS:
        msg.showerror("Error", "Chưa load PDF — không có đoạn nào để tạo lại.")
        return

    if FAIL_COUNT > 1:
        prompt = (f"Nhập số đoạn PDF cần tạo lại (cách nhau bằng dấu phẩy, vd: 0,5,12)\n"
                  f"Có {FAIL_COUNT} đoạn lỗi.\nTổng: {len(PDF_CHUNKS)} đoạn (0..{len(PDF_CHUNKS)-1}).")
    else:
        prompt = (f"Nhập số đoạn PDF cần tạo lại (cách nhau bằng dấu phẩy, vd: 0,5,12)\n"
                  f"Tổng: {len(PDF_CHUNKS)} đoạn (0..{len(PDF_CHUNKS)-1}).")

    dialog = ctk.CTkInputDialog(text=prompt, title="Regenerate đoạn PDF")
    value = dialog.get_input()
    if not value:
        return

    try:
        indices = []
        for part in value.split(","):
            part = part.strip()
            if part == "":
                continue
            indices.append(int(part))
        if not indices:
            msg.showerror("Error", "Không có số đoạn hợp lệ.")
            return
        invalid = [i for i in indices if i < 0 or i >= len(PDF_CHUNKS)]
        if invalid:
            msg.showerror("Error", f"Đoạn ngoài phạm vi: {', '.join(map(str, invalid))}")
            return

        def run_all():
            for index in indices:
                text = PDF_CHUNKS[index].strip()
                if not text:
                    log(f"[PDF] Đoạn {index} rỗng — bỏ qua")
                    continue
                asyncio.run(regenerate_pdf_line(index, text))

        threading.Thread(target=run_all, daemon=True).start()
    except ValueError:
        msg.showerror("Error", "Nhập sai. Dùng các số cách nhau bằng dấu phẩy.")


def open_editor(index):

    if index >= len(subtitles_cache):
        return

    sub = subtitles_cache[index]

    win = ctk.CTkToplevel(app)
    win.geometry("800x400")
    win.title(f"Edit Line {index}")

    label = ctk.CTkLabel(
        win,
        text=f"Editing subtitle line {index}",
        font=("Arial", 18, "bold")
    )

    label.pack(pady=10)

    textbox = ctk.CTkTextbox(win)
    textbox.pack(fill="both", expand=True, padx=10, pady=10)
    _attach_telex_input(textbox, quick_tts_telex_var)

    textbox.insert("1.0", sub.content)

    def save_and_regen():

        new_text = textbox.get("1.0", "end").strip()

        subtitles_cache[index].content = new_text

        with open(SRT_FILE, "w", encoding="utf-8") as f:
            f.write(srt.compose(subtitles_cache))

        load_subtitles()

        threading.Thread(
            target=lambda: asyncio.run(
                regenerate_line(index, clean_text(new_text))
            ),
            daemon=True
        ).start()

        win.destroy()

    btn = ctk.CTkButton(
        win,
        text="Save + Regenerate",
        command=save_and_regen,
        height=40
    )

    btn.pack(pady=10)


def ask_line_edit():

    if FAIL_COUNT > 1:
        prompt = f"Enter subtitle line numbers (comma-separated, e.g. 3,7,12)\n{FAIL_COUNT} failed lines detected."
    else:
        prompt = "Enter subtitle line number"

    dialog = ctk.CTkInputDialog(
        text=prompt,
        title="Regenerate Line"
    )

    value = dialog.get_input()

    if not value:
        return

    try:
        raw_parts = value.split(",")
        indices = []

        for part in raw_parts:
            part = part.strip()
            if part == "":
                continue
            idx = int(part)
            indices.append(idx)

        if not indices:
            msg.showerror("Error", "No valid line numbers entered")
            return

        load_subtitles(force_select=False)

        invalid = [i for i in indices if i >= len(subtitles_cache)]
        if invalid:
            msg.showerror("Error", f"Line(s) out of range: {', '.join(map(str, invalid))}")
            return

        def run_all():
            for index in indices:
                text = clean_text(subtitles_cache[index].content)
                asyncio.run(regenerate_line(index, text))

        threading.Thread(target=run_all, daemon=True).start()

    except:
        msg.showerror("Error", "Invalid input. Use numbers separated by commas.")


# ── 🎲 Gen 3 take, chọn 1 ────────────────────────────────────────────────────
# TTS không tất định — cùng text mỗi lần ra một kiểu đọc. Thay vì regen mò
# nhiều lần, sinh 3 bản một lượt (đi qua regenerate_line = full engine + QC),
# nghe A/B/C rồi chọn bản ưng nhất làm line_NNNN.mp3. Bản gốc (nếu có) được
# _backup_before_regen giữ ở .old.mp3 — đóng dialog không chọn gì thì khôi
# phục lại từ đó. File take đặt tên line_NNNN.takeK.mp3 (như .old.mp3: không
# khớp _QC_BAD_RE / missing-scan / merge nên vô hình với mọi scan).
# Pattern nút Dịch: tự khóa _TAKE_RUNNING, không đụng set_mode.
_TAKE_RUNNING = [False]
_TAKE_N = 3


def open_take_dialog():
    if _TAKE_RUNNING[0]:
        log("[3 take] Đang chạy — vui lòng đợi xong.")
        return
    if not subtitles_cache:
        load_subtitles(force_select=False)
    if not subtitles_cache:
        msg.showinfo("🎲 Gen 3 take", "Hãy Load SRT trước.")
        return
    if not OUTPUT_DIR or not os.path.isdir(OUTPUT_DIR):
        msg.showinfo("🎲 Gen 3 take", "Hãy chọn Output Folder trước.")
        return
    dialog = ctk.CTkInputDialog(
        text=f"Nhập số dòng cần gen 3 take (0..{len(subtitles_cache) - 1})",
        title="🎲 Gen 3 take")
    value = dialog.get_input()
    if not value:
        return
    try:
        index = int(value.strip())
    except (ValueError, TypeError):
        msg.showerror("🎲 Gen 3 take", "Số dòng không hợp lệ.")
        return
    if not (0 <= index < len(subtitles_cache)):
        msg.showerror("🎲 Gen 3 take", f"Dòng ngoài phạm vi 0..{len(subtitles_cache) - 1}.")
        return
    text = clean_text(subtitles_cache[index].content)
    if not text:
        msg.showinfo("🎲 Gen 3 take", "Dòng này không có nội dung đọc được.")
        return

    target = os.path.join(OUTPUT_DIR, f"line_{index:04d}.mp3")
    old_bak = target[:-4] + ".old.mp3"

    def _take_path(k):
        return os.path.join(OUTPUT_DIR, f"line_{index:04d}.take{k}.mp3")

    state = {"cancel": False, "chosen": False}

    win = ctk.CTkToplevel(app)
    win.title(f"🎲 Chọn take — dòng {index}")
    win.geometry("560x300")
    win.transient(app); win.lift(); win.attributes("-topmost", True)
    win.after(300, lambda: win.attributes("-topmost", False))

    _txt_show = text if len(text) <= 90 else text[:88] + "…"
    ctk.CTkLabel(win, text=f"Dòng {index}: {_txt_show}", font=("Arial", 12),
                 wraplength=520, justify="left").pack(pady=(12, 2), padx=14, anchor="w")
    ctk.CTkLabel(win, text="Mỗi take là một lần đọc khác nhau của cùng giọng đang cấu hình. "
                           "Nghe rồi bấm ✔ để giữ bản ưng nhất.",
                 font=("Arial", 11), text_color="#888",
                 wraplength=520, justify="left").pack(pady=(0, 8), padx=14, anchor="w")

    _stats = {}
    _btns = {}
    for k in range(1, _TAKE_N + 1):
        row = ctk.CTkFrame(win, fg_color="transparent")
        row.pack(fill="x", padx=14, pady=3)
        ctk.CTkLabel(row, text=f"Take {k}:", font=("Arial", 12, "bold"),
                     width=60, anchor="w").pack(side="left")
        _stats[k] = ctk.CTkLabel(row, text="… chờ", font=("Arial", 12),
                                 anchor="w")
        _stats[k].pack(side="left", expand=True, fill="x")
        b_play = ctk.CTkButton(row, text="▶", width=40, state="disabled",
                               command=lambda k=k: _play_audio_file(_take_path(k)))
        b_play.pack(side="left", padx=3)
        b_pick = ctk.CTkButton(row, text="✔ Chọn", width=80, state="disabled",
                               fg_color="#2fa572", hover_color="#37b87f",
                               command=lambda k=k: _choose(k))
        b_pick.pack(side="left", padx=3)
        _btns[k] = (b_play, b_pick)

    def _set_stat(k, s):
        try:
            _stats[k].configure(text=s)
        except Exception:
            pass

    def _take_done(k):
        _set_stat(k, "✅ sẵn sàng")
        try:
            _btns[k][0].configure(state="normal")
            _btns[k][1].configure(state="normal")
        except Exception:
            pass

    def _cleanup_takes():
        _qt_preview_close()   # nhả file MCI đang giữ trước khi xóa
        for j in range(1, _TAKE_N + 1):
            try:
                os.remove(_take_path(j))
            except Exception:
                pass

    def _choose(k):
        if _TAKE_RUNNING[0]:
            msg.showinfo("🎲 Gen 3 take", "Đợi gen xong cả 3 take rồi hãy chọn.")
            return
        if not os.path.isfile(_take_path(k)):
            return
        _qt_preview_close()
        try:
            shutil.copy2(_take_path(k), target)
        except Exception as e:
            msg.showerror("🎲 Gen 3 take", f"Không ghi được file: {e}")
            return
        state["chosen"] = True
        _cleanup_takes()
        log(f"🎲 [3 take] Dòng {index}: đã chọn take {k} → {os.path.basename(target)}")
        win.destroy()

    def _on_close():
        state["cancel"] = True
        if not _TAKE_RUNNING[0]:
            if not state["chosen"]:
                _cleanup_takes()
                # khôi phục bản gốc từ .old nếu regen đã lấy mất file
                if not os.path.isfile(target) and os.path.isfile(old_bak):
                    try:
                        shutil.copy2(old_bak, target)
                        log(f"🎲 [3 take] Không chọn take nào — khôi phục bản cũ dòng {index}.")
                    except Exception:
                        pass
        win.destroy()
    win.protocol("WM_DELETE_WINDOW", _on_close)

    def _worker():
        try:
            for k in range(1, _TAKE_N + 1):
                if state["cancel"]:
                    break
                app.after(0, lambda k=k: _set_stat(k, "⏳ đang tạo…"))
                try:
                    asyncio.run(regenerate_line(index, text))
                except Exception as e:
                    app.after(0, lambda k=k, e=e: _set_stat(k, f"❌ {e}"))
                    continue
                if os.path.isfile(target):
                    try:
                        if os.path.isfile(_take_path(k)):
                            os.remove(_take_path(k))
                        os.replace(target, _take_path(k))
                        app.after(0, lambda k=k: _take_done(k))
                    except Exception as e:
                        app.after(0, lambda k=k, e=e: _set_stat(k, f"❌ {e}"))
                else:
                    app.after(0, lambda k=k: _set_stat(k, "❌ FAIL (xem log)"))
        finally:
            _TAKE_RUNNING[0] = False

            def _after_run():
                if state["cancel"] and not state["chosen"]:
                    _cleanup_takes()
                    if not os.path.isfile(target) and os.path.isfile(old_bak):
                        try:
                            shutil.copy2(old_bak, target)
                            log(f"🎲 [3 take] Đã hủy — khôi phục bản cũ dòng {index}.")
                        except Exception:
                            pass
            app.after(0, _after_run)

    _TAKE_RUNNING[0] = True
    log(f"🎲 [3 take] Dòng {index}: tạo {_TAKE_N} bản đọc… "
        "(engine local sẽ chậm — mỗi take một lần chạy model)")
    threading.Thread(target=_worker, daemon=True).start()


# =========================
# Edit Studio
# =========================

def open_edit_studio():
    """Cửa sổ Edit Studio: load SRT + video + audio, click sub → seek video.
    Video playback uses ffmpeg raw-frame pipe → PIL → Canvas (no -wid dependency).
    Audio uses a separate ffplay -nodisp subprocess.
    """
    try:
        from PIL import ImageTk as _ITk
    except ImportError:
        msg.showerror("Edit Studio", "Pillow/ImageTk not available.")
        return

    win = ctk.CTkToplevel(app)
    win.title("Edit Studio")
    win.geometry("1300x780")
    win.configure(fg_color="#0d1117")
    win.lift()
    win.focus_force()
    win.attributes("-topmost", True)   # luôn nổi trên các cửa sổ khác
    # CTkToplevel đôi khi reset topmost sau khi khởi tạo → ép lại sau 200ms
    win.after(200, lambda: win.winfo_exists() and win.attributes("-topmost", True))

    # ── palette ───────────────────────────────────────────────────────────────
    DARK     = "#0d1117"
    PANEL    = "#161b22"
    ACCENT   = "#1f6feb"
    ROW_ODD  = "#161b22"
    ROW_EVEN = "#0d1117"
    ROW_SEL  = "#1f3a6e"
    TEXT     = "#e6edf3"
    TEXT_DIM = "#8b949e"

    # ── mutable state ─────────────────────────────────────────────────────────
    es = {
        'srt_path'    : SRT_FILE,
        'video_path'  : None,
        'audio_dir'   : OUTPUT_DIR,
        'audio_file'  : None,     # file audio dài đầy đủ đã nạp (vd final.mp3)
        'subtitles'   : list(subtitles_cache),
        'audio_files' : [],
        'audio_proc'  : None,
        'panel_mode'  : 'subs',
        'cur_sub'     : -1,
        'cur_aud'     : -1,       # audio row đang phát theo playhead
        'aud_meta'    : [],       # song song _aud_rows: (start_sec, end_sec, fpath)
        'm_loaded'    : {},       # alias → audio_idx đã preload sẵn (MCI open)
        'm_active'    : None,     # alias overlay đang phát
        'audio_master': None,     # alias dùng làm master clock (vị trí phát thật)
        'master_ms'   : -1,       # vị trí phát hiện tại (ms) do audio thread cập nhật
        'master_wall' : 0.0,      # time.time() lúc lấy master_ms (để nội suy)
        'audio_wav'   : None,     # WAV tiếng gốc video (trích 1 lần khi load)
        'wav_ready'   : False,
        'ticker_id'   : None,
        'duration'    : 0.0,
        # render state
        'render_proc'   : None,
        'render_active' : False,
        'seek_offset'   : 0.0,
        'play_start'    : None,
        'playing'       : False,
        'frame_w'       : 0,
        'frame_h'       : 0,
        'photo_ref'     : None,   # prevent GC
        'gen'           : 0,      # generation token — invalidates stale reader threads
        'fps'           : 25.0,
        '_tmp_wav'      : None,
        # ── playlist phát từng file nối tiếp (Load nhiều Audio) ──
        'seq_files'        : [],     # [(name, path), ...]
        'seq_idx'          : -1,     # file đang phát
        'seq_active'       : False,  # đang trong chế độ playlist
        'seq_seen_playing' : False,  # đã thấy MCI 'playing' cho file hiện tại
        'seq_len'          : 0,      # độ dài file hiện tại (ms)
        '_seq_mode'        : False,  # đang ở chế độ playlist (UI)
        '_seq_was_active'  : False,  # theo dõi để phát hiện kết thúc playlist
        '_seq_shown_idx'   : -2,     # idx đã hiển thị status
    }

    # ── helpers ───────────────────────────────────────────────────────────────
    def _fmt(s):
        s = max(0.0, float(s))
        h, rem = divmod(int(s), 3600)
        m, sec = divmod(rem, 60)
        return f"{h}:{m:02d}:{sec:02d}" if h else f"{m:02d}:{sec:02d}"

    def _td(td):
        return td.total_seconds()

    def _cur_pos():
        # ưu tiên vị trí phát thật của audio (master clock), nội suy cho mượt
        if es['playing']:
            mm = es['master_ms']
            if mm >= 0 and es.get('audio_master'):
                p = mm / 1000.0
                mw = es.get('master_wall')
                if mw:
                    p += (time.time() - mw)
                return p
            if es['play_start'] is not None:
                return es['seek_offset'] + (time.time() - es['play_start'])
        return es['seek_offset']

    # ── TOP TOOLBAR ───────────────────────────────────────────────────────────
    toolbar = tk.Frame(win, bg=PANEL, height=46)
    toolbar.pack(fill="x", side="top")

    def _tb(text, cmd):
        b = tk.Button(toolbar, text=text, command=cmd,
                      bg="#21262d", fg=TEXT, activebackground=ACCENT,
                      activeforeground="white", relief="flat",
                      padx=12, pady=7, cursor="hand2", font=("Arial", 11))
        b.pack(side="left", padx=4, pady=6)
        return b

    _tb("📂 Load SRT",         lambda: _load_srt())
    _tb("🎬 Load Video",        lambda: _load_video())
    _tb("🎵 Load Audio Folder", lambda: _load_audio_folder())
    _tb("🎧 Load Audio File",   lambda: _load_audio_file())
    _tb("🎶 Load nhiều Audio",  lambda: _load_audio_seq())

    status_var = tk.StringVar(value="Chưa load file nào")
    status_lbl = tk.Label(toolbar, textvariable=status_var, bg=PANEL, fg=TEXT_DIM,
                          font=("Arial", 11))
    status_lbl.pack(side="left", padx=14)

    _status_blink_id = [None]   # after-id của blink đang chạy (để cancel khi có status mới)

    def _set_status(text, error=False):
        """Set status text; error=True → vàng blink 5s, bình thường → xám."""
        # Hủy blink cũ nếu đang chạy
        if _status_blink_id[0]:
            try:
                win.after_cancel(_status_blink_id[0])
            except Exception:
                pass
            _status_blink_id[0] = None

        status_var.set(text)
        status_lbl.config(fg="#ffdd00" if error else TEXT_DIM)

        if error:
            def _blink(n=0):
                if not win.winfo_exists():
                    return
                status_lbl.config(fg="#ffffff" if n % 2 == 1 else "#ffdd00")
                if n < 16:   # 17 bước × 300ms ≈ 5.1s
                    _status_blink_id[0] = win.after(300, lambda: _blink(n + 1))
                else:
                    status_lbl.config(fg="#ffdd00")   # kết thúc ở vàng
                    _status_blink_id[0] = None
            _blink()

    # ── MAIN PANED AREA ───────────────────────────────────────────────────────
    paned = tk.PanedWindow(win, orient="horizontal", bg=DARK,
                           sashwidth=5, sashrelief="flat", bd=0)
    paned.pack(fill="both", expand=True)

    # ── LEFT: list panel ──────────────────────────────────────────────────────
    left_outer = tk.Frame(paned, bg=PANEL, width=430)
    paned.add(left_outer, minsize=280, stretch="never")

    tbar = tk.Frame(left_outer, bg="#21262d")
    tbar.pack(fill="x")

    btn_tab_subs = tk.Button(tbar, text="📄 Subtitles",
                             bg=ACCENT, fg="white", relief="flat",
                             padx=10, pady=7, cursor="hand2",
                             font=("Arial", 11, "bold"))
    btn_tab_subs.pack(side="left", fill="x", expand=True)

    btn_tab_audio = tk.Button(tbar, text="🎵 Audio Files",
                              bg="#21262d", fg=TEXT_DIM, relief="flat",
                              padx=10, pady=7, cursor="hand2",
                              font=("Arial", 11))
    btn_tab_audio.pack(side="left", fill="x", expand=True)

    list_outer = tk.Frame(left_outer, bg=PANEL)
    list_outer.pack(fill="both", expand=True)

    lcanvas = tk.Canvas(list_outer, bg=PANEL, highlightthickness=0)
    lscroll = tk.Scrollbar(list_outer, orient="vertical", command=lcanvas.yview)
    lcanvas.configure(yscrollcommand=lscroll.set)
    lscroll.pack(side="right", fill="y")
    lcanvas.pack(side="left", fill="both", expand=True)

    inner = tk.Frame(lcanvas, bg=PANEL)
    _iwin = lcanvas.create_window((0, 0), window=inner, anchor="nw")
    inner.bind("<Configure>",
               lambda e: lcanvas.configure(scrollregion=lcanvas.bbox("all")))
    lcanvas.bind("<Configure>",
                 lambda e: lcanvas.itemconfig(_iwin, width=lcanvas.winfo_width()))
    lcanvas.bind("<MouseWheel>",
                 lambda e: lcanvas.yview_scroll(-1 * (e.delta // 120), "units"))

    _sub_rows = []
    _aud_rows = []

    def _clear_list():
        for w in inner.winfo_children():
            w.destroy()
        _sub_rows.clear()
        _aud_rows.clear()

    def _build_subs():
        _clear_list()
        for i, sub in enumerate(es['subtitles']):
            bg = ROW_ODD if i % 2 else ROW_EVEN
            row = tk.Frame(inner, bg=bg, cursor="hand2")
            row.pack(fill="x", pady=1)
            ts = f"{_fmt(_td(sub.start))} → {_fmt(_td(sub.end))}"
            tk.Label(row, text=f"{sub.index:>3}",
                     bg=bg, fg=TEXT_DIM, font=("Consolas", 10), width=4,
                     anchor="e").pack(side="left", padx=(4, 2))
            tk.Label(row, text=ts, bg=bg, fg="#58a6ff",
                     font=("Consolas", 9)).pack(side="left", padx=(0, 6))
            txt = sub.content.replace("\n", " ")
            if len(txt) > 58:
                txt = txt[:55] + "…"
            lbl = tk.Label(row, text=txt, bg=bg, fg=TEXT,
                           font=("Arial", 10), anchor="w")
            lbl.pack(side="left", fill="x", expand=True, padx=(0, 4))

            def _click(e, idx=i, s=sub):
                seek_to(_td(s.start))
                _hl_sub(idx)

            row.bind("<Button-1>", _click)
            lbl.bind("<Button-1>", _click)
            for child in row.winfo_children():
                child.bind("<Button-1>", _click)
            _sub_rows.append(row)

    def _build_audio():
        # Chế độ playlist (Load nhiều Audio): hiện danh sách file + nút ▶,
        # bấm ▶ phát nối tiếp từ file đó.
        if es.get('_seq_mode') and es.get('seq_files'):
            _build_seq_list()
            return
        _clear_list()
        es['aud_meta'] = []
        es['cur_aud']  = -1
        for i, (fname, fpath) in enumerate(es['audio_files']):
            bg = ROW_ODD if i % 2 else ROW_EVEN
            row = tk.Frame(inner, bg=bg, cursor="hand2")
            row.pack(fill="x", pady=1)
            sub_s = None
            m = re.match(r"line_(\d+)\.mp3$", fname, re.IGNORECASE)
            if m:
                idx = int(m.group(1))
                if idx < len(es['subtitles']):
                    sub_s = es['subtitles'][idx]
            # lưu khung thời gian để playhead-follow ánh xạ pos → audio row
            if sub_s is not None:
                es['aud_meta'].append((_td(sub_s.start), _td(sub_s.end), fpath))
            else:
                es['aud_meta'].append((None, None, fpath))
            ts_txt = _fmt(_td(sub_s.start)) if sub_s else ""
            tk.Label(row, text=fname, bg=bg, fg=TEXT,
                     font=("Consolas", 10), anchor="w"
                     ).pack(side="left", fill="x", expand=True, padx=(6, 4))
            if ts_txt:
                tk.Label(row, text=ts_txt, bg=bg, fg=TEXT_DIM,
                         font=("Consolas", 9)).pack(side="left", padx=4)

            def _play_btn(p=fpath, s=sub_s):
                _play_audio(p, s)

            tk.Button(row, text="▶", command=_play_btn,
                      bg="#21262d", fg="#2ecc71", relief="flat",
                      padx=8, pady=2, cursor="hand2",
                      font=("Arial", 11, "bold")
                      ).pack(side="right", padx=4, pady=2)

            def _row_click(e, p=fpath, s=sub_s):
                _play_audio(p, s)

            row.bind("<Button-1>", _row_click)
            for child in row.winfo_children():
                if isinstance(child, tk.Label):
                    child.bind("<Button-1>", _row_click)
            _aud_rows.append(row)

    def _build_seq_list():
        """Danh sách playlist: mỗi dòng = tên file + nút ▶ (phát nối tiếp từ đó)."""
        _clear_list()
        es['aud_meta'] = []
        for i, (fname, fpath) in enumerate(es['seq_files']):
            bg = ROW_ODD if i % 2 else ROW_EVEN
            row = tk.Frame(inner, bg=bg, cursor="hand2")
            row.pack(fill="x", pady=1)
            tk.Label(row, text=fname, bg=bg, fg=TEXT,
                     font=("Consolas", 10), anchor="w"
                     ).pack(side="left", fill="x", expand=True, padx=(6, 4))

            def _play_btn(idx=i):
                _seq_play_from(idx)

            tk.Button(row, text="▶", command=_play_btn,
                      bg="#21262d", fg="#2ecc71", relief="flat",
                      padx=8, pady=2, cursor="hand2",
                      font=("Arial", 11, "bold")
                      ).pack(side="right", padx=4, pady=2)

            def _row_click(e, idx=i):
                _seq_play_from(idx)

            row.bind("<Button-1>", _row_click)
            for child in row.winfo_children():
                if isinstance(child, tk.Label):
                    child.bind("<Button-1>", _row_click)
            _aud_rows.append(row)
        # tô sáng file đang phát (nếu có)
        if 0 <= es.get('seq_idx', -1) < len(_aud_rows):
            _hl_audio(es['seq_idx'])

    def _hl_sub(idx):
        es['cur_sub'] = idx
        for i, row in enumerate(_sub_rows):
            bg = ROW_SEL if i == idx else (ROW_ODD if i % 2 else ROW_EVEN)
            row.configure(bg=bg)
            for w in row.winfo_children():
                try:
                    w.configure(bg=bg)
                except Exception:
                    pass
        if 0 <= idx < len(_sub_rows):
            _sub_rows[idx].update_idletasks()
            y     = _sub_rows[idx].winfo_y()
            ch    = lcanvas.winfo_height()
            total = inner.winfo_height()
            if total > 0:
                lcanvas.yview_moveto(max(0.0, (y - ch / 2) / total))

    def _hl_audio(idx):
        for i, row in enumerate(_aud_rows):
            bg = ROW_SEL if i == idx else (ROW_ODD if i % 2 else ROW_EVEN)
            row.configure(bg=bg)
            for w in row.winfo_children():
                try:
                    if not isinstance(w, tk.Button):   # giữ nguyên nền nút ▶
                        w.configure(bg=bg)
                except Exception:
                    pass
        if 0 <= idx < len(_aud_rows):
            _aud_rows[idx].update_idletasks()
            y     = _aud_rows[idx].winfo_y()
            ch    = lcanvas.winfo_height()
            total = inner.winfo_height()
            if total > 0:
                lcanvas.yview_moveto(max(0.0, (y - ch / 2) / total))

    def _set_tab(mode):
        es['panel_mode'] = mode
        if mode == 'subs':
            btn_tab_subs.configure(bg=ACCENT,    fg="white",  font=("Arial", 11, "bold"))
            btn_tab_audio.configure(bg="#21262d", fg=TEXT_DIM, font=("Arial", 11))
            _build_subs()
        else:
            btn_tab_subs.configure(bg="#21262d", fg=TEXT_DIM, font=("Arial", 11))
            btn_tab_audio.configure(bg=ACCENT,   fg="white",  font=("Arial", 11, "bold"))
            _build_audio()

    btn_tab_subs.configure(command=lambda: _set_tab('subs'))
    btn_tab_audio.configure(command=lambda: _set_tab('audio'))

    # ── RIGHT: video canvas + controls ────────────────────────────────────────
    right_outer = tk.Frame(paned, bg=DARK)
    paned.add(right_outer, stretch="always")

    # Canvas where ffmpeg frames are drawn via PIL
    vcanvas = tk.Canvas(right_outer, bg="black", highlightthickness=0)
    vcanvas.pack(fill="both", expand=True, padx=4, pady=(4, 0))

    no_video_lbl = tk.Label(vcanvas,
                            text="🎬  Load Video để xem ở đây\n\nClick dòng sub hoặc audio để seek",
                            bg="black", fg="#3d444d",
                            font=("Arial", 14), justify="center")
    no_video_lbl.place(relx=0.5, rely=0.5, anchor="center")

    cbar = tk.Frame(right_outer, bg=PANEL, height=52)
    cbar.pack(fill="x", side="bottom")

    def _cb(text, cmd, fg_c=TEXT):
        b = tk.Button(cbar, text=text, command=cmd,
                      bg="#21262d", fg=fg_c, activebackground=ACCENT,
                      activeforeground="white", relief="flat",
                      padx=10, pady=8, cursor="hand2", font=("Arial", 12))
        b.pack(side="left", padx=3, pady=6)
        return b

    _cb("◀◀ -10s", lambda: seek_to(_cur_pos() - 10))
    btn_pp = _cb("▶  Play", lambda: _toggle_play(), fg_c="#2ecc71")
    _cb("▶▶ +10s", lambda: seek_to(_cur_pos() + 10))
    _cb("⏹ Stop",  lambda: _stop_video(), fg_c="#ff5555")

    time_var = tk.StringVar(value="00:00 / --:--")
    tk.Label(cbar, textvariable=time_var, bg=PANEL, fg=TEXT_DIM,
             font=("Consolas", 11)).pack(side="left", padx=14)

    # ── VIDEO RENDER (ffmpeg pipe → PIL → Canvas) ─────────────────────────────
    # ── MCI audio engine (Windows winmm.dll) ─────────────────────────────────
    # Native Windows audio routing → works with Nahimic / NVIDIA virtual audio
    # and the user's default playback device (ffplay/SDL fails on these setups).
    import ctypes as _ct
    import winsound as _ws
    import queue as _queue
    _mci = _ct.windll.winmm.mciSendStringW
    # QUAN TRỌNG: MCI có "thread affinity" — thiết bị mở bởi thread nào, khi thread
    # đó kết thúc sẽ tự đóng. Nên TẤT CẢ lệnh MCI phải chạy trên MỘT thread duy
    # nhất tồn tại suốt vòng đời cửa sổ (_audio_loop), nhận lệnh qua queue.
    # _ALIAS_V = tiếng gốc video (WAV, master clock); _M_ALIASES = 2 alias overlay
    # mp3 ping-pong để preload trước (mở sẵn) → đổi dòng tức thì không trễ.
    _ALIAS_V   = "es_aud_v"
    _M_ALIASES = ["es_aud_m0", "es_aud_m1"]
    _ALIAS_SEQ = "es_aud_seq"   # playlist: phát từng file nối tiếp
    es['audio_q']   = _queue.Queue()
    es['audio_run'] = True

    def _mci_send(cmd):
        return _mci(cmd, None, 0, 0)

    def _mci_status_ms(alias):
        buf = _ct.create_unicode_buffer(128)
        if _mci(f'status {alias} position', buf, 128, 0) == 0:
            try:
                return int(buf.value.strip())
            except Exception:
                return -1
        return -1

    def _mci_mode(alias):
        buf = _ct.create_unicode_buffer(128)
        if _mci(f'status {alias} mode', buf, 128, 0) == 0:
            return buf.value.strip().lower()
        return ""

    def _mci_len_ms(alias):
        buf = _ct.create_unicode_buffer(128)
        if _mci(f'status {alias} length', buf, 128, 0) == 0:
            try:
                return int(buf.value.strip())
            except Exception:
                return 0
        return 0

    def _open_alias(alias, path, mtype=None):
        # mp3 cần 'type mpegvideo'; wav mở thẳng (waveaudio) — MCI không mở được mp4
        _mci_send(f'close {alias}')
        cmd = (f'open "{path}" type {mtype} alias {alias}' if mtype
               else f'open "{path}" alias {alias}')
        if _mci_send(cmd) != 0:
            return False
        _mci_send(f'set {alias} time format milliseconds')
        return True

    # ── Handlers (CHỈ chạy trong _audio_loop) ─────────────────────────────────
    def _h_stop_all():
        for al in [_ALIAS_V, _ALIAS_SEQ] + _M_ALIASES:
            _mci_send(f'stop {al}')
            _mci_send(f'close {al}')
        es['m_loaded']     = {}
        es['m_active']     = None
        es['audio_master'] = None
        es['master_ms']    = -1
        es['_v_open']      = None
        try:
            _ws.PlaySound(None, _ws.SND_PURGE)
        except Exception:
            pass

    def _h_video_audio(pos_sec):
        wav = es.get('audio_wav')
        if wav and os.path.exists(wav):
            if es.get('_v_open') != wav:
                if _open_alias(_ALIAS_V, wav):
                    es['_v_open'] = wav
                else:
                    es['_v_open'] = None
            if es.get('_v_open'):
                _mci_send(f'play {_ALIAS_V} from {int(pos_sec * 1000)}')
                es['audio_master'] = _ALIAS_V
                es['master_ms']    = int(pos_sec * 1000)
                return
        es['audio_master'] = None
        es['master_ms']    = -1

    def _h_preload(idx):
        if not (0 <= idx < len(es['aud_meta'])) or es['aud_meta'][idx][0] is None:
            return
        if idx in es['m_loaded'].values():
            return
        free = next((al for al in _M_ALIASES if al != es['m_active']), _M_ALIASES[0])
        es['m_loaded'].pop(free, None)
        if _open_alias(free, es['aud_meta'][idx][2], mtype="mpegvideo"):
            es['m_loaded'][free] = idx

    def _h_overlay(idx):
        if not (0 <= idx < len(es['aud_meta'])) or es['aud_meta'][idx][0] is None:
            return
        target = next((al for al, li in es['m_loaded'].items() if li == idx), None)
        if target is None:
            target = next((al for al in _M_ALIASES if al != es['m_active']),
                          _M_ALIASES[0])
            es['m_loaded'].pop(target, None)
            if not _open_alias(target, es['aud_meta'][idx][2], mtype="mpegvideo"):
                return
            es['m_loaded'][target] = idx
        prev = es['m_active']
        if prev and prev != target:
            _mci_send(f'stop {prev}')
        es['m_active'] = target
        _mci_send(f'play {target} from 0')

    def _h_seq_play(idx):
        """Mở + phát file thứ idx trong playlist (phát từng file nối tiếp)."""
        if not (0 <= idx < len(es['seq_files'])):
            es['seq_active'] = False
            es['audio_master'] = None
            es['master_ms'] = -1
            return
        # đóng mọi alias khác để chỉ phát playlist
        for al in [_ALIAS_V, _ALIAS_SEQ] + _M_ALIASES:
            _mci_send(f'stop {al}')
            _mci_send(f'close {al}')
        path = es['seq_files'][idx][1]
        ext = os.path.splitext(path)[1].lower()
        mtype = None if ext == ".wav" else "mpegvideo"
        if not _open_alias(_ALIAS_SEQ, path, mtype):
            # mở lỗi → thử file kế tiếp
            es['seq_idx'] = idx
            if idx + 1 < len(es['seq_files']):
                _h_seq_play(idx + 1)
            else:
                es['seq_active'] = False
                es['audio_master'] = None
            return
        es['seq_len'] = _mci_len_ms(_ALIAS_SEQ)
        _mci_send(f'play {_ALIAS_SEQ} from 0')
        es['seq_idx']          = idx
        es['seq_active']       = True
        es['seq_seen_playing'] = False
        es['audio_master']     = _ALIAS_SEQ
        es['master_ms']        = 0
        es['master_wall']      = time.time()
        es['duration']         = es['seq_len'] / 1000.0 if es['seq_len'] else 0.0

    def _h_seq_pause():
        if es.get('seq_active'):
            _mci_send(f'pause {_ALIAS_SEQ}')

    def _h_seq_resume():
        if es.get('seq_active'):
            if _mci_send(f'resume {_ALIAS_SEQ}') != 0:
                _mci_send(f'play {_ALIAS_SEQ}')
            es['master_wall'] = time.time()

    def _h_seq_stop():
        es['seq_active'] = False
        _mci_send(f'stop {_ALIAS_SEQ}')
        _mci_send(f'close {_ALIAS_SEQ}')
        es['audio_master'] = None
        es['master_ms'] = -1

    def _audio_loop():
        while es['audio_run']:
            cmd = None
            try:
                cmd = es['audio_q'].get(timeout=0.03)
            except _queue.Empty:
                pass
            if cmd:
                try:
                    op = cmd[0]
                    if   op == 'video_audio': _h_video_audio(cmd[1])
                    elif op == 'overlay':     _h_overlay(cmd[1])
                    elif op == 'preload':     _h_preload(cmd[1])
                    elif op == 'stop_all':    _h_stop_all()
                    elif op == 'seq_play':    _h_seq_play(cmd[1])
                    elif op == 'seq_pause':   _h_seq_pause()
                    elif op == 'seq_resume':  _h_seq_resume()
                    elif op == 'seq_stop':    _h_seq_stop()
                except Exception:
                    pass
            am = es['audio_master']
            if am:
                ms = _mci_status_ms(am)
                if ms >= 0:
                    es['master_ms']   = ms
                    es['master_wall'] = time.time()
                # Playlist: tự nhảy sang file kế khi file hiện tại phát xong
                if es.get('seq_active') and am == _ALIAS_SEQ:
                    mode = _mci_mode(am)
                    if mode == 'playing':
                        es['seq_seen_playing'] = True
                    elif mode == 'stopped' and es.get('seq_seen_playing'):
                        nxt = es['seq_idx'] + 1
                        if nxt < len(es['seq_files']):
                            _h_seq_play(nxt)            # phát ngay file kế
                        else:
                            es['seq_active'] = False    # hết playlist
                            _mci_send(f'close {_ALIAS_SEQ}')
                            es['audio_master'] = None
                            es['master_ms'] = -1
        _h_stop_all()   # thread thoát → đóng mọi thiết bị (dừng tiếng ngay)

    threading.Thread(target=_audio_loop, daemon=True).start()

    # ── Wrappers (gọi từ main/worker thread) — chỉ đẩy lệnh vào queue ─────────
    def _stop_audio():
        es['audio_q'].put(('stop_all',))

    def _play_video_audio(pos_sec):
        es['audio_q'].put(('video_audio', pos_sec))

    def _play_overlay(idx):
        es['audio_q'].put(('overlay', idx))

    def _preload_overlay(idx):
        es['audio_q'].put(('preload', idx))

    def _seq_play(idx):
        es['audio_q'].put(('seq_play', idx))

    def _seq_pause():
        es['audio_q'].put(('seq_pause',))

    def _seq_resume():
        es['audio_q'].put(('seq_resume',))

    def _seq_stop():
        es['audio_q'].put(('seq_stop',))

    def _exit_seq_mode():
        """Thoát chế độ playlist (khi chuyển sang Load Video/Audio File/Folder/SRT)."""
        if es.get('_seq_mode') or es.get('seq_active'):
            _seq_stop()
        es['_seq_mode']  = False
        es['seq_active'] = False

    def _seq_play_from(idx):
        """Phát playlist bắt đầu từ file thứ idx (bấm ▶ ở 1 dòng)."""
        if not es.get('seq_files'):
            return
        es['_seq_mode']       = True
        es['playing']         = True
        es['_seq_was_active'] = True
        es['_seq_shown_idx']  = -2
        btn_pp.configure(text="⏸ Pause")
        _seq_play(idx)

    def _stop_render():
        """Invalidate the current playback generation and kill ffmpeg."""
        es['gen'] += 1                  # any running reader thread is now stale
        es['render_active'] = False
        proc = es['render_proc']
        if proc:
            try:
                proc.stdout.close()
            except Exception:
                pass
            try:
                proc.kill()
            except Exception:
                pass
        es['render_proc'] = None
        es['playing']     = False
        es['play_start']  = None

    def _read_exact(proc, n):
        buf = bytearray()
        while len(buf) < n:
            chunk = proc.stdout.read(n - len(buf))
            if not chunk:
                break
            buf += chunk
        return bytes(buf)

    def _seek_audio_only(pos):
        """Phát file audio dài (audio_wav) như track chính khi KHÔNG có video.
        Dùng cho 'Load Audio File' (vd final.mp3): click phụ đề → nhảy tới
        đúng mốc thời gian, play/pause chạy trên chính track này."""
        if not (es.get('audio_wav') and es.get('wav_ready')):
            return
        pos = max(0.0, float(pos))
        _stop_render()
        _stop_audio()
        es['seek_offset'] = pos
        es['play_start']  = time.time()
        es['master_ms']   = -1
        es['playing']     = True
        btn_pp.configure(text="⏸ Pause")
        _play_video_audio(pos)   # mở audio_wav (waveaudio) làm master clock

    def seek_to(pos, overlay_idx=None):
        """Seek video frames to `pos` (sec) and play synced audio.
        Luôn phát tiếng gốc video tại `pos`. Nếu `overlay_idx` ≥ 0 thì phát thêm
        mp3 của dòng đó (trộn cùng lúc) — dùng cho click ▶ ở tab Audio.
        Audio là master clock; frame được pace theo wall-time để khớp.
        Toàn bộ việc nặng chạy trong worker thread (UI không đơ).
        """
        if not es['video_path']:
            # Không có video nhưng đã nạp file audio dài → phát audio-only
            _seek_audio_only(pos)
            return
        pos = max(0.0, float(pos))

        # tear down previous playback (bumps gen → old reader thread exits)
        _stop_render()
        _stop_audio()
        my_gen = es['gen']

        vcanvas.update_idletasks()
        W = max(vcanvas.winfo_width(),  640)
        H = max(vcanvas.winfo_height(), 360)
        es['frame_w'] = W
        es['frame_h'] = H
        fps = es['fps']
        frame_size = W * H * 3

        # mark playing immediately so the ticker/clock update
        es['seek_offset']   = pos
        es['play_start']    = time.time()
        es['master_ms']     = -1     # tránh đọc vị trí cũ → fallback wall-clock đến khi audio mới báo
        es['playing']       = True
        es['render_active'] = True
        btn_pp.configure(text="⏸ Pause")
        no_video_lbl.place_forget()

        # Audio plan: LUÔN phát tiếng gốc video tại `pos`.
        # Nếu có overlay_idx → phát thêm mp3 dòng đó (trộn cùng lúc).
        def _start_audio():
            # primary = tiếng gốc video (WAV đã trích → MCI waveaudio, master clock)
            _play_video_audio(pos)
            # overlay = mp3 dòng (MCI mpegvideo, trộn với primary)
            if overlay_idx is not None and overlay_idx >= 0:
                es['cur_aud'] = overlay_idx
                _play_overlay(overlay_idx)
                _preload_overlay(overlay_idx + 1)

        def _worker():
            ffmpeg_cmd = [
                get_ffmpeg(),
                "-ss", f"{pos:.3f}",
                "-i",  es['video_path'],
                "-vf", (f"scale={W}:{H}:force_original_aspect_ratio=decrease,"
                        f"pad={W}:{H}:(ow-iw)/2:(oh-ih)/2:black"),
                "-pix_fmt", "rgb24",
                "-r",  str(int(fps)),
                "-f",  "rawvideo",
                "-an",
                "pipe:1",
            ]
            try:
                proc = subprocess.Popen(
                    ffmpeg_cmd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.DEVNULL,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
            except Exception as ex:
                if win.winfo_exists():
                    win.after(0, lambda ex=ex: _set_status(f"ffmpeg error: {ex}", error=True))
                log(f"[Edit Studio] ❌ ffmpeg lỗi khi đọc video: {ex}")
                log("━━━ Hướng xử lý ━━━")
                log("  • Kiểm tra file video có bị hỏng không (thử mở bằng trình phát khác)")
                log("  • Kiểm tra ffmpeg hợp lệ tại ⚙ Cài đặt → ffmpeg folder")
                log("  • Thử convert video sang .mp4 (H.264) rồi load lại")
                return
            if es['gen'] != my_gen:
                try: proc.kill()
                except Exception: pass
                return
            es['render_proc'] = proc

            # pre-read frame 0 so the first image is ready the instant audio starts
            raw0 = _read_exact(proc, frame_size)
            if es['gen'] != my_gen:
                return
            if len(raw0) < frame_size:
                if win.winfo_exists():
                    win.after(0, lambda: _on_video_end(my_gen))
                return

            # start audio + clock together (tight sync)
            _start_audio()
            es['play_start'] = time.time()
            if es['gen'] != my_gen:
                _stop_audio()
                return

            # Master clock = vị trí phát thật của audio (MCI), nội suy bằng
            # wall-clock giữa 2 lần poll (~30ms) cho mượt. Video frames bám theo
            # → audio không bị frames vượt trước. Fallback wall-clock nếu no master.
            def _elapsed():
                mm = es['master_ms']
                if mm >= 0 and es.get('audio_master'):
                    e = mm / 1000.0 - pos
                    mw = es.get('master_wall')
                    if mw:
                        e += (time.time() - mw)   # nội suy giữa các lần poll
                    if e >= -0.05:
                        return e
                return time.time() - es['play_start']

            # ── Prefetch buffer: reader thread đọc+giải mã frames CHẠY TRƯỚC,
            #    nạp PIL Image vào hàng đợi → hấp thụ giật decode của ffmpeg.
            #    PhotoImage được tạo trên MAIN thread (Tk không thread-safe).
            frame_q = _queue.Queue(maxsize=int(fps) + 6)   # ~1s buffer

            def _reader():
                # frame 0 đã đọc sẵn
                try:
                    frame_q.put((0, Image.frombytes("RGB", (W, H), raw0)))
                except Exception:
                    return
                i = 1
                while es['gen'] == my_gen and es['render_active']:
                    raw = _read_exact(proc, frame_size)
                    if len(raw) < frame_size:
                        try: frame_q.put((None, None), timeout=1.0)
                        except _queue.Full: pass
                        return
                    try:
                        img = Image.frombytes("RGB", (W, H), raw)
                    except Exception:
                        return
                    # put có timeout → khi buffer đầy thì block (backpressure →
                    # ffmpeg tự dừng ở pipe); thoát sớm nếu gen đổi
                    while es['gen'] == my_gen and es['render_active']:
                        try:
                            frame_q.put((i, img), timeout=0.2)
                            break
                        except _queue.Full:
                            continue
                    i += 1

            threading.Thread(target=_reader, daemon=True).start()

            # ── Pacer: lấy frame từ buffer, chờ audio tới mốc, rồi hiển thị
            while es['gen'] == my_gen and es['render_active']:
                try:
                    fidx, img = frame_q.get(timeout=0.2)
                except _queue.Empty:
                    continue
                if fidx is None:   # sentinel = hết video
                    if win.winfo_exists():
                        win.after(0, lambda: _on_video_end(my_gen))
                    break
                target = fidx / fps
                while es['gen'] == my_gen and es['render_active']:
                    ahead = target - _elapsed()
                    if ahead <= 0.002:
                        break
                    time.sleep(min(0.015, ahead))
                if es['gen'] != my_gen or not es['render_active']:
                    break
                # tụt quá xa so với audio → bỏ frame để đuổi kịp
                if _elapsed() - target > 0.25:
                    continue
                if win.winfo_exists():
                    win.after(0, lambda im=img: _show_frame(im, my_gen))

        threading.Thread(target=_worker, daemon=True).start()

    def _show_frame(img, g):
        # Tạo PhotoImage trên MAIN thread (Tk an toàn) từ PIL Image nhận từ buffer
        if g != es['gen'] or not win.winfo_exists():
            return
        try:
            photo = _ITk.PhotoImage(image=img)
        except Exception:
            return
        es['photo_ref'] = photo          # giữ ref tránh GC
        vcanvas.delete("vframe")
        vcanvas.create_image(0, 0, anchor="nw", image=photo, tags="vframe")

    def _on_video_end(g):
        if g != es['gen']:
            return
        es['playing']       = False
        es['play_start']    = None
        es['render_active'] = False
        _stop_audio()
        btn_pp.configure(text="▶  Play")

    def _toggle_play():
        if es.get('_seq_mode') and es.get('seq_files'):
            # Playlist phát nối tiếp từng file
            if es['playing']:
                _seq_pause()
                es['playing'] = False
                btn_pp.configure(text="▶  Play")
            else:
                if es.get('seq_active'):
                    _seq_resume()
                else:
                    # đã phát hết → phát lại từ đầu
                    es['seq_idx'] = -1
                    _seq_play(0)
                es['playing'] = True
                btn_pp.configure(text="⏸ Pause")
            return
        if not es['video_path']:
            # Audio-only (file audio dài đã nạp, vd final.mp3)
            if es.get('audio_wav') and es.get('wav_ready'):
                if es['playing']:
                    es['seek_offset'] = _cur_pos()
                    _stop_audio()
                    es['playing'] = False
                    btn_pp.configure(text="▶  Play")
                else:
                    _seek_audio_only(es['seek_offset'])
            return
        if es['playing']:
            es['seek_offset'] = _cur_pos()
            _stop_render()
            _stop_audio()
            btn_pp.configure(text="▶  Play")
        else:
            seek_to(es['seek_offset'])

    def _stop_video():
        _stop_render()
        _stop_audio()
        es['seek_offset'] = 0.0
        btn_pp.configure(text="▶  Play")
        no_video_lbl.place(relx=0.5, rely=0.5, anchor="center")

    def _play_audio(path, sub=None):
        """Play a line mp3 file. If video loaded, jump frames to sub.start and
        play BOTH the video's original audio AND the mp3 in sync (mixed)."""
        fname = os.path.basename(path)
        _set_status(f"▶ {fname}")
        # tìm audio row index của file này
        row_idx = -1
        for i, meta in enumerate(es['aud_meta']):
            if meta[2] == path:
                row_idx = i
                break
        if row_idx >= 0:
            es['cur_aud'] = row_idx
            _hl_audio(row_idx)
        if sub is not None and es['video_path']:
            # video nhảy tới sub.start; audio = tiếng gốc video + mp3 overlay
            seek_to(_td(sub.start), overlay_idx=row_idx)
        else:
            # không có video → chỉ phát mp3 (overlay qua audio thread)
            _stop_render()
            _stop_audio()
            if row_idx >= 0:
                _play_overlay(row_idx)

    # ── TICKER ────────────────────────────────────────────────────────────────
    def _tick():
        if not win.winfo_exists():
            return
        pos = _cur_pos()
        dur = es['duration']
        time_var.set(f"{_fmt(pos)} / {_fmt(dur) if dur else '--:--'}")

        # ── Playlist phát nối tiếp ──
        if es.get('_seq_mode'):
            # cập nhật status khi đổi file (audio thread tự nhảy file)
            if es.get('seq_active'):
                idx = es['seq_idx']
                if idx != es.get('_seq_shown_idx') and 0 <= idx < len(es['seq_files']):
                    es['_seq_shown_idx'] = idx
                    name = es['seq_files'][idx][0]
                    _set_status(f"🎶 {idx+1}/{len(es['seq_files'])}: {name}")
                    # tô sáng dòng đang phát trong danh sách
                    if es['panel_mode'] == 'audio' and 0 <= idx < len(_aud_rows):
                        _hl_audio(idx)
            # phát hiện playlist kết thúc (audio thread set seq_active=False)
            if es['playing'] and es.get('_seq_was_active') and not es.get('seq_active'):
                es['playing'] = False
                es['seek_offset'] = 0.0
                btn_pp.configure(text="▶  Play")
                _set_status(f"🎶 Playlist xong ({len(es['seq_files'])} file).")
            es['_seq_was_active'] = es.get('seq_active')

        # Audio-only (file audio dài) chạy hết → dừng, reset nút Play
        # (bỏ qua khi đang ở chế độ playlist — playlist tự nhảy file)
        if (es['playing'] and not es['video_path'] and not es.get('_seq_mode')
                and dur and pos >= dur):
            es['playing']     = False
            es['seek_offset'] = dur
            _stop_audio()
            btn_pp.configure(text="▶  Play")

        if es['panel_mode'] == 'subs' and es['subtitles']:
            for i, sub in enumerate(es['subtitles']):
                if _td(sub.start) <= pos <= _td(sub.end):
                    if es['cur_sub'] != i:
                        _hl_sub(i)
                    break

        # Audio tab: khi video đang phát, mp3 của dòng hiện tại tự phát theo
        # playhead (overlay lên tiếng gốc video) + highlight row, giống subtitles.
        elif (es['panel_mode'] == 'audio' and es['playing']
              and es['aud_meta']):
            found = -1
            for i, (st, en, _fp) in enumerate(es['aud_meta']):
                if st is not None and st <= pos <= en:
                    found = i
                    break
            if found != es['cur_aud']:
                es['cur_aud'] = found
                if found >= 0:
                    _hl_audio(found)
                    # phát dòng hiện tại (đã preload → tức thì) + preload dòng kế
                    _play_overlay(found)
                    _preload_overlay(found + 1)
            elif found >= 0:
                # giữ preload dòng kế luôn sẵn sàng để không trễ khi sang dòng mới
                nxt = found + 1
                if (0 <= nxt < len(es['aud_meta'])
                        and nxt not in es['m_loaded'].values()):
                    _preload_overlay(nxt)

        es['ticker_id'] = win.after(200, _tick)

    # ── LOAD FUNCTIONS ────────────────────────────────────────────────────────
    def _load_srt(path=None):
        if path is None:
            path = filedialog.askopenfilename(
                parent=win, title="Chọn file SRT",
                filetypes=[("SRT files", "*.srt"), ("All files", "*.*")])
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                es['subtitles'] = list(srt.parse(f.read()))
            es['srt_path'] = path
            _set_status(
                f"SRT: {os.path.basename(path)}  ({len(es['subtitles'])} dòng)")
            if es['panel_mode'] == 'subs':
                _build_subs()
        except Exception as ex:
            _set_status(f"Lỗi SRT: {ex}", error=True)
            log(f"[Edit Studio] ❌ Không đọc được file SRT: {ex}")
            log("━━━ Hướng xử lý ━━━")
            log("  • Kiểm tra file có đúng định dạng .srt không")
            log("  • Mở file bằng Notepad, lưu lại với encoding UTF-8 (không BOM)")
            log("  • Thử dùng Subtitle Edit để sửa/export lại file SRT")

    def _load_video(path=None):
        if path is None:
            path = filedialog.askopenfilename(
                parent=win, title="Chọn file video",
                filetypes=[
                    ("Video", "*.mp4 *.mkv *.avi *.mov *.wmv *.flv *.webm *.ts"),
                    ("All files", "*.*"),
                ])
        if not path:
            return
        _exit_seq_mode()
        _stop_render()
        _stop_audio()
        es['video_path']  = path
        es['seek_offset'] = 0.0
        es['wav_ready']   = False
        # dọn WAV cũ
        old = es.get('audio_wav')
        if old:
            try: os.remove(old)
            except Exception: pass
        es['audio_wav'] = None
        try:
            out = subprocess.check_output(
                [get_ffprobe(), "-v", "error",
                 "-show_entries", "format=duration",
                 "-of", "default=noprint_wrappers=1:nokey=1", path],
                stderr=subprocess.DEVNULL,
            ).decode().strip()
            es['duration'] = float(out)
        except Exception:
            es['duration'] = 0.0
        base = os.path.basename(path)
        _set_status(f"⏳ Đang trích xuất audio: {base} …")

        # MCI không mở được mp4 → trích tiếng gốc ra WAV (waveaudio mở được + báo
        # vị trí phát = master clock). Làm 1 lần trong thread, xong mới phát.
        def _extract():
            import tempfile
            wav = os.path.join(tempfile.gettempdir(),
                               f"es_vidaudio_{os.getpid()}.wav")
            ok = False
            try:
                r = subprocess.run(
                    [get_ffmpeg(), "-y", "-i", path, "-vn",
                     "-acodec", "pcm_s16le", "-ar", "44100", "-ac", "2", wav],
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
                ok = (r.returncode == 0 and os.path.exists(wav)
                      and os.path.getsize(wav) > 1024)
            except Exception:
                ok = False
            if ok:
                es['audio_wav'] = wav
                es['wav_ready'] = True
            def _after():
                if not win.winfo_exists():
                    return
                _set_status(f"Video: {base}"
                            + ("" if ok else "  (⚠ không có tiếng)"),
                            error=not ok)
                if not ok:
                    log(f"[Edit Studio] ⚠ Video '{base}' không trích được audio")
                    log("━━━ Hướng xử lý ━━━")
                    log("  • Video có thể không có audio track (video câm)")
                    log("  • Thử mở video bằng trình phát khác để xác nhận có tiếng không")
                    log("  • Nếu cần tiếng: dùng 'Merge FFmpeg' để ghép audio vào video trước")
                    log("  • Xem frame/subtitle vẫn hoạt động bình thường, chỉ thiếu tiếng gốc")
                seek_to(0.0)
            if win.winfo_exists():
                win.after(0, _after)

        threading.Thread(target=_extract, daemon=True).start()

    def _load_audio_folder(path=None):
        if path is None:
            path = filedialog.askdirectory(parent=win,
                                           title="Chọn thư mục chứa audio")
        if not path:
            return
        _exit_seq_mode()
        es['audio_dir'] = path
        files = sorted(
            f for f in os.listdir(path)
            if f.lower().endswith(".mp3")
            and re.match(r"line_\d+", f, re.IGNORECASE)
        )
        es['audio_files'] = [(f, os.path.join(path, f)) for f in files]
        _set_status(
            f"Audio: {len(es['audio_files'])} files — {os.path.basename(path)}")
        if es['panel_mode'] == 'audio':
            _build_audio()

    def _load_audio_file(path=None):
        """Nạp 1 file audio dài đầy đủ (vd final.mp3 sau khi Merge FFmpeg).
        Có video → GIỮ NGUYÊN tiếng gốc video, trộn (amix) dub đè lên trên →
        nghe cả nhạc/SFX gốc lẫn lồng tiếng. Không video → click phụ đề để
        nhảy mốc + play/pause trên chính track audio này."""
        if path is None:
            init_dir = OUTPUT_DIR if (OUTPUT_DIR and os.path.isdir(OUTPUT_DIR)) else None
            init_file = ""
            if init_dir and os.path.exists(os.path.join(init_dir, "final.mp3")):
                init_file = "final.mp3"
            path = filedialog.askopenfilename(
                parent=win,
                title="Chọn file audio (vd final.mp3 sau khi Merge FFmpeg)",
                initialdir=init_dir, initialfile=init_file,
                filetypes=[
                    ("Audio", "*.mp3 *.wav *.m4a *.aac *.flac *.ogg *.opus"),
                    ("All files", "*.*"),
                ])
        if not path:
            return
        _exit_seq_mode()
        _stop_render()
        _stop_audio()
        es['playing']     = False
        es['seek_offset'] = 0.0
        es['wav_ready']   = False
        # dọn WAV cũ (tiếng gốc video hoặc audio đã nạp trước)
        old = es.get('audio_wav')
        if old:
            try: os.remove(old)
            except Exception: pass
        es['audio_wav']  = None
        es['audio_file'] = path
        base = os.path.basename(path)
        _set_status(f"⏳ Đang nạp audio: {base} …")

        # Chuyển sang WAV (waveaudio mở được + báo vị trí phát = master clock)
        has_video = bool(es['video_path'])
        vpath     = es['video_path']

        def _prep():
            import tempfile
            wav = os.path.join(tempfile.gettempdir(),
                               f"es_loadaudio_{os.getpid()}.wav")

            def _run(cmd):
                try:
                    r = subprocess.run(
                        cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                        creationflags=subprocess.CREATE_NO_WINDOW,
                    )
                    return (r.returncode == 0 and os.path.exists(wav)
                            and os.path.getsize(wav) > 1024)
                except Exception:
                    return False

            ok, dur, mixed = False, 0.0, False
            if has_video and vpath:
                # GIỮ tiếng gốc video + trộn dub (final.mp3) → 1 track master
                ok = _run([
                    get_ffmpeg(), "-y",
                    "-i", vpath, "-i", path,
                    "-filter_complex",
                    "[0:a][1:a]amix=inputs=2:duration=longest:normalize=0[a]",
                    "-map", "[a]",
                    "-acodec", "pcm_s16le", "-ar", "44100", "-ac", "2", wav,
                ])
                mixed = ok
            if not ok:
                # Không có video, hoặc video không có tiếng → chỉ dùng audio đã nạp
                ok = _run([
                    get_ffmpeg(), "-y", "-i", path, "-vn",
                    "-acodec", "pcm_s16le", "-ar", "44100", "-ac", "2", wav,
                ])
                mixed = False
            if ok:
                try:
                    out = subprocess.check_output(
                        [get_ffprobe(), "-v", "error",
                         "-show_entries", "format=duration",
                         "-of", "default=noprint_wrappers=1:nokey=1", wav],
                        stderr=subprocess.DEVNULL,
                        creationflags=subprocess.CREATE_NO_WINDOW,
                    ).decode().strip()
                    dur = float(out)
                except Exception:
                    dur = 0.0

            def _after():
                if not win.winfo_exists():
                    return
                if ok:
                    es['audio_wav'] = wav
                    es['_tmp_wav']  = wav     # dọn khi đóng cửa sổ
                    es['wav_ready'] = True
                    if not es['video_path'] and dur:
                        es['duration'] = dur
                    if mixed:
                        hint = "(giữ tiếng gốc video + lồng dub)"
                    elif es['video_path']:
                        hint = "(lồng lên video — video không có tiếng gốc)"
                    else:
                        hint = f"({_fmt(dur)})"
                    _set_status(f"🎧 Audio: {base}  {hint}")
                    # video → phát hình + audio này làm master; không video → audio-only
                    seek_to(0.0)
                else:
                    _set_status(f"Lỗi nạp audio: {base}", error=True)
                    log(f"[Edit Studio] ❌ Không nạp được audio: {base}")
                    log("━━━ Hướng xử lý ━━━")
                    log("  • Kiểm tra file audio có hợp lệ không (thử mở bằng trình phát khác)")
                    log("  • Kiểm tra ffmpeg hợp lệ tại ⚙ Cài đặt → ffmpeg folder")
            if win.winfo_exists():
                win.after(0, _after)

        threading.Thread(target=_prep, daemon=True).start()

    def _load_audio_seq():
        """Chọn NHIỀU file audio → phát nối tiếp TỪNG FILE (không nối, không
        timeline): file này phát xong thì file kế phát ngay. Sắp theo tên file."""
        paths = filedialog.askopenfilenames(
            parent=win,
            title="Chọn nhiều file audio (phát nối tiếp từng file)",
            filetypes=[
                ("Audio", "*.mp3 *.wav *.m4a *.aac *.flac *.ogg *.opus"),
                ("All files", "*.*"),
            ])
        if not paths:
            return
        paths = list(paths)
        # sắp xếp tự nhiên: line_0000, line_0001, ... , line_0010
        def _natkey(p):
            b = os.path.basename(p)
            return [int(t) if t.isdigit() else t.lower()
                    for t in re.split(r'(\d+)', b)]
        paths.sort(key=_natkey)

        _stop_render()
        _stop_audio()
        es['seq_files']      = [(os.path.basename(p), p) for p in paths]
        es['seq_idx']        = -1
        es['_seq_mode']      = True
        es['_seq_was_active'] = False
        es['_seq_shown_idx']  = -2
        es['playing']        = True
        es['seek_offset']    = 0.0
        btn_pp.configure(text="⏸ Pause")
        no_video_lbl.place_forget()
        _set_status(f"🎶 Playlist {len(es['seq_files'])} file — phát nối tiếp từng file")
        _set_tab('audio')           # hiện danh sách file (tên + nút ▶)
        _seq_play(0)

    # ── CLEANUP ───────────────────────────────────────────────────────────────
    def _on_close():
        # invalidate generation + stop everything immediately
        tid = es.get('ticker_id')
        if tid:
            try:
                win.after_cancel(tid)
            except Exception:
                pass
        es['ticker_id'] = None
        _stop_render()    # bumps gen, kills ffmpeg, unblocks reader thread
        _stop_audio()     # enqueue stop_all
        es['audio_run'] = False   # audio thread thoát → đóng mọi thiết bị MCI
        # clean up temp wavs
        for k in ('_tmp_wav', 'audio_wav'):
            tw = es.get(k)
            if tw:
                try:
                    os.remove(tw)
                except Exception:
                    pass
        win.destroy()

    win.protocol("WM_DELETE_WINDOW", _on_close)

    # ── AUTO-POPULATE ─────────────────────────────────────────────────────────
    if SRT_FILE and os.path.exists(SRT_FILE):
        win.after(100, lambda: _load_srt(SRT_FILE))
    elif subtitles_cache:
        es['subtitles'] = list(subtitles_cache)

    if OUTPUT_DIR and os.path.isdir(OUTPUT_DIR):
        files = sorted(
            f for f in os.listdir(OUTPUT_DIR)
            if f.lower().endswith(".mp3")
            and re.match(r"line_\d+", f, re.IGNORECASE)
        )
        if files:
            es['audio_files'] = [(f, os.path.join(OUTPUT_DIR, f)) for f in files]
            es['audio_dir']   = OUTPUT_DIR

    _set_tab('subs')
    es['ticker_id'] = win.after(200, _tick)


# =========================
# Pause / Resume
# =========================

def pause_tts():

    global paused

    paused = True

    log("PAUSED")

    app.after(0, lambda: (
        btn_pause.configure(state="disabled"),
        btn_resume.configure(state="normal"),
        btn_doc_pause.configure(state="disabled"),
        btn_doc_resume.configure(state="normal")
    ))


def resume_tts():

    global paused

    paused = False

    log(f"RESUME FROM {current_index}")

    app.after(0, lambda: (
        btn_resume.configure(state="disabled"),
        btn_pause.configure(state="normal"),
        btn_doc_resume.configure(state="disabled"),
        btn_doc_pause.configure(state="normal")
    ))


def stop_tts():

    global stop_requested

    stop_requested = True

    for process in RUNNING_PROCESSES[:]:

        try:
            process.kill()
        except:
            pass

    RUNNING_PROCESSES.clear()

    log("STOP REQUESTED")

    app.after(0, lambda: set_mode("tts_stopped"))


def restart_tts():

    global current_index
    global paused
    global stop_requested

    paused = False
    stop_requested = False
    current_index = 0

    clear_log()
    _refill_subtitle_list()   # giữ lại nội dung text (PDF/Word/TXT hoặc SRT) sau khi xóa log

    btn_reset_mode.configure(state="disabled")

    progress_var.set(0)
    progress_label.configure(text="0%")
    _hide_progress_bar()

    if _pdf_mode_active:
        # Xóa các file pdf_line_*.mp3
        deleted = 0
        for file in os.listdir(OUTPUT_DIR):
            if file.startswith("pdf_line_") and file.endswith(".mp3"):
                try:
                    os.remove(os.path.join(OUTPUT_DIR, file))
                    deleted += 1
                except Exception:
                    pass
        if deleted:
            log(f"DELETED {deleted} pdf mp3 file(s)")
        log("PDF: START FROM BEGINNING")
        start_pdf_tts()
    else:
        # Xóa các file line_*.mp3
        deleted = 0
        for file in os.listdir(OUTPUT_DIR):
            if file.startswith("line_") and file.endswith(".mp3"):
                try:
                    os.remove(os.path.join(OUTPUT_DIR, file))
                    deleted += 1
                except Exception:
                    pass
        if deleted:
            log(f"DELETED {deleted} mp3 file(s)")
        log("START FROM BEGINNING")
        start_tts()




