# =========================
# CLEAN EXIT
# =========================

def stop_all_processes():

    global stop_requested

    stop_requested = True

    for process in RUNNING_PROCESSES[:]:

        try:
            # /F: force, /T: kill toàn bộ cây tiến trình con (ffmpeg, bat, ...)
            subprocess.run(
                ["taskkill", "/F", "/T", "/PID", str(process.pid)],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=CREATE_NO_WINDOW
            )
        except:
            pass

        try:
            process.kill()
        except:
            pass

    RUNNING_PROCESSES.clear()


def _resolve_wav(filename):
    """Tìm đường dẫn tuyệt đối của file WAV.
    Thứ tự tìm kiếm:
      1. _internal/ (sys._MEIPASS) khi chạy EXE đã build
      2. Thư mục chứa .exe (khi frozen)
      3. Thư mục chứa script .py
      4. Thư mục hiện tại
    """
    # 1. _internal/ hoặc thư mục cạnh script
    path = get_resource_path(filename)
    if os.path.exists(path):
        return path
    # 2. Thư mục chứa file .exe (frozen) hoặc .py
    if getattr(sys, 'frozen', False):
        base = os.path.dirname(sys.executable)
    else:
        base = os.path.dirname(os.path.abspath(__file__))
    path = os.path.join(base, filename)
    if os.path.exists(path):
        return path
    # 3. Thư mục hiện tại
    path = os.path.join(os.getcwd(), filename)
    if os.path.exists(path):
        return path
    return None


def _play_wav_sync(filename):
    """Phát WAV đồng bộ (chặn cho đến khi xong) — dùng khi chuẩn bị thoát."""
    path = _resolve_wav(filename)
    if not path:
        return
    try:
        import winsound
        winsound.PlaySound(path, winsound.SND_FILENAME)  # SND_SYNC mặc định
    except Exception:
        try:
            ffplay = FFMPEG.replace("ffmpeg.exe", "ffplay.exe").replace("ffmpeg", "ffplay")
            subprocess.run(
                [ffplay, "-nodisp", "-autoexit", path],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=CREATE_NO_WINDOW
            )
        except Exception:
            pass


def _play_wav_async(filename):
    """Phát WAV bất đồng bộ trong thread riêng — dùng khi không thoát app."""
    threading.Thread(target=_play_wav_sync, args=(filename,), daemon=True).start()


# =========================
# BACKGROUND MUSIC (MP3)
# =========================

_bg_music_process = None

def _play_mp3_loop(filename):
    """Phát nhạc nền WAV bằng winsound (SND_ASYNC) — không chặn UI, dễ dừng."""
    global _bg_music_process
    # Tìm đường dẫn file — ưu tiên get_resource_path (hỗ trợ PyInstaller _internal/)
    path = get_resource_path(filename)
    if not os.path.exists(path):
        path = _resolve_wav(filename)
    if not path or not os.path.exists(path):
        return

    # Ưu tiên winsound (WAV native, nhẹ, không cần ffplay)
    try:
        import winsound
        winsound.PlaySound(path, winsound.SND_FILENAME | winsound.SND_ASYNC)
        return  # winsound.SND_ASYNC trả về ngay, phát một lần rồi thôi
    except Exception:
        pass

    # Fallback: ffplay nếu winsound thất bại
    try:
        ffplay = FFMPEG.replace("ffmpeg.exe", "ffplay.exe").replace("ffmpeg", "ffplay")
        _bg_music_process = subprocess.Popen(
            [ffplay, "-nodisp", "-volume", "80", "-autoexit", path],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=CREATE_NO_WINDOW
        )
        _bg_music_process.wait()
    except Exception:
        pass

def start_bg_music(filename):
    """Phát nhạc nền MP3 lặp vô hạn trong thread riêng."""
    threading.Thread(target=_play_mp3_loop, args=(filename,), daemon=True).start()

def stop_bg_music():
    """Dừng nhạc nền đang phát (winsound + ffplay fallback)."""
    global _bg_music_process
    # Dừng winsound (SND_PURGE dừng âm thanh đang loop)
    try:
        import winsound
        winsound.PlaySound(None, winsound.SND_PURGE)
    except Exception:
        pass
    # Dừng ffplay nếu đang chạy
    if _bg_music_process is not None:
        try:
            subprocess.run(
                ["taskkill", "/F", "/T", "/PID", str(_bg_music_process.pid)],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=CREATE_NO_WINDOW
            )
        except Exception:
            pass
        try:
            _bg_music_process.kill()
        except Exception:
            pass
        _bg_music_process = None


# ── Ghi nhớ thiết lập UI giữa các phiên (ui_prefs.json) ──────────────────────
# settings.json chỉ lưu đường dẫn + API key; còn cả chục toggle/ô nhập (tốc độ
# Edge, đọc số kiểu Việt, cắt lặng, loudnorm, delay, format merge...) trước đây
# reset mỗi lần mở app. File riêng cạnh settings.json (pattern voice_profiles)
# để _save_settings() không ghi đè. Lưu khi thoát/logout; nạp ngay sau đăng ký.
_UI_PREFS_FILE = os.path.join(
    os.path.dirname(_SETTINGS_FILE) or ".", "ui_prefs.json")
_UI_PREF_VARS = {}   # name → tk Variable

def _ui_prefs_register():
    _UI_PREF_VARS.update({
        "provider": provider_var, "voice": voice_var,
        "edge_rate": edge_rate_var, "edge_pitch": edge_pitch_var,
        "delay_min": delay_min_var, "delay_max": delay_max_var,
        "vi_num": vi_num_var, "auto_retry_fail": auto_retry_fail_var,
        "trim_silence": trim_silence_var, "teencode": teencode_var,
        "merge_center": merge_center_var, "merge_format": merge_format_var,
        "merge_loudnorm": merge_loudnorm_var, "merge_linevol": merge_linevol_var,
        "quick_tts_telex": quick_tts_telex_var,
        "stt_model": stt_model_var, "stt_lang": stt_lang_var,
        "stt_format": stt_format_label_var, "stt_segmode": stt_segmode_label_var,
        "autodub_model": autodub_model_var, "autodub_lang": autodub_lang_var,
        "autodub_translate": autodub_translate_var,
        "autodub_keep": autodub_keep_var, "autodub_burnsub": autodub_burnsub_var,
        "autodub_yt_dir": autodub_yt_dir_var, "autodub_yt_open": autodub_yt_open_var,
        "watch_dir": watch_dir_var,   # CHỈ đường dẫn — trạng thái bật không persist
        "translate_bilingual": translate_bilingual_var,
        "translate_then_tts": translate_then_tts_var,
        "translate_target": translate_target_var,
        "mux_keep_orig": mux_keep_orig_var, "mux_duck": mux_duck_var,
        "mux_demucs": mux_demucs_var,
        "pdf_gap_ms": pdf_gap_var, "pdf_m4b": pdf_m4b_var,
    })

def _ui_prefs_load():
    try:
        if not os.path.isfile(_UI_PREFS_FILE):
            return
        with open(_UI_PREFS_FILE, "r", encoding="utf-8") as f:
            d = json.load(f)
        if not isinstance(d, dict):
            return
        # MRU giọng nạp TRƯỚC set_provider để dropdown ghim đúng ngay từ đầu
        try:
            _MRU_VOICES[:] = [tuple(x) for x in d.get("_mru_voices", [])
                              if isinstance(x, (list, tuple)) and len(x) == 2]
        except Exception:
            pass
        # Lịch sử tốc độ batch (giây/dòng per engine) cho ước tính thời gian
        try:
            sh = d.get("_speed_history", {})
            if isinstance(sh, dict):
                _SPEED_HISTORY.update(
                    {str(k): float(v) for k, v in sh.items() if v})
        except Exception:
            pass
        # provider/voice có side-effect (pack API row, đổi danh sách voice)
        # → đi qua setter, provider TRƯỚC voice (set_provider reset voice list)
        if d.get("provider"):
            try:
                set_provider(d["provider"])
                provider_var.set(d["provider"])
            except Exception:
                pass
        if d.get("voice"):
            try:
                voice_var.set(d["voice"])
                set_voice(d["voice"])
            except Exception:
                pass
        for k, var in _UI_PREF_VARS.items():
            if k in ("provider", "voice") or k not in d:
                continue
            try:
                var.set(d[k])
            except Exception:
                pass
    except Exception as e:
        log(f"⚠ Không đọc được ui_prefs.json: {e}")

def _ui_prefs_save():
    try:
        d = {}
        for k, var in _UI_PREF_VARS.items():
            try:
                d[k] = var.get()
            except Exception:
                pass
        d["_mru_voices"] = [list(x) for x in _MRU_VOICES]
        d["_speed_history"] = dict(_SPEED_HISTORY)
        with open(_UI_PREFS_FILE, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

_ui_prefs_register()
_ui_prefs_load()


# ── 💬 Tooltip cho các nút chính ──────────────────────────────────────────────
# App đã ~60 nút, nhiều nút emoji khó đoán công dụng. Hover 0.55s → chú thích.
# Gắn qua globals().get(tên) nên nút bị đổi tên/xóa chỉ mất tooltip, không lỗi.
def _add_tooltip(widget, text):
    tip = {"win": None, "after": None}

    def _show():
        if tip["win"] is not None:
            return
        try:
            x = widget.winfo_rootx() + 12
            y = widget.winfo_rooty() + widget.winfo_height() + 4
            tw = tk.Toplevel(widget)
            tw.wm_overrideredirect(True)
            tw.wm_geometry(f"+{x}+{y}")
            tw.attributes("-topmost", True)
            tk.Label(tw, text=text, bg="#1f2430", fg="#e8ecf5",
                     font=("Arial", 9), justify="left", wraplength=360,
                     padx=8, pady=5, bd=1, relief="solid").pack()
            tip["win"] = tw
        except Exception:
            tip["win"] = None

    def _hide(_e=None):
        if tip["after"]:
            try:
                widget.after_cancel(tip["after"])
            except Exception:
                pass
            tip["after"] = None
        if tip["win"] is not None:
            try:
                tip["win"].destroy()
            except Exception:
                pass
            tip["win"] = None

    def _enter(_e=None):
        _hide()
        try:
            tip["after"] = widget.after(550, _show)
        except Exception:
            pass

    # add="+" để không đè các bind hover-color sẵn có
    widget.bind("<Enter>", _enter, add="+")
    widget.bind("<Leave>", _hide, add="+")
    widget.bind("<ButtonPress>", _hide, add="+")


