def _hf_cache_dirs():
    """Các thư mục cache HuggingFace có thể có (theo env hoặc mặc định ~/.cache)."""
    dirs = []
    for env in ("HF_HUB_CACHE", "HUGGINGFACE_HUB_CACHE"):
        v = os.environ.get(env)
        if v:
            dirs.append(v)
    hf_home = os.environ.get("HF_HOME")
    if hf_home:
        dirs.append(os.path.join(hf_home, "hub"))
    dirs.append(os.path.join(os.path.expanduser("~"), ".cache", "huggingface", "hub"))
    return dirs


def _hf_cache_has(repo_id):
    """True nếu repo HF đã có trong cache (đã tải về). repo_id dạng 'org/name'."""
    folder = "models--" + repo_id.replace("/", "--")
    for d in _hf_cache_dirs():
        try:
            if os.path.isdir(os.path.join(d, folder)):
                return True
        except Exception:
            pass
    return False


def _hf_cache_has_prefix(prefix):
    """True nếu CÓ ÍT NHẤT MỘT repo HF trong cache khớp tiền tố 'org/name'.
    Dùng cho faster-whisper (small/medium/large-v3 — bất kỳ bản nào đủ chạy)."""
    folder_prefix = "models--" + prefix.replace("/", "--")
    for d in _hf_cache_dirs():
        try:
            for name in os.listdir(d):
                if name.startswith(folder_prefix):
                    return True
        except Exception:
            pass
    return False


def _torch_hub_dirs():
    """Các thư mục cache torch.hub checkpoints có thể có (demucs htdemucs, Silero VAD)."""
    dirs = []
    th = os.environ.get("TORCH_HOME")
    if th:
        dirs.append(os.path.join(th, "hub", "checkpoints"))
    xdg = os.environ.get("XDG_CACHE_HOME")
    if xdg:
        dirs.append(os.path.join(xdg, "torch", "hub", "checkpoints"))
    dirs.append(os.path.join(os.path.expanduser("~"), ".cache", "torch", "hub", "checkpoints"))
    return dirs


def _torch_hub_has(prefix):
    """True nếu có file checkpoint torch.hub khớp tiền tố tên (vd 'htdemucs' → '955717e8-*.th')."""
    for d in _torch_hub_dirs():
        try:
            for name in os.listdir(d):
                if name.startswith(prefix):
                    return True
        except Exception:
            pass
    return False


def _run_startup_diagnostics():
    """Kiểm tra phụ thuộc runtime hệ thống + tính năng lúc khởi động.
    Ghi kết quả ra logbox; trả về list tên runtime QUAN TRỌNG bị thiếu."""
    critical_missing = []
    log_color("══════════ KIỂM TRA HỆ THỐNG ══════════")

    _OK  = "#22c55e"   # xanh lá — check OK
    _YEL = "#ffdd00"   # vàng     — header / cảnh báo / lỗi (default)

    # 0. Nơi lưu cấu hình/log (ghi được) — nếu khác thư mục exe nghĩa là cài MSI
    #    vào Program Files (chỉ đọc) nên đã chuyển sang %LOCALAPPDATA%.
    if os.path.abspath(_CONFIG_DIR) != os.path.abspath(_EXE_DIR):
        log_color(f"ℹ Cấu hình & log lưu tại: {_CONFIG_DIR}", _OK)
        log_color("   (thư mục cài đặt chỉ đọc → đã chuyển sang LOCALAPPDATA)", _OK)

    # 1. Internet
    if check_internet():
        log_color("✅ Internet: OK", _OK)
    else:
        log_color("❌ Internet: KHÔNG có kết nối (Edge TTS & provider online sẽ lỗi)")

    # 2. Visual C++ Redistributable (x64)
    ok, miss = _check_vcredist()
    if ok:
        log_color("✅ Visual C++ Redistributable 2015-2022 (x64): OK", _OK)
    else:
        log_color(f"❌ Visual C++ Redistributable (x64): THIẾU [{miss}] — cài vc_redist.x64.exe")
        critical_missing.append("Visual C++ Redistributable 2015-2022 (x64)")

    # 3. .NET Framework
    ok, rel = _check_dotnet()
    if ok:
        log_color(f"✅ .NET Framework 4.x: OK (Release {rel})", _OK)
    else:
        log_color("⚠ .NET Framework 4.8: không phát hiện — cần cho Subtitle Edit",
                  _YEL, force_color=True)

    # 4. GPU / CUDA
    has_gpu, drv, cuda = _check_cuda()
    if has_gpu:
        log_color(f"✅ GPU NVIDIA: {DETECTED_GPU or '?'} (driver {drv or '?'}, CUDA {cuda or '?'})", _OK)
        log_color(f"   → Video encoder: {VIDEO_ENCODER} (tăng tốc GPU)", _OK)
    else:
        log_color("⚠ Không có GPU NVIDIA — dùng CPU (libx264 + cpu cho AI, chậm hơn nhưng vẫn chạy)",
                  _YEL, force_color=True)

    # 5. ffmpeg / ffprobe
    fm, fp = get_ffmpeg(), get_ffprobe()
    if (fm == "ffmpeg" or os.path.exists(fm)) and (fp == "ffprobe" or os.path.exists(fp)):
        log_color("✅ ffmpeg / ffprobe: OK", _OK)
    else:
        log_color("❌ ffmpeg / ffprobe: THIẾU — video & merge sẽ lỗi")
        critical_missing.append("ffmpeg/ffprobe")

    log_color("────────── TÍNH NĂNG NÂNG CAO ──────────")

    # 6. RVC models + rvc_env
    def _near_exe(name):
        bases = []
        if getattr(sys, 'frozen', False):
            bases.append(os.path.dirname(sys.executable))
        bases.append(os.path.dirname(os.path.abspath(__file__)))
        for b in bases:
            p = os.path.join(b, name)
            if os.path.exists(p):
                return True
        return False
    if _near_exe("rmvpe.pt") and _near_exe("hubert_base.pt"):
        log_color("✅ RVC models (rmvpe.pt, hubert_base.pt): OK", _OK)
    else:
        log_color("⚠ RVC models: thiếu rmvpe.pt / hubert_base.pt — RVC Voice Clone sẽ lỗi",
                  _YEL, force_color=True)

    # 7. voxcpm_env python (VoxCPM / STT / SRT align / audio enhance)
    try:
        ckpt = voxcpm_ckpt_var.get().strip()
    except Exception:
        ckpt = ""
    vpy = _find_voxcpm_python(ckpt)   # dò cả cạnh exe kể cả khi chưa chọn model
    if vpy:
        log_color("✅ voxcpm_env python: OK (VoxCPM / STT / căn giọng / lọc audio)", _OK)
    else:
        log_color("⚠ voxcpm_env python: chưa tìm thấy — VoxCPM/STT/căn giọng tắt. Trỏ tại ⚙ Cài đặt",
                  _YEL, force_color=True)

    # 8. VoxCPM model dir
    if ckpt and os.path.isdir(ckpt):
        log_color(f"✅ VoxCPM model: OK ({ckpt})", _OK)
    else:
        log_color("⚠ VoxCPM model: chưa chọn thư mục — trỏ tại ⚙ Cài đặt",
                  _YEL, force_color=True)

    # 9. VideOCR CLI (+ model PaddleOCR PP-OCRv5 nằm BÊN TRONG thư mục CLI)
    if VIDEOCR_CLI_DIR and os.path.isdir(VIDEOCR_CLI_DIR):
        log_color("✅ VideOCR CLI: OK (tách sub cứng OCR)", _OK)
        # PaddleOCR model files — videocr_helper.py dò 'PaddleOCR.PP-OCRv5.support.files'
        # trong: VIDEOCR_INSTALL_DIR → thư mục CLI → Program Files\VideOCR.
        _ocr_roots = [VIDEOCR_CLI_DIR,
                      os.environ.get("VIDEOCR_INSTALL_DIR", "").strip(),
                      r"C:\Program Files\VideOCR"]
        _ocr_ok = any(r and os.path.isdir(os.path.join(r, "PaddleOCR.PP-OCRv5.support.files"))
                      for r in _ocr_roots)
        if _ocr_ok:
            log_color("✅ PaddleOCR PP-OCRv5 model: OK", _OK)
        else:
            log_color("⚠ PaddleOCR PP-OCRv5 model chưa có (PaddleOCR.PP-OCRv5.support.files) — "
                      "OCR sẽ tự tải lần đầu nếu CÓ net; máy KHÔNG net phải copy thư mục model vào VideOCR CLI",
                      _YEL, force_color=True)
    else:
        log_color("⚠ VideOCR CLI: chưa tìm thấy — Tách Sub Cứng tắt. Trỏ tại ⚙ Cài đặt",
                  _YEL, force_color=True)

    # 10. VieNeu env
    if _find_vieneu_python(VIENEU_MODEL_DIR):
        log_color("✅ vieneu_env python: OK (VieNeu-TTS)", _OK)
    else:
        log_color("⚠ vieneu_env python: chưa tìm thấy — VieNeu-TTS tắt. Đặt vieneu_env cạnh exe hoặc trỏ ⚙ Cài đặt",
                  _YEL, force_color=True)

    # 11. F5-TTS env + model
    try:
        _f5_model = f5tts_model_var.get().strip()
    except Exception:
        _f5_model = F5TTS_MODEL_DIR
    if _find_f5tts_python(_f5_model):
        log_color("✅ f5tts_env python: OK (F5-TTS-Vietnamese)", _OK)
    else:
        log_color("⚠ f5tts_env python: chưa tìm thấy — F5-TTS tắt. Đặt f5tts_env cạnh exe hoặc trỏ ⚙ Cài đặt",
                  _YEL, force_color=True)
    if _f5_model and os.path.isdir(_f5_model):
        log_color("✅ F5-TTS model: OK", _OK)
    else:
        log_color("⚠ F5-TTS model: chưa có (cần model_last.pt + vocab.txt) — đặt cạnh exe hoặc trỏ ⚙ Cài đặt",
                  _YEL, force_color=True)

    # 11b. OmniVoice env (model tự tải từ HF — không cần thư mục local)
    try:
        _omni_model = omnivoice_model_var.get().strip()
    except Exception:
        _omni_model = OMNIVOICE_MODEL_DIR
    if _find_omnivoice_python(_omni_model):
        log_color("✅ omnivoice_env python: OK (OmniVoice Vietnamese)", _OK)
    else:
        log_color("⚠ omnivoice_env python: chưa tìm thấy — OmniVoice tắt. Đặt omnivoice_env cạnh exe hoặc trỏ ⚙ Cài đặt",
                  _YEL, force_color=True)

    # 12. Model HuggingFace tải-runtime (KHÔNG nằm trong thư mục model copy tay).
    #     Trên máy CÓ net sẽ tự tải lần đầu; máy KHÔNG net phải copy %USERPROFILE%\.cache\huggingface.
    #     Hai cái dưới đây là phụ thuộc ẩn hay bị quên:
    #       - MOSS-Audio-Tokenizer-Nano: BẮT BUỘC cho VoxCPM
    #       - vocos-mel-24khz:           BẮT BUỘC cho F5-TTS (vocoder)
    #       - VieNeu-TTS-v3-Turbo:       model VieNeu (tự tải nếu không trỏ thư mục local)
    #       - omnivoice-vietnamese:      model OmniVoice (tự tải nếu không trỏ thư mục local)
    _hf_checks = [
        ("OpenMOSS-Team/MOSS-Audio-Tokenizer-Nano", "VoxCPM (audio tokenizer)"),
        ("charactr/vocos-mel-24khz",                 "F5-TTS (vocoder)"),
        ("pnnbao-ump/VieNeu-TTS-v3-Turbo",           "VieNeu-TTS (model)"),
        ("splendor1811/omnivoice-vietnamese",        "OmniVoice (model)"),
    ]
    _hf_missing = [(rid, feat) for rid, feat in _hf_checks if not _hf_cache_has(rid)]
    if not _hf_missing:
        log_color("✅ Model HF cache (MOSS, vocos, VieNeu, OmniVoice): OK", _OK)
    else:
        for rid, feat in _hf_missing:
            log_color(f"⚠ Model HF chưa có cache: {rid} — cần cho {feat}",
                      _YEL, force_color=True)
        log_color("   → Máy CÓ internet: tự tải lần đầu. Máy KHÔNG net: copy "
                  "%USERPROFILE%\\.cache\\huggingface\\ từ máy gốc sang",
                  _YEL, force_color=True)

    # 12b. faster-whisper (STT + Video→SRT) — bất kỳ bản nào (small/medium/large-v3) là đủ.
    #      Nằm trong HF cache; helper chạy bằng voxcpm_env. Hay bị quên trên máy mới.
    if _hf_cache_has_prefix("Systran/faster-whisper"):
        log_color("✅ faster-whisper cache: OK (STT / Video→SRT)", _OK)
    else:
        log_color("⚠ faster-whisper chưa có cache (Systran/faster-whisper-*) — STT & Video→SRT sẽ lỗi. "
                  "Máy CÓ net: tự tải lần đầu; máy KHÔNG net: copy %USERPROFILE%\\.cache\\huggingface\\",
                  _YEL, force_color=True)

    # 12c. Demucs htdemucs (tách nhạc trong 'Xử lý Audio') — cache ở TORCH HUB, không phải HF.
    #      File: ~/.cache/torch/hub/checkpoints/955717e8-*.th
    if _torch_hub_has("955717e8"):
        log_color("✅ Demucs htdemucs cache: OK (tách nhạc khỏi audio mẫu)", _OK)
    else:
        log_color("⚠ Demucs htdemucs chưa có cache — nút 'Tách nhạc' khi xử lý audio mẫu sẽ lỗi. "
                  "Máy CÓ net: tự tải lần đầu; máy KHÔNG net: copy %USERPROFILE%\\.cache\\torch\\hub\\checkpoints\\",
                  _YEL, force_color=True)

    # 12d. Model dịch Offline (NLLB / envit5 / opus-mt) — CHỈ cần khi dùng provider 'Offline'.
    #      Có thể là thư mục local HOẶC một HF id (org/name). Chỉ kiểm tra khi đã cấu hình
    #      hoặc đang chọn provider Offline — tránh nhiễu cho người chỉ dùng dịch online.
    _tr_model = (LOCAL_TRANSLATE_MODEL_DIR or "").strip()
    if TRANSLATE_PROVIDER == "Offline" or _tr_model:
        if not _tr_model:
            log_color("⚠ Dịch Offline: chưa trỏ model (NLLB/envit5) — trỏ tại ⚙ Cài đặt",
                      _YEL, force_color=True)
        elif os.path.isdir(_tr_model):
            log_color("✅ Model dịch Offline: OK (thư mục local)", _OK)
        elif "/" in _tr_model and _hf_cache_has(_tr_model):
            log_color("✅ Model dịch Offline: OK (HF cache)", _OK)
        else:
            log_color(f"⚠ Model dịch Offline chưa có: {_tr_model} — máy CÓ net tự tải lần đầu; "
                      "máy KHÔNG net copy %USERPROFILE%\\.cache\\huggingface\\ hoặc trỏ thư mục local",
                      _YEL, force_color=True)

    if critical_missing:
        log_color("⛔ THIẾU RUNTIME QUAN TRỌNG: " + ", ".join(critical_missing),
                  "#f97316", blink="#f97316")
    else:
        log_color("══════════ HỆ THỐNG SẴN SÀNG ══════════", _OK)
    return critical_missing


def _report_startup_diagnostics():
    """Chạy diagnostics trong daemon thread (tránh treo UI); popup trên main thread."""
    def _worker():
        try:
            missing = _run_startup_diagnostics()
        except Exception as e:
            try:
                log(f"⚠ Không chạy được kiểm tra hệ thống: {e}")
            except Exception:
                pass
            return
        if missing:
            app.after(0, lambda: msg.showwarning(
                "Thiếu thành phần runtime hệ thống",
                "⚠️  Máy đang thiếu thành phần sau (một số tính năng có thể lỗi):\n\n"
                + "\n".join(f"   • {m}" for m in missing)
                + "\n\nKhuyến nghị cài Microsoft Visual C++ Redistributable 2015-2022 (x64)\n"
                  "rồi khởi động lại phần mềm. Xem chi tiết tại log."
            ))
    threading.Thread(target=_worker, daemon=True).start()


def show_splash_then_auth():
    """Hiện splash screen với logo ở giữa màn hình, tắt sau 3s rồi chạy auth."""
    splash = tk.Toplevel()
    splash.overrideredirect(True)  # Không có thanh tiêu đề
    # Màu "chìa khóa" để bo tròn 4 góc (vùng góc tô màu này sẽ trong suốt).
    # Dùng hồng cánh sen — màu không xuất hiện trong ảnh, tránh key nhầm
    # các pixel tóc đen gần #000000 (gây "chấm trắng li ti").
    _KEY = "#FF00FF"
    splash.configure(bg=_KEY)
    try:
        splash.wm_attributes("-transparentcolor", _KEY)
    except Exception:
        pass

    # Kích thước splash (vuông — ảnh nền bo góc + chữ đè lên)
    sw, sh = 320, 320

    # Căn giữa màn hình
    screen_w = splash.winfo_screenwidth()
    screen_h = splash.winfo_screenheight()
    x = (screen_w - sw) // 2
    y = (screen_h - sh) // 2
    splash.geometry(f"{sw}x{sh}+{x}+{y}")
    splash.lift()
    splash.attributes("-topmost", True)

    # ===== Poster: ảnh nền phủ kín splash + chữ đè lên =====
    # Canvas phủ toàn bộ splash để vừa hiển thị ảnh vừa vẽ chữ chồng lên
    _sp_canvas = tk.Canvas(splash, width=sw, height=sh,
                           bg=_KEY, highlightthickness=0, bd=0)
    _sp_canvas.pack(fill="both", expand=True)

    # Dựng ảnh nền: cover-fit ảnh vào khung + đổ tối dần ở dưới (scrim)
    try:
        from PIL import ImageDraw
        _logo_path = ""
        for _cand in ("logo.png", "logo.ico"):
            try:
                _p = get_resource_path(_cand)
                if os.path.isfile(_p):
                    _logo_path = _p
                    break
            except Exception:
                continue
        base = Image.open(_logo_path)
        # Frame lớn nhất nếu là ICO nhiều frame
        if getattr(base, "n_frames", 1) > 1:
            best = base
            for i in range(base.n_frames):
                base.seek(i)
                if base.size[0] > best.size[0]:
                    best = base.copy()
            base = best
        base = base.convert("RGBA")
        # Cover-fit: scale phủ kín rồi crop giữa
        scale = max(sw / base.width, sh / base.height)
        nw, nh = max(1, int(base.width * scale)), max(1, int(base.height * scale))
        base = base.resize((nw, nh), Image.LANCZOS)
        left, top = (nw - sw) // 2, (nh - sh) // 2
        base = base.crop((left, top, left + sw, top + sh))
        # Scrim: trong suốt ở trên → tối đậm ở dưới để chữ dễ đọc
        scrim = Image.new("RGBA", (sw, sh), (0, 0, 0, 0))
        _d = ImageDraw.Draw(scrim)
        _band = int(sh * 0.40)
        for _yy in range(_band, sh):
            _a = int(238 * (_yy - _band) / max(1, (sh - _band)))
            _d.line([(0, _yy), (sw, _yy)], fill=(14, 14, 28, _a))
        base = Image.alpha_composite(base, scrim)
        # Bo tròn 4 góc: tô góc bằng màu _KEY để được key trong suốt
        _radius = 32
        _mask = Image.new("L", (sw, sh), 0)
        ImageDraw.Draw(_mask).rounded_rectangle(
            [0, 0, sw - 1, sh - 1], radius=_radius, fill=255)
        _rounded = Image.new("RGB", (sw, sh), (255, 0, 255))  # = _KEY #FF00FF
        _rounded.paste(base.convert("RGB"), (0, 0), _mask)
        poster_img = ImageTk.PhotoImage(_rounded)
        _sp_canvas.create_image(0, 0, anchor="nw", image=poster_img)
        _sp_canvas.image = poster_img  # Giữ reference
    except Exception:
        _sp_canvas.create_text(sw // 2, sh // 2 - 40, text="🎬",
                               font=("Segoe UI", 48), fill="white")

    # ===== Light Sweep: luồng sáng chéo quét qua bề mặt (bóng bẩy, sang trọng) =====
    try:
        from PIL import ImageDraw as _SwDraw, ImageChops as _SwChops
        # Mặt nạ bo góc giới hạn vệt sáng nằm gọn trong khung
        _swmask = Image.new("L", (sw, sh), 0)
        _SwDraw.Draw(_swmask).rounded_rectangle(
            [0, 0, sw - 1, sh - 1], radius=30, fill=255)

        # Dải sáng dọc với gradient mềm (lõi sáng + tản dần), rồi xoay nghiêng
        _bandw = 64
        _bandh = int((sw + sh) * 0.95)
        _core, _peak = 5.0, 95
        _col = []
        _cx = _bandw / 2.0
        for _x in range(_bandw):
            _dd = abs(_x - _cx)
            if _dd <= _core:
                _v = 1.0
            else:
                _v = max(0.0, 1.0 - (_dd - _core) / (_cx - _core))
                _v *= _v
            _col.append(int(_peak * _v))
        _strip = Image.new("L", (_bandw, 1))
        _strip.putdata(_col)
        _strip = _strip.resize((_bandw, _bandh))
        _white = Image.new("RGBA", (_bandw, _bandh), (255, 255, 255, 0))
        _white.putalpha(_strip)
        _streak = _white.rotate(30, expand=True, resample=Image.BICUBIC)
        _rw, _rh = _streak.size

        # Dựng sẵn các frame: vệt sáng trượt từ trái qua phải, cắt theo khung
        _SW_N = 40
        _sw_frames = []
        for _i in range(_SW_N):
            _ovr = Image.new("RGBA", (sw, sh), (0, 0, 0, 0))
            _px = int(-_rw + (sw + _rw) * _i / (_SW_N - 1))
            _ovr.alpha_composite(_streak, (_px, (sh - _rh) // 2))
            _ovr.putalpha(_SwChops.multiply(_ovr.split()[3], _swmask))
            _sw_frames.append(ImageTk.PhotoImage(_ovr))

        _sweep_id = _sp_canvas.create_image(0, 0, anchor="nw",
                                            image=_sw_frames[0])
        _sp_canvas._sw_frames = _sw_frames  # giữ reference khỏi bị GC
        _sw_idx = [0]

        def _animate_sweep():
            try:
                _sw_idx[0] = (_sw_idx[0] + 1) % _SW_N
                _sp_canvas.itemconfig(_sweep_id, image=_sw_frames[_sw_idx[0]])
                # nghỉ một nhịp ở đầu mỗi lượt cho cảm giác sang trọng
                _sp_canvas.after(900 if _sw_idx[0] == 0 else 45, _animate_sweep)
            except Exception:
                pass

        _sp_canvas.after(400, _animate_sweep)
    except Exception:
        pass

    # ===== Viền cầu vồng chuyển động (chạy vòng quanh khung như video) =====
    import math as _math
    _bm = 3            # cách mép
    _brad = 27         # bán kính bo của viền (nhỏ hơn ảnh để nằm gọn bên trong)

    def _round_rect_points(x0, y0, x1, y1, r, seg_edge=16, seg_arc=7):
        pts = []
        def edge(ax, ay, bx, by):
            for i in range(seg_edge):
                t = i / seg_edge
                pts.append((ax + (bx - ax) * t, ay + (by - ay) * t))
        def arc(cx, cy, a0):
            for i in range(seg_arc):
                a = _math.radians(a0 + 90 * i / seg_arc)
                pts.append((cx + r * _math.cos(a), cy + r * _math.sin(a)))
        edge(x0 + r, y0, x1 - r, y0)          # cạnh trên
        arc(x1 - r, y0 + r, -90)              # góc trên-phải
        edge(x1, y0 + r, x1, y1 - r)          # cạnh phải
        arc(x1 - r, y1 - r, 0)                # góc dưới-phải
        edge(x1 - r, y1, x0 + r, y1)          # cạnh dưới
        arc(x0 + r, y1 - r, 90)               # góc dưới-trái
        edge(x0, y1 - r, x0, y0 + r)          # cạnh trái
        arc(x0 + r, y0 + r, 180)              # góc trên-trái
        return pts

    _bpts = _round_rect_points(_bm, _bm, sw - _bm, sh - _bm, _brad)
    _bsegs = []
    _bn = len(_bpts)
    for _i in range(_bn):
        _x1b, _y1b = _bpts[_i]
        _x2b, _y2b = _bpts[(_i + 1) % _bn]
        _bsegs.append(_sp_canvas.create_line(
            _x1b, _y1b, _x2b, _y2b, width=5,
            capstyle="round", joinstyle="round", tags="rbborder"))
    _boff = [0.0]

    def _animate_border():
        try:
            off = _boff[0]
            n = len(_bsegs)
            for i, seg in enumerate(_bsegs):
                _sp_canvas.itemconfig(seg, fill=_rainbow_color(i / n + off))
            _boff[0] = (off + 0.012) % 1.0
            _sp_canvas.after(40, _animate_border)
        except Exception:
            pass

    _animate_border()

    # Vị trí chữ (đè lên vùng tối phía dưới ảnh)
    _ty_title = sh - 96
    _ty_by = sh - 56
    _ty_sub = sh - 30

    # Tên app — màu cầu vồng chuyển động, có bóng cho dễ đọc trên ảnh
    _sp_text = "SRT TTS Studio"
    _sp_font = tkFont.Font(family="Segoe UI", size=22, weight="bold")
    _sp_off = [0.0]

    def _animate_splash_title():
        try:
            _sp_canvas.delete("sptitle")
            chars = list(_sp_text)
            total_w = _sp_font.measure(_sp_text)
            x = sw // 2 - total_w // 2
            cy = _ty_title
            off = _sp_off[0]
            # Lớp bóng đen phía dưới
            for i, ch in enumerate(chars):
                ch_w = _sp_font.measure(ch)
                _sp_canvas.create_text(
                    x + ch_w // 2 + 2, cy + 2, text=ch, font=_sp_font,
                    fill="#000000", tags="sptitle"
                )
                x += ch_w
            # Lớp chữ màu cầu vồng
            x = sw // 2 - total_w // 2
            for i, ch in enumerate(chars):
                ch_w = _sp_font.measure(ch)
                hue = off + i / max(len(chars), 1) * 0.7
                _sp_canvas.create_text(
                    x + ch_w // 2, cy, text=ch, font=_sp_font,
                    fill=_rainbow_color(hue), tags="sptitle"
                )
                x += ch_w
            _sp_off[0] = (_sp_off[0] + 0.008) % 1.0
            _sp_canvas.after(33, _animate_splash_title)
        except Exception:
            pass

    _animate_splash_title()

    # "by Mr.Tân" — có bóng
    _sp_canvas.create_text(sw // 2 + 1, _ty_by + 1, text="by Mr.Tân",
                           font=("Segoe UI", 10), fill="#000000")
    _sp_canvas.create_text(sw // 2, _ty_by, text="by Mr.Tân",
                           font=("Segoe UI", 10), fill="#ffffff")

    # Dòng trạng thái — chấm "..." chạy kiểu loading ( . / .. / ... )
    _sub_base = "Đang khởi động & kiểm tra kết nối"
    _sub_font = tkFont.Font(family="Segoe UI", size=9)
    _sub_full_w = _sub_font.measure(_sub_base + "...")
    _sub_x = sw // 2 - _sub_full_w // 2   # neo trái để chấm mọc sang phải, chữ đứng yên
    _sub_dots = [0]

    def _animate_subdots():
        try:
            _sp_canvas.delete("subln")
            _txt = _sub_base + "." * (_sub_dots[0] % 3 + 1)   # 1 → 2 → 3 chấm
            _sp_canvas.create_text(_sub_x + 1, _ty_sub + 1, text=_txt, anchor="w",
                                   font=_sub_font, fill="#000000", tags="subln")
            _sp_canvas.create_text(_sub_x, _ty_sub, text=_txt, anchor="w",
                                   font=_sub_font, fill="#ffdd00", tags="subln")
            _sub_dots[0] += 1
            _sp_canvas.after(450, _animate_subdots)
        except Exception:
            pass

    _animate_subdots()

    def _close_splash():
        splash.destroy()
        if not check_internet():
            msg.showerror(
                "Không có kết nối Internet",
                "⚠️  Phần mềm yêu cầu kết nối Internet để hoạt động.\n\n"
                "Vui lòng kiểm tra lại kết nối mạng của bạn và khởi động lại chương trình."
            )
            os._exit(0)
        # Kiểm tra phụ thuộc runtime hệ thống (VC++/.NET/CUDA/GPU/ffmpeg/feature)
        app.after(200, _report_startup_diagnostics)
        app.after(100, run_auth)
        app.after(1500, _session_check_on_startup)

    splash.after(3000, _close_splash)
    start_bg_music("chungtakhongthuocvenhau.wav")


# Import ImageTk cho splash screen
try:
    from PIL import ImageTk
except ImportError:
    ImageTk = None

